// Source-based guidance drafts; individual clinical review remains required.
export const guidanceRecords=[
{"name":"Abscesso Dentário","aliases":[],"setting":"urgent","general":"Procure atendimento odontológico urgente. Enquanto aguarda, ofereça alimentos macios e mantenha higiene delicada.","diagnosis":"O foco dentário costuma precisar de intervenção; antibiótico isolado não substitui o tratamento do dente quando indicado.","expected":"A melhora depende do controle do foco e da extensão da infecção; não espere que desapareça sozinho.","alarm":"Observe inchaço facial crescente, febre, dor intensa ou dificuldade para abrir a boca.","immediate":"Dificuldade para respirar ou engolir, olho inchado ou alteração visual exige emergência imediata.","return":"Cumpra retorno odontológico e tratamento definitivo, mesmo se a dor melhorar após drenagem espontânea.","sources":[{"url":"https://www.nhs.uk/conditions/dental-abscess/","title":"NHS — Dental abscess","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Abscesso pulmonar","setting":"hospital","general":"Abscesso pulmonar exige avaliação hospitalar, imagem e investigação do contexto. Informe pneumonia prévia, engasgos, imunodeficiência e tratamentos recentes.","diagnosis":"Cumpra o plano da equipe; duração e necessidade de procedimento dependem da resposta e das complicações.","expected":"A recuperação costuma levar semanas; melhora clínica pode preceder a resolução radiológica.","alarm":"Febre persistente, dor crescente, sangue no escarro ou piora respiratória exigem reavaliação.","immediate":"Falta de ar intensa, cianose, confusão ou deterioração rápida exigem emergência.","return":"Alta somente com estabilidade e plano de reavaliação clínica e de imagem.","sources":[{"url":"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0345174","title":"Alshadfan et al. — Pediatric lung abscess: retrospective cohort (2026)","accessed":"2026-09-27"},{"url":"https://link.springer.com/article/10.1186/s12879-026-13014-1","title":"Ünal et al. — Pediatric lung abscesses: a 13-year journey (2026)","accessed":"2026-09-27"}],"reviewNotes":"Lacuna pediátrica atual suprida por estudos primários. Tipo secundário isoladamente não determina cirurgia. Escopo: orientação e encaminhamento; não seleciona regime, duração ou procedimento. Revisão documental assistida, sem homologação humana.","aliases":[],"status":"source-reviewed","evidenceSummary":"Duas coortes retrospectivas pediátricas de 2026: 23 crianças previamente saudáveis e 33 com casos primários/secundários. Sustentam seguimento prolongado e decisão individual; amostras pequenas, seleção hospitalar e ausência de comparação randomizada impedem fixar duração ou indicar drenagem universal.","decisionSupport":{"summary":"Escolher o contexto após avaliação; complicação ou falha de resposta prevalece sobre a classificação inicial.","requirements":["Idade, oxigenação e estabilidade","Imagem e complicações pleurais","Doença de base, imunidade e aspiração","Resposta ao tratamento e culturas"],"branchRequired":true,"branches":[{"id":"abscesso-primario","label":"Primário, resposta favorável","when":"Criança previamente saudável, sem complicação e melhorando sob tratamento.","setting":"hospital","overrides":{"diagnosis":"Acompanhe respiração, alimentação e resposta ao plano hospitalar.","expected":"Melhora gradual; imagem pode normalizar depois dos sintomas.","return":"Revisão e imagem no prazo individual de alta.","alarm":"Febre recorrente, dor ou tosse em piora.","immediate":"Procure emergência com falta de ar ou prostração."}},{"id":"abscesso-complexo","label":"Secundário, complicado ou refratário","when":"Doença de base, complicação de imagem ou evolução insatisfatória.","setting":"hospital","overrides":{"diagnosis":"Reavaliar causa, microbiologia e necessidade de intervenção especializada.","expected":"O curso depende da condição associada e da resposta.","return":"Seguimento conjunto com pneumologia/infectologia e especialidade de base.","alarm":"Piora respiratória, sangramento ou instabilidade são alarmes.","immediate":"Permaneça em assistência hospitalar; deterioração exige avaliação imediata."}}]},"revisedAt":"2026-09-27"},
{"name":"Abscesso subcutâneo","aliases":[],"setting":"urgent","general":"Procure avaliação presencial para definir necessidade de drenagem. Proteja a região e mantenha as mãos limpas ao cuidar da pele.","diagnosis":"Uma coleção de pus pode precisar de procedimento; não tente furar, espremer ou drenar em casa. O tratamento depende do tamanho, local e extensão.","expected":"A recuperação depende da drenagem quando indicada e do controle da infecção; aumento progressivo não é evolução esperada.","alarm":"Observe crescimento, dor crescente, calor, febre ou vermelhidão que se espalha além do nódulo.","immediate":"Procure pronto atendimento se houver piora rápida, calafrios, abatimento importante ou vermelhidão em expansão.","return":"Faça revisão conforme orientação após o procedimento; retorne antes se o nódulo aumentar ou persistir. Informe imunodeficiência ou diabetes.","sources":[{"url":"https://www.nhs.uk/conditions/skin-abscess/","title":"NHS — Skin abscess","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Abuso físico infantil","aliases":[],"setting":"urgent","general":"Leve a criança para avaliação médica em ambiente seguro. Acolha seu relato sem pressionar por detalhes nem repetir interrogatórios.","diagnosis":"Lesões podem estar presentes mesmo sem marcas evidentes. A equipe avaliará também a segurança da criança e de outras crianças expostas.","expected":"A recuperação depende das lesões identificadas e da proteção efetiva contra novas agressões; o apoio psicológico pode precisar continuar após a melhora física.","alarm":"Observe dor persistente, dificuldade para caminhar, vômitos, sonolência, medo intenso ou aparecimento de novas lesões.","immediate":"Procure emergência imediatamente diante de alteração da consciência, dificuldade respiratória, convulsão, sangramento importante ou perigo atual de nova agressão.","return":"Mantenha o seguimento pediátrico e psicossocial e cumpra o plano de proteção acordado com os serviços responsáveis.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Child_Abuse_Guideline/","title":"RCH — Child abuse","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. O fluxo de proteção/notificação brasileiro deve ser definido pelo serviço; não importar requisitos legais australianos.","status":"source-reviewed"},
{"name":"Abuso sexual infantil","aliases":[],"setting":"urgent","general":"Acolha sem culpar, ameaçar ou exigir que a criança repita detalhes. Garanta a companhia de um adulto protetor e afaste situações de risco.","diagnosis":"Procure serviço de referência para avaliação clínica, proteção, exames e medidas após exposição. O atendimento deve preservar privacidade e evitar novas experiências traumáticas.","expected":"A recuperação física e emocional varia; ausência de lesão visível não encerra a necessidade de cuidado e seguimento.","alarm":"Observe dor, sangramento, lesões, sofrimento intenso, medo de voltar ao ambiente ou ameaça atual à segurança.","immediate":"Procure urgência imediatamente se houver lesão aguda, sangramento importante, risco de nova violência ou crise emocional com risco de autoagressão.","return":"Combine seguimento médico, psicológico e social e confira os resultados e retornos programados.","sources":[{"url":"https://www.saude.mg.gov.br/violenciasexual/","title":"SES-MG — Atenção Integral às Vítimas de Violência Sexual","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/std/treatment-guidelines/sexual-assault-children.htm","title":"CDC — Sexual Assault or Abuse of Children","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Acidente ofídico botrópico","aliases":[],"setting":"hospital","general":"Procure imediatamente hospital com capacidade de atendimento a acidentes por serpentes. Informe horário, local da picada e evolução dos sintomas; não espere identificar a espécie para buscar atendimento.","diagnosis":"O acidente botrópico pode causar lesão local, sangramento e alteração renal. A equipe decidirá sobre o soro específico e acompanhará coagulação, sangue e função renal.","expected":"A recuperação depende da gravidade, do tempo até o tratamento e das complicações; a aparência discreta da picada não exclui envenenamento.","alarm":"Aumento do inchaço, sangramento, urina escura ou reduzida, fraqueza e tontura exigem comunicação imediata.","immediate":"Desmaio, falta de ar, sangramento importante ou pouca resposta: acione o SAMU 192.","return":"Após alta hospitalar, mantenha o retorno e os exames definidos; volte imediatamente se reaparecerem sangramento, piora local ou redução da urina.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/a/animais-peconhentos/acidentes-ofidicos/tratamento","title":"Ministério da Saúde — Acidentes ofídicos: tratamento","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Acidente ofídico crotálico","setting":"hospital","general":"Envenenamento por cascavel pode ter pouca alteração local, mas causar manifestações neurológicas, musculares e renais.","diagnosis":"Procure hospital imediatamente mesmo que a picada doa pouco. Informe horário e local do acidente; leve fotografia da serpente apenas se obtida sem aproximação ou risco.","expected":"A melhora depende da rapidez do atendimento e da gravidade do envenenamento. A equipe acompanha força muscular, respiração, coagulação e função renal; não é seguro aguardar sintomas em casa.","alarm":"Fraqueza, dificuldade para andar ou respirar, pálpebras caídas, visão dupla, urina escura, pouca urina ou sonolência exigem emergência.","immediate":"Lave o local, mantenha a pessoa calma e imóvel e transporte-a rapidamente. Não faça torniquete, cortes, sucção ou aplicações; não capture a serpente.","return":"Não aguarde em casa; após o atendimento, retorne imediatamente com piora da força, visão, respiração ou urina.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/a/animais-peconhentos/acidentes-ofidicos/sintomas","title":"Ministério da Saúde — Sintomas dos acidentes ofídicos","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/a/animais-peconhentos/acidentes-ofidicos/tratamento","title":"Ministério da Saúde — Tratamento dos acidentes ofídicos","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Acidente vascular encefálico (AVE) Hemorrágico na Criança","aliases":["AVC hemorrágico infantil","AVE hemorrágico"],"setting":"hospital","general":"Acione emergência diante de déficit neurológico súbito e informe a hora em que a criança estava bem pela última vez. Não ofereça alimentos se houver alteração da consciência ou deglutição.","diagnosis":"O sangramento cerebral precisa de imagem e avaliação neurológica urgente; tratamento não é o mesmo do AVC isquêmico.","expected":"A recuperação depende do local, extensão e causa, podendo exigir reabilitação prolongada.","alarm":"Observe fraqueza de um lado, dificuldade para falar, desequilíbrio ou cefaleia súbita intensa.","immediate":"Convulsão, desmaio ou qualquer novo déficit exigem SAMU 192.","return":"Após alta, mantenha neurologia e reabilitação; sintomas novos requerem retorno imediato.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Stroke/","title":"Royal Children’s Hospital — Stroke","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Orientação restrita à identificação e encaminhamento; não extrapola trombólise ou antitrombóticos do AVC isquêmico.","status":"source-reviewed"},
{"name":"Acidentes com Animais","aliases":[],"setting":"urgent","general":"Informe o animal, local e horário do acidente. Mordeduras com ferida precisam de limpeza e avaliação do risco de infecção.","diagnosis":"Picadas e mordeduras exigem condutas diferentes. A equipe avaliará necessidade de prevenção de raiva, tétano ou cuidado toxicológico.","expected":"A evolução depende do animal, exposição e lesão; aparência inicial discreta não exclui gravidade.","alarm":"Observe dor crescente, inchaço, vermelhidão ou sintomas gerais.","immediate":"Falta de ar, desmaio, sangramento importante ou piora rápida exige emergência.","return":"Após atendimento, cumpra revisões e medidas preventivas prescritas. Suspeita de animal peçonhento exige atendimento rápido.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Animal_and_human_bites/","title":"RCH — Animal and human bites","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/a/animais-peconhentos","title":"Ministério da Saúde — Animais peçonhentos","accessed":"2026-09-26"}],"reviewNotes":"Título amplo: diferencia mordeduras e envenenamento; não constitui protocolo único para todas as espécies. Fontes documentais para revisão médica.","status":"source-reviewed"},
{"name":"Acidose Metabólica em Pediatria","aliases":[],"setting":"hospital","general":"Acidose metabólica é um achado, não uma doença única. Informe diarreia, diabetes, jejum, doenças renais/metabólicas e exposições.","diagnosis":"A equipe deve identificar mecanismo e gravidade antes de corrigir; não use soluções alcalinas por conta própria.","expected":"A evolução depende da causa e da resposta clínica e laboratorial.","alarm":"Respiração profunda, vômitos, pouca urina ou prostração exigem avaliação.","immediate":"Confusão, convulsão, choque ou dificuldade respiratória requerem emergência.","return":"Alta e seguimento dependem da estabilização e do diagnóstico etiológico.","sources":[{"url":"https://cps.ca/en/documents/position/current-recommendations-for-management-of-paediatric-diabetic-ketoacidosis","title":"CPS — Paediatric diabetic ketoacidosis (2023)","accessed":"2026-09-27"},{"url":"https://www.scielo.br/j/jped/a/HPrgJQ5qCh5cJzm3KNYnwWw/?format=pdf&lang=en","title":"Andrade, Ihara e Troster — Metabolic acidosis in childhood (2007)","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Metabolic_disorders/","title":"RCH — Metabolic disorders","accessed":"2026-09-27"},{"url":"https://www.niddk.nih.gov/health-information/kidney-disease/renal-tubular-acidosis","title":"NIDDK — Renal tubular acidosis","accessed":"2026-09-27"}],"reviewNotes":"Triagem etiológica e seguimento, sem protocolo de reposição. Farmacologia/cálculos não aplicáveis. Revisão documental, sem homologação humana.","status":"source-reviewed","evidenceSummary":"CPS/RCH sustentam urgência e monitorização pediátrica; revisão SciELO antiga fundamenta mecanismos, complementada por NIDDK renal. Categorias podem coexistir. Não se transportam doses nem recomendações antigas de reposição.","decisionSupport":{"summary":"Classificação exige exames; causas mistas ou desconhecidas mantêm avaliação hospitalar, sem escolha automática.","requirements":["Gasometria, eletrólitos e ânion gap","Glicose, cetonas e lactato","Perfusão, hidratação e função renal","História de perdas, jejum e exposição"],"branchRequired":true,"branches":[{"id":"acidose-cad","label":"Cetoacidose diabética confirmada","when":"Hiperglicemia, cetose e acidose compatíveis, avaliadas pela equipe.","setting":"hospital","overrides":{"diagnosis":"Seguir protocolo pediátrico e monitorização neurológica/metabólica.","expected":"Normalizar glicose isoladamente não comprova resolução.","return":"Educação e seguimento do diabetes após estabilização.","alarm":"Cefaleia progressiva, vômitos ou mudança do comportamento.","immediate":"Alteração da consciência exige avaliação imediata."}},{"id":"acidose-perdas","label":"Perdas digestivas ou renais agudas","when":"Perdas agudas documentadas com repercussão clínica ou laboratorial.","setting":"hospital","overrides":{"diagnosis":"Acompanhar perdas, eletrólitos e função renal.","expected":"Perdas persistentes podem exigir correção e seguimento prolongados.","return":"Nefrologia se causa renal; revisar hidratação e crescimento.","alarm":"Fraqueza, palpitações ou redução da urina.","immediate":"Desmaio, prostração ou incapacidade de beber exigem urgência."}},{"id":"acidose-outros","label":"Hipoperfusão, intoxicação, erro metabólico ou causa incerta","when":"Contexto compatível ou investigação ainda inconclusiva.","setting":"hospital","overrides":{"diagnosis":"Priorizar estabilização e investigação dirigida, sem atrasar assistência.","expected":"Depende da causa; agravamento pode ser rápido.","return":"Seguimento etiológico após recuperação, sem alta por exame isolado.","alarm":"Respiração anormal, convulsão ou resposta reduzida.","immediate":"Acione emergência; não tente corrigir acidose em casa."}},{"id":"acidose-tubular-estavel","label":"Acidose tubular estável","when":"Diagnóstico confirmado e plano nefrológico, sem descompensação.","setting":"specialist","overrides":{"diagnosis":"Não altere reposição sem orientação; acompanhe crescimento.","expected":"Pode exigir seguimento prolongado.","return":"Eletrólitos e consultas conforme nefrologia.","alarm":"Vômitos, fraqueza ou pouca urina.","immediate":"Prostração ou desmaio exigem urgência."}}]},"revisedAt":"2026-09-27"},
{"name":"Acidose Respiratória na Criança","setting":"hospital","aliases":["Acidose respiratória"],"general":"Acúmulo de gás carbônico por ventilação insuficiente pode causar acidose e exige avaliação da causa.","diagnosis":"A forma aguda precisa de monitorização e, por vezes, suporte respiratório. Informe doenças prévias e exposição a substâncias sedativas.","expected":"A evolução depende da causa e da rapidez da correção; formas crônicas seguem plano especializado.","alarm":"Respiração lenta ou difícil, sonolência, confusão e dor de cabeça são alarmes.","immediate":"Acione emergência se houver redução da resposta, coloração azulada ou dificuldade respiratória importante.","return":"Após estabilização, siga o plano de tratamento da doença de base; piora respiratória exige retorno imediato.","sources":[{"url":"https://medlineplus.gov/ency/article/000092.htm","title":"MedlinePlus — Respiratory acidosis","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Síntese da fonte geral MedlinePlus para reconhecimento e encaminhamento. Acidose aguda não é orientação de alta nem plano de ventilação. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Actinomicose na Infância","aliases":[],"setting":"specialist","general":"Complete o tratamento orientado mesmo após melhora e mantenha higiene e acompanhamento odontológico quando houver foco na boca.","diagnosis":"A actinomicose é uma infecção bacteriana rara, podendo formar abscessos em diferentes regiões; não costuma passar de pessoa para pessoa.","expected":"A recuperação pode exigir meses e, em alguns casos, procedimento para tratar coleções.","alarm":"Informe aumento da massa, secreção persistente, febre ou dificuldade para se alimentar.","immediate":"Dificuldade para respirar ou engolir, dor intensa ou deterioração geral exigem atendimento imediato.","return":"Mantenha retornos para acompanhar o local afetado e a resposta, sem encurtar o tratamento por conta própria.","sources":[{"url":"https://www.nhs.uk/conditions/actinomycosis/","title":"NHS — Actinomycosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Adenoidite Aguda em Pediatria","aliases":["Adenoidite aguda"],"setting":"home","general":"Após avaliação, ofereça líquidos e mantenha higiene nasal conforme orientação. Evite fumaça e acompanhe a alimentação e o sono.","diagnosis":"A inflamação da adenoide pode ter causas virais, bacterianas ou outras. A necessidade de tratamento específico depende da avaliação.","expected":"Quadros virais costumam melhorar em cerca de uma semana; a evolução pode variar conforme a causa.","alarm":"Observe febre persistente, piora da obstrução, dificuldade alimentar ou pausas respiratórias durante o sono.","immediate":"Dificuldade importante para respirar, arroxeamento ou incapacidade de engolir exige atendimento imediato.","return":"Retorne se piorar ou não melhorar; com tratamento antibacteriano, ausência de resposta em dois dias exige revisão.","sources":[{"url":"https://my.clevelandclinic.org/health/diseases/adenoiditis","title":"Cleveland Clinic — Adenoiditis","accessed":"2026-09-26"}],"reviewNotes":"Fonte específica de adenoidite; não equiparada automaticamente à sinusite.","status":"source-reviewed"},
{"name":"Aderência balanoprepucial","aliases":[],"setting":"home","general":"Faça higiene externa suave durante o banho. Não puxe o prepúcio à força e não tente separar aderências em casa.","diagnosis":"A ligação entre a pele e a glande frequentemente é parte normal do desenvolvimento. Pequenos depósitos esbranquiçados de esmegma não significam, isoladamente, infecção.","expected":"A separação costuma ocorrer gradualmente ao longo da infância; a idade em que a pele se torna retrátil varia.","alarm":"Observe dificuldade para urinar, dor persistente, inchaço importante, febre ou mudança escura na ponta do pênis.","immediate":"Procure atendimento imediato se não conseguir urinar, se a pele ficar presa atrás da glande ou houver coloração azulada/escura.","return":"Reavalie em consulta se surgirem inflamações repetidas ou sintomas urinários. Quando a retração ocorrer naturalmente, ensine higiene e reposicionamento da pele.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/the_penis_and_foreskin/","title":"RCH — The penis and foreskin","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Adipsia","aliases":[],"setting":"specialist","general":"Siga um plano escrito de oferta de água, definido pela equipe. Na ausência de sede, esperar a criança pedir pode ser inadequado.","diagnosis":"Adipsia é redução ou ausência da sede. Precisa investigar a causa e verificar se há perda excessiva de água.","expected":"O controle depende da causa, dos exames e da capacidade de manter o plano hídrico; não há prazo universal.","alarm":"Observe mudança do peso, urina excessiva ou reduzida, vômitos e alteração do comportamento.","immediate":"Sonolência anormal, convulsão, incapacidade de beber ou desidratação exigem pronto atendimento.","return":"Combine controle de peso, sódio e balanço de líquidos, especialmente durante doenças intercorrentes.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Diabetes_insipidus/","title":"RCH — Diabetes insipidus","accessed":"2026-09-26"}],"reviewNotes":"Adipsia não equivale automaticamente a diabetes insípido. Fonte fundamenta risco da resposta de sede inadequada e monitorização.","status":"source-reviewed"},
{"name":"Agamaglobulinemia ligada ao X","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com imunologista, registre infecções e leve o plano de atendimento em consultas e viagens. Higienize as mãos e evite contato próximo com pessoas doentes.","diagnosis":"A deficiência de anticorpos facilita infecções recorrentes. Siga rigorosamente a reposição e a prevenção já prescritas, sem alterar intervalos por conta própria.","expected":"O acompanhamento reduz infecções e complicações, mas a condição exige cuidado contínuo; não há prazo único para resolução dos sintomas.","alarm":"Febre, tosse persistente, diarreia prolongada ou perda de peso precisam de contato rápido com a equipe.","immediate":"Vá imediatamente à emergência se houver falta de ar, prostração importante, confusão ou dificuldade para manter hidratação.","return":"Reavalie após cada infecção e mantenha controle do crescimento, dos pulmões e da resposta ao tratamento.","sources":[{"url":"https://www.medlineplus.gov/genetics/condition/x-linked-agammaglobulinemia/","title":"MedlinePlus Genetics — X-linked agammaglobulinemia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Agorafobia em Pediatria","aliases":[],"setting":"specialist","general":"Acolha o medo e combine passos graduais com profissional de saúde mental; preserve rotinas e apoio escolar sem punições.","diagnosis":"Agorafobia envolve medo de situações em que escapar ou obter ajuda pareça difícil; pode ocorrer com ou sem transtorno do pânico.","expected":"A melhora costuma exigir acompanhamento e prática gradual; avanços e recaídas podem acontecer.","alarm":"Informe isolamento crescente, recusa escolar, prejuízo alimentar ou do sono e sintomas depressivos.","immediate":"Risco de autoagressão ou incapacidade de manter segurança exige atendimento imediato.","return":"Retorne para revisar funcionamento e metas terapêuticas; se sair de casa for muito difícil, combine forma acessível de avaliação.","sources":[{"url":"https://www.nhs.uk/mental-health/conditions/agoraphobia/overview/","title":"NHS — Agoraphobia overview","accessed":"2026-09-26"},{"url":"https://cps.ca/en/documents/position/anxiety-in-children-and-youth-management","title":"Canadian Paediatric Society — Anxiety in children and youth: management","accessed":"2026-09-26"},{"url":"https://cps.ca/en/documents/position/anxiety-in-children-and-youth-diagnosis","title":"Canadian Paediatric Society — Anxiety in children and youth: diagnosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Alcalose Metabólica em Pediatria","aliases":["Alcalose metabólica"],"setting":"hospital","general":"O distúrbio exige avaliação da causa e dos eletrólitos. Informe vômitos, perdas digestivas e todos os tratamentos em uso.","diagnosis":"Alcalose metabólica pode acompanhar perdas de ácido e alterações de potássio ou volume; o resultado laboratorial precisa do contexto clínico.","expected":"A recuperação depende da correção segura da causa e dos desequilíbrios associados, com exames seriados quando indicados.","alarm":"Observe fraqueza, vômitos persistentes, sonolência, palpitações e redução da urina.","immediate":"Desmaio, convulsão, alteração respiratória ou fraqueza intensa exige atendimento imediato.","return":"A alta depende de estabilidade e causa esclarecida; siga revisão de eletrólitos e do problema desencadeante.","sources":[{"url":"https://medlineplus.gov/ency/article/001183.htm","title":"MedlinePlus — Alkalosis","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hypokalaemia/","title":"RCH — Hypokalaemia","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Pyloric_Stenosis/","title":"RCH — Pyloric stenosis","accessed":"2026-09-26"}],"reviewNotes":"Fonte oficial2025 distingue alcalose metabólica e respiratória; RCH complementa perdas, potássio e monitorização pediátrica. Não foi copiada orientação sobre respirar em saco de papel.","status":"source-reviewed"},
{"name":"Alergia a frutos do mar","aliases":[],"setting":"specialist","general":"Evite o alimento confirmado como desencadeante e confira ingredientes e contaminação cruzada. Avise escola e cuidadores e mantenha acessível o plano de emergência.","diagnosis":"Alergia a frutos do mar precisa de avaliação específica; não faça testes de ingestão em casa nem exclua todos os alimentos sem orientação nutricional.","expected":"A persistência da alergia varia; a tolerância deve ser reavaliada pelo especialista, sem prazo garantido para desaparecimento.","alarm":"Observe urticária, vômitos, inchaço e sintomas respiratórios após exposição.","immediate":"Falta de ar, língua ou garganta inchada, voz alterada, palidez intensa ou desmaio exigem emergência e aplicação do plano previamente prescrito.","return":"Retorne após qualquer reação e nas revisões da alergologia para atualizar prevenção e treinamento dos cuidadores.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Food_allergies/","title":"RCH — Food allergies","accessed":"2026-09-26"}],"reviewNotes":"Orientações gerais de alergia alimentar aplicadas a frutos do mar; não presume reatividade a todas as espécies.","status":"source-reviewed"},
{"name":"Alergia a medicamentos (Penicilina)","aliases":[],"setting":"specialist","general":"Registre o nome do medicamento, horário da dose, intervalo até a reação e sintomas; fotografias da pele podem ajudar a avaliação. Avise todos os profissionais sobre a suspeita.","diagnosis":"Manchas durante uma infecção nem sempre significam alergia verdadeira. A classificação e eventual retirada do rótulo exigem avaliação profissional; não faça teste de exposição em casa.","expected":"O risco de repetição depende do tipo de reação. A investigação pode confirmar alergia ou permitir o uso futuro com segurança.","alarm":"Urticária disseminada, inchaço de lábios, tosse súbita ou chiado após o medicamento precisam de avaliação rápida.","immediate":"Dificuldade respiratória, língua ou garganta inchada, desmaio ou criança muito mole: emergência imediata.","return":"Agende revisão da história com pediatra ou alergista e leve o registro da reação.","sources":[{"url":"https://frimley-healthiertogether.nhs.uk/professionals/prescribing-children/correctly-applying-penicillin-allergy-labels-children","title":"NHS Frimley — Correctly applying penicillin allergy labels in children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. A fonte não substitui protocolo para reações tardias graves; lesões de mucosa, bolhas extensas ou doença sistêmica exigem avaliação urgente.","status":"source-reviewed"},
{"name":"Alergia à proteína do leite de vaca","aliases":[],"setting":"specialist","general":"Faça exclusão do leite apenas conforme plano profissional, com substituição nutricional adequada. Mantenha acompanhamento de peso e crescimento; não interrompa a amamentação por conta própria.","diagnosis":"A alergia pode provocar manifestações imediatas ou tardias. A reintrodução do alimento deve seguir o tipo de reação e orientação da equipe.","expected":"Muitas crianças desenvolvem tolerância com o crescimento, mas o momento é individual e não deve ser testado sem plano.","alarm":"Observe recusa alimentar, baixo ganho de peso, sangue nas fezes ou vômitos repetidos.","immediate":"Falta de ar, língua inchada, desmaio ou vômitos intensos com palidez e prostração exigem atendimento imediato.","return":"Retorne para revisão da dieta, crescimento, diagnóstico e possibilidade de reintrodução supervisionada.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Non-IgE_mediated_food_allergy/","title":"RCH — Non-IgE mediated food allergy","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Food_allergies/","title":"RCH — Food allergies","accessed":"2026-09-26"}],"reviewNotes":"Distingue fenótipos IgE e não IgE. Plano alimentar/reintrodução dependem do fenótipo; não substitui confirmação diagnóstica.","status":"source-reviewed"},
{"name":"Alergia à proteína do leite de vaca IgE mediada","aliases":[],"setting":"specialist","general":"Siga o plano alimentar e confira os ingredientes a cada compra. Informe cuidadores e escola; mantenha o plano de emergência disponível e confirme substituições com a equipe.","diagnosis":"Na alergia IgE mediada, a reação pode ocorrer logo após leite ou derivados. Leite sem lactose não elimina a proteína alergênica; não faça reintrodução ou teste de leite assado por conta própria.","expected":"Muitas crianças desenvolvem tolerância, mas isso precisa ser reavaliado; não existe idade garantida para resolução. Acompanhe crescimento e adequação nutricional.","alarm":"Vômitos repetidos, urticária disseminada ou inchaço após exposição requerem orientação imediata.","immediate":"Falta de ar, língua inchada, palidez intensa ou desmaio: siga o plano de emergência e acione o SAMU 192.","return":"Retorne ao alergista e à nutrição nas datas combinadas, mesmo sem novas reações.","sources":[{"url":"https://www.cuh.nhs.uk/patient-information/milk-allergy/","title":"Cambridge University Hospitals — Milk allergy","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Alergia à proteína do leite de vaca não IgE mediada","setting":"specialist","general":"Reação alimentar tardia às proteínas do leite; pode ocorrer em lactentes amamentados ou alimentados com fórmula. Diferencia-se de intolerância à lactose.","diagnosis":"Siga a exclusão alimentar definida pelo profissional e apoio nutricional, preservando amamentação quando possível. Reintrodução deve ser planejada conforme o subtipo; não faça testes caseiros após reação grave.","expected":"A resposta à exclusão ocorre ao longo de dias ou semanas e varia com o subtipo. Crescimento e nutrição precisam ser acompanhados; melhora isolada não confirma automaticamente o diagnóstico.","alarm":"Urgência se houver dificuldade respiratória, prostração, desidratação, vômitos repetidos, sangue volumoso ou incapacidade de manter líquidos.","immediate":"Não faça exclusões prolongadas por conta própria. Mantenha hidratação e alimentação tolerada; lactentes devem ser avaliados para plano nutricional seguro.","return":"Retorne ao pediatra para revisar crescimento, resposta à retirada e reintrodução. Reavalie antes se os sintomas persistirem, piorarem ou surgirem sinais de alarme.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Non-IgE_mediated_food_allergy/","title":"RCH — Non-IgE mediated food allergy","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Alergia a veneno de himeópteros","setting":"specialist","general":"Picadas de abelha, vespa ou formiga podem causar alergia generalizada, comprometendo rapidamente respiração e circulação.","diagnosis":"Após reação generalizada, obtenha avaliação especializada e plano escrito para novas exposições. Siga o plano de emergência prescrito; uma reação grave pode ocorrer mesmo sem manchas na pele.","expected":"Reações locais e anafilaxia têm evoluções diferentes. Após anafilaxia, é necessária observação profissional porque os sintomas podem reaparecer, mesmo com melhora inicial.","alarm":"Dificuldade respiratória, língua ou garganta inchada, voz alterada, desmaio, palidez, cianose ou piora rápida sugerem anafilaxia.","immediate":"Na suspeita de anafilaxia, acione emergência e siga o plano prescrito. Mantenha a pessoa deitada; se precisar sentar para respirar, mantenha pernas estendidas. Não permita levantar ou caminhar.","return":"Após reação sistêmica, faça avaliação e orientação especializada; retorne imediatamente se sintomas reaparecerem.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Anaphylaxis/","title":"RCH — Anaphylaxis","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Alergia ao amendoim","aliases":["Alergia a amendoim"],"setting":"specialist","general":"Evite amendoim e confira ingredientes de alimentos e refeições. Avise familiares, escola e cuidadores sobre a alergia e o plano de emergência.","diagnosis":"Mantenha o plano individual escrito e a medicação de resgate prescrita disponível. Não faça testes de ingestão ou dessensibilização em casa.","expected":"A gravidade de uma próxima reação não é previsível pela reação anterior. O acompanhamento alergológico define reavaliação e possibilidades terapêuticas.","alarm":"Observe urticária, inchaço, vômitos, rouquidão, chiado, tontura ou sintomas em mais de uma parte do corpo após exposição.","immediate":"Dificuldade para respirar, inchaço de língua/garganta, desmaio ou criança muito mole exigem emergência e aplicação do plano de resgate.","return":"Após reação grave, procure atendimento mesmo se melhorar. Revise regularmente identificação de alimentos, técnica de resgate e treinamento dos cuidadores.","sources":[{"url":"https://www.nhs.uk/conditions/food-allergy/","title":"NHS — Food allergy","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Alergia ao ovo de galinha","aliases":[],"setting":"specialist","general":"Evite ovo e produtos definidos no plano individual; confira rótulos e avise escola e cuidadores. Não faça testes de reintrodução por conta própria.","diagnosis":"A tolerância a ovo bem assado não garante tolerância a outras preparações. Mantenha apenas alimentos expressamente liberados pelo alergologista.","expected":"Algumas crianças passam a tolerar ovo com o tempo, mas essa mudança precisa ser avaliada; a intensidade de uma reação futura não é previsível.","alarm":"Urticária, inchaço, vômitos ou tosse após exposição exigem seguir o plano de reação e observar progressão.","immediate":"Dificuldade para respirar, alteração da voz, desmaio ou inchaço de língua/garganta exigem atendimento de emergência imediato.","return":"Mantenha revisão de alergologia, crescimento e dieta; após qualquer reação relevante, atualize o plano de ação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Food_allergies/","title":"RCH — Food allergies","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Evitar ampliar a exclusão alimentar além do alérgeno confirmado.","status":"source-reviewed"},
{"name":"Alergia e Anafilaxia na Criança","aliases":["Anafilaxia","Reação alérgica"],"setting":"urgent","general":"Reconheça o plano de emergência individual e mantenha os cuidadores treinados. Em suspeita de anafilaxia, siga imediatamente esse plano e acione emergência; não espere apenas por manchas.","diagnosis":"Alergia leve e anafilaxia têm gravidades diferentes; comprometimento respiratório ou circulatório pode indicar anafilaxia.","expected":"Mesmo após melhora, a suspeita de anafilaxia requer observação hospitalar definida pela equipe.","alarm":"Observe voz alterada, inchaço da língua, dificuldade para respirar, vômitos associados ou tontura.","immediate":"Desmaio, falta de ar ou pouca resposta exigem SAMU 192; não permita levantar ou caminhar.","return":"Após estabilização, revise desencadeantes, prevenção e plano com alergologia.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Anaphylaxis/","title":"Royal Children’s Hospital — Anaphylaxis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Título composto; urgência aplica-se à suspeita de anafilaxia. Não foram incluídas doses ou novas opções farmacológicas.","status":"source-reviewed"},
{"name":"Alterações Dermatológicas do RN","setting":"specialist","aliases":["Alterações cutâneas do recém-nascido"],"general":"Avalie início, aspecto, distribuição, mucosas e estado geral. Faça higiene suave; prematuridade exige atenção à barreira cutânea.","diagnosis":"Não classifique uma erupção como benigna apenas pela ausência de febre.","expected":"A evolução depende do diagnóstico reconhecido, não do rótulo genérico.","alarm":"Vesículas suspeitas, bolhas, púrpura, necrose ou progressão rápida são alarmes.","immediate":"Recusa alimentar, temperatura anormal, prostração ou alteração respiratória exigem hospital.","return":"Defina diagnóstico e possibilidade de reavaliação antes de emitir orientação domiciliar.","sources":[{"url":"https://www.sbp.com.br/fileadmin/user_upload/sbp/2024/abril/11/_24424L-GPA_ISBN_-_Cuidado_Pele_e_Anexos_do_RN.pdf","title":"SBP — Cuidados com pele e anexos do recém-nascido (2024)","accessed":"2026-09-27"},{"url":"https://cps.ca/en/documents/position/prevention-management-neonatal-herpes-simplex-virus-infections","title":"CPS — Neonatal HSV infections (atualização 2025; reafirmação 2026)","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Recognition_of_the_seriously_unwell_neonate_and_young_infant/","title":"RCH — Seriously unwell neonate and young infant (2025)","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Integra PedWB 290: classificação, cuidados e destino, sem aprovação farmacológica. HSV pode apresentar-se até 42 dias; idade isolada não exclui. Revisão documental sem homologação humana.","evidenceSummary":"Guia SBP de cuidados/dermatoses e recomendações CPS/RCH de gravidade neonatal. Parte das recomendações de HSV baseia-se em opinião especializada publicada. O conjunto sustenta classificação e encaminhamento, não tratamento universal de todas as dermatoses.","decisionSupport":{"summary":"Selecionar somente após exame clínico; qualquer sinal sistêmico muda o destino para hospital.","requirements":["Idade pós-natal e gestacional","Morfologia, início, mucosas e evolução","Temperatura, mamadas, alerta e respiração","Diagnóstico clínico e possibilidade de retorno"],"branchRequired":true,"branches":[{"id":"rn-benigno","label":"Erupção benigna reconhecida","when":"Bebê bem; mília, eritema tóxico ou melanose transitória confirmados.","setting":"home","overrides":{"diagnosis":"Não esprema lesões; não necessitam tratamento empírico.","expected":"Mília/eritema regridem; pigmentação da melanose pode persistir meses.","return":"Revisão pediátrica; reavaliar padrão diferente ou persistente.","alarm":"Nova bolha, secreção ou piora do estado geral.","immediate":"Procure urgência se surgirem sinais sistêmicos."}},{"id":"rn-local","label":"Irritação localizada, bebê bem","when":"Causa local reconhecida, sem suspeita infecciosa ou comprometimento sistêmico.","setting":"home","overrides":{"diagnosis":"Reduza atrito e irritantes; use cuidados individualizados.","expected":"Espera-se melhora após corrigir o fator local.","return":"Reavalie se persistir ou se espalhar.","alarm":"Dor crescente, secreção, bolhas ou expansão.","immediate":"Procure atendimento no mesmo dia se piorar."}},{"id":"rn-grave","label":"Suspeita infecciosa, lesão grave ou quadro sistêmico","when":"Vesículas suspeitas, púrpura, necrose, desprendimento ou bebê doente.","setting":"hospital","overrides":{"diagnosis":"Investigar imediatamente; HSV não depende de história materna positiva.","expected":"A evolução depende da causa e do atendimento precoce.","return":"Seguimento definido pela equipe após estabilização.","alarm":"Ausência de febre ou vesículas não exclui infecção.","immediate":"Hospital agora; não espere exames para buscar assistência."}},{"id":"rn-indefinido","label":"Lesão não classificada","when":"Diagnóstico incerto, sem critérios atuais de emergência.","setting":"urgent","overrides":{"diagnosis":"Solicite avaliação presencial; não testar produtos empiricamente.","expected":"Não há prazo seguro sem identificar a lesão.","return":"Revisão breve até esclarecimento diagnóstico.","alarm":"Progressão ou qualquer alteração sistêmica.","immediate":"Sinais de gravidade exigem hospital imediatamente."}}]},"revisedAt":"2026-09-27"},
{"name":"Amebíase intestinal","aliases":[],"setting":"home","general":"Use água segura, lave as mãos após evacuar ou trocar fraldas e antes de preparar alimentos. Mantenha hidratação adequada à tolerância.","diagnosis":"O diagnóstico deve distinguir Entamoeba histolytica de organismos semelhantes. Complete todas as etapas prescritas, mesmo quando os sintomas diminuírem.","expected":"A resposta depende da forma intestinal e da adesão ao tratamento. Persistência ou piora da diarreia exige revisão, não repetição automática da receita.","alarm":"Observe sangue nas fezes, febre, dor abdominal crescente, vômitos persistentes ou sinais de perda de líquidos.","immediate":"Procure pronto atendimento com dor intensa, prostração, incapacidade de beber ou sangramento intestinal importante.","return":"Retorne se os sintomas persistirem, para revisar o diagnóstico e os exames de fezes. Dor abdominal alta com febre também deve ser reavaliada por possível complicação.","sources":[{"url":"https://www.cdc.gov/amebiasis/about/index.html","title":"CDC — Amebiasis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Amigdalite estreptocócica","aliases":[],"setting":"home","general":"Ofereça líquidos frequentemente, alimentos macios conforme tolerância e repouso relativo. Higienize as mãos e evite compartilhar copos e talheres.","diagnosis":"Complete o tratamento prescrito para infecção estreptocócica confirmada; não reaproveite antibióticos nem interrompa ao melhorar. A aparência da garganta isoladamente não confirma a bactéria.","expected":"A melhora deve ser progressiva com tratamento adequado. Retorne à escola quando estiver sem febre e após pelo menos 12–24 horas de tratamento efetivo.","alarm":"Dor crescente, febre persistente, inchaço no pescoço, redução da ingestão ou nova piora merecem reavaliação.","immediate":"Procure emergência se houver dificuldade respiratória, incapacidade de engolir saliva, voz abafada importante ou prostração intensa.","return":"Reavalie se não houver melhora clínica ou se surgirem sintomas novos; comunique reações ao tratamento.","sources":[{"url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html","title":"CDC — Clinical Guidance for Group A Streptococcal Pharyngitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Anafilaxia alimentar","aliases":[],"setting":"hospital","general":"Anafilaxia é emergência. Acione socorro e siga imediatamente o plano de resgate já prescrito; não aguarde exames ou o aparecimento de manchas na pele.","diagnosis":"Mantenha a criança deitada; se a respiração dificultar essa posição, ajuste com apoio e pernas estendidas. Não a deixe levantar ou caminhar.","expected":"Pode haver melhora rápida seguida de nova reação; é necessária avaliação e observação em serviço de saúde.","alarm":"Inchaço de língua ou garganta, rouquidão, falta de ar, palidez, moleza e desmaio são sinais graves.","immediate":"Qualquer dificuldade respiratória ou circulatória exige atendimento emergencial imediato, mesmo sem urticária.","return":"Após estabilização, organize alergologia, identificação do alimento, plano escrito e treinamento de família e escola.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/anaphylaxis/","title":"RCH — Anaphylaxis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Anafilaxia por medicamentos","aliases":[],"setting":"hospital","general":"Anafilaxia é uma emergência. Interrompa a exposição suspeita e acione atendimento; se houver dispositivo de resgate previamente prescrito, use conforme treinamento, sem atrasar o socorro.","diagnosis":"Reações a medicamentos podem comprometer respiração e circulação rapidamente, mesmo sem lesões evidentes na pele. Informe o medicamento e o momento da administração à equipe.","expected":"Mesmo após melhora inicial é necessária avaliação e observação hospitalar; a duração é determinada pelo quadro e pela resposta ao tratamento.","alarm":"Voz rouca, aperto na garganta, chiado, tontura e inchaço súbito indicam possível agravamento.","immediate":"Falta de ar, desmaio, coloração azulada ou criança sem resposta: SAMU 192 imediatamente.","return":"Após alta, revise o plano de emergência, o registro da alergia e o encaminhamento ao especialista; não reutilize o medicamento suspeito sem avaliação.","sources":[{"url":"https://www.nhs.uk/conditions/anaphylaxis/","title":"NHS — Anaphylaxis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Ancilostomíase","setting":"home","general":"Infecção intestinal por vermes que pode causar perda crônica de sangue. A transmissão ocorre quando larvas presentes no solo contaminado penetram a pele, frequentemente ao andar descalço.","diagnosis":"Use calçados e evite contato da pele com solo contaminado. Saneamento e higiene ajudam a prevenir nova infecção. Cumpra os exames e a avaliação de anemia indicados.","expected":"A resposta varia com a carga de vermes e a presença de anemia ou deficiência nutricional. O cansaço pode melhorar gradualmente; reinfecção é possível se a exposição continuar.","alarm":"Atenda rapidamente palidez intensa, desmaio, falta de ar, fraqueza marcada, dor abdominal intensa, vômitos persistentes ou desidratação.","immediate":"Procure unidade de saúde para confirmação e cuidado. Use calçados, saneamento adequado e evite contato da pele com solo possivelmente contaminado; não se automedique.","return":"Retorne conforme orientação para revisar o exame, sintomas e anemia. Reavalie sem melhora, com perda de peso ou recorrência.","sources":[{"url":"https://www.cdc.gov/sth/about/hookworm.html","title":"CDC — About Hookworm","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Anemia aplásica adquirida","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com hematologia e o calendário individual de exames. Informe todos os medicamentos e episódios de infecção ou sangramento.","diagnosis":"A redução das células sanguíneas pode comprometer defesa contra infecção, coagulação e transporte de oxigênio. A gravidade deve orientar cuidados e tratamento especializado.","expected":"A evolução varia conforme intensidade da falência da medula e resposta ao tratamento; não há prazo único de recuperação.","alarm":"Observe palidez crescente, cansaço, manchas roxas, pontos avermelhados, sangramento gengival ou nasal e palpitações.","immediate":"Febre ou sangramento que não cessa exigem avaliação imediata; falta de ar importante, desmaio ou piora abrupta também.","return":"Não aguarde a próxima consulta diante desses sinais. Compareça às revisões mesmo em períodos sem sintomas e peça um plano escrito de urgência à equipe.","sources":[{"url":"https://www.niddk.nih.gov/health-information/blood-diseases/aplastic-anemia-myelodysplastic-syndromes/symptoms-causes","title":"NIDDK — Aplastic anemia: symptoms and causes","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Anemia da prematuridade","aliases":[],"setting":"specialist","general":"Mantenha o acompanhamento do prematuro e leve registros de alimentação, crescimento, exames e tratamentos recebidos durante a internação.","diagnosis":"A queda de hemoglobina pode ser mais precoce no prematuro. A conduta considera idade, sintomas e suporte respiratório; o resultado isolado não determina transfusão.","expected":"A evolução é acompanhada por avaliações seriadas; não se deve confundir automaticamente anemia da prematuridade com deficiência de ferro.","alarm":"Avise a equipe se surgirem palidez acentuada, piora das mamadas, cansaço, menor ganho de peso ou mais pausas respiratórias.","immediate":"Pausas respiratórias, coloração azulada, dificuldade importante para respirar ou pouca resposta aos estímulos exigem emergência imediata.","return":"Compareça às avaliações e coletas programadas; não inicie nem suspenda suplementação ou tratamento sem ajuste pelo neonatologista.","sources":[{"url":"https://www.rch.org.au/bloodtrans/special_transfusions/Neonatal_transfusions/","title":"RCH — Neonatal transfusions","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Anemia de Diamond-Blackfan","setting":"specialist","aliases":["Diamond-Blackfan"],"general":"Doença da produção de células vermelhas exige hematologia e avaliação de outras alterações associadas.","diagnosis":"Cumpra os exames e o plano individual; não presuma deficiência nutricional nem acrescente suplementação por conta própria.","expected":"A gravidade varia, inclusive na mesma família. O acompanhamento é prolongado, com vigilância de anemia e outras complicações.","alarm":"Palidez crescente, cansaço intenso, palpitações ou dificuldade para mamar precisam de avaliação.","immediate":"Desmaio, falta de ar importante ou redução de consciência exigem emergência.","return":"Mantenha seguimento hematológico e genético, mesmo quando a anemia estiver controlada; sintomas novos requerem revisão.","sources":[{"url":"https://medlineplus.gov/genetics/condition/diamond-blackfan-anemia/","title":"MedlinePlus Genetics — Diamond-Blackfan anemia","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Anemia de Fanconi","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com hematologia e as demais especialidades indicadas. Leve resultados e informe a condição em qualquer atendimento.","diagnosis":"A anemia de Fanconi pode reduzir diferentes células do sangue e aumentar riscos de infecção, sangramento e câncer; não é a mesma doença que síndrome renal de Fanconi.","expected":"A evolução depende das contagens sanguíneas e das complicações. Mesmo após tratamento da medula, a vigilância prolongada continua necessária.","alarm":"Observe palidez acentuada, cansaço crescente, febre, feridas persistentes e novos sangramentos.","immediate":"Febre com neutropenia conhecida, falta de ar, desmaio ou hemorragia exigem avaliação imediata.","return":"Realize hemogramas e rastreamentos no calendário da equipe; peça orientação sobre vacinas, saúde bucal e aconselhamento genético.","sources":[{"url":"https://medlineplus.gov/ency/article/000334.htm","title":"MedlinePlus — Fanconi anemia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Anemia falciforme (SC)","aliases":[],"setting":"specialist","general":"Mantenha hidratação habitual, sono adequado, vacinação e os tratamentos prescritos. Leve o resumo do diagnóstico aos atendimentos e tenha um plano escrito para dor e intercorrências.","diagnosis":"A doença falciforme HbSC também pode apresentar complicações; o plano deve respeitar o genótipo, o histórico e as orientações da hematologia, sem copiar automaticamente o esquema de HbSS.","expected":"O acompanhamento é contínuo. Períodos sem sintomas não dispensam prevenção e avaliações programadas, incluindo possíveis alterações dos órgãos.","alarm":"Febre, dor que não melhora com o plano habitual, cansaço fora do padrão ou redução da ingestão exigem contato rápido.","immediate":"Falta de ar, dor no peito, alteração neurológica ou desmaio: procure emergência imediatamente.","return":"Retorne à hematologia conforme o plano individual e antecipadamente após crises ou novos sintomas.","sources":[{"url":"https://www.nhlbi.nih.gov/health/sickle-cell-disease/living-with","title":"NHLBI — Living With Sickle Cell Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Fonte de doença falciforme geral; medidas específicas de HbSC e indicação de medicamentos não foram extrapoladas.","status":"source-reviewed"},
{"name":"Anemia falciforme (SS)","setting":"specialist","general":"Doença hereditária em que a hemoglobina S altera o formato das hemácias, causando anemia e obstrução de vasos. Exige acompanhamento contínuo e plano individual.","diagnosis":"Mantenha hidratação habitual, vacinação, consultas e plano individual para dor e febre. Avise a equipe diante de infecção e leve informações do acompanhamento aos atendimentos de urgência.","expected":"É uma condição crônica, com crises e complicações de intensidade variável. Acompanhamento regular reduz riscos; melhora de uma crise não elimina a necessidade de vigilância.","alarm":"É urgência: febre, dor intensa ou persistente, dificuldade respiratória, dor no peito, fraqueza súbita, confusão, convulsão, palidez extrema ou aumento súbito do abdome.","immediate":"Na crise, procure serviço de saúde imediatamente; ofereça líquidos se a pessoa estiver alerta e conseguir beber, sem atrasar o atendimento. Leve o plano de cuidados.","return":"Mantenha consultas regulares com hematologia e atenção primária, vacinas e avaliações programadas. Retorne antes se a dor aumentar, febre surgir ou houver mudança neurológica.","sources":[{"url":"https://www.cdc.gov/sickle-cell/about/index.html","title":"CDC — About Sickle Cell Disease","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":["Anemia Falciforme em Pediatria"],"status":"source-reviewed"},
{"name":"Anemia ferropriva","aliases":[],"setting":"home","general":"Inclua alimentos ricos em ferro apropriados à idade e evite que o leite substitua as refeições. Guarde suplementos fora do alcance das crianças.","diagnosis":"Use o tratamento prescrito e confirme a quantidade de ferro elementar. Fezes mais escuras e constipação podem ocorrer; não dobre doses por conta própria.","expected":"A recuperação das reservas leva mais tempo que a melhora da anemia. O tratamento e os exames devem continuar pelo período definido na consulta.","alarm":"Observe piora da palidez, cansaço desproporcional, pouca disposição para mamar/comer ou intolerância ao tratamento.","immediate":"Procure atendimento se houver desmaio, falta de ar em repouso, grande prostração ou suspeita de ingestão excessiva do suplemento.","return":"Reavalie com hemograma e reservas de ferro; anemia grave requer revisão precoce. Falta de resposta exige conferir adesão e outras causas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Iron_deficiency/","title":"RCH — Iron deficiency","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Anemia Neonatal","aliases":[],"setting":"specialist","general":"Mantenha seguimento neonatal e informe prematuridade, sangramentos e intercorrências. Compareça aos exames solicitados.","diagnosis":"Anemia tem várias causas no recém-nascido. Necessidade de transfusão ou suplementação depende da condição clínica e dos exames.","expected":"A evolução varia com a causa, maturidade e doenças associadas; não existe um prazo único de recuperação.","alarm":"Observe palidez crescente, pouca disposição ou dificuldade para alimentar-se.","immediate":"Dificuldade respiratória, redução importante da resposta ou piora rápida exige emergência.","return":"Após alta, cumpra o plano de monitorização. Não inicie suplementos por conta própria nem interprete um valor isolado sem a equipe.","sources":[{"url":"https://www.cuh.nhs.uk/patient-information/will-my-baby-need-a-blood-transfusion/","title":"Cambridge University Hospitals — Will my baby need a blood transfusion?","accessed":"2026-09-26"},{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/general-medical-conditions/anaemia/","title":"GOSH — Anaemia","accessed":"2026-09-26"}],"reviewNotes":"Fonte neonatal para causas e decisão transfusional; sinais gerais de anemia complementados por material pediátrico GOSH. Sem critérios laboratoriais ou terapêuticos automáticos.","status":"source-reviewed"},
{"name":"Anemias Carenciais em Pediatria","aliases":["Anemias carenciais","Anemia nutricional"],"setting":"specialist","general":"Mantenha alimentação variada e a reposição especificamente prescrita. Guarde suplementos fora do alcance das crianças e não substitua refeições por excesso de leite.","diagnosis":"É necessário identificar a deficiência; ferro, folato e vitamina B12 não são intercambiáveis e podem coexistir outras causas.","expected":"A resposta é acompanhada por sintomas e exames; reposição pode continuar após melhora da hemoglobina.","alarm":"Relate intolerância ao tratamento, palidez crescente, perda de peso ou alterações do desenvolvimento.","immediate":"Falta de ar em repouso, desmaio, prostração importante ou sangramento exigem emergência.","return":"Retorne para confirmar resposta e corrigir a causa nutricional ou de absorção.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/iron_deficiency/","title":"Royal Children’s Hospital — Iron deficiency","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Micronutrient_deficiency/","title":"Royal Children’s Hospital — Micronutrient deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Angioedema hereditário","aliases":[],"setting":"specialist","general":"Tenha sempre disponível o plano individual de crise e informe o diagnóstico antes de procedimentos médicos ou odontológicos. Identifique os gatilhos já reconhecidos pela família.","diagnosis":"O inchaço hereditário pode atingir pele, intestino e garganta e não deve ser tratado como uma alergia comum. A equipe definirá prevenção e tratamento específico.","expected":"As crises podem repetir e sua intensidade varia; melhora de episódios anteriores não garante que uma nova crise seja leve.","alarm":"Dor abdominal intensa, vômitos, inchaço progressivo da face ou dificuldade para se alimentar precisam de avaliação rápida.","immediate":"Alteração da voz, ruído ao respirar, língua inchada ou dificuldade respiratória são emergência: acione ajuda imediatamente.","return":"Após crise, reveja o plano com imunologia e organize avaliação familiar quando indicada.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hereditary_angioedema_(C1-esterase_inhibitor_deficiency)/","title":"RCH — Hereditary angioedema","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Fonte aborda deficiência de C1-inibidor; outros mecanismos requerem individualização.","status":"source-reviewed"},
{"name":"Anomalia anorretal tipo fístula perineal","aliases":[],"setting":"specialist","general":"Faça seguimento com cirurgia pediátrica/coloproctologia. Observe evacuações, distensão abdominal, alimentação e crescimento, registrando mudanças.","diagnosis":"A fístula perineal é um subtipo de malformação anorretal; a anatomia e anomalias associadas definem o tratamento. Não realize dilatações, enemas ou manipulação sem treinamento da equipe.","expected":"O controle intestinal e a necessidade de cirurgia ou acompanhamento variam. Constipação pode persistir e requerer plano individual.","alarm":"Redução da eliminação de fezes, barriga progressivamente inchada, dor ou dificuldade para alimentar precisam de avaliação.","immediate":"Vômito verde, distensão importante, prostração ou impossibilidade de evacuar com piora clínica exigem urgência.","return":"Retorne para avaliação anatômica e plano intestinal; após cirurgia, siga as orientações específicas da alta.","sources":[{"url":"https://www.chop.edu/conditions-diseases/imperforate-anus-anorectal-malformation","title":"CHOP — Imperforate Anus/Anorectal Malformation","accessed":"2026-09-26"}],"reviewNotes":"Fonte abrange malformações anorretais e lesões baixas; não presume necessidade de colostomia para toda fístula perineal.","status":"source-reviewed"},
{"name":"Anomalia de Ebstein","aliases":["Anomalia de Ebstein em Pediatria"],"setting":"specialist","general":"Mantenha acompanhamento cardiológico e leve os exames a todas as consultas. Atividade física e rotina escolar devem seguir a capacidade da criança e a orientação da equipe.","diagnosis":"A anomalia de Ebstein afeta a válvula tricúspide e pode provocar arritmias ou dificuldade de bombeamento do coração. O tratamento varia conforme os sintomas e a anatomia.","expected":"Algumas crianças têm poucos sintomas; outras necessitam intervenções. Não há evolução única nem prazo de melhora que se aplique a todos.","alarm":"Observe cansaço progressivo, respiração acelerada, palpitações, piora para alimentar-se ou mudança da cor dos lábios.","immediate":"Falta de ar importante, desmaio, coloração azulada nova ou palpitações com mal-estar: emergência.","return":"Mantenha os retornos de cardiologia e antecipe a avaliação quando houver perda de capacidade para atividades habituais.","sources":[{"url":"https://medlineplus.gov/ency/article/007321.htm","title":"MedlinePlus — Ebstein anomaly","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Anomalias de Artérias Coronárias","setting":"specialist","aliases":["Anomalia coronariana congênita"],"general":"Alterações da origem ou do trajeto das coronárias têm riscos diferentes e precisam ser caracterizadas pela cardiologia.","diagnosis":"Restrições esportivas e necessidade de intervenção dependem da anatomia. Não retome exercício intenso sem a orientação da equipe.","expected":"Algumas alterações permanecem estáveis; outras comprometem a irrigação cardíaca e precisam de tratamento especializado.","alarm":"Dor torácica ao esforço, palpitações, tontura ou piora alimentar em bebês são alarmes.","immediate":"Desmaio durante exercício ou dor torácica com falta de ar exige emergência.","return":"Mantenha seguimento, inclusive após cirurgia; sintomas novos precisam de reavaliação.","sources":[{"url":"https://www.hopkinsmedicine.org/health/conditions-and-diseases/anomalous-coronary-artery-in-children","title":"Johns Hopkins — Anomalous Coronary Artery in Children","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Anticoagulação em Pediatria","setting":"specialist","aliases":["Terapia anticoagulante pediátrica"],"general":"Anticoagulação é uma estratégia de tratamento ou prevenção de trombose e requer indicação individual.","diagnosis":"Siga horários, técnica e exames do plano prescrito. Informe uso antes de procedimentos e consulte a equipe antes de qualquer novo produto.","expected":"A duração e a monitorização dependem da indicação, do medicamento e do risco de sangramento.","alarm":"Sangramento persistente, sangue na urina ou fezes, hematomas extensos e trauma craniano são alarmes.","immediate":"Sangramento importante, cefaleia súbita intensa ou alteração de consciência exigem emergência.","return":"Mantenha seguimento de hematologia; dúvidas, doses esquecidas e procedimentos precisam de orientação específica.","sources":[{"url":"https://www.rch.org.au/haematology/anticoagulaton_service/clexane-guidelines/","title":"RCH — Low Molecular Weight Heparin Guidelines","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Capítulo de procedimento/terapia, não diagnóstico. Fonte aberta refere-se a heparina de baixo peso molecular; síntese limitada a acompanhamento e reconhecimento de sangramento. Técnica, exames e duração dependem do anticoagulante prescrito. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Apneia da prematuridade","setting":"hospital","general":"Pausas respiratórias são comuns em prematuros por imaturidade do controle respiratório. A equipe observa respiração, frequência cardíaca e oxigenação continuamente.","diagnosis":"Durante a internação, acompanhe as orientações sobre manuseio e alimentação. Antes da alta, peça treinamento para reconhecer eventos e seguir o plano de emergência e sono seguro fornecido pela unidade.","expected":"Os episódios tendem a diminuir com a maturação. A alta depende de estabilidade clínica e de um período sem eventos clinicamente relevantes, conforme o protocolo da unidade.","alarm":"Durante internação, alarme do monitor, pausa prolongada, coloração azulada, flacidez ou necessidade repetida de estímulo exigem avaliação imediata da equipe.","immediate":"Acione imediatamente a equipe da UTI neonatal; não ofereça nada por via oral nem tente intervir além das orientações recebidas.","return":"Após a alta, cumpra o seguimento neonatal/pediátrico e procure urgência se houver pausas, dificuldade para respirar, cianose ou redução importante da responsividade.","sources":[{"url":"https://medlineplus.gov/ency/article/007227.htm","title":"MedlinePlus — Apnea of prematurity","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Arboviroses: Dengue, Zika e Chikungunya","aliases":["Arboviroses"],"setting":"home","general":"Após classificação de risco, siga o plano de hidratação e repouso e evite picadas. Não se automedique; suspeita de dengue exige revisão dos produtos utilizados.","diagnosis":"Dengue, Zika e chikungunya podem se parecer, mas têm complicações e acompanhamento diferentes.","expected":"Na dengue, piora pode surgir quando a febre baixa; dores articulares da chikungunya podem persistir. Zika exige atenção a sintomas neurológicos.","alarm":"Observe vômitos persistentes, dor abdominal intensa, sangramento, tontura ou redução da urina.","immediate":"Desmaio, falta de ar, fraqueza progressiva ou alteração da consciência exigem emergência.","return":"Cumpra reavaliações e retorne antes se aparecer qualquer alarme.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/dengue","title":"Ministério da Saúde — Dengue","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/z/zika-virus","title":"Ministério da Saúde — Zika vírus","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/c/chikungunya","title":"Ministério da Saúde — Chikungunya","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Não é diagnóstico etiológico único. Gestação, exposição congênita, comorbidades e sinais de gravidade exigem fluxos específicos.","status":"source-reviewed"},
{"name":"Arterite de Takayasu em Pediatria","setting":"specialist","aliases":["Arterite de Takayasu"],"general":"Inflamação das grandes artérias requer acompanhamento prolongado para proteger circulação e órgãos.","diagnosis":"Cumpra consultas e exames de imagem. Informe diferença de força, dor nos membros ao esforço ou dificuldades para medir a pressão.","expected":"A atividade pode oscilar; estreitamentos já formados podem persistir mesmo após controle da inflamação.","alarm":"Nova dor torácica, falta de ar, desmaio ou membro frio e doloroso são alarmes.","immediate":"Fraqueza súbita, alteração da fala ou perda visual exigem emergência imediata.","return":"Retorne conforme reumatologia e cardiologia; antecipe avaliação diante de novos sintomas ou pressão fora das metas individuais.","sources":[{"url":"https://rheumatology.org/patients/takayasu-arteritis","title":"ACR — Takayasu Arteritis","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Artrite Idiopática Juvenil","aliases":["AIJ"],"setting":"specialist","general":"Mantenha reumatologia pediátrica e reabilitação orientada. Observe dor, rigidez e participação nas atividades.","diagnosis":"É um conjunto de doenças; o subtipo determina riscos, tratamento e necessidade de avaliações oculares.","expected":"Pode alternar períodos de atividade e controle. A resposta e a duração variam entre crianças.","alarm":"Avise sobre articulação mais quente ou inchada, limitação nova, febre ou sintomas oculares.","immediate":"Febre com prostração intensa, deterioração rápida ou perda visual exige avaliação urgente.","return":"Cumpra consultas e exames, inclusive oculares quando indicados, mesmo sem queixas; não altere tratamento sozinho.","sources":[{"url":"https://www.niams.nih.gov/health-topics/juvenile-arthritis","title":"NIAMS — Juvenile arthritis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Artrite idiopática juvenil oligoarticular","aliases":["AIJ oligoarticular"],"setting":"specialist","general":"Mantenha consultas com reumatologia e registre rigidez ao despertar, inchaço e limitações para brincar ou caminhar.","diagnosis":"As avaliações oftalmológicas devem ocorrer mesmo sem sintomas, pois a inflamação ocular pode ser silenciosa. Não suspenda o acompanhamento quando as articulações melhorarem.","expected":"Pode haver períodos de atividade e remissão. Duração e extensão variam; o controle precoce reduz risco de lesões e alterações do crescimento.","alarm":"Observe novas articulações inchadas, rigidez crescente, mancar, redução dos movimentos ou mudanças na visão.","immediate":"Olho doloroso, vermelhidão ocular intensa, perda visual ou febre com articulação muito dolorosa exigem avaliação urgente.","return":"Antecipe a revisão se as atividades diárias piorarem. O reumatologista e o oftalmologista devem definir juntos o calendário de seguimento e a adaptação das atividades.","sources":[{"url":"https://www.niams.nih.gov/health-topics/juvenile-arthritis","title":"NIAMS — Juvenile idiopathic arthritis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Artrite idiopática juvenil poliarticular IgF negativo","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento reumatológico, atividade adaptada e fisioterapia conforme a capacidade. Não interrompa o tratamento por melhora aparente.","diagnosis":"O termo “IgF negativo” precisa ser esclarecido: a classificação publicada usa fator reumatoide (FR). Não presumir equivalência.","expected":"Podem ocorrer remissões e recaídas; não há prazo único de cura.","alarm":"Nova limitação, articulação muito quente, febre ou sintomas oculares exigem avaliação.","immediate":"Perda visual, dor ocular intensa ou criança prostrada com articulação dolorosa exigem urgência.","return":"Programe revisões articulares, crescimento, segurança do tratamento e avaliação oftalmológica, mesmo sem sintomas.","sources":[{"url":"https://www.niams.nih.gov/health-topics/juvenile-arthritis","title":"NIAMS — Juvenile arthritis: tipos, sintomas e seguimento","accessed":"2026-09-27"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10127939/","title":"ACR — Guideline 2021: cuidados não farmacológicos, monitorização e imunizações na AIJ (2022)","accessed":"2026-09-27"},{"url":"https://assets.contentstack.io/v3/assets/bltee37abb6b278ab2c/blta0e2b20e80959923/63321f52eb66820cfba10a44/jia-uveitis-guideline-2019.pdf","title":"ACR/Arthritis Foundation — Screening, monitoring and treatment of JIA-associated uveitis (2019)","accessed":"2026-09-27"}],"reviewNotes":"Nome original preservado; lacuna resolvida por confirmação obrigatória de subtipo, sem renomeação automática. Escopo: orientação, seguimento e detecção de complicações; não seleção farmacológica. Revisão documental assistida, sem homologação humana.","status":"source-reviewed","evidenceSummary":"Diretrizes ACR com revisão sistemática/GRADE e informação NIAMS para AIJ pediátrica. Muitas recomendações têm evidência baixa ou muito baixa e consenso especializado; intervalos oculares dependem do risco individual. Rótulo “IgF” não é critério classificatório nas fontes.","decisionSupport":{"summary":"Confirmar nomenclatura e subtipo antes de aplicar orientação específica; rastreamento ocular não depende de sintomas.","requirements":["Diagnóstico reumatológico e resultado do FR","Número de articulações nos primeiros seis meses","Idade de início, duração e ANA","Uveíte, atividade atual e tratamento"],"branchRequired":true,"branches":[{"id":"aij-fr-confirmado","label":"AIJ poliarticular FR negativo confirmada","when":"Reumatologista confirma subtipo: cinco ou mais articulações nos primeiros seis meses e FR negativo.","setting":"specialist","overrides":{"diagnosis":"Mantenha plano articular e rastreamento ocular estratificado por idade, ANA e duração.","expected":"Controle e função variam; uveíte pode ser silenciosa.","return":"ANA positivo, início antes de sete anos e duração até quatro anos: rastreamento trimestral. Outros riscos: seis a doze meses; uveíte exige calendário próprio.","alarm":"Dor, fotofobia ou vermelhidão ocular precisam de avaliação.","immediate":"Perda visual ou dor ocular intensa exigem urgência."}},{"id":"aij-subtipo-pendente","label":"Subtipo ou nomenclatura pendente","when":"“IgF” não esclarecido ou critérios de classificação não confirmados.","setting":"specialist","overrides":{"diagnosis":"Confirme o laudo; não atribua automaticamente FR negativo nem descarte outras causas.","expected":"Prognóstico depende do diagnóstico e da atividade.","return":"Reumatologia para classificação e calendário ocular individual.","alarm":"Febre e articulação muito dolorosa exigem excluir infecção.","immediate":"Prostração com febre ou incapacidade súbita de apoiar exige urgência."}}]},"revisedAt":"2026-09-27"},
{"name":"Artrite idiopática juvenil sistêmica","aliases":[],"setting":"specialist","general":"Mantenha tratamento e consultas com reumatologia pediátrica. Incentive atividade adaptada, descanso, alimentação e participação escolar conforme tolerância.","diagnosis":"A forma sistêmica pode afetar articulações e outros órgãos. Febre nova ou persistente deve ser discutida com a equipe, especialmente durante tratamento que altera a imunidade.","expected":"Pode alternar atividade e remissão; a melhora não autoriza suspensão por conta própria. Crescimento e possíveis efeitos do tratamento precisam de monitorização.","alarm":"Observe piora geral, febre contínua, novos sangramentos, dificuldade respiratória e dor intensa.","immediate":"Prostração importante, alteração de consciência, falta de ar ou sangramento exigem emergência.","return":"Antecipe revisão se houver perda funcional ou retorno da febre; mantenha exames e avaliações indicadas pelo subtipo.","sources":[{"url":"https://www.niams.nih.gov/health-topics/juvenile-arthritis","title":"NIAMS — Juvenile Idiopathic Arthritis","accessed":"2026-09-26"},{"url":"https://www.niams.nih.gov/health-topics/juvenile-arthritis/diagnosis-treatment-and-steps-to-take","title":"NIAMS — JIA: Diagnosis, Treatment and Steps to Take","accessed":"2026-09-26"}],"reviewNotes":"Rascunho para AIJ sistêmica; sinais de doença sistêmica grave exigem investigação, não diagnóstico automático de ativação macrofágica.","status":"source-reviewed"},
{"name":"Artrite séptica","aliases":["Artrite Séptica em Pediatria"],"setting":"hospital","general":"A suspeita de artrite séptica precisa de avaliação hospitalar rápida. Evite forçar ou manipular a articulação dolorosa e informe febre, início da dor e dificuldade para apoiar o membro.","diagnosis":"É uma infecção da articulação que pode exigir drenagem e tratamento prolongado. O acompanhamento considera exame, temperatura e resultados laboratoriais; melhora da dor não autoriza interromper o tratamento.","expected":"A recuperação varia, e o tratamento precoce reduz o risco de lesão articular. A alta e o retorno às atividades são definidos pela equipe.","alarm":"Febre reaparecendo, aumento da dor, inchaço ou recusa de movimentar o membro exigem reavaliação.","immediate":"Prostração intensa, desmaio, falta de ar ou piora rápida: emergência imediata.","return":"Após alta, cumpra todas as doses prescritas e compareça à revisão ortopédica e aos exames solicitados.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Septic_arthritis/","title":"Royal Children’s Hospital — Septic arthritis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Artrite séptica do joelho","setting":"hospital","general":"É uma infecção dentro da articulação e pode lesar rapidamente cartilagem e osso. Joelho doloroso, inchado e com movimento limitado requer avaliação urgente.","diagnosis":"Evite apoiar ou movimentar o joelho contra a dor até orientação. Cumpra o tratamento hospitalar e as revisões ortopédicas; recuperação do movimento deve seguir o plano profissional.","expected":"Com tratamento hospitalar precoce, a dor, o inchaço e a limitação devem melhorar; são necessários reexames para acompanhar resposta e complicações.","alarm":"Febre, dor intensa, incapacidade de apoiar ou mover o joelho, aumento rápido do inchaço, prostração ou piora geral são sinais de emergência.","immediate":"Procure imediatamente uma emergência pediátrica; mantenha a criança em repouso e não force o movimento do joelho.","return":"Retorne conforme orientação para revisão clínica e laboratorial; volte antes se febre persistir, a dor piorar, surgir vermelhidão progressiva ou a criança não apoiar.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Bone_and_joint_infection/","title":"RCH — Bone and joint infection","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Artrite séptica do quadril","aliases":[],"setting":"hospital","general":"Trata-se de infecção que precisa de atendimento hospitalar e avaliação ortopédica urgente. Não force a criança a caminhar ou movimentar o quadril doloroso.","diagnosis":"O tratamento pode incluir coleta do líquido e drenagem da articulação, além de terapia sistêmica. Exames não devem atrasar a assistência à criança gravemente doente.","expected":"A melhora é acompanhada pela febre, dor, mobilidade e exames. O tempo de recuperação depende da resposta e de complicações associadas.","alarm":"Observe febre, recusa para apoiar a perna, dor crescente, abatimento ou piora do estado geral.","immediate":"Se ainda não está internada, encaminhe imediatamente ao pronto atendimento. Durante a internação, comunique qualquer piora à equipe.","return":"Após alta formal, retorne imediatamente se voltar a febre ou houver piora da dor/movimento; mantenha seguimento ortopédico e tratamento completo.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Bone_and_joint_infection/","title":"RCH — Bone and joint infection","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Ascaridíase","aliases":[],"setting":"home","general":"Lave as mãos antes de comer e após usar o banheiro. Higienize frutas e verduras e utilize água segura; evite contato com solo contaminado por fezes.","diagnosis":"Realize o tratamento indicado e leve ao serviço informações sobre vermes eliminados ou exames de fezes. Não repita vermífugos sem necessidade definida.","expected":"O tratamento costuma eliminar a infecção, mas pode haver nova exposição se as condições de higiene e saneamento não forem corrigidas.","alarm":"Dor abdominal persistente, vômitos, perda de peso ou tosse importante precisam de reavaliação.","immediate":"Dor abdominal intensa com barriga distendida, vômitos repetidos ou interrupção da eliminação de fezes e gases exige emergência por risco de obstrução.","return":"Retorne se os sintomas persistirem e acompanhe alimentação, crescimento e necessidade de controle parasitológico individual.","sources":[{"url":"https://www.cdc.gov/sth/about/ascariasis.html","title":"CDC — About Ascariasis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Asfixia neonatal grave","aliases":[],"setting":"hospital","general":"O recém-nascido necessita de cuidado neonatal hospitalar, monitorização e suporte conforme a avaliação da equipe. Não se trata de condição para cuidado domiciliar inicial.","diagnosis":"A falta de oxigênio ao nascimento pode comprometer cérebro e outros órgãos. A equipe avalia precocemente indicação de terapias específicas e exames.","expected":"A evolução varia conforme gravidade, exame neurológico e exames complementares; não é possível prometer recuperação sem sequelas.","alarm":"Informe imediatamente pausas respiratórias, movimentos incomuns, rigidez, flacidez, sucção fraca ou pouca resposta.","immediate":"Na presença desses sinais fora do hospital, acione emergência imediatamente; não tente resfriar o bebê em casa.","return":"Após alta, mantenha seguimento de desenvolvimento, alimentação, audição, visão e neurologia conforme plano neonatal.","sources":[{"url":"https://www.nlg.nhs.uk/resources/hypoxic-ischaemic-encephalopathy-hie/","title":"NHS — Hypoxic-ischaemic encephalopathy","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Asfixia neonatal leve","aliases":[],"setting":"hospital","general":"O recém-nascido precisa de avaliação e observação pela equipe neonatal. Informe alterações de sucção, resposta aos estímulos, respiração ou movimentos; a expressão “leve” não dispensa vigilância.","diagnosis":"Asfixia ao nascimento e encefalopatia não são termos automaticamente equivalentes. A equipe verifica sinais neurológicos e de outros órgãos para confirmar o quadro e sua gravidade.","expected":"Muitos quadros leves evoluem bem, mas o prognóstico depende da avaliação repetida. Não é possível garantir ausência de consequências apenas pelo rótulo inicial.","alarm":"Dificuldade para mamar, sonolência excessiva, irritabilidade incomum, flacidez ou rigidez devem ser comunicadas imediatamente.","immediate":"Pausas respiratórias, convulsões, coloração azulada ou pouca resposta exigem atendimento emergencial.","return":"Após alta autorizada, siga o acompanhamento de crescimento e desenvolvimento e antecipe o retorno se surgirem dificuldades.","sources":[{"url":"https://www.nlg.nhs.uk/resources/hypoxic-ischaemic-encephalopathy-hie/","title":"Northern Lincolnshire and Goole NHS — Hypoxic-ischaemic encephalopathy","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Fonte de encefalopatia hipóxico-isquêmica; orientação limitada à vigilância após evento hipóxico, sem equiparar asfixia leve a diagnóstico confirmado de encefalopatia.","status":"source-reviewed"},
{"name":"Asfixia neonatal moderada","setting":"hospital","general":"Refere-se a comprometimento da oxigenação e circulação ao redor do nascimento, com possível lesão cerebral hipóxico-isquêmica. Requer estabilização e monitorização especializada.","diagnosis":"Participe das orientações da equipe neonatal sobre alimentação, posicionamento e sinais de crise. Antes da alta, confirme o plano de seguimento e encaminhamentos para desenvolvimento, audição e visão.","expected":"A evolução varia. Bebês com quadro moderado precisam de observação estreita, avaliação neurológica seriada e seguimento do desenvolvimento, pois sequelas podem aparecer depois.","alarm":"Convulsões, alteração persistente de consciência, dificuldade respiratória, hipotonia, alimentação insegura ou redução de movimentos exigem avaliação imediata.","immediate":"Acione a equipe neonatal imediatamente. Após a alta, leve o bebê à emergência diante de convulsão, apneia, cianose ou dificuldade para despertar.","return":"Mantenha todas as consultas de neurologia, pediatria e desenvolvimento; retorne precocemente se houver regressão, atraso, problemas de alimentação ou tônus anormal.","sources":[{"url":"https://www.nlg.nhs.uk/resources/hypoxic-ischaemic-encephalopathy-hie/","title":"NHS Northern Lincolnshire and Goole — Hypoxic-ischaemic encephalopathy","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Asfixia perinatal","aliases":[],"setting":"hospital","general":"O recém-nascido necessita de avaliação neonatal e monitorização hospitalar. A equipe deve acompanhar respiração, circulação, alimentação e função neurológica.","diagnosis":"Quando existe lesão por falta de oxigênio, medidas especializadas podem ser dependentes do tempo. Não tente resfriar ou aquecer o bebê por conta própria.","expected":"O prognóstico depende da intensidade da lesão, exames e evolução durante os primeiros dias. A aparência inicial isolada não define o desenvolvimento futuro.","alarm":"Comunique pausas respiratórias, movimentos repetitivos incomuns, alteração da cor, pouca resposta ou dificuldade para mamar.","immediate":"Se estiver fora do hospital e apresentar esses sinais, procure emergência imediatamente; dentro da unidade, chame a equipe sem demora.","return":"Após a alta, mantenha o acompanhamento de desenvolvimento e reabilitação indicado. Alterações de alimentação, movimentos ou aquisição de habilidades devem antecipar a revisão.","sources":[{"url":"https://www.rch.org.au/rchcpg/hospital_clinical_guideline_index/Therapeutic_hypothermia_in_the_neonate/","title":"RCH — Therapeutic hypothermia in the neonate","accessed":"2026-09-26"}],"reviewNotes":"A fonte trata encefalopatia hipóxico-isquêmica e cuidados neonatais; não presume que toda asfixia preencha critérios de hipotermia. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Asma atópica","aliases":[],"setting":"specialist","general":"Mantenha a casa e o carro sem fumaça e evite os gatilhos alérgicos conhecidos. Leve os dispositivos de inalação às consultas para conferir a técnica.","diagnosis":"Siga o plano escrito de controle e de crise. Tosse isolada não confirma crise de asma; a avaliação inclui esforço respiratório e resposta ao tratamento.","expected":"O controle pode permitir atividades habituais, mas crises podem ocorrer durante infecções ou exposições; sintomas noturnos frequentes indicam controle inadequado.","alarm":"Observe piora do chiado, maior necessidade de tratamento de alívio, sono interrompido ou limitação para brincar.","immediate":"Procure emergência se não conseguir falar normalmente, houver esforço intenso, lábios azulados, exaustão ou pouca resposta ao plano de crise.","return":"Reavalie após exacerbações e nas consultas programadas para ajustar controle, adesão e técnica.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Asthma/","title":"RCH — Asthma","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Asma em Pediatria (Ambulatório)","aliases":["Asma ambulatorial"],"setting":"home","general":"Siga o plano escrito de asma e revise técnica dos dispositivos com a equipe. Evite fumaça e gatilhos identificados.","diagnosis":"O controle é avaliado pelos sintomas, sono, atividade e necessidade de alívio; ausência de chiado não basta para avaliar uma crise.","expected":"O controle pode variar ao longo do tempo e requer revisões, mesmo quando a criança está bem.","alarm":"Avise se houver sintomas noturnos, limitação de atividades ou necessidade crescente de alívio.","immediate":"Dificuldade respiratória intensa ou piora apesar do plano de crise exige emergência.","return":"Após crise, faça reavaliação precoce e ajuste orientado do plano.","sources":[{"url":"https://www.nhs.uk/conditions/asthma/","title":"NHS — Asthma","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Asma em Pediatria (Hospitalar)","aliases":[],"setting":"hospital","general":"Durante a crise, informe tratamentos já administrados, internações anteriores e possíveis gatilhos; mantenha a criança acompanhada pela equipe.","diagnosis":"Asma com necessidade hospitalar exige reavaliações de esforço respiratório, oxigenação, capacidade de falar ou alimentar-se e resposta ao tratamento.","expected":"A melhora precisa ser sustentada antes da alta; a ausência de chiado não garante que a crise terminou.","alarm":"Cansaço crescente, dificuldade para falar, alimentação comprometida ou redução dos sons respiratórios são preocupantes.","immediate":"Sonolência, confusão, coloração azulada ou exaustão requerem intervenção imediata da equipe.","return":"Antes da alta, confirme plano escrito, técnica inalatória e retorno clínico.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Asthma_Acute/","title":"RCH — Acute asthma","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Asma não atópica","aliases":[],"setting":"specialist","general":"Mantenha um plano escrito de asma e treine a técnica do dispositivo inalatório. Evite fumaça e vapor de cigarros; identifique gatilhos pessoais.","diagnosis":"A ausência de alergia não elimina a possibilidade de asma. Infecções, exercício e irritantes também podem desencadear sintomas.","expected":"Com controle adequado, a criança costuma participar das atividades; sintomas e necessidade de tratamento variam ao longo do tempo.","alarm":"Observe piora noturna, limitação ao esforço e necessidade de resgate maior que a prevista no plano.","immediate":"Fala entrecortada, dificuldade intensa para respirar, lábios azulados, exaustão ou pouca resposta ao resgate exigem emergência.","return":"Reavalie após crises e periodicamente para conferir controle, técnica, adesão e necessidade de ajustar o plano.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Asthma/","title":"RCH — Asthma","accessed":"2026-09-26"}],"reviewNotes":"Cuidados de asma aplicáveis ao fenótipo não atópico; não extrapola terapias dirigidas à alergia.","status":"source-reviewed"},
{"name":"Aspergilose em Pediatria","aliases":["Aspergilose"],"setting":"specialist","general":"Siga acompanhamento especializado. Em imunossuprimidos, evite exposição intensa a poeira de obras, solo e materiais com mofo conforme orientação.","diagnosis":"Aspergilose pode ser invasiva, alérgica ou crônica; essas formas não têm o mesmo tratamento nem a mesma gravidade.","expected":"A evolução depende da forma clínica, da imunidade e dos órgãos envolvidos. Não há prazo universal de resolução.","alarm":"Relate febre persistente, dor torácica, piora da tosse, sangue no escarro ou sintomas neurológicos.","immediate":"Falta de ar, sangramento respiratório ou piora rápida, especialmente na imunossupressão, exige emergência.","return":"Mantenha revisão clínica e exames para avaliar resposta e possíveis efeitos do tratamento.","sources":[{"url":"https://www.idsociety.org/practice-guideline/aspergillosis/","title":"IDSA/PIDS — Aspergillosis guideline","accessed":"2026-09-26"}],"reviewNotes":"Classificação geral preservada; suspeita de forma invasiva requer avaliação hospitalar urgente.","status":"source-reviewed"},
{"name":"Aspiração de corpo estranho (amendoim)","aliases":[],"setting":"urgent","general":"Suspeita de amendoim aspirado exige avaliação imediata, mesmo se a tosse passar. Relate o episódio de engasgo; não ofereça novos alimentos nem faça tentativas cegas de retirar o objeto com os dedos.","diagnosis":"O corpo estranho pode permanecer na via aérea após uma aparente melhora. Exame ou radiografia normais não excluem a aspiração; a equipe avaliará a necessidade de broncoscopia.","expected":"A evolução depende do local e do tempo de permanência; aguardar em casa pode atrasar o tratamento de obstrução ou infecção.","alarm":"Tosse persistente, chiado localizado, rouquidão ou respiração diferente após engasgo são sinais relevantes.","immediate":"Incapacidade de respirar ou falar, coloração azulada ou perda de consciência: SAMU 192 e primeiros socorros orientados.","return":"Após retirada e alta, siga as instruções do serviço e retorne por sintomas respiratórios.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Foreign_bodies_inhaled/","title":"Royal Children’s Hospital — Foreign bodies inhaled","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Asplenia em Pediatria","aliases":[],"setting":"specialist","general":"Mantenha vacinas, prevenção prescrita e identificação médica; leve o plano de emergência em viagens e informe mordidas de animais.","diagnosis":"A ausência ou baixa função do baço aumenta o risco de infecção grave; vacinação e prevenção não eliminam completamente esse risco.","expected":"A vulnerabilidade persiste ao longo da vida, mesmo quando a criança permanece bem.","alarm":"Qualquer febre ou doença com mal-estar precisa de avaliação rápida, inclusive durante tratamento preventivo.","immediate":"Febre com prostração, vômitos, manchas ou piora súbita exige emergência; não aguarde a próxima consulta.","return":"Revise periodicamente o calendário vacinal, a prevenção e o plano para infecções.","sources":[{"url":"https://cps.ca/en/documents/position/preventing-treating-infections-in-children-with-asplenia","title":"Canadian Paediatric Society — Preventing and treating infections in children with asplenia or hyposplenia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Não transfere calendário vacinal canadense ao Brasil; vacinação deve seguir recomendações locais atualizadas.","status":"source-reviewed"},
{"name":"Ataxia cerebelar aguda","setting":"urgent","general":"É uma alteração de coordenação que pode aparecer após uma infecção. Pode causar marcha instável e dificuldade de coordenação.","diagnosis":"Início súbito precisa de avaliação médica para excluir causas graves. Após avaliação, supervisione a marcha, previna quedas e suspenda bicicleta, escadas e atividades com risco enquanto houver desequilíbrio.","expected":"Em muitos casos pós-infecciosos, a coordenação melhora progressivamente. A evolução varia; acompanhamento confirma recuperação e identifica persistência ou piora.","alarm":"Procure atendimento imediato se houver sonolência ou alteração de consciência, dor de cabeça intensa, vômitos repetidos, convulsão, fraqueza, dificuldade para falar ou piora rápida do equilíbrio.","immediate":"Mantenha a criança em ambiente seguro, evitando escadas e atividades sem supervisão. Não a deixe caminhar sozinha se estiver instável; procure avaliação médica no início súbito.","return":"Retorne se a marcha não melhorar, surgirem sinais neurológicos ou houver recorrência. O seguimento deve ser antecipado diante de piora.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Ataxia/","title":"RCH — Ataxia","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Atelectasia lobar","aliases":[],"setting":"urgent","general":"Procure avaliação para esclarecer a causa e a repercussão respiratória. Informe início súbito, engasgo prévio, cirurgia recente ou doença pulmonar conhecida.","diagnosis":"Atelectasia significa perda de expansão de uma parte do pulmão. As medidas necessárias dependem de obstrução, secreções, compressão ou outra causa; exercícios devem ser orientados.","expected":"A recuperação depende da correção da causa. Uma área pode reexpandir gradualmente; extensão maior, sobretudo em lactentes, pode comprometer a oxigenação.","alarm":"Observe esforço para respirar, dor no peito, tosse que piora, febre ou redução da disposição.","immediate":"Dificuldade respiratória, lábios azulados, pausas respiratórias ou sonolência anormal exigem pronto atendimento imediato.","return":"Reavalie se não houver melhora ou surgir febre. O profissional definirá necessidade de exame de controle, fisioterapia dirigida ou investigação de corpo estranho.","sources":[{"url":"https://www.medlineplus.gov/ency/article/000065.htm","title":"MedlinePlus — Atelectasis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Atresia de Vias Biliares em Pediatria","aliases":["Atresia de vias biliares"],"setting":"urgent","general":"Fezes muito claras e icterícia persistente em um bebê precisam de investigação rápida. Leve registros da cor das fezes e exames.","diagnosis":"A obstrução das vias biliares exige avaliação hepatológica e cirúrgica. A oportunidade da intervenção influencia os resultados.","expected":"A cirurgia pode melhorar a drenagem da bile, mas não garante cura; muitos pacientes precisam de acompanhamento e eventual transplante.","alarm":"Observe febre, piora do amarelo, barriga aumentada, dificuldade alimentar e crescimento insuficiente.","immediate":"Febre com prostração, sangramento ou piora importante após cirurgia exige pronto atendimento.","return":"Mantenha seguimento de função hepática, nutrição e complicações, mesmo após melhora inicial.","sources":[{"url":"https://www.niddk.nih.gov/health-information/liver-disease/biliary-atresia/treatment","title":"NIDDK — Treatment for Biliary Atresia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Atresia Duodenal em Pediatria","setting":"hospital","aliases":["Atresia duodenal"],"general":"Obstrução congênita do intestino exige assistência neonatal e cirúrgica; não é resolvida por cuidados caseiros.","diagnosis":"Não ofereça alimentação por iniciativa própria antes da liberação da equipe. Após cirurgia, siga a retomada alimentar orientada.","expected":"A recuperação intestinal pode ser gradual, com necessidade temporária de suporte nutricional; o curso depende de condições associadas.","alarm":"Vômitos verdes, distensão, pouca urina e prostração são alarmes.","immediate":"Procure emergência diante de vômito verde no recém-nascido, mesmo que pareça bem entre episódios.","return":"Após alta, mantenha revisão cirúrgica e retorne antes por vômitos persistentes, febre ou dificuldade alimentar.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/duodenal-atresia/","title":"GOSH — Duodenal atresia","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Atresia Jejunoileal","aliases":["Atresia jejuno-ileal"],"setting":"hospital","general":"A suspeita de obstrução intestinal no recém-nascido exige hospital com cirurgia pediátrica. Não force alimentação diante de vômito verde ou distensão.","diagnosis":"A atresia bloqueia a passagem intestinal; o tratamento requer estabilização e correção cirúrgica individualizada.","expected":"O tempo para retomar alimentação varia com a extensão da lesão, o intestino preservado e as condições associadas.","alarm":"Comunique vômitos, distensão crescente, sangue nas fezes ou mudança importante de comportamento.","immediate":"Vômito verde, prostração ou piora respiratória exigem avaliação imediata.","return":"Após a alta cirúrgica, mantenha vigilância de crescimento, nutrição e evacuações; recorrência de sinais obstrutivos requer retorno urgente.","sources":[{"url":"https://www.cincinnatichildrens.org/health/i/intestinal-atresia-stenosis","title":"Cincinnati Children’s — Intestinal atresia and stenosis","accessed":"2026-09-26"},{"url":"https://pediatricctsurgery.ucsf.edu/condition/intestinal-atresia","title":"UCSF Department of Surgery — Intestinal atresia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Atresia Pulmonar com Septo IV Íntegro","aliases":["Atresia pulmonar com septo interventricular íntegro"],"setting":"hospital","general":"O recém-nascido precisa de cardiologia especializada e monitorização hospitalar. Informe piora de cor, respiração e alimentação.","diagnosis":"O sangue não passa normalmente do ventrículo direito aos pulmões. A anatomia individual determina os procedimentos necessários.","expected":"A evolução depende do desenvolvimento do coração e da estratégia de intervenção; pode exigir múltiplas etapas.","alarm":"Observe coloração azulada crescente, cansaço nas mamadas, respiração rápida ou pouca atividade.","immediate":"Cianose importante, dificuldade respiratória ou pouca resposta exige emergência imediata.","return":"Após alta formal, siga metas e sinais de retorno personalizados e mantenha seguimento cardiológico continuado.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/pulmonary-atresia.html","title":"CDC — Pulmonary atresia","accessed":"2026-09-26"}],"reviewNotes":"Fonte diferencia septo íntegro de atresia com CIV; não define técnica cirúrgica automaticamente. Revisão médica necessária.","status":"source-reviewed"},
{"name":"Atresia tricúspide","aliases":[],"setting":"specialist","general":"Mantenha seguimento com cardiologia pediátrica e leve o resumo das cirurgias, saturação habitual e plano de alimentação a todo atendimento.","diagnosis":"É uma cardiopatia congênita complexa. A necessidade de procedimentos e de internação depende da circulação e das condições atuais; medicações não corrigem a anatomia.","expected":"A evolução varia conforme a anatomia e as etapas cirúrgicas; o acompanhamento continua mesmo após melhora e crescimento adequados.","alarm":"Observe mamadas mais cansativas, menor ganho de peso, respiração mais rápida, inchaço ou mudança da cor habitual.","immediate":"Piora súbita da coloração azulada, falta de ar, desmaio, sonolência anormal ou recusa alimentar importante exigem emergência imediata.","return":"Mantenha os retornos cardiológicos e avaliação nutricional; peça orientação antes de mudar atividade física ou plano de cuidados.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/tricuspid-atresia.html","title":"CDC — Tricuspid Atresia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"AVE Isquêmico (AVEi) em Pediatria","setting":"hospital","aliases":["AVC isquêmico","AVE isquêmico"],"general":"Déficit neurológico súbito na criança pode representar AVC e precisa de avaliação imediata.","diagnosis":"Anote o horário em que estava bem pela última vez. Não ofereça comida ou líquidos se houver alteração de consciência ou deglutição.","expected":"A recuperação é variável e pode requerer reabilitação prolongada; o tratamento inicial depende de exames e tempo de início.","alarm":"Fraqueza de um lado, fala alterada, perda visual ou desequilíbrio súbito são alarmes.","immediate":"Acione emergência imediatamente, mesmo que os sintomas melhorem espontaneamente.","return":"Após alta, cumpra neurologia, reabilitação e investigação da causa; novo déficit exige emergência.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Stroke/","title":"RCH — Stroke","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Bartonelose (Doença da arranhadura do gato)","aliases":[],"setting":"home","general":"Lave arranhões com água e sabão, mantenha higiene das mãos e controle veterinário de pulgas. Evite novas mordidas, arranhões e lambedura de feridas.","diagnosis":"Após avaliação, acompanhe o tamanho dos gânglios e a febre. Não esprema nem tente drenar os nódulos em casa.","expected":"Muitos casos localizados melhoram sem complicações, mas o tempo varia; imunossuprimidos podem precisar de cuidado mais intensivo.","alarm":"Febre persistente, gânglio em crescimento, dor importante ou alteração visual precisam de reavaliação.","immediate":"Confusão, convulsão, dificuldade respiratória ou perda visual aguda exigem atendimento imediato.","return":"Retorne se não houver melhora ou surgirem novos sintomas; informe exposição a gatos e qualquer condição que reduza a imunidade.","sources":[{"url":"https://www.cdc.gov/bartonella/about/about-cat-scratch-disease.html","title":"CDC — About Cat Scratch Disease","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Beribéri em Pediatria","aliases":[],"setting":"urgent","general":"Informe dieta restrita, dificuldade de alimentação e problemas de absorção; mantenha avaliação nutricional e pediátrica.","diagnosis":"Beribéri resulta de deficiência de tiamina e pode afetar nervos ou coração; crescimento aparentemente normal não exclui deficiência.","expected":"A recuperação depende da gravidade e da correção precoce, além de resolver a causa nutricional.","alarm":"Observe fraqueza, alterações da marcha, irritabilidade, inchaço ou cansaço para respirar e alimentar-se.","immediate":"Confusão, redução da consciência ou sinais de insuficiência cardíaca exigem atendimento imediato; casos sintomáticos podem precisar tratamento hospitalar.","return":"Retorne para acompanhar resposta e garantir alimentação e reposição individualizadas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Micronutrient_deficiency/","title":"RCH — Micronutrient deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Beta-talassemia maior","aliases":[],"setting":"specialist","general":"Mantenha as consultas, transfusões e o tratamento prescrito nos dias combinados. Leve o cartão de acompanhamento aos atendimentos e não acrescente suplementos por conta própria.","diagnosis":"A beta-talassemia maior causa anemia importante e exige acompanhamento especializado. As transfusões podem levar a excesso de ferro, que precisa ser monitorado e tratado pela equipe.","expected":"O cuidado é prolongado e individualizado. A regularidade do tratamento e do controle de coração, crescimento e outros órgãos ajuda a reduzir complicações.","alarm":"Piora da palidez, fraqueza, cansaço aos esforços ou dificuldade de manter o tratamento precisam de contato com a hematologia.","immediate":"Falta de ar em repouso, desmaio, dor no peito ou reação importante durante transfusão: emergência.","return":"Compareça às revisões e exames periódicos mesmo quando a criança estiver aparentemente bem.","sources":[{"url":"https://www.nhs.uk/conditions/thalassaemia/","title":"NHS — Thalassaemia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Beta-talassemia menor","setting":"home","general":"É uma forma de traço beta-talassêmico. A pessoa pode ter glóbulos vermelhos menores e anemia leve, mas frequentemente não apresenta sintomas relevantes.","diagnosis":"Informe o traço nas consultas e leve exames anteriores. Suplementação deve depender da demonstração de deficiência, sem atribuir toda anemia ao traço. Considere aconselhamento genético no planejamento familiar.","expected":"O traço costuma permanecer estável e não evolui como talassemia maior. Pode ser transmitido; aconselhamento genético é útil antes da gestação.","alarm":"Busque avaliação se houver cansaço importante, falta de ar, palpitações, palidez acentuada ou piora documentada da anemia; esses achados podem ter outra causa associada.","immediate":"Não atribua automaticamente toda anemia ao traço. Leve hemogramas anteriores e histórico familiar ao profissional; a investigação deve orientar qualquer suplementação.","return":"Retorne para revisar exames e esclarecer o diagnóstico. Procure aconselhamento reprodutivo quando houver parceiro com traço, doença da hemoglobina ou histórico familiar relevante.","sources":[{"url":"https://www.nhs.uk/conditions/thalassaemia/carriers/","title":"NHS — Thalassaemia carriers","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Bocavírus","aliases":["Infecção por bocavírus"],"setting":"home","general":"Quando a avaliação permitir cuidado domiciliar, mantenha hidratação, alimentação em pequenas ofertas e observação da respiração. Reduza exposição a fumaça e pratique higiene das mãos.","diagnosis":"A detecção de bocavírus não prova, isoladamente, que ele explique todos os sintomas; coinfecções e persistência do vírus podem ocorrer.","expected":"A evolução depende da síndrome respiratória e da idade, especialmente nos lactentes.","alarm":"Observe redução das mamadas, pouca urina ou esforço respiratório crescente.","immediate":"Pausas respiratórias, lábios arroxeados ou pouca resposta exigem emergência.","return":"Retorne se houver piora, dificuldade para hidratar ou evolução diferente da prevista na avaliação.","sources":[{"url":"https://wwwnc.cdc.gov/eid/article/18/2/11-1293_article","title":"CDC Emerging Infectious Diseases — Human bocavirus infection in children","accessed":"2026-09-26"},{"url":"https://cps.ca/en/documents/position/bronchiolitis","title":"Canadian Paediatric Society — Bronchiolitis: diagnosis, monitoring and management","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Pesquisa primária fundamenta a interpretação do bocavírus; suporte e alertas foram condicionados à síndrome respiratória. Bronquiolite não equivale a toda infecção por bocavírus.","status":"source-reviewed"},
{"name":"Bossa serossanguinolenta","aliases":["Caput succedaneum"],"setting":"home","general":"Após confirmação pela equipe neonatal, observe o couro cabeludo sem apertar ou manipular o inchaço. Continue os cuidados habituais e as mamadas orientadas.","diagnosis":"Esse edema superficial pode surgir pela pressão durante o parto. Deve ser diferenciado pelo exame de outras coleções ou sangramentos da cabeça.","expected":"A bossa isolada geralmente diminui espontaneamente em poucos dias. O tamanho deve reduzir, sem surgimento de sinais gerais de doença.","alarm":"Observe aumento em vez de redução, coloração amarela da pele, piora da alimentação ou mudança no comportamento do recém-nascido.","immediate":"Inchaço rapidamente progressivo, palidez importante, pouca resposta ou dificuldade respiratória exigem avaliação imediata; não atribua esses achados à bossa habitual.","return":"Mantenha revisão neonatal e procure avaliação se a lesão não estiver diminuindo ou se surgirem dúvidas sobre sua evolução.","sources":[{"url":"https://www.medlineplus.gov/ency/article/001587.htm","title":"MedlinePlus — Caput succedaneum","accessed":"2026-09-26"}],"reviewNotes":"Fonte sustenta evolução autolimitada e risco de icterícia. Sinais sistêmicos exigem exclusão de outros diagnósticos. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Botulismo em Pediatria","setting":"hospital","aliases":["Botulismo"],"general":"Botulismo pode causar fraqueza progressiva e falência respiratória; a suspeita exige hospital imediatamente.","diagnosis":"Informe alimentos ingeridos e exposições. Em lactentes, relate constipação, choro fraco, dificuldade de sucção ou perda de sustentação da cabeça.","expected":"A recuperação pode ser lenta e exigir suporte respiratório e alimentar; melhora parcial não dispensa vigilância.","alarm":"Fraqueza, pálpebras caídas, dificuldade para engolir ou respirar são alarmes.","immediate":"Procure emergência sem esperar confirmação laboratorial; não ofereça líquidos se houver dificuldade para engolir.","return":"O seguimento após alta é individualizado para recuperação motora, alimentação e respiração.","sources":[{"url":"https://www.cdc.gov/botulism/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of Botulism","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Broncoespasmo e Anestesia em Pediatria","aliases":[],"setting":"hospital","general":"Informe asma, infecção respiratória recente, alergias e reações anteriores à anestesia; forneça a lista de tratamentos em uso.","diagnosis":"Broncoespasmo durante anestesia exige avaliação imediata, incluindo outras causas de dificuldade ventilatória, como obstrução do tubo e reação alérgica.","expected":"A evolução depende do desencadeante e da resposta; pode ser necessária observação intensiva.","alarm":"Queda da oxigenação, dificuldade para ventilar e instabilidade circulatória são sinais monitorados pela equipe.","immediate":"Em ambiente cirúrgico, a equipe de anestesia deve intervir imediatamente; não é situação para manejo domiciliar.","return":"Após recuperação, solicite registro do evento e plano antes de futuras anestesias.","sources":[{"url":"https://pedsanesthesia.org/wp-content/uploads/2024/11/SPAPediCrisisChecklistNov2024.pdf","title":"Society for Pediatric Anesthesia — PediCrisis Checklist, Bronchospasm, novembro 2024","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Bronquiolite","setting":"home","aliases":["Bronquiolite viral"],"general":"Infecção respiratória de lactentes pode dificultar respiração e alimentação; bebês pequenos ou com doenças associadas têm maior risco.","diagnosis":"Ofereça mamadas menores e frequentes conforme tolerância, evitando fumaça. Observe respiração, ingestão e fraldas molhadas. Para bebês menores de 1 ano, deite de barriga para cima em cada sono, em superfície firme, plana e sem inclinação, mesmo com nariz entupido. Não eleve a cabeceira ou o colchão e não use travesseiros, cunhas ou posicionadores para dormir.","expected":"O quadro costuma ser autolimitado, mas pode piorar nos primeiros dias; a tosse pode demorar a desaparecer.","alarm":"Esforço respiratório, redução importante da alimentação, pouca urina ou sonolência são alarmes.","immediate":"Pausas respiratórias, coloração azulada ou dificuldade para despertar exigem emergência.","return":"Retorne diante de piora ou dificuldade para manter hidratação; alta depende de avaliação individual.","sources":[{"url":"https://cps.ca/en/documents/position/bronchiolitis","title":"Canadian Paediatric Society — Bronchiolitis: children one to 24 months","accessed":"2026-09-26"},{"url":"https://www.healthychildren.org/English/tips-tools/ask-the-pediatrician/Pages/my-baby-has-a-stuffy-nose-how-can-i-help-them-sleep-safely.aspx","title":"AAP / Rachel Y. Moon — My baby has a stuffy nose. How can I help them sleep safely? Atualizado em 16/12/2025","accessed":"2026-10-17"}],"status":"source-reviewed","reviewNotes":"Fonte CPS cobre predominantemente crianças previamente saudáveis de 1–24 meses. Neonatos e comorbidades exigem avaliação específica; rótulo home pressupõe avaliação de gravidade e plano de retorno. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Bronquiolite obliterante","aliases":[],"setting":"specialist","general":"Acompanhe com pneumologia pediátrica; evite fumaça e mantenha vacinação e atividade adaptadas ao plano individual.","diagnosis":"Bronquiolite obliterante é doença crônica das pequenas vias aéreas; a causa deve ser registrada antes de definir conduta.","expected":"A obstrução pode persistir; sintomas, função pulmonar e necessidade de suporte variam, sem prazo universal de recuperação.","alarm":"Maior esforço respiratório, queda de tolerância ao esforço ou febre exigem reavaliação.","immediate":"Cianose, dificuldade para falar ou beber, sonolência ou falta de ar intensa exigem emergência.","return":"Combine seguimento clínico e funcional; necessidade de tomografia deve ser individualizada.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12259327/","title":"Wan et al. — Postinfectious Bronchiolitis Obliterans in Children (2025)","accessed":"2026-09-27"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12392748/","title":"ATS — Summary for Clinicians: Detection of BOS after Pediatric HSCT (2025)","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/30798629/","title":"Kavaliunaite e Aurora — Diagnosing and managing bronchiolitis obliterans in children (2019)","accessed":"2026-09-27"}],"reviewNotes":"Etiologias separadas para impedir transporte automático de protocolos. Não estabelece esquema farmacológico nem tomografias seriadas universais. Revisão documental assistida; seguimento especialista continua obrigatório.","status":"source-reviewed","evidenceSummary":"Revisão pediátrica pós-infecciosa de 2025, síntese da diretriz ATS e revisão/opinião especializada publicada. Doença rara, com estudos heterogêneos e evidência terapêutica limitada. A diretriz ATS aborda detecção pós-transplante hematopoético, não todos os tratamentos ou etiologias.","decisionSupport":{"summary":"Escolher etiologia confirmada; contexto transplantado exige equipe de transplante e não admite extrapolar protocolo pós-infeccioso.","requirements":["Infecção antecedente e evolução","Transplante hematopoético ou pulmonar","Função pulmonar possível para idade","Oxigenação, imagem, infecção e gravidade"],"branchRequired":true,"branches":[{"id":"bo-posinfecciosa","label":"Pós-infecciosa","when":"Obstrução persistente após infecção respiratória, com diagnóstico especialista.","setting":"specialist","overrides":{"diagnosis":"Revisar limitações funcionais, crescimento e plano para intercorrências.","expected":"Pode haver estabilidade ou limitação prolongada.","return":"Pneumologia; exames conforme evolução.","alarm":"Piora da respiração ou queda de atividade.","immediate":"Sinais de insuficiência respiratória exigem emergência."}},{"id":"bo-tcth","label":"Após transplante hematopoético","when":"Suspeita ou confirmação após transplante de células-tronco hematopoéticas.","setting":"specialist","overrides":{"diagnosis":"Manter vigilância funcional mesmo sem sintomas, conforme equipe transplantadora.","expected":"Alterações iniciais podem ser silenciosas.","return":"Calendário funcional e investigação de infecção definidos pela equipe.","alarm":"Tosse nova, dispneia ou perda de função.","immediate":"Piora aguda exige avaliação imediata e aviso ao centro."}},{"id":"bo-outro","label":"Transplante pulmonar ou etiologia diferente/incerta","when":"Contexto não enquadrado no ramo pós-infeccioso ou pós-transplante hematopoético.","setting":"specialist","overrides":{"diagnosis":"Definir causa e investigar com centro especializado.","expected":"Depende da etiologia e das complicações.","return":"Seguimento específico, sem presumir equivalência entre síndromes.","alarm":"Declínio respiratório ou febre.","immediate":"Procure emergência se houver descompensação."}}]},"revisedAt":"2026-09-27"},
{"name":"Bronquiolite viral aguda por Rinovírus","aliases":[],"setting":"home","general":"Após avaliação e liberação, ofereça mamadas menores e frequentes, observe fraldas molhadas e evite fumaça. Higienize as mãos de cuidadores.","diagnosis":"Bronquiolite por rinovírus é uma infecção viral; a conduta depende principalmente da respiração, hidratação, idade e fatores de risco. Para bebês menores de 1 ano, deite de barriga para cima em cada sono, em superfície firme, plana e sem inclinação, mesmo com nariz entupido. Não eleve a cabeceira ou o colchão e não use travesseiros, cunhas ou posicionadores para dormir.","expected":"Pode piorar nos primeiros dias; a recuperação respiratória ocorre gradualmente, enquanto a tosse pode persistir por semanas.","alarm":"Menos da metade da alimentação habitual, respiração rápida em repouso e redução de urina precisam de avaliação.","immediate":"Pausas respiratórias, lábios azulados, dificuldade intensa para respirar ou para despertar exigem emergência.","return":"Reavalie mais cedo lactentes pequenos, prematuros e crianças com doença cardíaca/pulmonar; retorne se piorar ou não evoluir como esperado.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Bronchiolitis/","title":"RCH — Bronchiolitis","accessed":"2026-09-26"},{"url":"https://www.healthychildren.org/English/tips-tools/ask-the-pediatrician/Pages/my-baby-has-a-stuffy-nose-how-can-i-help-them-sleep-safely.aspx","title":"AAP / Rachel Y. Moon — My baby has a stuffy nose. How can I help them sleep safely? Atualizado em 16/12/2025","accessed":"2026-10-17"}],"reviewNotes":"Orientações sindrômicas de bronquiolite viral, aplicáveis ao rinovírus; não presume mesma duração ou gravidade em todos os vírus.","status":"source-reviewed"},
{"name":"Bronquiolite viral aguda por VSR","aliases":[],"setting":"home","general":"Após avaliação que permita cuidado domiciliar, ofereça mamadas menores e mais frequentes, observe a respiração e a urina e mantenha o ambiente sem fumaça. Higienize as mãos e acompanhe também durante a noite.","diagnosis":"A bronquiolite por VSR afeta os pequenos brônquios; o cuidado se concentra em respiração e hidratação. Não acrescente xaropes ou outras medicações sem indicação individual. Para bebês menores de 1 ano, deite de barriga para cima em cada sono, em superfície firme, plana e sem inclinação, mesmo com nariz entupido. Não eleve a cabeceira ou o colchão e não use travesseiros, cunhas ou posicionadores para dormir.","expected":"É comum piorar entre o terceiro e o quinto dia; a tosse pode persistir por até cerca de três semanas, com melhora progressiva.","alarm":"Menor aceitação alimentar, poucas fraldas molhadas ou piora respiratória exigem reavaliação rápida.","immediate":"Pausas respiratórias, lábios azulados, grande esforço para respirar ou dificuldade para despertar: emergência.","return":"Retorne conforme o risco e a orientação da consulta; antecipar por piora ou dificuldade para hidratar.","sources":[{"url":"https://www.nhs.uk/conditions/bronchiolitis/","title":"NHS — Bronchiolitis","accessed":"2026-09-26"},{"url":"https://www.healthychildren.org/English/tips-tools/ask-the-pediatrician/Pages/my-baby-has-a-stuffy-nose-how-can-i-help-them-sleep-safely.aspx","title":"AAP / Rachel Y. Moon — My baby has a stuffy nose. How can I help them sleep safely? Atualizado em 16/12/2025","accessed":"2026-10-17"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Brucelose","setting":"specialist","general":"A brucelose é uma infecção bacteriana que pode ocorrer após contato com animais infectados ou consumo de produtos não pasteurizados. Pode ser sistêmica.","diagnosis":"Informe contato com animais, trabalho rural e consumo de leite ou derivados não pasteurizados. Cumpra o acompanhamento e o tratamento completos; evite novas exposições e manipulação desprotegida de animais doentes.","expected":"Sintomas podem persistir ou voltar. O acompanhamento verifica resposta e complicações, que podem envolver diferentes órgãos.","alarm":"Procure atendimento rapidamente para febre persistente, confusão, falta de ar, dor intensa, sinais neurológicos ou piora do estado geral, especialmente após exposição relevante.","immediate":"Interrompa o consumo do produto suspeito e informe a exposição às autoridades ou ao serviço de saúde. Evite produtos lácteos não pasteurizados e não manipule animais doentes sem proteção.","return":"Retorne conforme o plano do serviço para revisar resultados e evolução. Reavalie se a febre reaparecer, persistir ou surgirem novos sintomas após a consulta.","sources":[{"url":"https://www.cdc.gov/brucellosis/about/index.html","title":"CDC — About Brucellosis","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Candidíase de fraldas","aliases":[],"setting":"home","general":"Troque fraldas molhadas ou sujas prontamente, limpe suavemente com água morna e deixe a pele secar. Permita períodos sem fralda quando possível.","diagnosis":"Mantenha a barreira cutânea orientada e complete o tratamento específico prescrito. Evite talco, antissépticos e produtos perfumados que irritem a região.","expected":"A candidíase pode demorar mais para desaparecer que uma assadura simples e pode reaparecer. Melhorar parcialmente não significa que o tratamento terminou.","alarm":"Observe extensão da vermelhidão, dor crescente, feridas, bolhas, secreção ou ausência de melhora.","immediate":"Febre, prostração, lesões rapidamente disseminadas ou dor intensa exigem avaliação rápida, pois podem indicar outro problema associado.","return":"Retorne se o tratamento não estiver funcionando ou se a assadura persistir; o diagnóstico precisa ser revisto e outras dermatoses podem ser consideradas.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Nappy_rash/","title":"RCH — Nappy rash","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Candidíase oral (Sapo)","aliases":[],"setting":"home","general":"Mantenha a higiene das mãos e dos objetos usados na alimentação. Não raspe as placas da boca, pois isso pode machucar e causar sangramento.","diagnosis":"Use o tratamento exatamente como orientado. Se houver dor ou feridas nos mamilos durante a amamentação, informe a equipe para avaliar também a mãe.","expected":"As lesões e o desconforto devem regredir com o cuidado adequado; reaparecimento frequente precisa de avaliação da causa.","alarm":"Observe recusa das mamadas, choro ao sugar, lesões extensas ou persistência apesar do tratamento.","immediate":"Procure atendimento imediato se o bebê não conseguir se alimentar, urinar muito menos, apresentar febre ou ficar muito sonolento.","return":"Retorne se não houver melhora, se surgirem novas lesões ou se a dificuldade alimentar continuar.","sources":[{"url":"https://medlineplus.gov/ency/article/007615.htm","title":"MedlinePlus — Thrush in newborns","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Cardiomiopatia Dilatada na Pediatria","aliases":[],"setting":"specialist","general":"Siga o plano da cardiologia e combine previamente limites de esforço, nutrição e necessidade de avaliação dos familiares.","diagnosis":"A dilatação enfraquece o bombeamento cardíaco; a investigação procura causas genéticas e adquiridas e avalia o ritmo cardíaco.","expected":"A evolução varia com a causa e a função do coração; pode haver necessidade de cuidado prolongado ou terapias especializadas.","alarm":"Informe cansaço crescente, piora da alimentação, baixo ganho de peso ou dificuldade respiratória.","immediate":"Desmaio, falta de ar intensa ou deterioração súbita exigem pronto atendimento.","return":"Mantenha ecocardiogramas e consultas; ajuste atividades e tratamentos exclusivamente com a equipe.","sources":[{"url":"https://www.acc.org/latest-in-cardiology/ten-points-to-remember/2023/06/16/13/48/treatment-strategies-for-cardiomyopathy","title":"ACC — Treatment Strategies for Cardiomyopathy in Children","accessed":"2026-09-26"},{"url":"https://www.ucsfbenioffchildrens.org/conditions/cardiomyopathy","title":"UCSF Benioff — Cardiomyopathy","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Cardiomiopatia Hipertrófica em Pediatria","aliases":["Cardiomiopatia hipertrófica"],"setting":"specialist","general":"Mantenha o acompanhamento cardiológico mesmo sem sintomas. Atividade física e hidratação devem seguir o plano individual da equipe.","diagnosis":"O espessamento do músculo cardíaco pode alterar o fluxo e o ritmo do coração. Avaliação de familiares pode ser necessária.","expected":"A evolução varia; ausência de sintomas não elimina o risco de arritmia. O seguimento ajuda a reconhecer mudanças.","alarm":"Relate palpitações, cansaço novo, dor no peito, tontura ou redução da tolerância ao esforço.","immediate":"Desmaio, dor torácica com esforço ou falta de ar intensa exigem atendimento imediato.","return":"Compareça às avaliações e exames cardíacos programados; informe novos sintomas antes da próxima consulta.","sources":[{"url":"https://www.chop.edu/conditions-diseases/cardiomyopathy","title":"CHOP — Cardiomyopathy","accessed":"2026-09-26"}],"reviewNotes":"Orientação restrita à cardiomiopatia hipertrófica dentro da fonte sobre diferentes cardiomiopatias.","status":"source-reviewed"},
{"name":"Caxumba","aliases":[],"setting":"home","general":"Mantenha hidratação e repouso conforme disposição. Evite contato próximo e compartilhamento de objetos com saliva.","diagnosis":"Afastamento de escola e contatos deve durar até cinco dias após início do inchaço das parótidas, seguindo orientação local.","expected":"O inchaço costuma reduzir ao longo da semana seguinte ao pico, mas a evolução varia.","alarm":"Observe dificuldade para beber, dor testicular, cefaleia forte ou alteração auditiva.","immediate":"Rigidez de nuca, convulsão, redução da resposta ou falta de ar exige emergência.","return":"Retorne se houver piora ou ausência de melhora e revise vacinação dos contatos com a equipe.","sources":[{"url":"https://www.cdc.gov/mumps/hcp/clinical-overview/index.html","title":"CDC — Clinical overview of mumps","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Cefaleia na Infância","aliases":["Cefaleia"],"setting":"home","general":"Após avaliação, mantenha hidratação, sono regular e registro dos episódios, possíveis desencadeantes e repercussão nas atividades.","diagnosis":"Cefaleia tem causas diversas; o padrão e o exame orientam se são necessários exames adicionais.","expected":"Quadros primários podem recorrer. Mudanças do padrão exigem reavaliação, mesmo com diagnóstico anterior.","alarm":"Observe dor progressiva, despertar noturno, vômitos sem explicação ou piora com tosse e posição.","immediate":"Dor súbita muito intensa, convulsão, fraqueza, confusão ou rigidez de nuca exige emergência.","return":"Retorne se a dor persistir, limitar atividades ou exigir uso frequente de medicação.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Headache/","title":"RCH — Headache","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Cefaleia tensional","aliases":[],"setting":"home","general":"Regularize sono, refeições e hidratação. Faça pausas durante atividades, relaxamento e registro dos episódios, duração e fatores associados.","diagnosis":"A cefaleia tensional pode relacionar-se a tensão muscular e estresse. O diagnóstico pressupõe avaliação e ausência de características que apontem outra causa.","expected":"Os episódios podem melhorar com medidas de rotina; recorrência frequente ou interferência na escola exige revisão do plano.","alarm":"Observe dor progressiva, vômitos, febre, mudança visual ou despertar noturno causado pela dor.","immediate":"Dor súbita muito intensa, desmaio, confusão, fraqueza ou dificuldade para falar exigem urgência.","return":"Retorne se ocorrer semanalmente, piorar ou exigir analgésico repetidamente; leve o diário e evite automedicação frequente.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Headaches/","title":"RCH — Headaches","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Cefalohematoma","aliases":[],"setting":"home","general":"Mantenha os cuidados habituais do recém-nascido e observe alimentação, atividade e coloração da pele. Não massageie, aperte nem tente drenar o volume na cabeça; qualquer procedimento depende de avaliação médica.","diagnosis":"O cefalohematoma é uma coleção de sangue limitada ao osso afetado. O profissional deve confirmar essa característica, pois outros tipos de inchaço no couro cabeludo exigem condutas diferentes.","expected":"A redução costuma ser lenta, ao longo de dias a semanas. Pode ocorrer aumento da icterícia durante a reabsorção.","alarm":"Aumento rápido do volume, palidez, piora da mamada ou pele muito amarela exigem avaliação urgente.","immediate":"Sonolência extrema, dificuldade respiratória ou pouca resposta: emergência neonatal.","return":"Mantenha a revisão do recém-nascido e a avaliação de icterícia orientadas; antecipe se o inchaço ou o estado geral piorarem.","sources":[{"url":"https://neonatalnetworkssoutheast.nhs.uk/wp-content/uploads/2023/10/Wessex-postnatal-ward_Baby-check-findings-head-swellings.pdf","title":"NHS Neonatal Network — Baby check findings: head swellings","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Fonte descreve cefalohematoma e icterícia; orientação de emergência considera necessidade de excluir outras hemorragias neonatais.","status":"source-reviewed"},
{"name":"Celulite em Pediatria","aliases":[],"setting":"home","general":"Após avaliação e liberação para casa, siga o tratamento prescrito e observe a área; informe feridas, picadas, mordidas ou contato com água.","diagnosis":"Celulite é infecção da pele e tecidos próximos; localização, extensão e estado geral definem a necessidade de internação.","expected":"A melhora deve ser acompanhada, pois vermelhidão inicial isolada não determina falha; piora clínica exige reavaliação.","alarm":"Observe aumento rápido da área, febre, dor crescente ou acometimento perto dos olhos.","immediate":"Dor desproporcional, rápida progressão, prostração ou sinais de má circulação exigem emergência.","return":"Reavalie em 24–48 horas se não houver resposta satisfatória, ou antes se piorar.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Cellulitis_and_other_bacterial_skin_infections/","title":"RCH — Cellulitis and other bacterial skin infections","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Cuidados domiciliares somente em quadro leve avaliado; face/olhos e infecção profunda requerem outra avaliação.","status":"source-reviewed"},
{"name":"Celulite orbitária","setting":"hospital","general":"Infecção profunda ao redor do olho, potencialmente grave e com risco para visão e cérebro.","diagnosis":"Procure hospital imediatamente; essa infecção exige avaliação especializada. Não pressione o olho nem tente drenar o inchaço. Informe dor ao mover os olhos, alteração visual ou sinusite recente.","expected":"A resposta depende da extensão e de possíveis complicações. São necessárias reavaliações da visão e do estado geral; algumas situações exigem intervenção cirúrgica e internação prolongada.","alarm":"Alteração visual, olho deslocado, dor intensa ao movimento, cefaleia forte, vômitos, sonolência ou piora rápida são sinais de gravidade.","immediate":"Encaminhar imediatamente ao pronto atendimento hospitalar; não tentar tratar em casa.","return":"Após a alta, retornar conforme oftalmologia/pediatria; voltar imediatamente se qualquer sinal de alarme reaparecer.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Periorbital_and_orbital_cellulitis/","title":"RCH — Periorbital and orbital cellulitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":["Celulite Orbitária em Pediatria"],"status":"source-reviewed"},
{"name":"Celulite periorbitária","aliases":["Celulite Periorbitária Infantil"],"setting":"urgent","general":"A infecção ao redor da pálpebra requer avaliação médica e acompanhamento próximo. Registre se o inchaço, a dor e a febre estão melhorando.","diagnosis":"Tratamento em casa só é apropriado quando a criança está bem, o acometimento é leve e a revisão está garantida. É essencial distinguir infecção da órbita.","expected":"Espera-se início de melhora com tratamento adequado; ausência de melhora ou deterioração em 24–48 horas exige reavaliação.","alarm":"Observe dor para mover o olho, limitação dos movimentos, visão dupla, redução visual, olho projetado para frente ou dor de cabeça forte.","immediate":"Qualquer alteração da visão ou movimento ocular, prostração, vômitos com cefaleia ou piora rápida exige pronto atendimento imediato.","return":"Mantenha a revisão programada e complete o tratamento. Crianças menores ou quadros mais intensos podem necessitar internação.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Periorbital_and_orbital_cellulitis/","title":"RCH — Periorbital and orbital cellulitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Cetoacidose Diabética em Pediatria","aliases":["Cetoacidose diabética","CAD"],"setting":"hospital","general":"Cetoacidose diabética exige atendimento hospitalar imediato. Informe o esquema habitual, últimas administrações, glicemias e intercorrências; não tente resolver o quadro apenas em casa.","diagnosis":"A equipe precisa acompanhar hidratação, eletrólitos, cetonas e estado neurológico durante a correção.","expected":"A melhora da glicemia isoladamente não confirma resolução; a recuperação depende da correção metabólica segura.","alarm":"Avise imediatamente sobre vômitos, dor de cabeça, sonolência ou mudança de comportamento durante o tratamento.","immediate":"Respiração muito profunda, desmaio, convulsão ou redução da consciência são emergências.","return":"Após alta, revise o plano para dias de doença, monitorização e contato com a equipe de diabetes.","sources":[{"url":"https://cps.ca/en/documents/position/current-recommendations-for-management-of-paediatric-diabetic-ketoacidosis","title":"Canadian Paediatric Society — Current recommendations for management of paediatric diabetic ketoacidosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Choque Circulatório em Crianças","aliases":["Choque circulatório"],"setting":"hospital","general":"Acione emergência imediatamente e descreva alterações de consciência, respiração e circulação. Não aguarde aferição de pressão para buscar ajuda.","diagnosis":"Choque significa circulação insuficiente para os órgãos e pode ter causas diferentes; requer estabilização e tratamento hospitalar.","expected":"A evolução pode ser rápida. A resposta é acompanhada continuamente e depende da causa.","alarm":"Observe extremidades frias, palidez, pele manchada, pouca resposta ou respiração anormal.","immediate":"Desmaio, dificuldade para despertar ou piora respiratória exige assistência imediata.","return":"Seguimento e orientações após alta dependem da causa, dos órgãos afetados e da recuperação; não há alta automática.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Resuscitation__Care_of_the_seriously_unwell_child/","title":"RCH — Care of the seriously unwell child","accessed":"2026-09-26"}],"reviewNotes":"Orientação de encaminhamento e reconhecimento, não protocolo de ressuscitação. Neonatos e trauma exigem protocolos específicos.","status":"source-reviewed"},
{"name":"Cifose de Scheuermann","aliases":[],"setting":"specialist","general":"Mantenha as atividades liberadas e siga o programa de fisioterapia. Não force a coluna a ficar reta nem utilize coletes sem avaliação especializada.","diagnosis":"A cifose de Scheuermann é uma alteração estrutural do crescimento vertebral, diferente de postura relaxada. O tratamento considera curva, dor e crescimento restante.","expected":"Casos leves podem ser acompanhados; outros precisam de colete ou cirurgia. A evolução é gradual e não se prevê correção imediata.","alarm":"Dor crescente, deformidade que aumenta, dificuldade para atividades ou lesões causadas pelo colete devem ser comunicadas.","immediate":"Fraqueza nova, alteração da sensibilidade, perda do controle urinário/intestinal ou dificuldade respiratória importante exigem avaliação urgente.","return":"Mantenha retornos com ortopedia para acompanhar crescimento e ajuste do colete, se prescrito, evitando interrompê-lo sem revisão.","sources":[{"url":"https://www.southtees.nhs.uk/resources/kyphosis-and-scheuermanns-kyphosis/","title":"South Tees NHS — Kyphosis and Scheuermann’s kyphosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"CINCA/NOMID","aliases":["CINCA","NOMID"],"setting":"specialist","general":"Mantenha acompanhamento com reumatologia e avaliação dos órgãos envolvidos. Registre febre, lesões cutâneas, dor e alterações do comportamento.","diagnosis":"CINCA/NOMID é uma condição inflamatória rara, geralmente de início muito precoce, que pode afetar articulações, cérebro, olhos e outros órgãos.","expected":"A doença é prolongada; controle da inflamação e prevenção de danos exigem plano individual.","alarm":"Observe cefaleia, mudança visual ou auditiva, piora articular, dificuldade de marcha ou alteração do desenvolvimento.","immediate":"Convulsão, sonolência anormal, dor ocular intensa ou déficit neurológico novo exige emergência.","return":"Siga avaliações de crescimento, desenvolvimento, visão, audição e função renal conforme a equipe.","sources":[{"url":"https://medlineplus.gov/genetics/condition/cryopyrin-associated-periodic-syndromes/","title":"MedlinePlus Genetics — Cryopyrin-associated periodic syndromes","accessed":"2026-09-26"}],"reviewNotes":"Orientação específica para NOMID dentro do espectro CAPS; não extrapolada de fenótipos mais leves.","status":"source-reviewed"},
{"name":"Cisticercose em Pediatria","aliases":["Cisticercose"],"setting":"specialist","general":"Mantenha acompanhamento especializado e não inicie tratamento antiparasitário por conta própria. Leve exames anteriores e informe convulsões ou alterações visuais.","diagnosis":"O cuidado depende do local, quantidade e estágio das lesões. Comprometimento neurológico exige controlar primeiro suas complicações.","expected":"A resposta varia; lesões calcificadas, viáveis e formas fora do cérebro não seguem o mesmo plano.","alarm":"Observe cefaleia crescente, vômitos repetidos, convulsões, alteração da visão ou comportamento.","immediate":"Convulsão prolongada, perda de consciência ou cefaleia intensa com vômitos exige emergência.","return":"Siga revisões clínicas e exames de imagem conforme localização e evolução, mesmo após melhora dos sintomas.","sources":[{"url":"https://www.cdc.gov/cysticercosis/hcp/clinical-care/index.html","title":"CDC — Clinical Care of Cysticercosis","accessed":"2026-09-26"}],"reviewNotes":"Título pediátrico ampliado de cisticercose humana; orientação condicional preserva as diferentes localizações.","status":"source-reviewed"},
{"name":"Cisticercose humana","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento especializado e leve exames de imagem e resultados anteriores. Reforce higiene das mãos e segurança da água e dos alimentos.","diagnosis":"A conduta depende de localização, número e estágio dos cistos; acometimento do cérebro ou olhos requer abordagem específica. Não inicie antiparasitário por conta própria.","expected":"A evolução é variável, e algumas lesões não exigem tratamento para eliminar o parasita; sintomas podem demandar cuidado próprio.","alarm":"Observe nova dor de cabeça, vômitos, alteração visual e crises convulsivas.","immediate":"Primeira convulsão, crise prolongada, alteração de consciência, fraqueza ou perda visual exigem emergência.","return":"Retorne conforme o plano de neurologia/infectologia/oftalmologia e para revisão de sintomas e imagens, sem presumir cura apenas pela melhora clínica.","sources":[{"url":"https://www.cdc.gov/cysticercosis/about/index.html","title":"CDC — About Cysticercosis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Citomegalovirose adquirida","aliases":[],"setting":"home","general":"Ofereça líquidos e alimentação conforme aceitação, permita repouso e lave as mãos após contato com secreções ou troca de fraldas. Não compartilhe copos, talheres ou chupetas.","diagnosis":"Estas orientações se referem à infecção adquirida após o nascimento. Pessoas com imunidade reduzida necessitam avaliação específica; não aplique automaticamente o acompanhamento da forma congênita.","expected":"Em pessoas saudáveis, a infecção costuma causar poucos sintomas e geralmente não exige tratamento específico. Cansaço e febre podem prolongar-se, exigindo revisão se persistirem.","alarm":"Icterícia, dor abdominal importante, febre prolongada, alterações visuais ou piora do estado geral merecem avaliação.","immediate":"Falta de ar, alteração de consciência ou desidratação importante: emergência.","return":"Retorne se não houver melhora progressiva ou se a criança for imunocomprometida; o seguimento depende dos órgãos envolvidos.","sources":[{"url":"https://www.cdc.gov/cytomegalovirus/about/index.html","title":"CDC — About Cytomegalovirus","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Citomegalovirose congênita","setting":"specialist","general":"Infecção pelo citomegalovírus adquirida antes do nascimento; muitos bebês não têm sinais, mas alguns apresentam sequelas.","diagnosis":"Cumpra avaliações da audição, visão e desenvolvimento, mesmo que o bebê pareça bem. Suspeita logo após o nascimento exige investigação rápida, pois a confirmação de infecção congênita tem janela limitada.","expected":"Muitos bebês permanecem sem problemas importantes; outros desenvolvem alterações auditivas ou do desenvolvimento. Perda de audição pode surgir depois de uma triagem normal, justificando acompanhamento continuado.","alarm":"Convulsão, dificuldade respiratória, sonolência importante, problemas para alimentar, icterícia intensa ou piora exigem atendimento imediato.","immediate":"Bebê com suspeita deve ser avaliado rapidamente por pediatria/infectologia, sem aguardar sintomas.","return":"Manter seguimento pediátrico, auditivo e visual; cumprir reavaliações, pois perdas auditivas podem surgir tardiamente.","sources":[{"url":"https://www.cdc.gov/cytomegalovirus/congenital-infection/index.html","title":"CDC — CMV in Newborns","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Coarctação da Aorta em Pediatria","aliases":["Coarctação da aorta"],"setting":"specialist","general":"Mantenha acompanhamento com cardiologia pediátrica, inclusive após correção. Observe alimentação, crescimento e tolerância às atividades; siga a orientação individual sobre exercício.","diagnosis":"O estreitamento da aorta pode elevar a pressão e prejudicar a circulação. No recém-nascido, pode descompensar rapidamente.","expected":"A evolução depende da gravidade e do tratamento; correção não dispensa seguimento da pressão e da aorta.","alarm":"Avise sobre cansaço crescente, dificuldade nas mamadas, palidez ou respiração acelerada.","immediate":"Falta de ar importante, desmaio, extremidades frias ou bebê pouco responsivo exigem emergência.","return":"Compareça aos controles cardiológicos e antecipe a avaliação se surgirem sintomas novos.","sources":[{"url":"https://medlineplus.gov/ency/article/000191.htm","title":"MedlinePlus — Coarctation of the aorta","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Coartação da aorta","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento cardiológico, controle de pressão e orientações individualizadas sobre atividade física. Informe à equipe qualquer dificuldade de alimentação ou cansaço.","diagnosis":"O estreitamento da aorta pode limitar o fluxo de sangue; a gravidade e necessidade de intervenção dependem da anatomia e repercussão. Em recém-nascidos, pode ser crítico.","expected":"Mesmo após correção, é necessário seguimento ao longo da vida; podem persistir alterações da pressão ou surgir novo estreitamento.","alarm":"Observe palidez, suor excessivo, respiração difícil, irritabilidade fora do habitual ou piora da tolerância às atividades.","immediate":"Lactente com dificuldade respiratória, palidez intensa, pouca resposta ou recusa importante das mamadas precisa de pronto atendimento imediato.","return":"Não interrompa revisões quando não houver sintomas. Antecipe consulta se houver piora do esforço, alimentação ou pressão registrada.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/coarctation-of-the-aorta.html","title":"CDC — Coarctation of the aorta","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Colelitíase e Colecistite em Pediatria","setting":"specialist","aliases":["Colelitíase","Colecistite"],"general":"Registre dor, vômitos, febre, icterícia e fatores associados. Leve ultrassom e exames; evite automedicação ou restrições nutricionais amplas.","diagnosis":"Cálculo incidental, dor biliar e inflamação/obstrução exigem caminhos distintos; cirurgia ou medicamentos não são automáticos para todo achado.","expected":"A evolução depende de sintomas, idade, doenças associadas e complicações.","alarm":"Dor persistente, febre, vômitos repetidos, urina escura ou icterícia exigem reavaliação.","immediate":"Dor intensa com febre ou icterícia, prostração ou incapacidade de beber exigem urgência hospitalar.","return":"Defina acompanhamento com pediatria/gastroenterologia e cirurgia pediátrica conforme apresentação.","sources":[{"url":"https://www.mdpi.com/2227-9067/11/12/1553","title":"Çakar et al. — Cholelithiasis in Infants: Risk Factors, Management, and the Role of Ursodeoxycholic Acid (2024)","accessed":"2026-09-27"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8061037/","title":"Diez et al. — Cholelithiasis and cholecystitis in children and adolescents (2021)","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Fonte geral substituída por investigação pediátrica aberta. Escopo: estratificar apresentação e destino; não fixa tempo cirúrgico, tratamento medicamentoso ou calendário ultrassonográfico universal. Revisão documental, sem homologação humana.","evidenceSummary":"Coorte retrospectiva de 98 lactentes e estudo retrospectivo com levantamento de serviços pediátricos. Sustentam heterogeneidade e separação por sintomas/complicações; sem randomização, não demonstram eficácia comparativa de medicamentos. Resultados de lactentes não se generalizam a adolescentes ou hemólise.","decisionSupport":{"summary":"Selecionar apresentação atual; sinais de complicação prevalecem sobre descoberta inicialmente incidental.","requirements":["Idade, dor e duração","Febre, vômitos, icterícia e hidratação","Ultrassom e exames hepatobiliares/pancreáticos","Hemólise, doença associada e exposições"],"branchRequired":true,"branches":[{"id":"biliar-assintomatico","label":"Cálculo incidental, assintomático","when":"Achado de imagem sem sintomas ou evidência de complicação.","setting":"specialist","overrides":{"diagnosis":"Acompanhar e revisar fatores associados; não pressupor intervenção.","expected":"Alguns cálculos em lactentes podem desaparecer; não é garantia individual.","return":"Reavaliação e imagem conforme risco.","alarm":"Nova dor, febre ou icterícia.","immediate":"Procure urgência se surgirem sinais de complicação."}},{"id":"biliar-sintomatico","label":"Sintomático, sem complicação demonstrada","when":"Dor compatível, criança estável, avaliação sem inflamação ou obstrução.","setting":"specialist","overrides":{"diagnosis":"Discutir opções com cirurgia pediátrica e reconhecer recorrência.","expected":"Sintomas podem repetir; plano depende da avaliação.","return":"Retorno programado; antecipar se dor persistir.","alarm":"Febre, icterícia ou vômitos persistentes.","immediate":"Dor intensa ou piora geral exige urgência."}},{"id":"biliar-complicado","label":"Colecistite, obstrução ou pancreatite suspeita","when":"Dor com sinais inflamatórios, icterícia ou exames sugestivos de complicação.","setting":"hospital","overrides":{"diagnosis":"Avaliação hospitalar e cirúrgica; não tratar como cólica simples.","expected":"Evolução depende da complicação e da resposta.","return":"Seguimento após estabilização e plano definitivo.","alarm":"Piora da dor, febre ou desidratação.","immediate":"Encaminhe imediatamente; não aguarde retorno eletivo."}}]},"revisedAt":"2026-09-27"},
{"name":"Cólera em Pediatria","aliases":["Cólera"],"setting":"urgent","general":"Procure atendimento rapidamente diante de diarreia aquosa volumosa. Se a criança estiver alerta e conseguir beber, inicie solução de reidratação preparada corretamente enquanto busca assistência.","diagnosis":"Cólera pode causar perda muito rápida de água e sais; a gravidade depende principalmente da desidratação.","expected":"Com reidratação adequada, a recuperação costuma ser favorável, mas formas graves podem piorar em poucas horas.","alarm":"Sede intensa, vômitos, pouca urina ou fraqueza indicam necessidade de reavaliação urgente.","immediate":"Sonolência, incapacidade de beber, desmaio ou extremidades frias exigem emergência.","return":"Siga o acompanhamento e as orientações sanitárias sobre água, alimentos, higiene e contatos.","sources":[{"url":"https://www.who.int/news-room/fact-sheets/detail/cholera","title":"Organização Mundial da Saúde — Cholera","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Colestase em Pediatria","aliases":["Colestase"],"setting":"urgent","general":"Colestase é sempre patológica. Observe cor das fezes, urina, icterícia, alimentação e crescimento; leve exames e lista de medicamentos.","diagnosis":"A causa depende da idade. Icterícia prolongada no lactente exige bilirrubina fracionada; ultrassom normal não exclui toda doença biliar.","expected":"Não há prazo único: evolução e reversibilidade dependem da causa e da rapidez do diagnóstico.","alarm":"Fezes muito claras, urina escura, piora da icterícia, prurido ou crescimento insuficiente exigem avaliação.","immediate":"Sangramento, sonolência, febre com dor abdominal, vômitos persistentes ou deterioração exigem hospital.","return":"Seguimento clínico, nutricional e laboratorial deve ser individualizado.","sources":[{"url":"https://www.analesdepediatria.org/en-download-pdf-S234128792500417X","title":"SEGHNP/AEPap/SEPEAP — Assessment and Management of Cholestasis: Consensus Document (2025)","accessed":"2026-09-27"},{"url":"https://www.naspghan.org/files/documents/pdfs/position-papers/Guideline_for_the_Evaluation_of_Cholestatic.23.pdf","title":"NASPGHAN/ESPGHAN — Evaluation of Cholestatic Jaundice in Infants (2017)","accessed":"2026-09-27"},{"url":"https://naspghan.org/wp-content/uploads/2019/09/JPGN_Nutrition_Support_of_Children_With_Chronic_Liver.23.pdf","title":"NASPGHAN/ESPGHAN — Nutrition Support of Children With Chronic Liver Diseases (2019)","accessed":"2026-09-27"}],"reviewNotes":"Lacuna etária suprida por consenso pediátrico amplo, mantendo ramo específico de lactentes. Não seleciona tratamento etiológico nem suplementação empírica. Revisão documental assistida, sem homologação humana.","status":"source-reviewed","evidenceSummary":"Consenso de 2025 para crianças/adolescentes, diretriz de lactentes e posição sobre nutrição na hepatopatia crônica. Recomendações combinam literatura e consenso especialista; evidência nutricional é limitada e etiologias raras diferem. Nenhum documento autoriza tratamento único para toda colestase.","decisionSupport":{"summary":"Idade, gravidade e causa definem destino; lactente aparentemente bem ainda pode ter doença tempo-dependente.","requirements":["Idade e início da icterícia","Fezes, urina e bilirrubina fracionada","Coagulação, glicose e função hepática","Sinais sistêmicos, imagem e causa estabelecida"],"branchRequired":true,"branches":[{"id":"colestase-lactente","label":"Lactente com suspeita ou confirmação","when":"Lactente com colestase confirmada ou forte suspeita, especialmente fezes acólicas.","setting":"hospital","overrides":{"diagnosis":"Avaliar prontamente; excluir atresia biliar e outras causas sem aguardar piora.","expected":"Boa aparência não exclui doença grave.","return":"Encaminhamento imediato à referência pediátrica/hepatológica.","alarm":"Fezes esbranquiçadas ou sangramento.","immediate":"Procure hospital; não espere semanas por retorno."}},{"id":"colestase-aguda","label":"Quadro agudo ou sinais de complicação","when":"Criança maior com deterioração, possível obstrução, infecção ou falência hepática.","setting":"hospital","overrides":{"diagnosis":"Investigar e monitorizar em hospital.","expected":"Depende da causa e da estabilização.","return":"Plano etiológico após fase aguda.","alarm":"Alteração da consciência, sangramento ou febre com dor.","immediate":"Atendimento hospitalar imediato."}},{"id":"colestase-cronica","label":"Causa crônica conhecida, clinicamente estável","when":"Criança maior com diagnóstico estabelecido e sem sinais de descompensação.","setting":"specialist","overrides":{"diagnosis":"Acompanhar crescimento, prurido e estado nutricional; suplementos somente individualizados.","expected":"Pode exigir acompanhamento prolongado.","return":"Hepatologia/nutrição com exames conforme doença.","alarm":"Piora de prurido, peso, icterícia ou distensão.","immediate":"Sangramento, sonolência ou piora súbita exigem hospital."}}]},"revisedAt":"2026-09-27"},
{"name":"Comunicação interatrial","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento cardiológico mesmo quando a criança parece bem. Leve resultados dos ecocardiogramas e informe cansaço durante mamadas ou brincadeiras.","diagnosis":"A comunicação entre os átrios pode ter tamanhos diferentes. O médico avalia se basta observar ou se é necessário fechamento; medicamentos não fecham o defeito.","expected":"Alguns defeitos pequenos podem fechar, mas outros persistem. Mesmo após fechamento, a necessidade de seguimento é definida pela cardiologia.","alarm":"Observe infecções respiratórias frequentes, dificuldade para crescer, palpitações, cansaço desproporcional ou inchaço.","immediate":"Falta de ar importante, desmaio, coloração azulada nova ou palpitação acompanhada de mal-estar intenso requerem emergência.","return":"Cumpra os retornos programados e confirme atividades permitidas e cuidados após procedimentos; antecipe avaliação se aparecerem sintomas novos.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/atrial-septal-defect.html","title":"CDC — Atrial Septal Defect","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Comunicação interventricular","aliases":["Comunicação Interventricular (CIV)"],"setting":"specialist","general":"Mantenha consultas cardiológicas, acompanhamento do peso e observação das mamadas. Siga apenas as restrições de líquidos ou atividades definidas para a criança.","diagnosis":"O tamanho, localização e repercussão da comunicação determinam a necessidade de observação ou correção. Um sopro isolado não informa a gravidade.","expected":"Defeitos pequenos podem fechar espontaneamente; outros exigem intervenção. A evolução deve ser acompanhada pelo cardiologista.","alarm":"Observe suor e cansaço para mamar, respiração acelerada, baixa ingestão e dificuldade de ganhar peso.","immediate":"Lábios azulados, falta de ar importante, desmaio ou prostração intensa exigem atendimento imediato.","return":"Antecipe o retorno se a alimentação ou o crescimento piorarem; mantenha o calendário de exame clínico e ecocardiograma.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/ventricular-septal-defect.html","title":"CDC — Ventricular Septal Defect","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Condiloma acuminado infantil","aliases":[],"setting":"specialist","general":"Procure avaliação pediátrica especializada, preserve a privacidade da criança e não aplique produtos caseiros ou tratamentos para verrugas comuns na região genital. Evite manipular as lesões.","diagnosis":"Verrugas anogenitais na infância têm diferentes possibilidades de transmissão. O achado isolado não prova violência, mas exige investigação cuidadosa por profissionais capacitados e proteção quando houver suspeita.","expected":"A evolução e a escolha entre observar ou tratar dependem da extensão, sintomas e contexto. Recorrência pode ocorrer e requer seguimento.","alarm":"Dor, sangramento, secreção, dificuldade para urinar ou aumento importante das lesões exigem revisão.","immediate":"Sangramento intenso, dor aguda, retenção urinária ou risco atual à segurança da criança: atendimento imediato.","return":"Combine retorno com pediatria e dermatologia; exames adicionais e medidas de proteção são individualizados.","sources":[{"url":"https://www.cdc.gov/std/treatment-guidelines/sexual-assault-children.htm","title":"CDC — Sexual Assault or Abuse of Children: STI Treatment Guidelines","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Fonte principal fundamenta avaliação pediátrica/proteção; modalidades terapêuticas e prazos de resolução não foram definidos.","status":"source-reviewed"},
{"name":"Conjuntivite em Pediatria","aliases":["Conjuntivite"],"setting":"home","general":"Higienize as mãos e remova secreções suavemente com material limpo. Evite compartilhar toalhas ou colírios e suspenda lentes de contato até avaliação.","diagnosis":"Olho vermelho pode ter causas virais, bacterianas, alérgicas ou outras; nem todo caso necessita antibiótico.","expected":"A duração depende da causa; persistência ou piora exige reconsiderar o diagnóstico.","alarm":"Dor, sensibilidade à luz, edema importante ou dificuldade para abrir o olho são sinais de alerta.","immediate":"Redução da visão, dor intensa, trauma ocular ou olho vermelho no recém-nascido exigem avaliação imediata.","return":"Retorne se não melhorar conforme o plano ou surgirem novos sintomas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_red_eye/","title":"Royal Children’s Hospital — Acute red eye","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Conjuntivite neonatal por Chlamydia","setting":"urgent","general":"Infecção ocular do recém-nascido geralmente adquirida no parto; requer avaliação para proteger os olhos e pesquisar infecção associada.","diagnosis":"Procure avaliação no mesmo dia e cumpra todo o tratamento indicado; cuidados apenas na superfície do olho podem ser insuficientes. A equipe também orientará avaliação materna e dos contatos pertinentes.","expected":"A melhora precisa ser confirmada em revisão. Infecção respiratória pode coexistir ou aparecer depois; tosse, respiração rápida e dificuldade para mamar exigem nova avaliação.","alarm":"Dificuldade respiratória, febre, prostração, recusa alimentar, piora do inchaço ou alteração ocular exigem urgência.","immediate":"Recém-nascido com conjuntivite deve ser visto no mesmo dia por serviço de saúde; higiene das mãos reduz transmissão.","return":"Retornar para reavaliação conforme orientação e imediatamente se houver sinais respiratórios ou piora ocular.","sources":[{"url":"https://www.cdc.gov/std/treatment-guidelines/chlamydia.htm","title":"CDC — Chlamydial Infections: STI Treatment Guidelines","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Conjuntivite neonatal por Neisseria gonorrhoeae","aliases":[],"setting":"hospital","general":"O recém-nascido necessita de avaliação imediata em serviço com atendimento pediátrico e oftalmológico. Não aguarde resposta a colírios usados em casa.","diagnosis":"A infecção pode lesar a córnea e se disseminar. O tratamento sistêmico e a investigação de outras infecções devem ser definidos pela equipe; terapia tópica isolada não basta.","expected":"O desfecho depende do início rápido do tratamento e da presença de complicações oculares ou sistêmicas.","alarm":"Observe secreção purulenta intensa, inchaço das pálpebras, alteração da superfície do olho, febre, pouca resposta ou dificuldade para mamar.","immediate":"Procure emergência já diante da suspeita; comunique imediatamente piora da respiração, convulsões ou redução da resposta.","return":"Após estabilização, mantenha revisão ocular e pediátrica. A mãe e parceiros devem receber avaliação e tratamento para interromper a transmissão.","sources":[{"url":"https://www.cdc.gov/std/treatment-guidelines/gonorrhea-neonates.htm","title":"CDC — Gonococcal infections among neonates","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Conjuntivite neonatal química","aliases":[],"setting":"urgent","general":"Todo recém-nascido com olhos vermelhos, inchados ou com secreção deve ser avaliado prontamente. Lave as mãos antes de tocar o rosto.","diagnosis":"A irritação química após colírios do nascimento pode parecer uma infecção. Não presuma a causa sem avaliação nem coloque leite, receitas caseiras ou colírios não prescritos.","expected":"Quando a causa química é confirmada, a irritação costuma desaparecer em 24–36 horas; persistência ou piora exige reconsiderar o diagnóstico.","alarm":"Aumento da vermelhidão, secreção espessa, inchaço importante ou dificuldade para abrir os olhos são sinais de atenção.","immediate":"Febre, prostração, recusa alimentar, alteração aparente da córnea ou piora rápida exigem emergência imediata.","return":"Reavalie no prazo definido e retorne antes se não houver melhora esperada ou surgir secreção purulenta.","sources":[{"url":"https://www.cdc.gov/conjunctivitis/newborns/index.html","title":"CDC — Pink Eye in Newborns","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Constipação Intestinal em Pediatria","aliases":[],"setting":"home","general":"Crie rotina tranquila para evacuar, com apoio para os pés, alimentação variada e líquidos habituais; não castigue escapes fecais.","diagnosis":"Na constipação funcional pode haver retenção e fezes endurecidas; dieta isolada nem sempre desfaz o acúmulo.","expected":"A recuperação pode exigir meses de tratamento e acompanhamento; não suspenda o plano ao primeiro dia sem sintomas.","alarm":"Informe dor persistente, sangue recorrente, crescimento insuficiente ou sintomas desde o período neonatal.","immediate":"Barriga muito distendida com vômitos verdes ou deterioração geral exige pronto atendimento.","return":"Retorne para ajustar o plano e o diário intestinal, principalmente se evacuações continuarem dolorosas ou houver recaídas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Constipation_Guideline/","title":"RCH — Constipation","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Constipação intestinal funcional","aliases":[],"setting":"home","general":"Ofereça alimentação variada, água conforme idade e rotina tranquila para evacuar após refeições, com apoio para os pés. Elogie o esforço, sem castigos.","diagnosis":"Retenção por medo ou dor e escape de fezes podem fazer parte da constipação. Siga o plano de desimpactação/manutenção quando prescrito.","expected":"A recuperação pode exigir tratamento prolongado; interromper assim que surge uma evacuação favorece recaída.","alarm":"Observe dor persistente, sangue recorrente, perda de peso ou dificuldade de crescimento.","immediate":"Dor abdominal forte com distensão e vômitos, especialmente verdes, exige avaliação imediata.","return":"Retorne para ajustar o plano se as fezes continuarem duras, dolorosas ou com escapes; lactentes devem ser avaliados antes de medidas medicamentosas.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Constipation/","title":"RCH — Constipation","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Coqueluche","aliases":["Coqueluche em Pediatria"],"setting":"urgent","general":"Procure avaliação médica e informe contato com pessoas tossindo, vacinação e duração dos sintomas. Mantenha distância de lactentes e siga a orientação do serviço para afastamento e avaliação dos contatos.","diagnosis":"Crises de tosse podem causar vômitos e interromper a respiração; bebês, especialmente pequenos, precisam de vigilância mais intensa e podem necessitar internação. Não tente suprimir as crises com medicação por conta própria.","expected":"A tosse pode persistir por semanas, mesmo durante a recuperação; melhora lenta não elimina a necessidade de observar respiração e alimentação.","alarm":"Vômitos repetidos, dificuldade para mamar, pouca urina e exaustão devem ser reavaliados rapidamente.","immediate":"Apneia, coloração azulada, convulsão ou dificuldade respiratória: emergência imediata.","return":"Retorne na data definida e antes dela se as crises impedirem a alimentação ou houver piora clínica.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/c/coqueluche","title":"Ministério da Saúde — Coqueluche","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Coreia de Sydenham","setting":"specialist","general":"Movimentos involuntários relacionados à febre reumática após infecção estreptocócica; pode afetar fala, marcha, escrita e emoções.","diagnosis":"Proteja a criança de quedas e facilite atividades escolares e alimentação conforme suas limitações. Mantenha acompanhamento cardíaco e neurológico; mudanças emocionais devem ser acolhidas, sem punição pelos movimentos.","expected":"Os movimentos podem oscilar e melhorar ao longo de meses, mas recorrências são possíveis. Mesmo com melhora motora, a necessidade de seguimento cardíaco e prevenção individual permanece.","alarm":"Incapacidade de andar ou alimentar-se, engasgos, confusão, convulsão, falta de ar ou dor no peito exigem atendimento urgente.","immediate":"Encaminhar para pediatria especializada para confirmar causa e procurar comprometimento cardíaco; proteger a criança de quedas.","return":"Acompanhar com pediatria e cardiologia conforme plano; retornar se movimentos, comportamento ou sintomas cardíacos piorarem.","sources":[{"url":"https://medlineplus.gov/ency/article/001358.htm","title":"MedlinePlus — Sydenham chorea","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Coriorretinite","aliases":["Coriorretinite"],"setting":"urgent","general":"Procure oftalmologia prontamente. Leve exames anteriores e informe infecções, imunossupressão e alterações visuais, mesmo discretas.","diagnosis":"Inflamação de retina e coroide pode ser infecciosa ou não infecciosa. Atividade, localização e causa precisam ser avaliadas antes de orientar tratamento.","expected":"A recuperação visual varia; cicatrizes e recorrências são possíveis. Crianças podem não perceber ou relatar perda visual.","alarm":"Visão embaçada, manchas móveis, fotofobia ou dor exigem avaliação rápida.","immediate":"Perda súbita da visão exige emergência oftalmológica.","return":"Mantenha revisões para atividade, visão, pressão ocular e efeitos do tratamento; não reutilize colírios por conta própria.","sources":[{"url":"https://www.nhs.uk/conditions/uveitis/","title":"NHS — Uveitis","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/toxoplasmosis/hcp/clinical-care/index.html","title":"CDC — Clinical care of toxoplasmosis, 2026","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/37357450/","title":"Tuğal-Tutkun — An overview of pediatric uveitis, 2023","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD002218_antibiotics-compared-no-treatment-or-placebo-treatment-toxoplasma-retinochoroiditis","title":"Cochrane — Toxoplasma retinochoroiditis, CD002218","accessed":"2026-09-27"}],"reviewNotes":"Escopo ampliado por etiologia e atividade; não presume toxoplasmose universal. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"Revisão pediátrica narrativa, orientação oficial e revisão sistemática. Crianças com uveíte; ensaios de toxoplasmose incluem adultos. Etiologias heterogêneas; benefício visual dos tratamentos não é uniforme.","decisionSupport":{"summary":"Selecione causa e atividade definidas pelo oftalmologista; a aparência descrita em mensagem não confirma etiologia.","requirements":["Idade e imunidade","Acuidade visual e localização da lesão","Atividade versus cicatriz","Etiologia investigada e manifestações sistêmicas"],"branchRequired":true,"branches":[{"id":"infectious","label":"Inflamação infecciosa ativa","when":"Infecção identificada ou suspeita fundamentada.","setting":"urgent","overrides":{"diagnosis":"Investigue o agente e possível infecção congênita; toxoplasmose não representa todas as causas.","expected":"Resposta depende do agente e extensão.","return":"Oftalmologia e infectologia quando indicada.","alarm":"Piora visual ou sistêmica.","immediate":"Perda visual súbita: emergência."}},{"id":"noninfectious","label":"Inflamação não infecciosa","when":"Causa inflamatória estabelecida após investigação.","setting":"specialist","overrides":{"diagnosis":"Avalie associação sistêmica com equipe pediátrica.","expected":"Pode exigir controle prolongado.","return":"Vigie inflamação e complicações oculares.","alarm":"Sintomas novos ou piora visual.","immediate":"Perda visual súbita: emergência."}},{"id":"inactive","label":"Lesão cicatricial inativa","when":"Inatividade confirmada no exame.","setting":"specialist","overrides":{"diagnosis":"Cicatriz toxoplásmica isolada não indica tratar infecção ativa.","expected":"Déficit visual residual pode persistir.","return":"Mantenha vigilância de recorrência.","alarm":"Novas manchas ou visão pior.","immediate":"Perda súbita: avaliação imediata."}}]},"revisedAt":"2026-09-27"},
{"name":"Coronavírus (Covid-19) em Pediatria","setting":"home","aliases":["Covid-19","COVID-19"],"general":"A maioria das crianças apresenta doença leve, mas algumas necessitam avaliação rápida por risco de complicações.","diagnosis":"Ofereça líquidos e repouso conforme tolerância. Siga recomendações locais de prevenção e procure avaliação precoce se houver condição de maior risco.","expected":"A recuperação varia; sintomas persistentes ou nova febre após melhora precisam de revisão.","alarm":"Dificuldade respiratória, desidratação, sonolência incomum ou febre persistente com dor abdominal e manchas são alarmes.","immediate":"Procure emergência com falta de ar importante, confusão ou dificuldade para despertar.","return":"Retorne se piorar ou não recuperar atividades habituais; mantenha acompanhamento dos sintomas prolongados.","sources":[{"url":"https://www.cdc.gov/covid/hcp/clinical-care/for-pediatric-hcp.html","title":"CDC — Information for Pediatric Healthcare Providers: COVID-19","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Costocondrite em Pediatria","aliases":["Costocondrite"],"setting":"home","general":"Após avaliação que confirme causa musculoesquelética, reduza temporariamente atividades que reproduzem a dor e retome-as gradualmente conforme tolerado.","diagnosis":"Costocondrite costuma causar dor localizada reproduzida à palpação ou ao movimento; não é possível confirmar apenas pela descrição de dor no peito.","expected":"A evolução é variável, e persistência exige revisão do diagnóstico e do plano.","alarm":"Relate dor aos esforços, febre, palpitações ou mudança do padrão.","immediate":"Falta de ar, desmaio ou dor torácica intensa e diferente exigem emergência.","return":"Retorne se não houver melhora conforme orientado ou se a dor limitar escola, sono e atividades.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/chest_pain/","title":"Royal Children’s Hospital — Chest pain","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Criptorquidia","aliases":[],"setting":"specialist","general":"Mantenha as consultas pediátricas para confirmar a localização dos testículos e encaminhamento à cirurgia/urologia pediátrica. Não tente puxar ou massagear o testículo.","diagnosis":"É necessário distinguir testículo não descido de testículo retrátil. A persistência fora do escroto pode exigir correção cirúrgica, com planejamento na infância.","expected":"Alguns descem nos primeiros meses, mas ausência persistente precisa de avaliação; não é adequado esperar indefinidamente pela descida espontânea.","alarm":"Observe dor ou inchaço na virilha/escroto, vermelhidão ou surgimento de massa dolorosa.","immediate":"Dor súbita, especialmente com vômitos, exige pronto atendimento para excluir torção ou outra urgência, mesmo sem testículo visível no escroto.","return":"Compareça ao especialista no prazo orientado e mantenha revisão após cirurgia. O acompanhamento permite discutir fertilidade e riscos futuros conforme o caso.","sources":[{"url":"https://www.nhs.uk/conditions/undescended-testicles/","title":"NHS — Undescended testicles","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental; diagnóstico diferencial e prazo cirúrgico devem ser individualizados. Não confundir com testículo ectópico ou retrátil.","status":"source-reviewed"},
{"name":"Crise Convulsiva em Pediatria","aliases":[],"setting":"urgent","general":"Afaste objetos perigosos, proteja a cabeça e marque o tempo; não contenha os movimentos nem coloque objetos na boca.","diagnosis":"Uma crise isolada não confirma epilepsia; a causa e o estado após o episódio precisam de avaliação.","expected":"A recuperação depende da causa; sonolência pode ocorrer, mas ausência de recuperação exige atendimento.","alarm":"Observe respiração, lesões e novas crises; informe medicamentos de resgate já administrados.","immediate":"Acione socorro na primeira crise, se durar cinco minutos, repetir sem recuperação ou houver dificuldade respiratória.","return":"Após avaliação, receba plano de ação e supervisão em atividades com água ou altura.","sources":[{"url":"https://www.rch.org.au/afebrile_seizures/","title":"RCH — Seizures acute management","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Seizures_safety_issues_and_how_to_help/","title":"RCH Kids Health Info — Seizures safety issues and how to help","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Primeira fonte lida por redirecionamento da página RCH afebrile_seizures; limiar de cinco minutos baseado na diretriz clínica.","status":"source-reviewed"},
{"name":"Crise febril complexa","aliases":[],"setting":"urgent","general":"Durante uma crise, proteja a criança de quedas, coloque-a de lado quando possível e marque o tempo. Não coloque objetos na boca nem ofereça líquidos.","diagnosis":"Crise prolongada, focal ou repetida no mesmo episódio febril precisa de avaliação pediátrica para investigar a causa da febre e outros diagnósticos.","expected":"O prognóstico depende das características da crise e da avaliação. Uma crise febril complexa não significa automaticamente epilepsia.","alarm":"Persistência de sonolência fora do esperado, fraqueza de um lado, rigidez de nuca ou nova crise são sinais preocupantes.","immediate":"Acione emergência se a crise durar cinco minutos, houver dificuldade respiratória ou a criança não recuperar a consciência.","return":"Após o atendimento, mantenha o retorno recomendado e um plano escrito para novas crises, quando indicado.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Febrile_seizure/","title":"RCH — Febrile seizure","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Crise febril simples","aliases":[],"setting":"home","general":"Durante uma crise, proteja a cabeça, afaste objetos e marque o tempo. Não contenha movimentos nem coloque objetos, água ou medicamentos na boca.","diagnosis":"A classificação como crise febril simples exige avaliação. Procure a causa da febre e ofereça líquidos apenas quando a criança estiver plenamente desperta.","expected":"A maioria é breve e a criança recupera progressivamente a interação; pode haver recorrência em futuras febres.","alarm":"Sonolência persistente, crise focal, repetição no mesmo episódio ou sinais de doença grave precisam de reavaliação.","immediate":"Acione emergência na primeira crise, duração de cinco minutos, dificuldade respiratória ou recuperação inadequada.","return":"Retorne para revisar a causa da febre; medicamentos para febre aliviam desconforto, mas não garantem prevenção de outra crise.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Febrile_convulsions/","title":"RCH — Febrile seizures","accessed":"2026-09-26"}],"reviewNotes":"Aplicável somente após confirmação clínica de crise simples; não confundir faixa usual com diagnóstico obrigatório.","status":"source-reviewed"},
{"name":"Crise Hipertensiva na Infância","setting":"hospital","aliases":["Crise hipertensiva"],"general":"Pressão muito elevada com sintomas pode representar emergência e lesar cérebro, coração ou rins.","diagnosis":"Procure avaliação presencial; leve registros de pressão e tratamentos usados. Não tente reduzir a pressão rapidamente em casa.","expected":"A estabilização é monitorada e depende da causa e de lesão de órgãos; a redução deve ser controlada.","alarm":"Cefaleia intensa, alteração visual, vômitos, pouca urina ou falta de ar são alarmes.","immediate":"Convulsão, confusão, desmaio ou dificuldade respiratória exigem emergência imediatamente.","return":"Após estabilização, mantenha seguimento pediátrico ou renal e plano escrito de monitorização; retorne antes se os sintomas voltarem.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hypertension/","title":"RCH — Hypertension in children and adolescents","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Crises Falcêmicas em Pediatria","aliases":["Crise falcêmica"],"setting":"urgent","general":"Siga o plano individual da hematologia e procure avaliação se a dor não responder ao cuidado previamente prescrito.","diagnosis":"Crises dolorosas, infecções e complicações pulmonares ou neurológicas exigem abordagens diferentes. Dor torácica não deve ser presumida como dor habitual.","expected":"A evolução depende do tipo de crise; complicações podem progredir rapidamente.","alarm":"Observe febre, palidez acentuada, cansaço, aumento abdominal ou dor diferente do padrão.","immediate":"Falta de ar, dor torácica, alteração da fala ou força e prostração importante exigem emergência.","return":"Retorne conforme orientação após cada episódio e mantenha prevenção, vacinação e seguimento hematológico.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/sickle_cell_disease_guideline/","title":"RCH — Sickle cell disease","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"CRMO","setting":"specialist","aliases":["Osteomielite crônica recorrente multifocal","Osteíte crônica não bacteriana"],"general":"Inflamação óssea autoinflamatória não é uma infecção; requer acompanhamento de reumatologia.","diagnosis":"Siga orientações de atividade conforme os ossos acometidos e cumpra exames de imagem, mesmo quando a dor diminuir.","expected":"Pode haver remissão ou recorrências; dor persistente nem sempre significa inflamação ativa e precisa de reavaliação.","alarm":"Dor nova na coluna, perda de função ou febre durante imunossupressão são alarmes.","immediate":"Fraqueza de membros, incapacidade súbita de andar ou perda do controle urinário exigem emergência.","return":"Mantenha seguimento e discuta limitações esportivas, sobretudo se houver acometimento vertebral.","sources":[{"url":"https://rheumatology.org/patients/chronic-recurrent-multifocal-osteomyelitis-crmo","title":"ACR — Chronic Recurrent Multifocal Osteomyelitis (CRMO)","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Crupe em Pediatria","aliases":["Crupe","Laringotraqueobronquite viral"],"setting":"home","general":"Após avaliação de quadro leve, mantenha a criança calma e junto do responsável. Observe a respiração sem provocar agitação.","diagnosis":"Tosse rouca e ruído ao inspirar sugerem crupe; apresentações atípicas, sobretudo em bebês pequenos, exigem reavaliação.","expected":"A intensidade pode variar, e piora respiratória muda a necessidade de atendimento.","alarm":"Observe ruído respiratório em repouso, esforço para respirar ou dificuldade de beber.","immediate":"Sonolência, palidez, coloração azulada ou exaustão exige emergência. Ruído mais fraco com piora geral não indica melhora.","return":"Retorne se os sintomas piorarem ou voltarem após tratamento; alta depende da avaliação clínica.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Croup_Laryngotracheobronchitis/","title":"RCH — Croup","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Crupe espasmódico","aliases":[],"setting":"home","general":"Após avaliação que permita cuidado domiciliar, mantenha a criança calma, ofereça líquidos se conseguir engolir e observe a respiração, inclusive à noite. Evite vapor quente, pelo risco de queimadura.","diagnosis":"Tosse rouca e ruído ao inspirar podem ocorrer no crupe. Episódios chamados espasmódicos ou recorrentes precisam de avaliação própria; não presumir infecção nem atribuir toda tosse a esse diagnóstico.","expected":"O crupe espasmódico pode começar abruptamente à noite e voltar em outros momentos. Episódios persistentes ou recorrentes precisam de avaliação, sem presumir que sejam sempre leves.","alarm":"Ruído respiratório em repouso, dificuldade para beber ou piora durante a noite requerem avaliação rápida.","immediate":"Grande esforço para respirar, saliva escorrendo com dificuldade para engolir, coloração azulada ou sonolência: emergência.","return":"Retorne se piorar, se não melhorar ou se os episódios voltarem.","sources":[{"url":"https://www.nhs.uk/conditions/croup/","title":"NHS — Croup","accessed":"2026-09-26"},{"url":"https://www.healthychildren.org/English/health-issues/conditions/chest-lungs/Pages/Croup-Treatment.aspx","title":"American Academy of Pediatrics — Croup in Young Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica. Fonte adicional da AAP aborda especificamente crupe espasmódico; não foram extrapoladas hipóteses causais para tratamento automático.","status":"source-reviewed"},
{"name":"Defeito do Tubo Neural no Período Neonatal","aliases":[],"setting":"hospital","general":"O recém-nascido precisa de avaliação neonatal para definir anatomia, estabilidade e cuidados com a família.","diagnosis":"Classifique o defeito antes de emitir orientações. Lesões espinhais abertas, encefalocele e anencefalia têm necessidades diferentes.","expected":"O prognóstico depende da estrutura envolvida, comprometimento neurológico e malformações associadas.","alarm":"Comunique alteração da alimentação, movimentos, respiração ou nível de resposta.","immediate":"Apneia, convulsão ou deterioração aguda exige atendimento neonatal imediato, respeitando eventual plano de cuidados já pactuado.","return":"Organize seguimento e apoio familiar conforme o tipo confirmado; não há plano único de alta.","sources":[{"url":"https://www.cdc.gov/birth-defects/about/neural-tube-defects.html","title":"CDC — Neural tube defects, 2025","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/spina-bifida/about/index.html","title":"CDC — About spina bifida, 2025","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/spina-bifida/treatment/index.html","title":"CDC — Manage spina bifida","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/birth-defects/about/encephalocele.html","title":"CDC — Encephalocele, 2026","accessed":"2026-09-27"},{"url":"https://www.gov.uk/government/publications/anencephaly-description-in-brief/anencephaly-information-for-parents","title":"NHS England — Anencephaly: information for parents, 2026","accessed":"2026-09-27"}],"reviewNotes":"Inclui defeitos cranianos e espinhais, preservando objetivos individualizados. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"Orientações oficiais por defeito anatômico. Fetos, recém-nascidos e crianças afetadas. Não predizem resultado individual nem determinam técnica cirúrgica.","decisionSupport":{"summary":"Selecionar o defeito anatômico confirmado; não inferir o prognóstico apenas pelo título.","requirements":["Tipo, cobertura e localização da lesão","Hidrocefalia e função neurológica/urinária","Estabilidade neonatal e plano familiar"],"branchRequired":true,"branches":[{"id":"open_spinal","label":"Defeito espinhal aberto","when":"Mielomeningocele ou lesão aberta confirmada.","setting":"hospital","overrides":{"diagnosis":"Necessita neurocirurgia e proteção orientada presencialmente.","expected":"Déficits podem persistir após fechamento.","return":"Seguimento neurológico, urinário e motor.","alarm":"Mudanças urinárias ou aumento cefálico.","immediate":"Febre ou piora neurológica: emergência."}},{"id":"closed_spinal","label":"Defeito espinhal fechado","when":"Defeito coberto, após classificação especializada.","setting":"specialist","overrides":{"diagnosis":"Espinha bífida oculta pode ser assintomática.","expected":"Depende de comprometimento neural associado.","return":"Revisões conforme função e anatomia.","alarm":"Fraqueza ou alteração urinária.","immediate":"Deterioração aguda: avaliação imediata."}},{"id":"encephalocele","label":"Encefalocele","when":"Protrusão craniana confirmada.","setting":"hospital","overrides":{"diagnosis":"Neurocirurgia define correção conforme conteúdo e localização.","expected":"Cirurgia não elimina necessariamente déficits.","return":"Acompanhe desenvolvimento e hidrocefalia.","alarm":"Convulsões ou piora funcional.","immediate":"Redução da resposta: emergência."}},{"id":"anencephaly","label":"Anencefalia","when":"Diagnóstico confirmado pela equipe.","setting":"hospital","overrides":{"diagnosis":"Planeje conforto e apoio à família.","expected":"Condição sem cura, com sobrevivência geralmente breve.","return":"Apoio contínuo e aconselhamento familiar.","alarm":"Sinais de desconforto.","immediate":"Acione a equipe conforme plano pactuado."}}]},"revisedAt":"2026-09-27"},
{"name":"Defeitos do Septo Ventricular (DSV)","aliases":["Defeito do septo ventricular"],"setting":"specialist","general":"Mantenha consultas cardiológicas e observe crescimento, mamadas e tolerância às atividades.","diagnosis":"Corresponde à comunicação interventricular. O tamanho, a localização e outras cardiopatias determinam sua repercussão.","expected":"Defeitos pequenos podem fechar espontaneamente; outros precisam de intervenção. A evolução não é igual em todos.","alarm":"Observe cansaço alimentar, respiração rápida, sudorese ou ganho de peso insuficiente.","immediate":"Falta de ar importante, coloração azulada ou redução da resposta exige emergência.","return":"Retorne para ecocardiogramas conforme orientação, mesmo sem sintomas. Se integrar cardiopatia complexa, siga o plano anatômico específico e antecipe revisão diante de piora.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/ventricular-septal-defect.html","title":"CDC — Ventricular septal defect","accessed":"2026-09-26"}],"reviewNotes":"Equivalência terminológica DSV = CIV; não extrapola fechamento isolado para circulação complexa. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Defeitos no Metabolismo da Fenilalanina","aliases":["Distúrbios do metabolismo da fenilalanina"],"setting":"specialist","general":"Teste do pezinho alterado exige contato rápido com o centro metabólico. Não modifique toda a alimentação sem plano especializado.","diagnosis":"É necessário distinguir fenilcetonúria e alterações de cofatores como BH4, pois o cuidado não é idêntico.","expected":"O tratamento precoce e o controle continuado ajudam a proteger o desenvolvimento; acompanhamento é prolongado e individual.","alarm":"Observe dificuldades alimentares, perda de habilidades, movimentos anormais ou mudanças importantes do comportamento.","immediate":"Convulsão, alteração de consciência ou dificuldade importante de engolir exige pronto atendimento.","return":"Siga controles de fenilalanina, nutrição, crescimento e desenvolvimento, ajustando o plano durante intercorrências e fases do crescimento.","sources":[{"url":"https://www.nhs.uk/conditions/phenylketonuria/","title":"NHS/GOV.UK — Phenylketonuria: detailed information","accessed":"2026-09-26"},{"url":"https://medlineplus.gov/genetics/condition/tetrahydrobiopterin-deficiency/","title":"MedlinePlus Genetics — Tetrahydrobiopterin deficiency","accessed":"2026-09-26"}],"reviewNotes":"Fonte de fenilcetonúria complementada com BH4 para não universalizar dieta como único tratamento.","status":"source-reviewed"},
{"name":"Defeitos no Metabolismo da Galactose","aliases":["Distúrbios do metabolismo da galactose"],"setting":"specialist","general":"Siga o plano alimentar do centro metabólico e não faça substituições sem orientação. A suspeita em recém-nascido requer avaliação imediata.","diagnosis":"Existem diferentes defeitos do metabolismo da galactose. A forma clássica e variantes menos graves não devem receber o mesmo plano automaticamente.","expected":"O cuidado depende do defeito confirmado; a forma clássica exige acompanhamento prolongado, mesmo com controle alimentar.","alarm":"Observe dificuldade alimentar, vômitos, icterícia, baixo ganho de peso ou alteração da disposição.","immediate":"Prostração, febre, sangramento ou piora rápida em bebê exige emergência.","return":"Mantenha revisão metabólica, nutricional e do desenvolvimento; reavalie a dieta durante crescimento e intercorrências.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5306419/","title":"GalNet — International guideline for classical galactosemia","accessed":"2026-09-26"}],"reviewNotes":"Fonte específica da forma clássica; variantes não foram equiparadas. Protocolo do subtipo deve ser confirmado.","status":"source-reviewed"},
{"name":"Defeitos no Metabolismo da Tirosina","aliases":["Distúrbios do metabolismo da tirosina"],"setting":"specialist","general":"Leve triagem neonatal, exames e plano alimentar à equipe metabólica. Não restrinja proteínas nem use suplementos sem orientação.","diagnosis":"Tirosina elevada isoladamente não identifica o defeito. Confirme subtipo, marcadores bioquímicos e, quando indicado, diagnóstico molecular.","expected":"Evolução depende do defeito e dos órgãos envolvidos; melhora laboratorial não garante recuperação do desenvolvimento.","alarm":"Comunique icterícia, sangramento, vômitos, dor ocular, regressão ou desequilíbrio.","immediate":"Convulsão, dificuldade respiratória ou alteração de consciência exige emergência.","return":"Mantenha nutrição especializada, avaliação do desenvolvimento e vigilância dirigida ao diagnóstico.","sources":[{"url":"https://www.ncbi.nlm.nih.gov/books/NBK1515/","title":"GeneReviews — Tyrosinemia type I, atualização 2025","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/books/NBK608431/","title":"GeneReviews — Tyrosinemia type II, 2024","accessed":"2026-09-27"},{"url":"https://medlineplus.gov/genetics/condition/tyrosinemia/","title":"MedlinePlus Genetics — Tyrosinemia","accessed":"2026-09-27"},{"url":"https://www.scielo.br/j/rpp/a/h6cVZMdw7d9WfdSvYBstNjq/?lang=pt","title":"Tirosinemia tipo III: irmãos e revisão da literatura, Rev Paul Pediatr 2020","accessed":"2026-09-27"},{"url":"https://medlineplus.gov/genetics/condition/alkaptonuria/","title":"MedlinePlus Genetics — Alkaptonuria","accessed":"2026-09-27"}],"reviewNotes":"Ramo não esclarecido mantém investigação, sem plano terapêutico inventado. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"GeneReviews, síntese genética e relato de irmãos. Doenças hereditárias pediátricas; tipo III muito raro. Relatos não comprovam eficácia dietética nem prognóstico uniforme.","decisionSupport":{"summary":"Confirmar o defeito; as recomendações de tirosinemia I não se aplicam a todas as alterações da tirosina.","requirements":["Idade, crescimento e ingestão","Succinilacetona e aminoácidos","Subtipo confirmado","Sinais hepáticos, renais, oculares e neurológicos"],"branchRequired":true,"branches":[{"id":"type_i","label":"Tirosinemia I","when":"Deficiência de FAH confirmada ou forte suspeita especializada.","setting":"specialist","overrides":{"diagnosis":"Siga plano metabólico e de intercorrências; evite jejum prolongado.","expected":"Risco hepático e renal exige vigilância.","return":"Monitore fígado, rins e desenvolvimento.","alarm":"Vômitos ou sangramento.","immediate":"Crise neurológica: hospital."}},{"id":"type_ii","label":"Tirosinemia II","when":"Deficiência de TAT confirmada.","setting":"specialist","overrides":{"diagnosis":"Priorize plano nutricional, olhos e pele.","expected":"Manifestação ocular e cutânea é variável.","return":"Oftalmologia e acompanhamento metabólico.","alarm":"Dor ocular ou fotofobia.","immediate":"Perda visual: urgência."}},{"id":"type_iii","label":"Tirosinemia III","when":"Deficiência de HPD confirmada.","setting":"specialist","overrides":{"diagnosis":"Acompanhe nutrição e neurodesenvolvimento individualmente.","expected":"Há apresentações assintomáticas e neurológicas.","return":"Vigie aprendizagem e função motora.","alarm":"Regressão ou ataxia.","immediate":"Convulsão: emergência."}},{"id":"other","label":"Outro defeito ou alteração transitória","when":"Subtipo diferente ou ainda não esclarecido.","setting":"specialist","overrides":{"diagnosis":"Diferencie imaturidade hepática e outros defeitos, incluindo alcaptonúria.","expected":"Não extrapole prognóstico das tirosinemias.","return":"Confirmação metabólica e plano próprio.","alarm":"Mudança clínica nova.","immediate":"Deterioração aguda: emergência."}}]},"revisedAt":"2026-09-27"},
{"name":"Deficiência de Adenosina Deaminase 2","aliases":["DADA2"],"setting":"specialist","general":"Mantenha seguimento com equipe especializada e leve o histórico de infecções, inflamação e eventos neurológicos.","diagnosis":"A doença pode afetar vasos, sangue e imunidade; manifestações variam mesmo entre familiares.","expected":"O curso é variável e exige vigilância continuada. Ausência de sintomas em um momento não elimina riscos futuros.","alarm":"Informe febre persistente, manchas em rede, infecções frequentes, palidez ou sangramento.","immediate":"Fraqueza súbita, alteração da fala, convulsão ou diminuição da consciência exige emergência por possível comprometimento neurológico.","return":"Siga exames e revisões individualizados; aconselhamento genético e avaliação familiar dependem da equipe.","sources":[{"url":"https://medlineplus.gov/genetics/condition/adenosine-deaminase-2-deficiency/","title":"MedlinePlus Genetics — Adenosine deaminase 2 deficiency","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Deficiência de Biotina","aliases":["Deficiência de vitamina B7"],"setting":"specialist","general":"Mantenha avaliação da causa e a reposição prescrita. Informe o uso de biotina antes de exames, pois suplementos podem alterar resultados laboratoriais.","diagnosis":"Deficiência nutricional e deficiência de biotinidase não são sinônimos; a forma metabólica precisa de investigação e acompanhamento próprios.","expected":"A resposta depende da causa e da precocidade do tratamento; manifestações neurológicas requerem atenção especial.","alarm":"Relate perda de habilidades, sonolência, fraqueza, lesões de pele ou alteração auditiva.","immediate":"Convulsão, dificuldade respiratória ou pouca resposta exigem emergência.","return":"Retorne para avaliar desenvolvimento, resposta e necessidade de tratamento contínuo; não interrompa reposição metabólica sem orientação.","sources":[{"url":"https://ods.od.nih.gov/factsheets/Biotin-HealthProfessional/","title":"NIH Office of Dietary Supplements — Biotin: health professional fact sheet","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/b/biotinidase","title":"Ministério da Saúde — Deficiência de biotinidase","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Preservada distinção entre carência de biotina e defeito enzimático. Biotinidase não foi incluída como sinônimo automático do título.","status":"source-reviewed"},
{"name":"Deficiência de Fator VII","aliases":[],"setting":"specialist","general":"Mantenha plano escrito de hematologia e informe a deficiência antes de cirurgias, procedimentos odontológicos ou após traumatismos.","diagnosis":"A deficiência de fator VII pode causar sangramentos variados; a gravidade clínica não é prevista apenas pelo resultado laboratorial.","expected":"Algumas pessoas têm poucos sintomas, enquanto outras precisam de cuidados regulares; o plano depende do histórico de sangramento.","alarm":"Observe sangramento nasal persistente, sangue na urina ou fezes e articulação dolorosa ou inchada.","immediate":"Trauma craniano, dor de cabeça súbita intensa, sangramento volumoso ou desmaio exigem emergência.","return":"Retorne para revisar episódios e planejar procedimentos; não ajuste tratamentos por conta própria.","sources":[{"url":"https://medlineplus.gov/genetics/condition/factor-vii-deficiency/","title":"MedlinePlus Genetics — Factor VII deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Deficiência de Fator XIII","aliases":[],"setting":"specialist","general":"Mantenha contato com hematologia e informe o diagnóstico antes de cirurgias ou procedimentos dentários. Evite atividades com alto risco de trauma.","diagnosis":"A deficiência do fator XIII compromete a estabilidade do coágulo. A forma hereditária pode causar sangramento desde o período neonatal.","expected":"O risco depende da deficiência e do controle; ausência de sangramento recente não dispensa acompanhamento.","alarm":"Observe hematomas, sangramento persistente, dor articular ou dificuldade de cicatrização.","immediate":"Trauma na cabeça, cefaleia intensa, alteração de consciência ou sangramento importante exigem emergência.","return":"Siga o plano preventivo e os exames definidos pela hematologia; comunique qualquer sangramento novo.","sources":[{"url":"https://medlineplus.gov/genetics/condition/factor-xiii-deficiency/","title":"MedlinePlus Genetics — Factor XIII deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Deficiência de hormônio do crescimento (GH)","setting":"specialist","general":"Produção insuficiente de GH pode reduzir a velocidade de crescimento; baixa estatura isolada não confirma deficiência.","diagnosis":"Leve registros anteriores de altura e peso às consultas e cumpra as medições programadas. Siga o plano do endocrinologista; não use produtos de crescimento ou mude o tratamento por conta própria.","expected":"A resposta depende da causa, da idade e do acompanhamento. O crescimento é avaliado ao longo do tempo; não se pode prometer uma estatura final nem melhora imediata.","alarm":"Cefaleia persistente, alterações visuais, vômitos, hipoglicemia ou regressão do desenvolvimento exigem avaliação rápida.","immediate":"Solicitar avaliação pediátrica/endócrina quando a curva cair ou o crescimento for persistentemente lento; não usar produtos por conta própria.","return":"Levar registros de altura e peso e comparecer às medições programadas; retornar antes se surgirem sinais neurológicos.","sources":[{"url":"https://www.medlineplus.gov/ency/article/001176.htm","title":"MedlinePlus — Growth hormone deficiency: children","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Deficiência seletiva de IgA","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento imunológico e registre infecções, diarreia persistente e reações a tratamentos. Avise a equipe sobre a deficiência antes de transfusões.","diagnosis":"Muitas pessoas não apresentam sintomas. O cuidado é orientado pelas infecções e condições associadas; o diagnóstico não significa necessidade automática de reposição de imunoglobulina.","expected":"A evolução é variável; algumas crianças permanecem bem e outras precisam de acompanhamento por infecções recorrentes ou doenças autoimunes.","alarm":"Observe infecções repetidas, tosse persistente, diarreia prolongada, perda de peso ou piora da disposição.","immediate":"Dificuldade respiratória, prostração intensa, ou reação súbita durante transfusão exigem atendimento imediato.","return":"Procure avaliação ao surgirem sintomas infecciosos ou intestinais e mantenha a vacinação individualmente orientada. Reações prévias a sangue/hemoderivados devem constar claramente no registro clínico.","sources":[{"url":"https://www.medlineplus.gov/ency/article/001476.htm","title":"MedlinePlus — Selective deficiency of IgA","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Dengue clássica","aliases":[],"setting":"home","general":"Siga o plano de hidratação e de retornos definido no atendimento. Observe ingestão de líquidos, quantidade de urina e estado geral ao longo do dia.","diagnosis":"O rótulo dengue clássica não dispensa reclassificação de gravidade. A melhora da febre pode coincidir com o início da fase de maior risco.","expected":"A vigilância deve aumentar quando a febre cai, principalmente entre o terceiro e o sétimo dia; não interprete esse momento como cura garantida.","alarm":"Dor abdominal persistente, vômitos repetidos, sangramento, irritabilidade ou sonolência precisam de atenção.","immediate":"Retorne imediatamente se houver qualquer sinal de alarme, desmaio, mãos frias, falta de ar ou pouca urina.","return":"Cumpra o retorno agendado, mesmo que a febre desapareça; a equipe determinará a frequência de avaliação e exames.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/dengue/faq/dengue/quais-sao-os-sinais-de","title":"Ministério da Saúde — Dengue: sinais de alarme","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Dengue com sinais de alarme","aliases":[],"setting":"hospital","general":"Dengue com sinais de alarme exige atendimento imediato e monitorização. Leve a informação do primeiro dia de febre e dos medicamentos utilizados.","diagnosis":"A queda da febre não significa necessariamente recuperação. A equipe deve acompanhar hidratação, circulação, sangramentos e exames conforme a evolução.","expected":"A fase crítica pode começar quando a febre diminui; a evolução pode mudar em poucas horas.","alarm":"Observe dor abdominal intensa, vômitos frequentes, sangramentos, irritabilidade, sonolência, tontura e diminuição de urina.","immediate":"Desmaio, pele fria, falta de ar, sangramento importante ou dificuldade de despertar exigem emergência, sem aguardar retorno agendado.","return":"Somente após alta definida pela equipe, cumpra retorno e orientações de hidratação individualizados; não use anti-inflamatórios por conta própria.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/dengue","title":"Ministério da Saúde — Dengue","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Dengue grave","aliases":[],"setting":"hospital","general":"Dengue grave exige hospitalização e monitorização; estas orientações não autorizam cuidado domiciliar. Informe todos os medicamentos usados e não acrescente remédios ou líquidos em grande quantidade sem a orientação da equipe.","diagnosis":"Pode haver extravasamento de líquido, hemorragia ou comprometimento de órgãos. A hidratação precisa ser ajustada com reavaliações frequentes da circulação, respiração, urina e exames.","expected":"A queda da febre não significa necessariamente melhora; pode coincidir com a fase crítica. A evolução depende da resposta ao tratamento e das complicações.","alarm":"Dor abdominal intensa, vômitos persistentes, sangramento, tontura e irritabilidade devem ser comunicados imediatamente.","immediate":"Desmaio, falta de ar, extremidades frias ou pouca resposta: emergência imediata.","return":"Depois de alta formal, cumpra o retorno programado e procure o serviço se qualquer sinal de alarme reaparecer.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/dengue","title":"Ministério da Saúde — Dengue","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Depressão infantil","setting":"specialist","general":"Transtorno de humor pode aparecer como tristeza, irritabilidade, perda de interesse, alterações de sono, apetite ou desempenho.","diagnosis":"Escute a criança sem julgamento e mantenha rotina possível de sono, alimentação e atividades. Procure equipe de saúde mental e combine apoio escolar; pergunte sobre segurança quando houver falas preocupantes.","expected":"Com cuidado adequado, os sintomas podem melhorar gradualmente, mas a resposta varia e recaídas são possíveis. Acompanhamento precisa continuar mesmo após melhora, conforme o plano profissional.","alarm":"Fala sobre morte, autoagressão, plano suicida, psicose, incapacidade de autocuidado ou risco imediato requer emergência e supervisão contínua.","immediate":"Procurar avaliação de saúde mental; diante de risco, não deixar a criança sozinha e buscar emergência local.","return":"Manter acompanhamento com família e escola conforme plano; retornar rapidamente se sintomas ou risco aumentarem.","sources":[{"url":"https://www.nhs.uk/mental-health/children-and-young-adults/advice-for-parents/children-depressed-signs/","title":"NHS — Depression in children and young people","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":["Depressão em Pediatria"],"status":"source-reviewed"},
{"name":"Dermatite atópica","aliases":["Dermatite Atópica em Pediatria"],"setting":"home","general":"Hidrate a pele regularmente, inclusive fora das crises. Prefira limpeza suave e evite calor excessivo, produtos irritantes e os gatilhos reconhecidos para a criança.","diagnosis":"Mantenha unhas curtas e siga o plano de tratamento para cada região. Não retire alimentos da dieta sem avaliação de alergia ou indicação profissional.","expected":"A doença alterna melhora e crises. Muitas crianças melhoram com a idade, mas o cuidado diário ajuda a reduzir recaídas e coceira.","alarm":"Observe aumento de dor, calor, pus, secreção, bolhas ou piora súbita da área afetada.","immediate":"Febre com pele dolorosa, bolhas disseminadas ou criança muito abatida requer avaliação urgente para descartar infecção importante.","return":"Reavalie se as crises persistirem, afetarem o sono ou não responderem ao plano. Ajuste o tratamento com o profissional.","sources":[{"url":"https://www.nhs.uk/conditions/atopic-eczema/","title":"NHS — Atopic eczema","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Dermatite atópica moderada","aliases":[],"setting":"home","general":"Hidrate a pele diariamente com produto sem perfume e prefira roupas macias. Evite superaquecimento, sabonetes irritantes e coçar; mantenha as unhas curtas.","diagnosis":"Use o tratamento das áreas inflamadas como prescrito. Não exclua alimentos sem avaliação, pois isso pode prejudicar o crescimento e raramente resolve o eczema.","expected":"A dermatite costuma alternar melhora e crises. O cuidado regular continua mesmo quando a pele parece normal, para diminuir novas exacerbações.","alarm":"Secreção, crostas, dor crescente, piora do sono ou extensão das lesões indicam necessidade de reavaliação.","immediate":"Febre com lesões dolorosas que se espalham, bolhas ou acometimento próximo dos olhos exige atendimento imediato.","return":"Reveja o plano se as crises forem frequentes ou o tratamento não controlar coceira e inflamação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/eczema/","title":"RCH — Eczema (atopic dermatitis)","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Dermatite das Fraldas","aliases":["Dermatite de fraldas","Assadura"],"setting":"home","general":"Troque fraldas com frequência, limpe suavemente e seque sem esfregar. Permita períodos sem fralda e use a barreira orientada.","diagnosis":"Nem toda assadura é fungo. Distribuição, feridas e resposta aos cuidados ajudam a identificar irritação, infecção ou outras causas.","expected":"A evolução depende da causa e da redução do contato com irritantes; persistência exige reexaminar o diagnóstico.","alarm":"Observe feridas, pus, dor crescente, extensão para outras regiões ou dificuldade alimentar.","immediate":"Febre com prostração, bolhas extensas ou piora importante em recém-nascido exige atendimento imediato.","return":"Retorne se não melhorar com os cuidados combinados ou se aparecerem novos sinais.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Nappy_rash/","title":"RCH — Nappy rash","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Dermatite de contato alérgica","aliases":[],"setting":"home","general":"Evite contato com a substância identificada e use cuidados de pele orientados. Prefira higiene suave e produtos sem o componente desencadeante.","diagnosis":"A dermatite alérgica pode surgir horas ou dias após o contato. Casos recorrentes podem precisar de investigação dermatológica e testes específicos.","expected":"A pele tende a melhorar quando a exposição cessa, mas a recuperação é gradual e novas exposições podem provocar recaídas.","alarm":"Observe piora rápida, dor crescente, pus, calor local ou febre, que podem indicar complicação.","immediate":"Inchaço de língua ou garganta, falta de ar ou desmaio não são uma dermatite simples e exigem emergência.","return":"Retorne se a área for extensa, o agente não for identificado ou não houver resposta ao plano indicado.","sources":[{"url":"https://www.nhs.uk/conditions/contact-dermatitis/","title":"NHS — Contact dermatitis","accessed":"2026-09-26"},{"url":"https://www.nhs.uk/conditions/contact-dermatitis/symptoms/","title":"NHS — Contact dermatitis: symptoms","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Dermatite de fraldas","aliases":[],"setting":"home","general":"Troque fraldas sujas ou molhadas logo que possível, limpe suavemente e seque sem esfregar. Deixe a pele respirar quando viável e prefira produtos sem perfume ou álcool.","diagnosis":"O contato prolongado com urina e fezes e o atrito irritam a pele. Infecção associada precisa ser avaliada; não use combinações de pomadas ou tratamentos fortes sem orientação.","expected":"A irritação simples deve melhorar com cuidados locais, mas persistência, extensão ou piora podem indicar outra causa e necessidade de revisão.","alarm":"Feridas profundas, bolhas, pus, espalhamento para outras áreas ou dor importante precisam de avaliação.","immediate":"Febre com criança prostrada, recusa de alimentação ou lesões rapidamente progressivas: atendimento imediato.","return":"Retorne se não houver melhora, se o quadro voltar repetidamente ou se os produtos aplicados parecerem piorar a pele.","sources":[{"url":"https://www.nhs.uk/baby/caring-for-a-newborn/nappy-rash/","title":"NHS — Nappy rash","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Dermatite seborreica do lactente","setting":"home","general":"Crosta láctea é comum, geralmente inofensiva e não contagiosa.","diagnosis":"Lave o couro cabeludo suavemente e use escova macia para soltar apenas escamas já desprendidas. Não arranque crostas nem aplique produtos irritantes; peça orientação antes de usar tratamentos na pele do bebê.","expected":"A apresentação típica é indolor e tende a desaparecer ao longo dos primeiros meses, embora possa reaparecer. Coceira intensa, secreção ou desconforto sugerem necessidade de revisar o diagnóstico.","alarm":"Procure avaliação se houver sangramento, secreção, dor, inchaço, mau cheiro ou lesões disseminadas.","immediate":"Não é emergência em apresentação típica; mantenha higiene suave e evite coçar.","return":"Procure revisão se as medidas suaves não ajudarem, se as lesões se espalharem ou houver dúvida sobre o diagnóstico. Febre e bebê abatido exigem avaliação imediata.","sources":[{"url":"https://www.nhs.uk/conditions/cradle-cap/","title":"NHS — Cradle cap","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Dermatomiosite juvenil","aliases":["Dermatomiosite Juvenil (DMJ)"],"setting":"specialist","general":"Mantenha acompanhamento reumatológico e registre mudanças de força, cansaço e lesões na pele. Evite mudanças de tratamento sem conversar com a equipe.","diagnosis":"A doença pode inflamar músculos e pele. A necessidade de exames, reabilitação e controle de exposição solar deve ser individualizada; o tratamento precoce busca prevenir lesões.","expected":"Pode haver remissão, recaídas ou atividade por vários anos. A evolução não pode ser prevista apenas pela aparência das lesões cutâneas.","alarm":"Observe piora para levantar, subir degraus ou elevar os braços, febre e redução importante das atividades.","immediate":"Dificuldade para engolir ou respirar, engasgos repetidos ou fraqueza rapidamente progressiva exigem pronto atendimento.","return":"Antecipe a revisão diante de nova perda de força. Mantenha seguimento prolongado mesmo quando a pele e os movimentos parecerem melhores.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/juvenile-dermatomyositis-jdm/","title":"GOSH — Juvenile dermatomyositis","accessed":"2026-09-26"}],"reviewNotes":"Fonte institucional antiga ainda disponível; síntese de princípios gerais. Sinais bulbares/respiratórios são critérios de urgência a confirmar na revisão médica individual.","status":"source-reviewed"},
{"name":"Derrame pleural paraneumônico","aliases":[],"setting":"urgent","general":"A criança precisa de avaliação pediátrica para definir gravidade e local de tratamento. Não force exercícios ou alimentação quando estiver com dificuldade respiratória.","diagnosis":"O derrame associado à pneumonia pode ser simples ou complicado. A ultrassonografia pode ajudar; o volume isolado não determina a gravidade.","expected":"A melhora depende do controle da infecção e, em alguns casos, de drenagem. Não há prazo único para desaparecimento do líquido.","alarm":"Febre persistente, dor torácica, respiração rápida ou dificuldade para beber exigem reavaliação.","immediate":"Lábios azulados, esforço respiratório intenso, sonolência anormal ou desmaio exigem emergência imediata.","return":"Se houver alta após avaliação, siga retorno próximo; em internação, comunique piora prontamente à equipe e cumpra seguimento após a alta.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Parapneumonic_effusion/","title":"RCH — Parapneumonic effusion","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Desconforto Respiratório Agudo Pediátrico","aliases":[],"setting":"hospital","general":"Procure atendimento imediato se a criança estiver com dificuldade respiratória importante. Mantenha-a calma e evite manipulação desnecessária.","diagnosis":"Desconforto respiratório é um sinal clínico; PARDS é uma síndrome definida por avaliação clínica, oxigenação e imagem. Não são sinônimos.","expected":"A recuperação depende da causa, gravidade e resposta ao suporte; doença pulmonar prévia modifica a avaliação.","alarm":"Observe retrações, gemência, redução da atividade, dificuldade para falar ou alimentar-se e esforço respiratório crescente.","immediate":"Apneia, coloração azulada, exaustão ou redução da consciência exige emergência. Não espere um número baixo no oxímetro.","return":"O plano de retorno depende da causa esclarecida e da recuperação; após doença crítica, avaliar também função física e desenvolvimento.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Assessment_of_severity_of_respiratory_conditions/","title":"RCH — Assessment of severity of respiratory conditions, 2024","accessed":"2026-09-27"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9848214/","title":"PALICC-2 — Executive summary, 2023","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36661434/","title":"PALICC-2 — Outcomes of children surviving PARDS, 2023","accessed":"2026-09-27"}],"reviewNotes":"Sem parâmetros ventilatórios, protocolo de intubação ou alta automática. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"Consenso internacional com revisão sistemática e diretriz pediátrica. Crianças com doença respiratória aguda/PARDS. Muitas recomendações são condicionais ou boas práticas; critérios perinatais diferem.","decisionSupport":{"summary":"Esclarecer se o termo descreve um sintoma ou PARDS confirmado; a gravidade clínica determina atendimento imediato.","requirements":["Idade e doença perinatal ativa","Início e causa provável","Consciência, alimentação e esforço","Oxigenação e suporte habitual/atual","Imagem e avaliação cardiopulmonar"],"branchRequired":true,"branches":[{"id":"symptom","label":"Desconforto sem PARDS confirmado","when":"Dificuldade respiratória ainda em investigação.","setting":"urgent","overrides":{"diagnosis":"Investigue infecção, obstrução e causas extrapulmonares conforme apresentação.","expected":"Depende da causa identificada.","return":"Seguimento etiológico após estabilização.","alarm":"Esforço ou alimentação piores.","immediate":"Cianose, apneia ou sonolência: emergência."}},{"id":"pards","label":"PARDS confirmado","when":"Equipe confirma critérios PALICC-2 e contexto aplicável.","setting":"hospital","overrides":{"diagnosis":"Requer suporte e monitorização hospitalares; não calcular gravidade pelo nome.","expected":"Pode deixar repercussões pulmonares e funcionais.","return":"Planeje avaliação respiratória, física e neurocognitiva após alta.","alarm":"Piora da oxigenação ou função.","immediate":"Deterioração: acione imediatamente a equipe."}}]},"revisedAt":"2026-09-27"},
{"name":"Desnutrição Energético-Proteica Infantil","setting":"urgent","aliases":["Desnutrição energético-proteica","Desnutrição infantil"],"general":"Desnutrição precisa de avaliação do crescimento, alimentação e doenças associadas; formas graves podem exigir internação.","diagnosis":"Siga plano nutricional supervisionado e apoio à amamentação quando aplicável. Não faça reposição alimentar intensiva ou mudanças abruptas por conta própria.","expected":"A recuperação é gradual e depende da gravidade, da causa e do acesso contínuo a alimentação adequada.","alarm":"Edema, perda de peso, recusa alimentar, vômitos ou prostração são alarmes.","immediate":"Incapacidade de beber, convulsão, letargia ou piora rápida requerem emergência.","return":"Mantenha revisões frequentes de crescimento e alimentação, com apoio à família e investigação de recaídas.","sources":[{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK601655/","title":"WHO — Wasting and nutritional oedema guideline: recommendations (2023)","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Diretriz WHO aberta cobre menores de 5 anos; gravidade, idade e problemas alimentares determinam internação ou seguimento. Não é protocolo alimentar universal para todas as idades. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Diabetes insípido central","aliases":[],"setting":"specialist","general":"Garanta acesso à água e siga o plano de ingestão e monitorização estabelecido pela equipe. Registre mudanças importantes na sede e no volume de urina.","diagnosis":"A forma central relaciona-se à falta de ação hormonal adequada. O tratamento e os líquidos precisam de ajuste individual, com acompanhamento do sódio.","expected":"A evolução depende da causa; algumas situações são temporárias e outras exigem cuidado contínuo.","alarm":"Observe sede intensa, urina muito aumentada, vômitos, dor de cabeça, sonolência ou mudança de comportamento.","immediate":"Incapacidade de beber, confusão, convulsão, desmaio ou prostração intensa exigem atendimento imediato.","return":"Contate endocrinologia se houver doença intercorrente ou alteração da ingestão; não suspenda nem dobre o tratamento por conta própria.","sources":[{"url":"https://www.niddk.nih.gov/health-information/kidney-disease/diabetes-insipidus","title":"NIDDK — Diabetes Insipidus","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Diabetes mellitus tipo 1","aliases":["Diabetes Mellitus Tipo 1 em Pediatria"],"setting":"specialist","general":"Siga o plano individual de monitorização, alimentação e administração do tratamento. Tenha material de controle e resgate disponível e oriente escola e cuidadores sobre como reconhecer intercorrências.","diagnosis":"Diabetes tipo 1 necessita tratamento contínuo. Doença intercorrente, exercício ou alimentação diferente podem modificar as necessidades; utilize as instruções escritas da equipe para essas situações.","expected":"É possível manter atividades e desenvolvimento, mas os controles e revisões permanecem necessários mesmo em períodos estáveis. Não altere o esquema com base apenas em um valor isolado.","alarm":"Tremor, suor, tontura, sede ou urina excessivas e resultados fora das metas exigem ação conforme o plano.","immediate":"Desmaio, convulsão, alteração de consciência, vômitos com respiração anormal ou incapacidade de ingerir líquidos: emergência.","return":"Contate a equipe diante de dificuldades repetidas e mantenha os retornos programados.","sources":[{"url":"https://www.nhs.uk/conditions/type-1-diabetes/living-with/","title":"NHS — Living with type 1 diabetes","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Diabetes mellitus tipo 2","setting":"specialist","general":"É doença crônica em que o organismo não usa bem a insulina; requer avaliação e acompanhamento clínico.","diagnosis":"Siga o plano de alimentação, atividade física e monitorização combinado com a equipe. A família deve aprender metas, sinais de glicose alterada e conduta durante doenças, sem modificar o tratamento sozinha.","expected":"O controle é contínuo e pode mudar com crescimento e puberdade. Acompanhamento regular monitora glicose e complicações; ausência de sintomas não significa que os níveis estejam adequados.","alarm":"Confusão, desmaio, respiração difícil, vômitos persistentes ou grande prostração exigem urgência.","immediate":"Com sinais intensos ou piora rápida, vá à emergência; não aguarde consulta de rotina.","return":"Mantenha consultas e exames individualizados. Antecipe avaliação com sede ou urina excessivas, perda de peso, mudanças persistentes nas medidas ou dificuldade para cumprir o plano.","sources":[{"url":"https://www.cdc.gov/diabetes/about/about-type-2-diabetes.html","title":"CDC — Type 2 Diabetes","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":["Diabetes Mellitus Tipo 2 em Pediatria"],"status":"source-reviewed"},
{"name":"Diarreia em Pediatria","aliases":["Diarreia"],"setting":"home","general":"Se não houver gravidade e após avaliação, mantenha alimentação e amamentação. Ofereça solução de reidratação conforme o plano, preparada exatamente como indicado na embalagem.","diagnosis":"A principal medida é prevenir e corrigir desidratação; sangue nas fezes ou diarreia persistente exigem investigação específica.","expected":"A evolução depende da causa; frequência isolada não substitui avaliar ingestão, urina e estado geral.","alarm":"Sede intensa, pouca urina, vômitos repetidos, sangue ou recusa alimentar são alertas.","immediate":"Sonolência, incapacidade de beber, desmaio ou extremidades frias exigem emergência.","return":"Retorne se não melhorar em dois dias ou antes diante de qualquer piora.","sources":[{"url":"https://www.gov.br/saude/pt-br/centrais-de-conteudo/publicacoes/svsa/doencas-diarreicas-agudas/manejo-do-paciente-com-diarreia-avaliacao-do-estado-do-paciente/@@download/file","title":"Ministério da Saúde — Manejo do paciente com diarreia: avaliação do estado do paciente","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Cuidado domiciliar corresponde a criança sem desidratação grave e com capacidade de hidratação; não substitui planos hospitalares.","status":"source-reviewed"},
{"name":"Difteria","aliases":["Difteria em Pediatria"],"setting":"hospital","general":"A suspeita de difteria exige atendimento hospitalar imediato. Avise o serviço previamente sobre a suspeita para organizar precauções e reduzir exposição de outras pessoas.","diagnosis":"A doença pode comprometer garganta, coração, nervos e rins. O tratamento específico deve ser iniciado pela equipe; não tente remover placas da garganta em casa.","expected":"A evolução depende da rapidez da assistência e da extensão da doença. Mesmo sintomas iniciais discretos não excluem risco de complicações.","alarm":"Observe dificuldade para respirar ou engolir, inchaço do pescoço, palidez, fraqueza ou alteração dos batimentos.","immediate":"Dificuldade respiratória ou redução da consciência é emergência. Não espere surgirem sinais graves para buscar atendimento com suspeita clínica.","return":"Após a fase aguda, siga o acompanhamento orientado e a atualização vacinal. Contatos próximos precisam das orientações da vigilância e da equipe assistente.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/difteria","title":"Ministério da Saúde — Difteria","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Discinesia Ciliar Primária e Heterotaxia","aliases":["Discinesia ciliar primária e síndrome de heterotaxia"],"setting":"specialist","general":"Mantenha os cuidados respiratórios e de eliminação de secreções ensinados pela equipe. Não suprima a tosse sem avaliação.","diagnosis":"A discinesia ciliar prejudica a limpeza das vias aéreas; heterotaxia envolve posição anormal dos órgãos, com possíveis alterações cardíacas e esplênicas.","expected":"A evolução depende dos órgãos afetados e das infecções; acompanhamento prolongado é necessário.","alarm":"Observe aumento de secreção, febre, piora respiratória, dificuldade alimentar ou dor abdominal.","immediate":"Falta de ar, arroxeamento ou febre com prostração exige emergência; ausência de baço aumenta a urgência da febre.","return":"Siga pneumologia, cardiologia e outras especialidades conforme a anatomia e a função dos órgãos.","sources":[{"url":"https://www.nhlbi.nih.gov/health/primary-ciliary-dyskinesia/treatment","title":"NHLBI — Primary Ciliary Dyskinesia: Treatment","accessed":"2026-09-26"},{"url":"https://www.chop.edu/conditions-diseases/heterotaxy-syndrome-isomerism","title":"CHOP — Heterotaxy Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Condições associáveis, mas não equivalentes; não pressupor heterotaxia em toda discinesia.","status":"source-reviewed"},
{"name":"Disfunção Miccional em Pediatria","aliases":["Disfunção miccional","Incontinência urinária diurna"],"setting":"home","general":"Estabeleça idas regulares ao banheiro, sem punições. Incentive posição confortável, hidratação adequada e cuidado da constipação conforme o plano; registre micções e escapes.","diagnosis":"Escapes diurnos podem ter causas funcionais ou orgânicas. Gotejamento contínuo ou criança nunca seca merece investigação específica.","expected":"A melhora com mudanças de rotina costuma ser gradual; a resposta deve ser acompanhada.","alarm":"Relate dor ao urinar, febre, sangue na urina, sede excessiva ou perda de peso.","immediate":"Incapacidade de urinar, dor intensa ou febre com prostração exigem atendimento imediato.","return":"Retorne com o diário para revisar adesão, intestino e necessidade de encaminhamento.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Urinary_incontinence/","title":"Royal Children’s Hospital — Urinary incontinence – daytime wetting","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Displasia broncopulmonar","aliases":[],"setting":"specialist","general":"Mantenha o seguimento do prematuro, alimentação orientada e ambiente sem fumaça. Se houver oxigênio domiciliar, siga rigorosamente o plano e as metas prescritas.","diagnosis":"A displasia broncopulmonar pode afetar respiração, alimentação e crescimento. Os ajustes do suporte dependem da avaliação, não apenas da aparência da criança.","expected":"Há evolução variável com o crescimento pulmonar; algumas crianças precisam de suporte e acompanhamento prolongados. Não suspenda oxigênio por melhora aparente.","alarm":"Avise sobre mais cansaço nas mamadas, menor ingestão, pior ganho de peso, febre ou maior necessidade de suporte.","immediate":"Pausas respiratórias, coloração azulada, esforço importante ou sonolência incomum exigem atendimento imediato.","return":"Compareça às revisões pulmonares e do desenvolvimento, incluindo avaliação de audição, visão e nutrição conforme a equipe.","sources":[{"url":"https://www.nhlbi.nih.gov/health/bronchopulmonary-dysplasia","title":"NHLBI — Bronchopulmonary Dysplasia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Displasia broncopulmonar clássica","aliases":[],"setting":"specialist","general":"Mantenha seguimento neonatal/pulmonar, nutrição, crescimento e desenvolvimento. Evite fumaça e confirme vacinação e prevenção respiratória apropriadas à criança.","diagnosis":"O termo clássico descreve um padrão histórico de lesão e reparação pulmonar. O cuidado atual deve considerar sintomas, oxigenação, alimentação e complicações, não somente esse rótulo.","expected":"Pode haver melhora com crescimento pulmonar, mas sintomas e necessidade de suporte podem persistir. A trajetória individual não é prevista pela classificação histórica.","alarm":"Observe maior esforço, cansaço às mamadas, engasgos, menor crescimento ou saturação abaixo da meta individual, se houver monitor prescrito.","immediate":"Apneia, lábios azulados, pouca resposta ou dificuldade respiratória intensa exige emergência. Oxigenação baixa pode ocorrer sem coloração azulada.","return":"Revise necessidades de suporte durante sono, vigília e alimentação. Não suspenda oxigênio por aparência de melhora; antecipe contato se precisar de mais suporte ou surgirem sintomas novos.","sources":[{"url":"https://www.thoracic.org/patients/patient-resources/resources/bpd-treatment.pdf","title":"ATS — Treatment of bronchopulmonary dysplasia, atualização 2018","accessed":"2026-09-27"},{"url":"https://www.nhlbi.nih.gov/health/bronchopulmonary-dysplasia","title":"NHLBI — Bronchopulmonary dysplasia, 2022","accessed":"2026-09-27"},{"url":"https://www.scielo.br/j/jbpml/a/9HgjTzVJ9GQMVhN3V47CrMp/?lang=en","title":"Análise de apoptose/proliferação em pulmões de prematuros com DBP, JBPML","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD003214_what-are-benefits-and-risks-inhaled-bronchodilators-preterm-newborns-preventing-and-treating-lung","title":"Cochrane — Bronchodilators in preterm infants, CD003214, 2024","accessed":"2026-09-27"}],"reviewNotes":"Reconhece o subtipo histórico sem inventar prescrição por fenótipo. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"Orientação ATS/NHLBI, estudo anatomopatológico e revisão sistemática. Prematuros com DBP; estudo histológico incluiu autópsias. Anatomia não prediz resposta terapêutica. Ensaios preventivos não demonstram benefício universal no tratamento estabelecido.","decisionSupport":{"summary":"O rótulo clássico não determina um regime próprio; selecionar cuidados por estado atual e suporte documentado.","requirements":["Idade gestacional e corrigida","Suporte e meta de oxigenação prescritos","Sintomas, crescimento e segurança alimentar","Hipertensão pulmonar e outras complicações","Plano para falha do equipamento e emergência"],"branchRequired":false,"branches":[]},"revisedAt":"2026-09-27"},
{"name":"Displasia de desenvolvimento do quadril","aliases":[],"setting":"specialist","general":"Compareça às avaliações de ortopedia e exames de imagem. Se houver aparelho, use e higienize conforme o treinamento recebido; não ajuste tiras nem suspenda o uso por conta própria.","diagnosis":"A articulação do quadril pode estar instável ou fora de posição, mesmo sem dor. O tratamento e o tipo de aparelho dependem da idade e da avaliação especializada.","expected":"Muitos casos evoluem bem com tratamento adequado; a duração varia. O acompanhamento confirma se o quadril se desenvolve e se mantém na posição esperada.","alarm":"Lesões de pele, desconforto persistente, redução de movimentos ou problemas no aparelho precisam de contato com a equipe.","immediate":"Membro frio, muito inchado, arroxeado ou dor intensa: avaliação imediata.","return":"Mantenha todas as revisões para ajustes e controle, mesmo quando a criança parecer confortável.","sources":[{"url":"https://www.nhs.uk/conditions/developmental-dysplasia-of-the-hip/","title":"NHS — Developmental dysplasia of the hip","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Doença celíaca","setting":"specialist","general":"Doença celíaca é uma reação imune ao glúten que pode lesar o intestino. O diagnóstico confirmado exige cuidado nutricional continuado.","diagnosis":"Após confirmação, siga dieta sem glúten com orientação nutricional e atenção à contaminação cruzada. Se a investigação ainda estiver em andamento, não retire glúten sem orientação porque isso interfere nos exames.","expected":"Sintomas e absorção tendem a melhorar com a dieta adequada, em ritmo variável. Crescimento e deficiências nutricionais precisam ser acompanhados; ausência de sintomas não autoriza abandonar o cuidado.","alarm":"Desidratação, sangue nas fezes, vômitos persistentes, dor intensa ou prostração pedem atendimento urgente.","immediate":"Ofereça líquidos se tolerados e procure urgência diante desses sinais; não faça dieta restritiva improvisada.","return":"Retorne ao especialista para resultados e plano nutricional; acompanhamento ajuda a prevenir deficiências.","sources":[{"url":"https://www.nhs.uk/conditions/coeliac-disease/","title":"NHS — Coeliac disease","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Doença da Arranhadura do Gato na Criança","aliases":["Doença da arranhadura do gato"],"setting":"specialist","general":"Informe contato com gatos e arranhaduras. Não esprema gânglios aumentados e evite novas lesões.","diagnosis":"A necessidade de tratamento depende da gravidade e da imunidade; casos atípicos podem exigir exames.","expected":"Muitos quadros se resolvem gradualmente, mas formas disseminadas precisam de acompanhamento especializado.","alarm":"Observe aumento doloroso dos gânglios, febre persistente ou sintomas fora do local inicial.","immediate":"Alteração visual, confusão, falta de ar ou importante prostração exige avaliação urgente.","return":"Retorne para conferir evolução dos gânglios. Crianças imunocomprometidas precisam de abordagem precoce e não devem aguardar resolução espontânea sem acompanhamento.","sources":[{"url":"https://www.cdc.gov/bartonella/hcp/clinical-overview/cat-scratch-disease.html","title":"CDC — Cat scratch disease","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Doença da Membrana Hialina","aliases":["Síndrome do desconforto respiratório neonatal por deficiência de surfactante"],"setting":"hospital","general":"O recém-nascido com dificuldade respiratória precisa de assistência neonatal. Mantenha comunicação com a equipe sobre suporte, alimentação e evolução.","diagnosis":"A doença da membrana hialina é uma forma de desconforto respiratório ligada à deficiência de surfactante, especialmente na prematuridade.","expected":"A resposta depende da idade gestacional, do suporte e de complicações. Não há previsão individual apenas pelo nome do diagnóstico.","alarm":"Observe gemência, esforço respiratório, coloração azulada, pausas respiratórias ou piora súbita.","immediate":"Qualquer deterioração deve ser comunicada imediatamente à equipe neonatal para reavaliação e suporte.","return":"Após estabilização e alta, mantenha seguimento de crescimento, alimentação e desenvolvimento conforme a prematuridade e o curso.","sources":[{"url":"https://www.safercare.vic.gov.au/best-practice-improvement/clinical-guidance/neonatal/respiratory-distress-syndrome-rds-in-neonates","title":"Safer Care Victoria — Respiratory distress syndrome in neonates","accessed":"2026-09-26"}],"reviewNotes":"Fonte sinaliza revisão atrasada; utilizada para definição, sinais e suporte, sem copiar regimes terapêuticos.","status":"source-reviewed"},
{"name":"Doença de Behçet em Pediatria","aliases":[],"setting":"specialist","general":"Registre crises e mantenha seguimento reumatológico, incluindo avaliação dos olhos quando indicada; não suspenda o plano porque as úlceras melhoraram.","diagnosis":"Behçet pode afetar boca, genitais, pele, olhos, vasos e outros órgãos; o tratamento depende das manifestações.","expected":"Pode alternar períodos de melhora e recaída; não há prazo único de cura.","alarm":"Informe olho vermelho ou doloroso, mudança visual, sangue nas fezes ou inchaço doloroso de uma perna.","immediate":"Perda visual súbita, tosse com sangue, cefaleia intensa nova, convulsão ou fraqueza súbita exigem emergência.","return":"Mantenha vigilância individual dos órgãos envolvidos e reavalie sintomas novos prontamente.","sources":[{"url":"https://www.nhs.uk/conditions/behcets-disease/","title":"NHS — Behçet’s disease","accessed":"2026-09-26"},{"url":"https://www.nhs.uk/conditions/behcets-disease/symptoms/","title":"NHS — Behçet’s disease symptoms","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Doença de Caroli","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com hepatologia. Avise a equipe quando surgirem dor abdominal, febre ou mudança da cor da pele.","diagnosis":"A dilatação de ductos biliares favorece cálculos e infecções. Doença de Caroli e síndrome de Caroli com fibrose exigem distinção.","expected":"A evolução varia com a distribuição das alterações e as complicações; intervenções são escolhidas individualmente.","alarm":"Observe febre, calafrios, dor do lado direito da barriga, vômitos ou icterícia.","immediate":"A combinação de febre, dor abdominal e icterícia exige avaliação urgente por possível infecção das vias biliares.","return":"Siga controles hepáticos e de imagem, com avaliação renal quando pertinente ao subtipo.","sources":[{"url":"https://my.clevelandclinic.org/health/diseases/caroli-disease","title":"Cleveland Clinic — Caroli Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Doença de Chagas aguda","aliases":[],"setting":"urgent","general":"Procure avaliação rápida e informe viagens, alimentos compartilhados em surtos, contato com barbeiros e casos semelhantes. Mantenha acompanhamento após confirmação diagnóstica.","diagnosis":"A fase aguda pode causar febre prolongada e alterações cardíacas. O tratamento precoce deve ser acompanhado por equipe que monitore resposta e possíveis efeitos adversos.","expected":"Quanto mais cedo identificada e tratada, melhor a perspectiva de controle. A redução da febre não comprova, sozinha, eliminação da infecção.","alarm":"Observe fraqueza intensa, inchaço no rosto/pernas, palpitações, dor no peito ou falta de ar.","immediate":"Falta de ar, desmaio, palpitações persistentes ou piora importante do estado geral exigem pronto atendimento.","return":"Compareça aos exames e consultas de controle mesmo após melhora. O seguimento deve verificar resposta e possíveis manifestações cardíacas ou digestivas ao longo do tempo.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/d/doenca-de-chagas","title":"Ministério da Saúde — Doença de Chagas","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Doença de Chagas congênita","aliases":[],"setting":"specialist","general":"Compareça às avaliações do bebê mesmo quando ele parece saudável. Leve exames da gestação, da mãe e da criança para a equipe.","diagnosis":"A infecção congênita pode ter poucos sintomas e precisa de tratamento e confirmação de resposta. Exames de anticorpos do recém-nascido podem refletir anticorpos maternos.","expected":"O tratamento precoce tem elevada chance de cura, mas a equipe deve confirmar a resposta; ausência de sintomas não comprova eliminação da infecção.","alarm":"Dificuldade para mamar, crescimento inadequado, palidez, barriga aumentada ou febre precisam de avaliação rápida.","immediate":"Falta de ar, convulsões, prostração intensa ou recusa alimentar importante exigem atendimento de emergência.","return":"Mantenha o controle laboratorial e clínico até conclusão; a equipe também orientará investigação da mãe e dos irmãos.","sources":[{"url":"https://www.cdc.gov/chagas/hcp/clinical-care/congenital.html","title":"CDC — Clinical Considerations for Congenital Chagas Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Doença de Chagas em Pediatria","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento e os exames solicitados, mesmo sem sintomas; informe forma de exposição e resultados maternos quando pertinentes.","diagnosis":"A doença de Chagas pode ter fase inicial pouco sintomática e complicações cardíacas ou digestivas posteriores; não se transmite pelo contato cotidiano.","expected":"O tratamento precoce oferece melhores perspectivas, mas resposta e seguimento dependem da fase e dos órgãos afetados.","alarm":"Informe palpitações, dificuldade para engolir, cansaço crescente ou alteração intestinal persistente.","immediate":"Desmaio, falta de ar importante ou dor torácica com mal-estar exigem pronto atendimento.","return":"Retorne para documentar resposta e monitorar complicações; ausência de sintomas não dispensa seguimento.","sources":[{"url":"https://www.cdc.gov/chagas/about/index.html","title":"CDC — About Chagas Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Doença de Crohn","aliases":["Doença de Crohn em Pediatria"],"setting":"specialist","general":"Mantenha o tratamento e seguimento gastroenterológico, com apoio nutricional e acompanhamento de crescimento. Registre dor, evacuações, sangue, apetite e peso.","diagnosis":"Não retire grupos alimentares nem interrompa tratamento por conta própria. A alimentação deve atender às necessidades e tolerância de cada fase.","expected":"Crohn é uma doença crônica, com períodos de melhora e atividade; o objetivo é controlar inflamação e prevenir complicações.","alarm":"Observe febre, perda de peso, piora da diarreia, dor crescente ou lesões dolorosas junto ao ânus.","immediate":"Dor intensa com barriga distendida, vômitos persistentes, sangramento importante ou desidratação exigem urgência.","return":"Antecipe contato em piora; mantenha consultas e exames mesmo quando os sintomas estiverem controlados.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/crohns-disease","title":"NIDDK — Crohn’s Disease","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Doença de Hirschsprung","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento cirúrgico e observe evacuações, alimentação e distensão abdominal. Faça procedimentos retais somente se ensinados pela equipe.","diagnosis":"A ausência de nervos em parte do intestino prejudica a eliminação das fezes; o tratamento depende de correção especializada.","expected":"Após cirurgia, muitos evoluem bem, mas constipação e enterocolite ainda podem ocorrer.","alarm":"Observe barriga inchada, dor nova, febre ou diarreia de odor muito forte.","immediate":"Esses sinais, especialmente com prostração ou vômitos, exigem emergência para excluir enterocolite.","return":"Mantenha retorno cirúrgico e apoio ao controle intestinal; não espere a consulta diante de piora.","sources":[{"url":"https://www.nhs.uk/conditions/hirschsprungs-disease/","title":"NHS — Hirschsprung disease","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Doença de Kawasaki","aliases":[],"setting":"hospital","general":"A suspeita de Kawasaki exige avaliação pediátrica rápida e investigação cardíaca; informe quantos dias houve febre e as alterações observadas.","diagnosis":"A inflamação pode atingir as artérias coronárias, inclusive quando nem todos os sinais clássicos estão presentes.","expected":"O controle da febre não encerra o acompanhamento; a evolução depende do envolvimento cardíaco e da resposta ao tratamento.","alarm":"Febre que persiste ou reaparece e retorno dos sintomas devem ser comunicados prontamente.","immediate":"Prostração intensa, desmaio, dificuldade respiratória ou extremidades frias exigem atendimento imediato.","return":"Após alta autorizada, cumpra o plano de ecocardiogramas e consulte a equipe sobre vacinação.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Kawasaki_Disease/","title":"RCH — Kawasaki disease, atualização janeiro 2026","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Doença de Kawasaki clássica","aliases":[],"setting":"hospital","general":"Procure avaliação hospitalar para suspeita de Kawasaki e informe quantos dias de febre ocorreram. Leve registros de temperatura, fotografias de alterações na pele e a relação dos medicamentos usados.","diagnosis":"A inflamação pode atingir vasos do coração e exige tratamento específico e avaliação cardíaca. Não trate por conta própria nem interrompa o esquema após a febre ceder.","expected":"A recuperação clínica pode anteceder a normalização dos exames. A necessidade de seguimento prolongado depende principalmente dos achados cardíacos e da resposta ao tratamento.","alarm":"Persistência ou retorno de febre, cansaço importante, recusa de líquidos ou alteração do estado geral devem ser comunicados rapidamente.","immediate":"Dor no peito, desmaio, falta de ar ou pouca resposta: emergência.","return":"Após alta, cumpra revisões e ecocardiogramas; confirme com a equipe as orientações sobre vacinação e atividades.","sources":[{"url":"https://www.nhs.uk/conditions/kawasaki-disease/","title":"NHS — Kawasaki disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Doença de Kawasaki incompleta","setting":"hospital","general":"É vasculite infantil potencialmente grave; a forma incompleta tem menos sinais clássicos, mas ainda pode afetar coronárias.","diagnosis":"A suspeita exige avaliação hospitalar. Informe quantos dias houve febre e alterações transitórias de olhos, boca, pele ou extremidades; mantenha os exames cardíacos mesmo depois da melhora.","expected":"A resposta ao tratamento é acompanhada no hospital e em retornos. Complicações coronárias podem aparecer apesar de menos sinais externos; a forma incompleta não significa doença leve.","alarm":"Febre prolongada com prostração, dificuldade respiratória, dor torácica, extremidades frias ou piora requer emergência.","immediate":"Encaminhe imediatamente ao hospital; não tente observar em casa quando houver suspeita.","return":"O retorno e os ecocardiogramas devem seguir o cardiologista; não interrompa o acompanhamento após melhora da febre.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Kawasaki_Disease/","title":"RCH — Kawasaki disease","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Doença de Legg-Calvé-Perthes","aliases":["Doença de Perthes"],"setting":"specialist","general":"Mantenha acompanhamento ortopédico e adapte as atividades às recomendações. Evite corrida e impacto quando houver restrição; não force exercícios que provoquem dor.","diagnosis":"O quadril passa por alterações na irrigação e remodelação do osso. A idade, extensão e mobilidade orientam fisioterapia, dispositivos ou cirurgia quando necessários.","expected":"A recuperação é lenta e pode levar anos; a necessidade de tratamento e o resultado variam entre crianças.","alarm":"Observe aumento da dor, limitação de movimento, piora da claudicação ou dificuldade para participar das atividades permitidas.","immediate":"Dor intensa de início súbito, incapacidade nova de apoiar a perna ou febre com dor articular exigem avaliação urgente, sem presumir ser apenas a doença conhecida.","return":"Mantenha revisões e imagens programadas durante toda a evolução. Antecipe a consulta se a função piorar.","sources":[{"url":"https://www.rch.org.au/uploadedFiles/Main/Content/ortho/factsheets/PERTHES-DISEASE.pdf","title":"RCH — Perthes disease","accessed":"2026-09-26"}],"reviewNotes":"Fonte educacional de 2007: princípios e evolução variável; não usada para definir técnica cirúrgica. Requer revisão médica individual.","status":"source-reviewed"},
{"name":"Doença de Osgood-Schlatter","aliases":[],"setting":"home","general":"Ajuste atividades conforme a dor e a orientação recebida. Exercícios de alongamento e fortalecimento podem ajudar; proteja a pele ao aplicar frio.","diagnosis":"A dor costuma ocorrer na saliência abaixo do joelho durante o crescimento, principalmente com corridas e saltos.","expected":"Os sintomas podem oscilar até o fim do crescimento; uma saliência óssea pode permanecer mesmo após melhora.","alarm":"Observe dor em repouso, claudicação importante ou limitação que impede as atividades habituais.","immediate":"Incapacidade súbita de apoiar, trauma importante ou joelho quente com febre exige avaliação imediata.","return":"Retorne se a dor persistir apesar dos cuidados ou se o padrão mudar.","sources":[{"url":"https://www.orthoinfo.org/diseases--conditions/osgood-schlatter-disease-knee-pain","title":"AAOS/POSNA — Osgood-Schlatter Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Doença de Von Willebrand","aliases":["Doença de Von Willebrand na Infância"],"setting":"specialist","general":"Informe o diagnóstico em atendimentos, cirurgias e procedimentos odontológicos. Tenha o plano individual para sangramento e registre episódios e duração.","diagnosis":"A doença tem subtipos e gravidades diferentes; o tratamento deve ser definido pelo hematologista. Não use medicamentos que possam aumentar sangramento sem conferir sua segurança.","expected":"O acompanhamento reduz complicações, mas a tendência a sangrar pode persistir. Ausência de sangramento recente não significa resolução da condição.","alarm":"Sangramento nasal prolongado, menstruação muito intensa, urina avermelhada ou hematomas novos merecem orientação da equipe.","immediate":"Sangramento que não cessa, trauma craniano acompanhado de sintomas, vômito com sangue, fezes negras ou desmaio exigem emergência.","return":"Mantenha revisão hematológica e prepare um plano específico antes de procedimentos; comunique mudança no padrão de sangramento.","sources":[{"url":"https://www.cdc.gov/von-willebrand/about/index.html","title":"CDC — About von Willebrand Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Doença de Wilson em Pediatria","aliases":["Doença de Wilson"],"setting":"specialist","general":"Mantenha tratamento e acompanhamento contínuos. Discuta alimentação e suplementos com a equipe, especialmente produtos contendo cobre.","diagnosis":"A doença provoca acúmulo de cobre em órgãos; a melhora dos sintomas não elimina a necessidade de tratamento.","expected":"Com controle adequado, podem ser prevenidas complicações. A evolução depende dos órgãos atingidos e da adesão.","alarm":"Observe icterícia, piora da coordenação, mudanças de comportamento ou perda de disposição.","immediate":"Confusão, sangramento, dificuldade respiratória ou deterioração rápida exige emergência.","return":"Cumpra exames regulares de resposta e segurança. Não suspenda tratamento e comunique efeitos adversos ou dificuldades para mantê-lo.","sources":[{"url":"https://www.niddk.nih.gov/health-information/liver-disease/wilson-disease","title":"NIDDK — Wilson disease","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Doença do refluxo gastroesofágico","aliases":["Doença do Refluxo Gastroesofágico em Pediatria"],"setting":"specialist","general":"Observe alimentação, vômitos e ganho de peso. Evite oferecer volume excessivo; mudanças de dieta ou consistência devem ser orientadas para a idade.","diagnosis":"DRGE envolve sintomas relevantes ou complicações; regurgitação isolada de um bebê que cresce bem não basta para esse diagnóstico.","expected":"A evolução varia com idade e causa. A resposta às medidas deve ser reavaliada, sem prolongar tratamento automaticamente.","alarm":"Recusa alimentar, dor para engolir, perda de peso ou vômitos persistentes precisam de avaliação.","immediate":"Vômito verde, sangue no vômito, fezes negras, dificuldade respiratória ou desidratação exigem atendimento imediato.","return":"Retorne para revisão do crescimento e sintomas; em lactentes, mantenha posição segura de sono e discuta qualquer mudança alimentar antes de aplicá-la.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/acid-reflux-ger-gerd-infants","title":"NIDDK — Acid Reflux in Infants","accessed":"2026-09-26"},{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/acid-reflux-ger-gerd-children/symptoms-causes","title":"NIDDK — Symptoms & Causes of GER & GERD in Children","accessed":"2026-09-26"}],"reviewNotes":"Fontes distintas para lactentes e crianças maiores; medidas alimentares e de sono dependem da idade e não são intercambiáveis.","status":"source-reviewed"},
{"name":"Doença do Soro","aliases":[],"setting":"home","general":"Registre os produtos usados e informe quando surgiram febre, manchas e dores articulares. Não repita por conta própria o possível desencadeante; a equipe deve orientar sua suspensão ou substituição.","diagnosis":"Doença do soro e reação semelhante à doença do soro precisam ser diferenciadas de outras causas de exantema.","expected":"Após retirada do desencadeante, costuma haver melhora, mas a duração varia e a forma verdadeira pode exigir investigação adicional.","alarm":"Observe piora da febre, edema, dificuldade para caminhar ou mudança da urina.","immediate":"Falta de ar, pouca resposta ou comprometimento importante exigem emergência.","return":"Retorne se não melhorar conforme combinado.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Serum_Sickness_and_Serum_Sickness_like_reactions_(SSLRs)/","title":"Royal Children’s Hospital — Serum sickness and serum sickness-like reactions","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Alta apenas após avaliação de quadro estável. Não equiparar automaticamente reação semelhante à doença do soro e doença do soro por imunocomplexos.","status":"source-reviewed"},
{"name":"Doença granulomatosa crônica","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com imunologia e cumpra o plano de prevenção de infecções. Informe o diagnóstico em toda consulta e entre em contato cedo quando surgirem sintomas novos.","diagnosis":"A doença granulomatosa crônica prejudica a defesa contra determinadas bactérias e fungos. Infecções de pele, pulmão e outros órgãos podem precisar de investigação e tratamento especializado.","expected":"O curso é prolongado e varia entre pessoas. O controle e a prevenção reduzem complicações, mas a ausência de sintomas não permite suspender cuidados prescritos.","alarm":"Febre, tosse persistente, lesões de pele que aumentam, dor óssea ou infecção sem melhora exigem avaliação rápida.","immediate":"Falta de ar, confusão, prostração intensa ou piora acelerada: emergência.","return":"Retorne regularmente à equipe e antecipadamente sempre que houver suspeita de infecção ou dificuldade para manter o tratamento.","sources":[{"url":"https://medlineplus.gov/ency/article/001239.htm","title":"MedlinePlus — Chronic granulomatous disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Doença Mão-Pé-Boca","aliases":["Doença mão-pé-boca"],"setting":"home","general":"Ofereça líquidos em pequenas quantidades, de preferência frescos, e alimentos tolerados. Mantenha as bolhas limpas e evite manipulá-las.","diagnosis":"Feridas na boca podem dificultar beber; a hidratação merece atenção especial em crianças pequenas.","expected":"A maioria dos quadros melhora em sete a dez dias, mas a evolução deve ser acompanhada.","alarm":"Observe redução da urina, recusa persistente de líquidos, febre prolongada ou sintomas intensos.","immediate":"Sonolência anormal, rigidez no pescoço, fraqueza ou desidratação importante exigem pronto atendimento.","return":"Procure revisão se a febre durar mais de três dias ou não houver melhora após dez dias.","sources":[{"url":"https://www.cdc.gov/hand-foot-mouth/signs-symptoms/index.html","title":"CDC — HFMD Symptoms and Complications","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Doença Meningocócica em Pediatria","aliases":["Doença meningocócica"],"setting":"hospital","general":"Suspeita de doença meningocócica exige emergência imediata. Informe início dos sintomas e contatos próximos; não espere o surgimento de manchas para procurar ajuda.","diagnosis":"A infecção pode causar meningite ou infecção generalizada e evoluir rapidamente. A equipe define tratamento e medidas para contatos.","expected":"A evolução depende da gravidade e da rapidez do atendimento; melhora inicial não dispensa monitorização.","alarm":"Febre com prostração, vômitos, rigidez de nuca, irritabilidade ou manchas arroxeadas é preocupante.","immediate":"Pouca resposta, convulsão, dificuldade respiratória ou piora rápida exigem SAMU 192.","return":"Após alta, mantenha seguimento das possíveis sequelas e orientações de vigilância.","sources":[{"url":"https://www.cdc.gov/meningococcal/hcp/clinical-guidance/index.html","title":"CDC — Clinical guidance for meningococcal disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Abrange meningite e meningococcemia; não restringe a um sorogrupo.","status":"source-reviewed"},
{"name":"Doença Mista do Tecido Conjuntivo em Pediatria","aliases":["Doença mista do tecido conjuntivo"],"setting":"specialist","general":"Mantenha acompanhamento reumatológico e registre limitações nas atividades. Informe mudanças na circulação dos dedos, força muscular e respiração.","diagnosis":"A doença pode combinar manifestações de diferentes condições autoimunes; o padrão clínico pode mudar durante o seguimento.","expected":"O curso é variável. Remissão é possível, mas também podem surgir novas manifestações e necessidade de revisar o diagnóstico.","alarm":"Observe falta de ar, redução da tolerância ao esforço, dor torácica, fraqueza ou dificuldade para engolir.","immediate":"Dificuldade respiratória importante, desmaio ou déficit neurológico novo exige pronto atendimento.","return":"Siga controles dos órgãos envolvidos, especialmente pulmões e circulação, e da segurança do tratamento.","sources":[{"url":"https://pubmed.ncbi.nlm.nih.gov/41412094/","title":"Chevalier et al. — Juvenile-onset mixed connective tissue disease cohort","accessed":"2026-09-26"}],"reviewNotes":"Coorte pediátrica primária; não define tratamento universal ou probabilidade individual de evolução.","status":"source-reviewed"},
{"name":"Doença Renal Crônica em Pediatria","setting":"specialist","aliases":["Doença renal crônica","DRC"],"general":"Comprometimento renal crônico requer nefrologia e acompanhamento de crescimento, pressão e nutrição.","diagnosis":"Siga a orientação individual de líquidos, sal e alimentação; não use suplementos ou novos produtos sem consultar a equipe.","expected":"A progressão varia com a causa e o estágio. Ausência de sintomas não elimina necessidade de exames.","alarm":"Inchaço crescente, pouca urina, vômitos, cansaço acentuado ou pressão alterada são alarmes.","immediate":"Falta de ar, confusão, convulsão ou piora rápida exigem emergência.","return":"Mantenha controles de função renal e complicações; antecipe avaliação durante doenças que alterem ingestão ou hidratação.","sources":[{"url":"https://www.niddk.nih.gov/health-information/kidney-disease/children","title":"NIDDK — Kidney Disease in Children","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Dor Abdominal Crônica em Pediatria","aliases":["Dor abdominal crônica"],"setting":"home","general":"Após avaliação, mantenha refeições, sono e participação escolar conforme tolerado. Registre sintomas e fatores associados sem restringir alimentos indiscriminadamente.","diagnosis":"Dor recorrente pode ter causas funcionais ou orgânicas; dor funcional é real e não significa que a criança esteja inventando.","expected":"A evolução varia; recuperar atividades e reduzir o impacto da dor são objetivos importantes.","alarm":"Perda de peso, sangue nas fezes, febre inexplicada ou vômitos persistentes precisam de reavaliação.","immediate":"Dor intensa progressiva, vômito verde, desmaio ou prostração exigem emergência.","return":"Retorne se os sintomas persistirem ou prejudicarem alimentação, crescimento, sono ou escola.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Abdominal_pain_-_chronic/","title":"Royal Children’s Hospital — Abdominal pain – chronic","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Drenagem anômala total das veias pulmonares","setting":"hospital","general":"É cardiopatia congênita crítica: as veias pulmonares chegam ao lado errado do coração e o fluxo fica comprometido.","diagnosis":"O bebê precisa de cardiologia e cirurgia cardíaca especializadas. Alimentação, esforço e transporte devem seguir a equipe, sobretudo quando há dificuldade respiratória; leve os exames aos atendimentos.","expected":"A evolução depende da anatomia e da presença de obstrução. É necessária correção especializada e seguimento cardíaco prolongado; a melhora após cirurgia não dispensa revisões.","alarm":"Cianose intensa, respiração difícil, colapso, sonolência extrema ou alimentação impossível são emergência.","immediate":"Acione emergência e transporte ao hospital; não há orientação segura de alta domiciliar para doença crítica.","return":"Permanece sob cardiologia e cirurgia; siga rigorosamente consultas e sinais definidos pela equipe.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/tapvr.html","title":"CDC — Total Anomalous Pulmonary Venous Return","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Drenagem Anômala Total de Veias Pulmonares","aliases":["Drenagem anômala total das veias pulmonares","DATVP"],"setting":"hospital","general":"O bebê necessita avaliação em centro de cardiologia pediátrica. Mantenha a equipe informada sobre respiração, coloração e dificuldade para mamar.","diagnosis":"As veias pulmonares drenam em local anormal. A presença de obstrução modifica a gravidade e a urgência da correção.","expected":"O tratamento é cirúrgico; o resultado depende da anatomia, da obstrução e do estado clínico antes da operação.","alarm":"Coloração azulada, respiração rápida e cansaço ao alimentar indicam comprometimento.","immediate":"Piora respiratória, arroxeamento ou pouca resposta exigem estabilização imediata; não aguarde consulta ambulatorial.","return":"Após a cirurgia, mantenha seguimento cardiológico para avaliar fluxo das veias, crescimento e recuperação.","sources":[{"url":"https://www.chop.edu/conditions-diseases/total-anomalous-pulmonary-venous-return-tapvr","title":"CHOP — Total Anomalous Pulmonary Venous Return","accessed":"2026-09-26"}],"reviewNotes":"Não extrapolar para drenagem anômala parcial.","status":"source-reviewed"},
{"name":"Dupla via de saída do ventrículo direito","aliases":["DORV","DSVD"],"setting":"specialist","general":"Mantenha acompanhamento em cardiologia pediátrica e o plano individual de alimentação, crescimento e monitorização. Leve relatórios das operações e exames a cada atendimento.","diagnosis":"A anatomia varia entre crianças e define circulação, gravidade e tipo de cirurgia. Não use metas ou restrições de outra cardiopatia como se fossem equivalentes.","expected":"A evolução depende das conexões cardíacas, defeitos associados e resposta às intervenções; pode ser necessário tratamento em etapas e seguimento prolongado.","alarm":"Observe suor e cansaço durante mamadas, ganho de peso insuficiente, inchaço, respiração acelerada ou coloração azulada.","immediate":"Piora da falta de ar, coloração azulada nova/intensa, desmaio ou pouca resposta exige emergência imediata.","return":"Antecipe a consulta com queda da ingestão ou crescimento. Mesmo após cirurgia, mantenha as revisões e as orientações individualizadas sobre procedimentos e atividade física.","sources":[{"url":"https://medlineplus.gov/ency/article/007328.htm","title":"MedlinePlus — Double outlet right ventricle","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Ectima na Criança","setting":"urgent","aliases":["Ectima"],"general":"Ectima é uma infecção ulcerada da pele, mais profunda que o impetigo, e precisa de avaliação profissional.","diagnosis":"Mantenha higiene suave, evite manipular crostas e não compartilhe toalhas. Siga o tratamento e o cuidado local prescritos.","expected":"A recuperação depende da profundidade e extensão; podem permanecer cicatrizes. Lesões que aumentam precisam de revisão.","alarm":"Dor crescente, febre, vermelhidão que se espalha ou novas úlceras são alarmes.","immediate":"Procure urgência por piora rápida, prostração ou sinais de infecção extensa.","return":"Retorne para confirmar cicatrização e revisar resultados de exames quando solicitados; não prolongue tratamento sozinho.","sources":[{"url":"https://www.idsociety.org/practice-guideline/skin-and-soft-tissue-infections/","title":"IDSA — Skin and Soft Tissue Infections guideline","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Diretriz IDSA de 2014 efetivamente aberta; fonte ainda disponibilizada oficialmente. Orientações gerais de cuidado e reavaliação, sem atualização posológica neste arquivo. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Embolia e Infarto Pulmonar em Pediatria","aliases":["Embolia pulmonar","Infarto pulmonar"],"setting":"hospital","general":"Suspeita de embolia pulmonar exige avaliação hospitalar. Informe doenças, cirurgias, imobilização, cateteres e tratamentos recentes à equipe.","diagnosis":"A obstrução de vasos pulmonares pode causar lesão do tecido pulmonar; exames confirmam a causa e a extensão.","expected":"A recuperação depende da gravidade, da repercussão cardíaca e do controle do fator desencadeante; acompanhamento previne recorrências.","alarm":"Observe falta de ar súbita, dor torácica ao respirar, palpitações, desmaio ou tosse com sangue.","immediate":"Qualquer piora respiratória importante, desmaio ou sangramento relevante exige atendimento imediato.","return":"Após alta, siga o plano especializado de monitorização, prevenção de novos eventos e segurança do tratamento.","sources":[{"url":"https://www.stanfordchildrens.org/en/topic/default?id=pulmonary-embolism-85-P01308","title":"Stanford Medicine Children’s Health — Pulmonary Embolism","accessed":"2026-09-26"}],"reviewNotes":"Orientação de emergência e seguimento, sem transpor esquemas de anticoagulação adultos.","status":"source-reviewed"},
{"name":"Empiema pleural","aliases":[],"setting":"hospital","general":"O empiema exige acompanhamento hospitalar e avaliação da equipe pediátrica, respiratória e cirúrgica. Mantenha o responsável informado sobre respiração, alimentação e dor.","diagnosis":"Há infecção no espaço ao redor do pulmão. O tratamento pode exigir drenagem além do controle da infecção; não tente manejar o quadro somente em casa.","expected":"A recuperação depende da extensão e da resposta ao tratamento. Febre ou dificuldade respiratória persistentes podem exigir nova avaliação do foco.","alarm":"Informe imediatamente aumento da dor, piora da respiração, menor ingestão ou problemas no dreno, quando presente.","immediate":"Esforço respiratório intenso, coloração azulada, alteração da consciência ou sinais de choque são emergência.","return":"Após alta formal, siga o tratamento e as revisões indicadas; retorne prontamente se febre ou dificuldade respiratória reaparecerem.","sources":[{"url":"https://www.alderhey.nhs.uk/conditions/patient-information-leaflets/empyema-piag-353/","title":"Alder Hey Children’s Hospital — Empyema","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Encefalite herpética","aliases":[],"setting":"hospital","general":"Encefalite herpética necessita de atendimento hospitalar urgente e monitorização. Não aguarde evolução em casa nem trate como uma virose comum.","diagnosis":"A avaliação investiga inflamação cerebral e sua causa; o tratamento precisa começar oportunamente conforme a suspeita clínica.","expected":"A recuperação depende da gravidade e pode ser prolongada; crises, alterações de memória, comportamento ou desenvolvimento podem requerer reabilitação.","alarm":"Febre com confusão, mudança de comportamento, fala alterada, convulsão ou fraqueza são sinais importantes.","immediate":"Qualquer redução de consciência, crise convulsiva ou dificuldade respiratória exige emergência imediata.","return":"Após alta, mantenha neurologia e reabilitação, e siga um plano claro para crises e retorno. Avise a equipe sobre qualquer perda de habilidades.","sources":[{"url":"https://www.nhs.uk/conditions/encephalitis/","title":"NHS — Encephalitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte inclui encefalite por herpes; recomendações de encaminhamento e seguimento, sem extrapolar terapia entre etiologias.","status":"source-reviewed"},
{"name":"Encefalopatia hipóxico-isquêmica","aliases":[],"setting":"hospital","general":"Acompanhamento neonatal e observação neurológica são indispensáveis. Avise mudanças de sucção, resposta, tônus ou movimentos. A equipe explicará os exames e a possibilidade de tratamento específico. A família pode participar dos cuidados conforme a estabilidade e as orientações da unidade.","diagnosis":"O tratamento depende da gravidade; intervenções específicas exigem avaliação urgente da equipe neonatal.","expected":"O prognóstico depende das avaliações e exames seriados; não se pode garantir recuperação sem sequelas.","alarm":"Sonolência excessiva, dificuldade para mamar ou movimentos anormais precisam de comunicação imediata.","immediate":"Apneia, convulsão, coloração azulada ou pouca resposta são emergências.","return":"Após a alta, mantenha seguimento do desenvolvimento e encaminhamentos de reabilitação quando indicados.","sources":[{"url":"https://www.nlg.nhs.uk/resources/hypoxic-ischaemic-encephalopathy-hie/","title":"Northern Lincolnshire and Goole NHS — Hypoxic-ischaemic encephalopathy","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/rchcpg/hospital_clinical_guideline_index/Therapeutic_hypothermia_in_the_neonate/","title":"Royal Children’s Hospital — Therapeutic hypothermia in the neonate","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; plano hospitalar individualizado. Fonte adicional fundamenta vigilância neurológica e participação da família. Critérios para hipotermia não foram transpostos para receita domiciliar.","status":"source-reviewed"},
{"name":"Endocardite Infecciosa em Pediatria","setting":"hospital","aliases":["Endocardite infecciosa"],"general":"Infecção do revestimento interno do coração é grave e precisa de cuidado especializado.","diagnosis":"Informe cardiopatia, procedimentos recentes e exposições. Cumpra integralmente o tratamento e mantenha cuidados odontológicos conforme orientação.","expected":"A recuperação pode levar semanas; algumas situações exigem cirurgia. Melhorar da febre não significa fim do tratamento.","alarm":"Febre persistente, falta de ar, cansaço crescente ou novos sintomas neurológicos são alarmes.","immediate":"Desmaio, dor torácica intensa, fraqueza súbita ou dificuldade respiratória requerem emergência.","return":"Após alta, mantenha cardiologia e infectologia; siga o plano individual de prevenção antes de procedimentos.","sources":[{"url":"https://www.nhs.uk/conditions/endocarditis/","title":"NHS — Endocarditis","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Enterobíase (Oxiuríase)","setting":"home","general":"Infecção intestinal por oxiúros, comum em crianças e transmitida quando ovos chegam à boca pelas mãos ou superfícies.","diagnosis":"Lave mãos, mantenha unhas curtas e evite roê-las. Troque e lave roupas íntimas e de cama conforme orientação; banho pela manhã e cuidado com contatos ajudam a reduzir reinfecção.","expected":"A coceira tende a melhorar com o cuidado adequado, mas reinfecção é comum. Conviventes podem precisar de abordagem coordenada; sintomas persistentes exigem confirmar o diagnóstico e revisar o plano.","alarm":"Dor abdominal forte, vômitos persistentes, sangramento, febre ou lesão genital importante exigem avaliação.","immediate":"Procure atendimento urgente nos sinais de alarme; não compartilhe tratamento sem orientação profissional.","return":"Retorne se a coceira persistir ou voltar; avalie conviventes conforme orientação local e reforce higiene.","sources":[{"url":"https://www.cdc.gov/pinworm/about/index.html","title":"CDC — About Pinworm Infection","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":["Enterobíase em Pediatria"],"status":"source-reviewed"},
{"name":"Enterocolite Necrosante","aliases":["Enterocolite necrosante neonatal"],"setting":"hospital","general":"Suspeita de enterocolite necrosante exige cuidado neonatal hospitalar. Informe mudanças da alimentação, evacuações e comportamento; não reinicie alimentação sem autorização da equipe.","diagnosis":"A inflamação intestinal pode evoluir com lesão grave, necessitando monitorização, suporte e, em alguns casos, cirurgia.","expected":"A evolução depende da extensão e resposta ao tratamento; a retomada da alimentação é individualizada.","alarm":"Distensão abdominal, sangue nas fezes, vômitos ou piora da tolerância alimentar devem ser comunicados imediatamente.","immediate":"Apneia, pouca resposta, abdome muito distendido ou deterioração circulatória exigem intervenção urgente.","return":"Após alta, acompanhe crescimento, nutrição e novos sintomas de obstrução intestinal.","sources":[{"url":"https://idmp.ucsf.edu/document/necrotizing-enterocolitis-icn-final-pdf","title":"UCSF — Necrotizing enterocolitis neonatal protocol","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Enterocolite necrotante","aliases":[],"setting":"hospital","general":"O recém-nascido necessita de acompanhamento em unidade neonatal e possível avaliação cirúrgica. Alimentação e líquidos serão controlados pela equipe conforme o funcionamento intestinal.","diagnosis":"A inflamação pode danificar ou perfurar o intestino. Não ofereça leite, água ou outras substâncias fora do plano hospitalar.","expected":"A evolução depende da extensão da lesão e da resposta ao tratamento. Alguns casos melhoram com cuidado clínico, outros precisam de cirurgia e recuperação prolongada.","alarm":"Comunique aumento da barriga, dor ao toque, vômitos, sangue nas fezes, alteração da cor ou piora da resposta do bebê.","immediate":"Suspeita fora do hospital exige emergência imediata; durante a internação, qualquer piora deve ser comunicada sem demora.","return":"Após alta, siga o plano de alimentação e crescimento. Vômitos persistentes, distensão progressiva ou dificuldade alimentar requerem reavaliação rápida.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/necrotising-enterocolitis/","title":"GOSH — Necrotising enterocolitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Enurese na Infância","aliases":["Enurese"],"setting":"home","general":"Evite culpa e punição. Valorize a participação na rotina e mantenha hábitos regulares de beber água e ir ao banheiro.","diagnosis":"Molhar a cama pode refletir maturação; sintomas urinários diurnos, constipação ou início recente exigem investigação própria.","expected":"A melhora costuma ser gradual. Estratégias como alarme precisam de persistência e acompanhamento.","alarm":"Avise se surgirem dor ao urinar, muita sede, perda de peso ou escapes diurnos.","immediate":"Febre com mal-estar importante ou dificuldade para urinar exige avaliação rápida.","return":"Retorne para revisar resposta e dificuldades. Não restrinja líquidos excessivamente nem interrompa o sono com punições.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Enuresis_-_Bed_wetting_and_Monosymptomatic_Enuresis/","title":"RCH — Enuresis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Enurese noturna monossintomática","aliases":[],"setting":"home","general":"Evite punição ou constrangimento: molhar a cama não é escolha da criança. Mantenha rotina de banheiro e ingestão de líquidos distribuída durante o dia.","diagnosis":"Na forma monossintomática não há sintomas urinários diurnos. Constipação, dor ao urinar ou escapes de dia precisam ser informados porque mudam a avaliação.","expected":"O controle costuma melhorar com o desenvolvimento, mas o tempo varia. Alarmes e outros tratamentos exigem participação da família e orientação profissional.","alarm":"Novo escape diurno, sede exagerada, urina excessiva, perda de peso ou retorno da enurese após longo período seco merecem reavaliação.","immediate":"Febre com dor lombar, vômitos, prostração ou dificuldade para urinar exige atendimento rápido.","return":"Retorne para avaliar adesão e resposta; recompense comportamentos combinados, não somente noites secas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Enuresis_-_Bed_wetting_and_Monosymptomatic_Enuresis/","title":"RCH — Enuresis: Bed wetting and Monosymptomatic Enuresis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Enxaqueca com aura","aliases":[],"setting":"home","general":"Procure ambiente tranquilo durante a crise, mantenha hidratação e regularidade do sono e refeições. Anote duração, sintomas visuais e gatilhos.","diagnosis":"Aura deve ser caracterizada pelo médico; sintomas novos ou diferentes do padrão habitual não devem ser atribuídos automaticamente à enxaqueca.","expected":"As crises podem recorrer, e a intensidade varia. O objetivo é aliviar episódios e reduzir impacto escolar e familiar.","alarm":"Observe aumento da frequência, vômitos persistentes ou mudança do padrão das manifestações.","immediate":"Dor súbita muito intensa, desmaio, confusão, fraqueza ou alteração neurológica persistente exigem avaliação imediata.","return":"Retorne se as crises forem frequentes ou incapacitantes; leve o diário e evite uso repetido de analgésicos sem revisão.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Migraine_headache/","title":"RCH — Migraine","accessed":"2026-09-26"}],"reviewNotes":"Rascunho exige caracterização individual da aura e distinção de sinais neurológicos novos.","status":"source-reviewed"},
{"name":"Enxaqueca na Infância","aliases":["Enxaqueca infantil"],"setting":"home","general":"Mantenha sono regular, refeições, hidratação e diário das crises. Durante a dor, permita repouso em ambiente tranquilo e siga o plano prescrito.","diagnosis":"Enxaqueca deve ser diferenciada de causas secundárias; evite uso repetido de produtos para dor sem revisão.","expected":"As crises podem recorrer, mas frequência e impacto podem melhorar com acompanhamento e manejo dos fatores associados.","alarm":"Mudança do padrão, piora progressiva, vômitos persistentes ou despertar pela dor precisam de revisão.","immediate":"Cefaleia súbita muito intensa, febre com rigidez de nuca ou déficit neurológico exigem emergência.","return":"Retorne se crises prejudicarem escola, sono ou atividades.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Headache/","title":"Royal Children’s Hospital — Headache","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Enxaqueca sem aura","aliases":[],"setting":"home","general":"Mantenha horários regulares de sono e refeições, hidratação e atividade adequada. Durante a crise, permita repouso em local tranquilo e pouco iluminado; registre frequência, duração e possíveis gatilhos.","diagnosis":"Enxaqueca sem aura não exige sintomas visuais prévios. O diagnóstico precisa considerar o padrão da dor e o exame; evite uso repetido de analgésicos sem revisão.","expected":"As crises podem reaparecer, mas um plano individual e mudanças de rotina podem reduzir seu impacto. Não há prazo único para desaparecerem definitivamente.","alarm":"Mudança do padrão, crises mais frequentes, vômitos persistentes ou prejuízo escolar importante justificam reavaliação.","immediate":"Dor súbita muito intensa, alteração de consciência, fraqueza nova ou febre com rigidez de nuca: emergência.","return":"Mantenha revisão com o diário de sintomas; antecipe se o plano não controlar as crises.","sources":[{"url":"https://www.alderhey.nhs.uk/wp-content/uploads/2023/07/Migraine-in-Children-Leaflet-and-Headache-Diary-PIAG-35.pdf","title":"Alder Hey NHS — Migraine in children and headache diary","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Sinais de emergência exigem exclusão de causas secundárias; não atribuir automaticamente sintomas neurológicos novos à enxaqueca.","status":"source-reviewed"},
{"name":"Epifisiólise","aliases":["Epifisiólise proximal do fêmur"],"setting":"urgent","general":"Não permita apoiar peso na perna afetada até avaliação. Procure emergência com ortopedia; transporte a criança com ajuda, evitando caminhar para testar a dor.","diagnosis":"O deslizamento da região de crescimento do fêmur pode causar dor no quadril, coxa ou apenas no joelho.","expected":"A evolução depende da estabilidade e do tratamento; atraso pode aumentar complicações.","alarm":"Claudicação, rotação diferente da perna ou piora da dor exigem atenção.","immediate":"Incapacidade de apoiar, dor intensa ou piora súbita requerem atendimento imediato.","return":"Após tratamento, siga rigorosamente as restrições de carga e o seguimento ortopédico, inclusive do quadril oposto.","sources":[{"url":"https://www.rch.org.au/ortho/for_health_professionals/Slipped_upper_femoral_epiphysis_%E2%80%93_SUFE/","title":"Royal Children’s Hospital Orthopaedics — Slipped upper femoral epiphysis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Epifisiólise proximal do fêmur","aliases":["Epifisiólise femoral proximal","SUFE"],"setting":"hospital","general":"Evite apoio de peso nas pernas até avaliação ortopédica. Transporte a criança carregada ou em cadeira de rodas; não force caminhada nem exercícios do quadril.","diagnosis":"A cabeça do fêmur desloca-se na região de crescimento e geralmente necessita estabilização cirúrgica. A dor pode estar no quadril, virilha, coxa ou somente no joelho.","expected":"O resultado depende da gravidade, estabilidade e rapidez do tratamento. A recuperação e liberação para atividades devem ser definidas pelo cirurgião.","alarm":"Observe piora súbita da dor, nova incapacidade de andar, encurtamento aparente ou rotação incomum da perna.","immediate":"Diante de suspeita, procure pronto atendimento ortopédico imediatamente sem apoiar peso, mesmo se ainda conseguir caminhar.","return":"Após a cirurgia, mantenha as restrições e consultas indicadas. Dor nova no outro quadril ou joelho também requer avaliação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/slipped_upper_femoral_epiphysis_sufe/","title":"RCH — Slipped upper femoral epiphysis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Epifisite da tuberosidade tibial (Osgood-Schlatter)","setting":"home","general":"Dor e sensibilidade na tuberosidade tibial relacionam-se ao crescimento e à tração repetida do tendão patelar.","diagnosis":"Ajuste atividades que provoquem dor, especialmente corrida, saltos e ajoelhar. Alongamentos e retorno ao esporte devem seguir orientação profissional, sem forçar treino doloroso nem imobilizar por conta própria.","expected":"Oscila com a atividade e tende a melhorar ao fim do crescimento; a proeminência óssea pode persistir. Ajuste a atividade à dor.","alarm":"Avalie prontamente se não apoiar ou mover o joelho, houver trauma importante, febre, vermelhidão intensa, dor noturna persistente ou apresentação atípica.","immediate":"Pare a atividade dolorosa, aplique gelo protegido por pano e organize avaliação; não force treino com dor.","return":"Retome gradualmente quando atividades habituais e esportivas forem indolores, conforme orientação. Reduza a carga se os sintomas voltarem e reavalie dor persistente ou limitação funcional.","sources":[{"url":"https://www.rch.org.au/ortho/for_health_professionals/Osgood-Schlatter_disease/","title":"RCH Orthopaedics — Osgood-Schlatter disease","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Epiglotite","aliases":[],"setting":"hospital","general":"Acione emergência e mantenha a criança calma, na posição em que respira melhor, preferencialmente com o responsável. Não force exame da garganta, deitar ou ingestão.","diagnosis":"Epiglotite pode obstruir rapidamente a via aérea e necessita equipe preparada para protegê-la.","expected":"A evolução pode mudar em minutos; melhora aparente não permite observação domiciliar.","alarm":"Salivação excessiva, voz abafada, dificuldade para engolir, ruído respiratório e posição inclinada para frente são preocupantes.","immediate":"Dificuldade respiratória, coloração azulada ou pouca resposta exigem SAMU 192.","return":"O acompanhamento e a alta serão definidos após estabilização hospitalar e resolução do risco de obstrução.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_upper_airway_obstruction/","title":"Royal Children’s Hospital — Acute upper airway obstruction","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Epiglotite aguda","aliases":[],"setting":"hospital","general":"Acione atendimento de emergência imediatamente. Mantenha a criança calma, na posição em que respira melhor, sem forçá-la a deitar.","diagnosis":"A inflamação da epiglote pode fechar rapidamente a passagem de ar. Não tente examinar profundamente a garganta ou oferecer comida e bebida se houver dificuldade para engolir.","expected":"A recuperação pode ser boa com tratamento rápido, mas exige monitorização hospitalar e, em alguns casos, suporte da via aérea.","alarm":"Voz alterada, salivação excessiva, dificuldade para engolir e ruído ao inspirar indicam risco.","immediate":"Qualquer dificuldade respiratória ou suspeita de epiglotite exige emergência sem esperar a evolução em casa.","return":"Depois da alta, siga a revisão indicada e verifique a situação vacinal com a equipe; nova dificuldade respiratória exige retorno imediato.","sources":[{"url":"https://www.nhs.uk/conditions/epiglottitis/","title":"NHS — Epiglottitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Epilepsia em Pediatria","setting":"specialist","aliases":["Epilepsia"],"general":"Epilepsia tem diferentes tipos de crises e exige plano individual de cuidado e segurança.","diagnosis":"Mantenha tratamento e rotina de sono. Familiares e escola devem conhecer o plano para crises e atividades que precisam de supervisão.","expected":"O controle varia conforme a síndrome e a resposta; não suspenda o cuidado por ausência recente de crises.","alarm":"Crise diferente do habitual, lesão ou recuperação incompleta exigem avaliação.","immediate":"Chame emergência para crise prolongada, crises repetidas sem recuperação ou dificuldade respiratória; siga o plano de resgate se treinado.","return":"Mantenha neurologia e registro das crises, efeitos adversos e mudanças do desenvolvimento.","sources":[{"url":"https://www.nhs.uk/conditions/epilepsy/","title":"NHS — Epilepsy","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Epilepsia mioclônica juvenil","aliases":[],"setting":"specialist","general":"Mantenha horários de sono e o plano de tratamento, evitando privação de sono e álcool. Informe escola e cuidadores sobre primeiros socorros.","diagnosis":"Os abalos ao despertar podem fazer parte da síndrome. Registre crises e não altere o tratamento quando houver melhora sem conversar com neurologia.","expected":"A tendência a crises pode persistir na vida adulta; o controle e a resposta variam individualmente.","alarm":"Observe aumento dos abalos, quedas, perda de consciência ou novo tipo de episódio.","immediate":"Crise com cinco minutos, repetição sem recuperação, trauma importante ou dificuldade respiratória exige emergência.","return":"Retorne para revisar controle e efeitos adversos. Durante crises, proteja de lesões, coloque de lado quando possível e não introduza nada na boca.","sources":[{"url":"https://medlineplus.gov/genetics/condition/juvenile-myoclonic-epilepsy/","title":"MedlinePlus — Juvenile myoclonic epilepsy","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/epilepsy/first-aid-for-seizures/index.html","title":"CDC — First Aid for Seizures","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Epispádia","aliases":[],"setting":"specialist","general":"Mantenha higiene delicada e acompanhamento com urologia pediátrica. Observe o jato e a frequência urinária, sem manipulações para tentar corrigir a abertura; leve exames e registros às consultas.","diagnosis":"A epispádia é uma alteração congênita da uretra e pode estar associada a perda urinária, refluxo ou outras anomalias. A avaliação define se há necessidade de cirurgia.","expected":"O resultado depende da anatomia e de eventuais condições associadas; algumas crianças precisam de mais de uma intervenção e seguimento da função urinária.","alarm":"Dor para urinar, febre, sangue na urina ou alteração recente do padrão urinário exigem contato com o serviço.","immediate":"Incapacidade de urinar, dor intensa, vômitos com prostração ou piora importante: atendimento imediato.","return":"Cumpra o retorno urológico e os exames renais recomendados, inclusive após tratamento cirúrgico.","sources":[{"url":"https://medlineplus.gov/ency/article/001285.htm","title":"MedlinePlus — Epispadias","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Epistaxe na Criança","aliases":["Epistaxe","Sangramento nasal"],"setting":"home","general":"Sente a criança inclinada para frente e comprima continuamente a parte macia do nariz por dez minutos; se necessário, repita. Não incline a cabeça para trás.","diagnosis":"Sangramento nasal costuma vir da região anterior, mas episódios frequentes ou em menores de dois anos precisam de avaliação.","expected":"Pequenos episódios podem cessar com compressão e recorrer durante cicatrização.","alarm":"Observe duração, volume, hematomas ou sangramento em outros locais.","immediate":"Hemorragia intensa, desmaio, dificuldade respiratória ou sangramento persistente apesar da compressão exigem atendimento imediato.","return":"Evite cutucar ou assoar forte; retorne se houver repetição frequente ou falha das medidas orientadas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Epistaxis/","title":"Royal Children’s Hospital — Epistaxis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Diretriz atualizada em abril de 2026; manobra de primeiros socorros preservada, sem doses farmacológicas.","status":"source-reviewed"},
{"name":"Equinococose em Pediatria","aliases":["Equinococose"],"setting":"specialist","general":"Mantenha infectologia e a equipe responsável pelo órgão afetado. Leve exames de imagem anteriores.","diagnosis":"A conduta depende do tipo, localização e características dos cistos. Observação e intervenção têm indicações distintas.","expected":"O controle pode exigir acompanhamento prolongado; redução de sintomas não prova desaparecimento do cisto.","alarm":"Observe dor nova, febre, icterícia, tosse ou falta de ar, conforme o órgão envolvido.","immediate":"Dor intensa súbita, dificuldade respiratória, desmaio ou reação alérgica generalizada exige emergência.","return":"Cumpra exames seriados. Não permita punção de lesão suspeita sem planejamento especializado e não interrompa seguimento por melhora aparente.","sources":[{"url":"https://www.cdc.gov/echinococcosis/hcp/clinical-care/index.html","title":"CDC — Clinical treatment of echinococcosis","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/echinococcosis/hcp/clinical-overview/index.html","title":"CDC — Clinical overview of echinococcosis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Erisipela","aliases":["Erisipela em Pediatria"],"setting":"urgent","general":"Procure avaliação no mesmo dia. Informe feridas, eczema, fissuras, picadas, exposição à água e tratamentos já usados.","diagnosis":"Erisipela é infecção superficial da pele que pode acompanhar febre. A equipe deve diferenciá-la de outras causas de vermelhidão e definir gravidade, localização e possibilidade de cuidado domiciliar.","expected":"Após tratamento adequado, espera-se início de melhora em dois a três dias; a pele pode levar mais tempo para normalizar. Piora importante em qualquer momento exige reavaliação.","alarm":"Observe expansão da área, febre persistente, bolhas, listras ascendentes ou dor crescente. Lesões próximas aos olhos ou nariz exigem avaliação especializada.","immediate":"Dor desproporcional, rápida progressão, sonolência, desmaio ou estado geral muito comprometido exige emergência; considere infecção profunda ou sepse.","return":"Retorne se não começar a melhorar em dois a três dias ou antes se piorar. Cumpra o tratamento prescrito e cuide das portas de entrada da pele. Não esprema lesões nem substitua o tratamento por produtos caseiros.","sources":[{"url":"https://www.nice.org.uk/guidance/ng141/chapter/Recommendations","title":"NICE NG141 — Cellulitis and erysipelas: recommendations","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/24566790/","title":"Sociedad Argentina de Pediatría — Consenso de infecções da pele, 2014","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD004299_interventions-cellulitis-and-erysipelas","title":"Cochrane — Interventions for cellulitis and erysipelas, CD004299","accessed":"2026-09-27"}],"reviewNotes":"Revisão agora específica para erisipela; cuidados especiais não são extrapolados. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"Diretriz que inclui crianças e consenso pediátrico; revisão sistemática. Infecções comunitárias; consenso exclui neonatos e imunodeprimidos. Evidência comparativa é heterogênea e antiga; não permite escolher automaticamente o melhor antibiótico.","decisionSupport":{"summary":"Classifique gravidade e fatores especiais; recém-nascidos, imunocomprometidos e envolvimento periocular requerem avaliação específica.","requirements":["Idade, especialmente período neonatal","Local, extensão e velocidade de progressão","Estado geral e intensidade da dor","Imunidade e doenças associadas","Capacidade de ingerir tratamento","Exposições e resposta inicial"],"branchRequired":false,"branches":[]},"revisedAt":"2026-09-27"},
{"name":"Eritema infeccioso (Parvovírus B19)","aliases":["Eritema infeccioso","Quinta doença"],"setting":"home","general":"Mantenha repouso conforme necessidade, líquidos e higiene das mãos. Avise se a criança possui doença do sangue ou baixa imunidade.","diagnosis":"Informe contatos gestantes para que procurem orientação de sua equipe. Em crianças saudáveis, o cuidado costuma focar conforto e observação dos sintomas.","expected":"A erupção geralmente melhora em cerca de uma semana a dez dias, mas pode reaparecer por semanas. A maioria dos casos é leve.","alarm":"Observe palidez nova ou crescente, cansaço intenso, falta de ar ou febre persistente; doenças hematológicas aumentam o risco de anemia importante.","immediate":"Palidez acentuada com fraqueza, falta de ar, desmaio ou pouca resposta exige pronto atendimento.","return":"Reavalie se houver piora, sintomas prolongados ou condição de risco. Não conclua que toda erupção de face seja parvovirose sem avaliação clínica.","sources":[{"url":"https://www.cdc.gov/parvovirus-b19/about/index.html","title":"CDC — About parvovirus B19","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Eritema multiforme","aliases":[],"setting":"home","general":"Mantenha a pele limpa e evite manipular bolhas. Observe se a criança consegue beber, comer e urinar normalmente. Informe todos os medicamentos usados recentemente.","diagnosis":"O eritema multiforme pode acompanhar infecções ou medicamentos. Lesões em boca, olhos ou genitais precisam de avaliação e não devem ser consideradas uma erupção leve automaticamente.","expected":"Formas leves costumam melhorar em duas a quatro semanas; podem ocorrer novos episódios e a evolução muda se houver mucosas comprometidas.","alarm":"Dor intensa, febre, lesões que se expandem ou dificuldade para alimentar-se justificam avaliação rápida.","immediate":"Falta de ar, inchaço de língua/garganta, desmaio ou prostração acentuada exigem emergência imediata.","return":"Retorne se houver recorrência, piora ou persistência além do esperado; procure antes se surgir acometimento dos olhos.","sources":[{"url":"https://www.nhs.uk/conditions/erythema-multiforme/","title":"NHS — Erythema multiforme","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Uso domiciliar apenas após classificação clínica como forma leve.","status":"source-reviewed"},
{"name":"Eritroparvovirose B19 (parvovirose B19)","aliases":["Eritema infeccioso por parvovírus B19"],"setting":"home","general":"Ofereça líquidos e descanso conforme a disposição; informe contato com gestantes e se a criança tem doença hematológica ou baixa imunidade.","diagnosis":"O parvovírus B19 geralmente causa quadro leve e manchas na pele; pessoas com condições específicas têm maior risco de anemia.","expected":"As manchas costumam melhorar e podem reaparecer por algumas semanas, sem significar necessariamente nova infecção.","alarm":"Observe palidez acentuada, cansaço incomum, palpitações ou piora do estado geral.","immediate":"Falta de ar, desmaio ou prostração intensa exigem pronto atendimento, especialmente em doenças hemolíticas.","return":"Procure avaliação precoce se houver imunossupressão, anemia prévia ou evolução diferente do habitual.","sources":[{"url":"https://www.cdc.gov/parvovirus-b19/about/index.html","title":"CDC — About Parvovirus B19","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Escabiose","aliases":["Escabiose em Pediatria"],"setting":"home","general":"Trate contatos próximos conforme orientação, no mesmo período. Lave roupas, toalhas e roupa de cama usadas recentemente e não compartilhe objetos pessoais.","diagnosis":"Complete a aplicação exatamente como prescrita, respeitando idade e áreas indicadas. Não use inseticidas ambientais ou produtos veterinários na pele.","expected":"A coceira pode continuar após eliminação do ácaro; nova lesão ou persistência prolongada merece revisão, sem repetir tratamento indiscriminadamente.","alarm":"Observe feridas com pus, dor crescente, febre ou crostas extensas, especialmente em imunossuprimidos.","immediate":"Febre com prostração ou infecção de pele rapidamente progressiva exige atendimento imediato.","return":"Retorne se surgirem novos sulcos/lesões ou não houver melhora; confirme orientação para retorno à escola e manejo de todos os contatos.","sources":[{"url":"https://www.cdc.gov/scabies/about/index.html","title":"CDC — About Scabies","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Escarlatina","aliases":[],"setting":"home","general":"Ofereça líquidos e alimentos que sejam confortáveis para engolir, mantenha higiene das mãos e não compartilhe copos ou talheres. Cumpra integralmente o tratamento prescrito.","diagnosis":"A escarlatina é uma infecção transmissível que precisa de avaliação. Mantenha a criança afastada da creche ou escola por pelo menos 24 horas após a primeira dose do antibiótico prescrito, conforme orientação do NHS. Siga também a orientação assistencial; não se baseie apenas no desaparecimento das manchas para o retorno.","expected":"Geralmente melhora em cerca de uma semana; pode haver descamação da pele durante a recuperação. Piora ou novo adoecimento após melhora exige revisão.","alarm":"Dificuldade para beber, febre persistente, dor crescente ou novo mal-estar precisam de reavaliação.","immediate":"Falta de ar, sonolência incomum, dificuldade para engolir saliva ou sinais de desidratação importante: emergência.","return":"Retorne se não houver melhora ou se surgirem novas manifestações nas semanas seguintes.","sources":[{"url":"https://www.nhs.uk/conditions/scarlet-fever/","title":"NHS — Scarlet fever (revisão de 23/12/2024)","accessed":"2026-10-15"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed","revisedAt":"2026-10-15"},
{"name":"Esclerodermia localizada (Morfeia)","setting":"specialist","general":"Doença inflamatória com áreas endurecidas ou espessadas e alteração de cor; formas profundas podem atingir tecidos subjacentes.","diagnosis":"Mantenha seguimento com equipe especializada. Registre novas áreas e alterações de mobilidade; fisioterapia e cuidados da pele devem ser individualizados, especialmente quando houver articulações, face ou tecidos profundos envolvidos.","expected":"A atividade e a duração variam; podem permanecer alterações de cor, espessura ou atrofia mesmo após controle. Formas profundas exigem vigilância do crescimento e da função.","alarm":"Avaliação rápida se progressão acelerada, dor, limitação articular, assimetria de membro, lesão facial/couro cabeludo, sintomas neurológicos ou alteração ocular.","immediate":"Não use produtos irritantes nem tratamento por conta própria; registre mudanças e encaminhe rapidamente se a doença for extensa ou profunda.","return":"Mantenha revisões para atividade, crescimento, mobilidade e complicações; retorne antes com novas áreas ou piora.","sources":[{"url":"https://www.dukehealth.org/treatments/pediatric-rheumatology/localized-scleroderma","title":"Duke Health — Juvenile Localized Scleroderma","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Esclerose tuberosa","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento multidisciplinar e o calendário de avaliações dos órgãos envolvidos. Registre episódios suspeitos de convulsão e mudanças de desenvolvimento ou comportamento.","diagnosis":"A doença pode afetar cérebro, rins, coração, pele e outros órgãos; o acompanhamento é individual, mesmo quando não há sintomas aparentes.","expected":"A evolução varia amplamente e exige vigilância ao longo da vida. Crescimento de lesões ou surgimento de sintomas não segue um prazo uniforme.","alarm":"Observe novas crises, perda de habilidades, cefaleia persistente, vômitos, dor na região lombar ou alteração urinária.","immediate":"Convulsão prolongada, repetição sem recuperação, perda de consciência, dor intensa com sangue na urina ou dificuldade respiratória exige emergência.","return":"Antecipe a consulta com sintomas novos e mantenha exames programados. A família deve ter plano para crises e orientação sobre necessidades de aprendizagem e desenvolvimento.","sources":[{"url":"https://www.genomicseducation.hee.nhs.uk/genotes/knowledge-hub/tuberous-sclerosis-complex/","title":"NHS Genomics Education — Tuberous sclerosis complex","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Escoliose idiopática do adolescente","aliases":[],"setting":"specialist","general":"Mantenha atividades liberadas e apoio escolar e emocional. Se houver colete, use-o pelo tempo prescrito e informe desconforto que impeça sua utilização.","diagnosis":"A escoliose precisa ser acompanhada durante o crescimento. A decisão entre observar, usar colete ou operar considera a curva e sua progressão.","expected":"Curvas pequenas podem permanecer estáveis; outras aumentam enquanto a criança cresce. Exercícios auxiliam condicionamento, mas não garantem correção da deformidade.","alarm":"Aumento da assimetria, dor persistente, lesões por pressão do colete ou limitação crescente exigem revisão.","immediate":"Fraqueza nova, alteração da sensibilidade, perda do controle urinário/intestinal ou dificuldade respiratória relevante exigem atendimento urgente.","return":"Cumpra retornos com ortopedia e exames programados; não deixe de acompanhar por ausência de dor.","sources":[{"url":"https://www.niams.nih.gov/health-topics/scoliosis/diagnosis-treatment-and-steps-to-take","title":"NIAMS — Scoliosis in Children and Teens: Treatment","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Escroto Agudo em Pediatria","aliases":[],"setting":"urgent","general":"Procure avaliação cirúrgica imediatamente diante de dor ou inchaço escrotal agudo; informe quando começou e se houve trauma.","diagnosis":"É necessário excluir torção testicular e hérnia encarcerada; exames não devem atrasar a avaliação especializada.","expected":"A possibilidade de preservar o testículo depende da rapidez do atendimento e da causa encontrada.","alarm":"Dor súbita, vômitos, vermelhidão ou testículo em posição diferente aumentam a preocupação.","immediate":"Vá ao pronto atendimento agora, mesmo se a dor melhorar espontaneamente; recém-nascidos podem ter alteração de cor sem dor aparente.","return":"O seguimento e os cuidados posteriores dependem do diagnóstico e da avaliação cirúrgica.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_scrotal_pain_or_swelling/","title":"RCH — Acute scrotal pain or swelling","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Esofagite eosinofílica","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento gastroenterológico e nutricional. Observe tempo das refeições, dificuldade para engolir, vômitos e ganho de peso.","diagnosis":"A esofagite eosinofílica é uma inflamação crônica do esôfago. Dietas de exclusão devem ser planejadas para evitar deficiência nutricional.","expected":"A melhora dos sintomas não confirma sozinha o controle da inflamação; a equipe define exames de acompanhamento e ajustes.","alarm":"Alimentação cada vez mais lenta, recusa alimentar, dor ao engolir ou sensação de comida parada merecem contato com a equipe.","immediate":"Alimento impactado com incapacidade de engolir saliva, engasgo ou dificuldade respiratória exige urgência.","return":"Retorne no calendário combinado e antes se houver perda de peso ou piora da deglutição; não tente empurrar alimento preso.","sources":[{"url":"https://www.chop.edu/conditions-diseases/eosinophilic-esophagitis","title":"CHOP — Eosinophilic Esophagitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Esporotricose em Pediatria","aliases":["Esporotricose"],"setting":"specialist","general":"Evite contato desprotegido com lesões de animais e procure avaliação veterinária do animal suspeito. Não abandone animais doentes.","diagnosis":"A infecção pode ocorrer por arranhadura, mordida ou trauma com material contaminado. A forma clínica orienta a investigação.","expected":"O tratamento costuma ser prolongado, com duração variável. Melhora inicial não autoriza interromper o acompanhamento.","alarm":"Observe novas lesões, nódulos, dor articular, sintomas oculares, febre ou sintomas respiratórios.","immediate":"Falta de ar, alteração visual ou piora importante do estado geral exige atendimento imediato.","return":"Mantenha seguimento até resolução definida pela equipe, com revisão da extensão e da resposta.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/e/esporotricose-humana","title":"Ministério da Saúde — Esporotricose Humana","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Esquistossomose em Pediatria","setting":"specialist","aliases":["Esquistossomose"],"general":"Evite contato com água doce em locais de transmissão e informe a exposição ao serviço de saúde.","diagnosis":"Cumpra exames e tratamento orientados; sintomas discretos não excluem infecção.","expected":"A evolução varia com a fase e os órgãos acometidos; melhora isolada não comprova cura.","alarm":"Sangue nas fezes, aumento abdominal ou emagrecimento precisam de reavaliação.","immediate":"Sangramento importante, desmaio ou falta de ar exigem emergência.","return":"Retorne para controle da resposta e mantenha seguimento especializado se houver comprometimento hepático ou outras complicações.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/e/esquistossomose","title":"Ministério da Saúde — Esquistossomose","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"No contexto brasileiro, corresponde à esquistossomose por S. mansoni já pesquisada no conjunto inicial. Orientações resumidas com equivalência explicitada; formas graves exigem avaliação especializada. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Esquizofrenia Infantil","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento em saúde mental infantojuvenil. Escute com respeito, acolha o sofrimento e organize uma rotina previsível.","diagnosis":"O diagnóstico é raro em crianças e requer avaliação cuidadosa; ouvir vozes isoladamente não estabelece esquizofrenia.","expected":"O curso varia. Tratamento continuado e suporte familiar podem melhorar funcionamento e participação social.","alarm":"Informe piora de isolamento, sono, autocuidado, experiências perceptivas ou comportamento.","immediate":"Risco de suicídio, agressão ou incapacidade de permanecer em segurança exige atendimento de emergência.","return":"Faça revisões regulares do plano e dos efeitos adversos; mudanças de tratamento devem ser combinadas com a equipe.","sources":[{"url":"https://www.nimh.nih.gov/health/publications/schizophrenia","title":"NIMH — Schizophrenia","accessed":"2026-09-26"}],"reviewNotes":"Fonte abrange esquizofrenia e ressalta raridade infantil. Diagnóstico e plano pediátrico exigem especialista; conteúdo documental, sem homologação clínica.","status":"source-reviewed"},
{"name":"Estado de Mal Epiléptico em Pediatria","aliases":[],"setting":"hospital","general":"Acione socorro e informe duração da crise, episódios anteriores e qualquer medicamento de resgate já utilizado; proteja contra lesões.","diagnosis":"Crise prolongada ou crises repetidas sem recuperação constituem emergência e podem comprometer respiração e circulação.","expected":"A equipe precisa controlar a crise e investigar a causa; a recuperação depende da duração e da condição associada.","alarm":"Não espere cessar espontaneamente se a crise atingiu cinco minutos; observe mudança da respiração ou coloração.","immediate":"A criança deve receber atendimento hospitalar imediato, com suporte intensivo quando necessário.","return":"Após estabilização, a equipe definirá seguimento neurológico e plano para novas crises.","sources":[{"url":"https://www.childrens.health.qld.gov.au/for-health-professionals/queensland-paediatric-emergency-care-qpec/queensland-paediatric-clinical-guidelines/status-epilepticus","title":"Children’s Health Queensland — Status epilepticus","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Estafilococcia cutânea","aliases":[],"setting":"home","general":"Mantenha a pele limpa, cubra lesões que drenam e lave as mãos antes e depois dos cuidados. Não esprema caroços e não compartilhe toalhas ou objetos em contato com as feridas.","diagnosis":"Estafilococcia cutânea inclui diferentes apresentações, como abscesso e celulite. A avaliação precisa definir o tipo, a extensão e se há necessidade de drenagem ou tratamento específico.","expected":"Lesões localizadas podem melhorar com o cuidado correto; não existe prazo único para todas as formas. Aumento da área afetada exige revisão.","alarm":"Dor crescente, pele muito quente, pus, febre ou lesões recorrentes devem ser avaliados.","immediate":"Piora rápida, dor desproporcional, prostração, desmaio ou falta de ar: emergência.","return":"Retorne se não houver melhora ou se o quadro voltar; o profissional decidirá se é necessário investigar colonização ou outras condições.","sources":[{"url":"https://www.nhs.uk/conditions/staphylococcal-infections/","title":"NHS — Staph infection","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Estenose Aórtica em Pediatria","aliases":["Estenose aórtica"],"setting":"specialist","general":"Siga o plano da cardiologia pediátrica e confirme quais atividades físicas são permitidas. Não aumente o esforço se houver sintomas.","diagnosis":"O estreitamento da saída do coração dificulta o fluxo de sangue; sua localização e gravidade determinam monitorização ou intervenção.","expected":"Quadros leves podem permanecer estáveis, mas a evolução varia e requer ecocardiogramas conforme o especialista.","alarm":"Relate cansaço desproporcional, dor no peito, palpitações, tontura ou dificuldade para alimentar-se.","immediate":"Desmaio, dor torácica com esforço ou falta de ar importante exigem avaliação imediata.","return":"Mantenha retornos mesmo sem sintomas e antecipe-os se a capacidade de realizar atividades diminuir.","sources":[{"url":"https://www.cincinnatichildrens.org/health/a/avs","title":"Cincinnati Children’s — Aortic valve stenosis in infants and children","accessed":"2026-09-26"},{"url":"https://www.leedsth.nhs.uk/patients/resources/aortic-valve-disease/","title":"Leeds Teaching Hospitals NHS — Aortic valve disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Fonte pediátrica específica acrescentada; não equipara obstrução valvar, subvalvar e supravalvar. Limites de esforço e intervenções permanecem individualizados.","status":"source-reviewed"},
{"name":"Estenose de Valva Pulmonar","setting":"specialist","aliases":["Estenose pulmonar valvar"],"general":"O estreitamento da valva pulmonar tem gravidade variável; algumas crianças precisam apenas de vigilância especializada.","diagnosis":"Mantenha consultas e ecocardiogramas mesmo sem sintomas. Atividade física e necessidade de intervenção dependem da avaliação cardiológica.","expected":"Quadros leves podem permanecer estáveis; outros necessitam procedimento e acompanhamento posterior.","alarm":"Cansaço desproporcional, piora alimentar, coloração azulada ou redução da tolerância ao esforço precisam de avaliação.","immediate":"Desmaio, dor torácica ou falta de ar intensa exigem emergência.","return":"Retorne nos prazos do cardiologista e antecipe a consulta diante de novos sintomas, mesmo após um procedimento bem-sucedido.","sources":[{"url":"https://www.leedsth.nhs.uk/patients/resources/pulmonary-stenosis-in-children/","title":"Leeds Teaching Hospitals — Pulmonary Stenosis in children","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Estenose hipertrófica do piloro","setting":"hospital","general":"Estreitamento da saída gástrica por hipertrofia do piloro, causando obstrução e podendo provocar desidratação e alterações metabólicas.","diagnosis":"Procure avaliação hospitalar para vômitos progressivos em um lactente. Registre mamadas e fraldas molhadas; siga a orientação da equipe sobre alimentação antes e depois da correção cirúrgica.","expected":"A alimentação costuma ser retomada gradualmente após estabilização e cirurgia, conforme tolerância. O tempo de recuperação depende da hidratação e da evolução; vômitos persistentes precisam ser reavaliados.","alarm":"Vômito verde ou sanguinolento, prostração, pouca urina, boca seca, olhos fundos ou piora rápida exigem emergência.","immediate":"Leve o bebê à emergência se houver vômito verde, prostração ou pouca urina. Não tente corrigir a obstrução com mudanças alimentares ou medidas caseiras.","return":"Retornar imediatamente com vômitos persistentes, desidratação, febre, distensão ou recusa alimentar; cumprir revisão pós-operatória.","sources":[{"url":"https://medlineplus.gov/ency/article/000970.htm","title":"MedlinePlus — Pyloric stenosis in infants","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Estenose Mitral em Pediatria","aliases":["Estenose mitral"],"setting":"specialist","general":"Mantenha acompanhamento cardiológico e informe limitações ao esforço ou dificuldades alimentares.","diagnosis":"O estreitamento dificulta a passagem do sangue dentro do coração. A causa e a anatomia orientam o tratamento.","expected":"Medicamentos podem aliviar repercussões, mas não corrigem o estreitamento; alguns casos precisam de procedimento.","alarm":"Observe cansaço crescente, falta de ar, palpitações ou redução da capacidade habitual.","immediate":"Dificuldade respiratória importante, desmaio ou dor torácica intensa exige emergência.","return":"Compareça aos exames programados e antecipe a consulta com sintomas novos. Se houver origem reumática ou prótese, siga também as orientações específicas.","sources":[{"url":"https://www.heart.org/en/health-topics/heart-valve-problems-and-disease/heart-valve-problems-and-causes/problem-mitral-valve-stenosis","title":"AHA — Mitral valve stenosis","accessed":"2026-09-26"}],"reviewNotes":"Fonte inclui causas congênitas e reumáticas. Sem extrapolação de procedimentos ou anticoagulação universais para crianças. Revisão médica necessária.","status":"source-reviewed"},
{"name":"Estenose valvar aórtica","aliases":[],"setting":"specialist","general":"Mantenha revisões cardiológicas mesmo sem sintomas e cuide da saúde bucal. Atividades físicas devem seguir a liberação individual da cardiologia.","diagnosis":"O estreitamento da válvula aumenta o trabalho do coração. Exames seriados orientam necessidade e momento de procedimentos; o grau de obstrução não é igual em todas as crianças.","expected":"A condição pode mudar com o crescimento. Tratamentos podem aliviar a obstrução, mas não dispensam seguimento e podem exigir futuras intervenções.","alarm":"Observe redução da tolerância ao esforço, cansaço, dor torácica, palpitações ou tontura; em bebês, dificuldade para mamar e respirar.","immediate":"Desmaio, dor no peito durante esforço, falta de ar importante ou palidez intensa exigem atendimento imediato.","return":"Interrompa exercício que provoque sintomas e antecipe a revisão. Informe febre persistente e procedimentos odontológicos à equipe assistente.","sources":[{"url":"https://www.leedsth.nhs.uk/patients/resources/aortic-stenosis-in-children/","title":"Leeds Teaching Hospitals — Aortic stenosis in children","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Estenose valvar pulmonar","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento cardiológico e informe cansaço nas mamadas, ao caminhar ou durante brincadeiras. Leve exames prévios e registros de procedimentos.","diagnosis":"A válvula estreitada dificulta a passagem do sangue para os pulmões. A conduta depende da intensidade da obstrução, dos sintomas e do funcionamento do coração.","expected":"Algumas formas leves exigem observação; outras precisam de intervenção. Mesmo após tratamento, podem surgir alterações que justificam seguimento prolongado.","alarm":"Palpitações, inchaço, dificuldade para ganhar peso ou piora da tolerância às atividades precisam ser comunicados.","immediate":"Falta de ar importante, desmaio, dor torácica com mal-estar ou coloração azulada nova exigem emergência.","return":"Retorne nas datas da cardiologia e confirme quais atividades são adequadas à condição atual; antecipe avaliação se aparecerem sintomas.","sources":[{"url":"https://www.medlineplus.gov/ency/article/001096.htm","title":"MedlinePlus — Pulmonic valve stenosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Estomatite Aftosa Recorrente (Aftas)","aliases":["Aftas recorrentes"],"setting":"home","general":"Ofereça alimentos macios e líquidos tolerados. Evite comidas ácidas, muito quentes ou ásperas e use escova macia.","diagnosis":"Aftas recorrentes precisam de revisão quando atípicas; não são necessariamente herpes nem infecção bacteriana.","expected":"Lesões comuns melhoram em uma a duas semanas, mas podem reaparecer.","alarm":"Observe lesão que persiste além de três semanas, aumenta, sangra ou se acompanha de lesões genitais e articulações dolorosas.","immediate":"Incapacidade de beber, desidratação ou importante piora geral exige avaliação urgente.","return":"Retorne em recorrências frequentes ou diferentes do padrão para investigar causas e ajustar cuidado.","sources":[{"url":"https://www.nhs.uk/conditions/mouth-ulcers/","title":"NHS — Mouth ulcers","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Estridor","setting":"urgent","aliases":["Estridor respiratório"],"general":"Ruído agudo ao respirar é um sinal de estreitamento das vias aéreas, com diferentes causas.","diagnosis":"Mantenha a criança calma na posição mais confortável. Não force exame da garganta nem alimentação se houver dificuldade respiratória.","expected":"A evolução depende da causa; melhora aparente não dispensa avaliação de início súbito ou sintomas persistentes.","alarm":"Ruído em repouso, esforço respiratório, baba, dificuldade de engolir ou voz alterada são alarmes.","immediate":"Coloração azulada, exaustão ou redução da consciência exigem emergência imediata.","return":"O retorno depende do diagnóstico; procure reavaliação antes se o ruído ou o esforço aumentarem.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_upper_airway_obstruction/","title":"RCH — Acute upper airway obstruction","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Estrongiloidíase","aliases":[],"setting":"specialist","general":"Use calçados, evite contato com solo contaminado e mantenha higiene e saneamento. Complete o tratamento prescrito e compareça ao controle.","diagnosis":"Informe a infecção antes de qualquer tratamento que reduza a imunidade. Ela pode permanecer no organismo e se agravar nessa situação.","expected":"A evolução depende do estado imune e da resposta; ausência de sintomas não garante eliminação do parasita.","alarm":"Observe dor abdominal, diarreia persistente, emagrecimento, tosse ou piora do estado geral.","immediate":"Falta de ar, febre com prostração, confusão, sangue nas fezes ou dor abdominal intensa exigem emergência, sobretudo em imunossuprimidos.","return":"Retorne para confirmar resposta e definir necessidade de exames. Não inicie corticoide por conta própria e não suspenda tratamento habitual sem orientação.","sources":[{"url":"https://www.cdc.gov/strongyloides/about/index.html","title":"CDC — About Strongyloides","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Exantema súbito (Roséola infantum)","aliases":["Exantema Súbito"],"setting":"home","general":"Ofereça líquidos e mamadas frequentes, permita repouso e acompanhe disposição e urina. Observe o comportamento da criança, além do número no termômetro.","diagnosis":"Na roséola típica, as manchas costumam aparecer quando a febre melhora. Febre com manchas também pode ter outras causas; não confirme o diagnóstico apenas pelo aspecto da pele.","expected":"A infecção geralmente melhora em uma semana, e as manchas costumam desaparecer em poucos dias. A persistência de febre ou piora do estado geral não deve ser atribuída automaticamente à roséola.","alarm":"Recusa de líquidos, poucas fraldas molhadas, febre prolongada ou grande irritabilidade exigem revisão.","immediate":"Convulsão, manchas que não clareiam à pressão, dificuldade respiratória ou pouca resposta: emergência.","return":"Retorne antes do previsto se houver piora; lactente pequeno com febre requer avaliação imediata.","sources":[{"url":"https://www.nhs.uk/conditions/roseola/","title":"NHS — Roseola","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Exantemas Febris em Pediatria","aliases":["Exantema febril"],"setting":"home","general":"Após avaliação que permita cuidado domiciliar, observe estado geral, ingestão e evolução das manchas. Informe vacinas, contatos, viagens e novos produtos utilizados.","diagnosis":"Febre com manchas tem muitas causas; o aspecto da pele isoladamente não confirma virose.","expected":"A evolução depende do diagnóstico; uma criança inicialmente bem pode precisar de nova avaliação se o quadro mudar.","alarm":"Manchas que não clareiam à pressão, dor importante, sangramento ou prostração precisam de avaliação urgente.","immediate":"Piora rápida, falta de ar, convulsão ou pouca resposta exigem emergência.","return":"Retorne se a febre persistir ou surgirem novos sinais; siga afastamento específico após esclarecimento da causa.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Petechiae_and_purpura/","title":"Royal Children’s Hospital — Petechiae and purpura","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Orientação sindrômica de vigilância, não substitui material específico de sarampo, varicela, dengue e outras etiologias. Alta somente após avaliação clínica tranquilizadora.","status":"source-reviewed"},
{"name":"Extremo Baixo Peso ao Nascimento (EBPN)","setting":"hospital","aliases":["Extremo baixo peso ao nascer","EBPN"],"general":"Recém-nascido de extremo baixo peso precisa de cuidado neonatal para temperatura, respiração, alimentação e desenvolvimento.","diagnosis":"Participe dos cuidados orientados, incluindo contato pele a pele quando possível e apoio ao leite materno, conforme estabilidade e equipe.","expected":"A internação e a evolução variam; crescimento e desenvolvimento precisam de acompanhamento prolongado.","alarm":"Pausas respiratórias, mudança de cor, temperatura anormal ou dificuldade alimentar são alarmes.","immediate":"Avise imediatamente a equipe; após alta, esses sinais exigem atendimento urgente.","return":"Mantenha seguimento neonatal, crescimento, audição, visão e desenvolvimento, com plano de retorno individualizado.","sources":[{"url":"https://www.who.int/news/item/15-11-2022-who-advises-immediate-skin-to-skin-care-for-survival-of-small-and-preterm-babies","title":"WHO — Immediate skin-to-skin care for survival of small and preterm babies","accessed":"2026-09-26"},{"url":"https://www.who.int/publications/i/item/9789240058262/","title":"WHO — Care of the preterm or low-birth-weight infant","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"WHO aborda prematuros/baixo peso em geral; extremo baixo peso requer individualização neonatal. Contato pele a pele, alimentação e alta dependem da condição clínica e do plano assistencial. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Extrofia de Bexiga e Epispádia","aliases":[],"setting":"hospital","general":"Procure equipe de urologia pediátrica experiente. Não pressione nem manipule a bexiga exposta; siga os cuidados de proteção definidos pela equipe.","diagnosis":"A abertura da bexiga e a posição anormal da uretra exigem avaliação da anatomia, dos rins e das condições para reconstrução.","expected":"O tratamento pode envolver etapas e acompanhamento prolongado; continência e função renal variam conforme a anatomia e a resposta.","alarm":"Observe sangramento, alteração da mucosa, febre ou dificuldade de drenagem urinária.","immediate":"Avise imediatamente a equipe diante de piora geral, sangramento importante ou interrupção da drenagem.","return":"Após procedimentos, mantenha revisão urológica e cuidados específicos com sondas e feridas.","sources":[{"url":"https://www.chop.edu/conditions-diseases/bladder-exstrophy","title":"CHOP — Bladder Exstrophy","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Extrofia vesical","aliases":[],"setting":"hospital","general":"Contate centro de urologia pediátrica experiente. Informe se a bexiga está exposta, se houve reconstrução e quais dispositivos estão presentes.","diagnosis":"A anatomia e a etapa do tratamento definem os cuidados. Avalie alterações urinárias, genitais e pélvicas associadas.","expected":"Reconstrução pode exigir etapas; continência e função renal precisam de seguimento prolongado. Encaminhamento precoce não implica cirurgia imediata para todos.","alarm":"Observe lesão da mucosa, abertura de ferida, febre ou mudança na drenagem urinária.","immediate":"Mucosa exposta no recém-nascido exige atendimento neonatal/urológico imediato. Prostração, sangramento importante ou falha da drenagem requer avaliação urgente.","return":"Preserve relatórios e plano escrito de dispositivos. Mantenha cuidado renal, urinário e apoio psicossocial, incluindo transição à vida adulta.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/bladder-exstrophy-and-epispadias/","title":"GOSH — Bladder exstrophy and epispadias, 2018","accessed":"2026-09-27"},{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/transitional-urology","title":"EAU/ESPU — Paediatric Urology: transitional urology, 2026","accessed":"2026-09-27"},{"url":"https://www.hopkinsmedicine.org/news/articles/2025/11/a-lifetime-of-care-for-patients-born-with-bladder-exstrophy","title":"Johns Hopkins — A lifetime of care for bladder exstrophy, 2025","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/29368874/","title":"Sabetkish et al. — Preoperative care of exposed mucosal template, 2018","accessed":"2026-09-27"}],"reviewNotes":"Confrontado com tema PedWB 4; sem prazo cirúrgico ou material universal. Revisão documental assistida; sem homologação humana ou autorização farmacológica.","status":"source-reviewed","evidenceSummary":"Diretriz EAU, cuidado institucional e opinião publicada de Heather DiCarlo; pequena série. Extrofia pediátrica e transição à idade adulta. Técnicas variam; série pequena não valida qualquer filme doméstico.","decisionSupport":{"summary":"Distinguir mucosa exposta de reconstrução prévia: essa informação muda manuseio, destino e sinais de complicação.","requirements":["Idade e anatomia confirmada","Mucosa exposta ou etapa reconstrutiva","Cateteres/canais e drenagem habitual","Função renal e plano do centro"],"branchRequired":true,"branches":[{"id":"exposed","label":"Bexiga exposta","when":"Antes do fechamento ou reabertura confirmada.","setting":"hospital","overrides":{"diagnosis":"Proteja a mucosa conforme orientação da equipe receptora; evite trauma e produtos improvisados.","expected":"Momento da reconstrução é individual.","return":"Transferência e acompanhamento pelo centro.","alarm":"Ressecamento, lesão ou sangramento.","immediate":"Deterioração neonatal: emergência."}},{"id":"reconstructed","label":"Após reconstrução","when":"Anatomia e dispositivos documentados.","setting":"specialist","overrides":{"diagnosis":"Siga instruções específicas; não retire ou manipule dispositivos sem treinamento.","expected":"Função urinária pode exigir intervenções adicionais.","return":"Seguimento renal e de continência prolongado.","alarm":"Febre, dor ou drenagem reduzida.","immediate":"Obstrução ou abertura da ferida: avaliação imediata."}}]},"revisedAt":"2026-09-27"},
{"name":"Faringoamigdalite na Infância","aliases":["Faringoamigdalite"],"setting":"home","general":"Ofereça líquidos e alimentos tolerados, mantenha repouso conforme disposição e higiene das mãos.","diagnosis":"Muitos quadros são virais. Quando houver suspeita de estreptococo, a avaliação e os testes indicados orientam o tratamento.","expected":"Os sintomas devem melhorar progressivamente; piora ou persistência exige revisão do diagnóstico.","alarm":"Observe dificuldade para beber, febre persistente ou dor que aumenta rapidamente.","immediate":"Dificuldade respiratória, incapacidade de engolir, alteração da fala ou dificuldade para abrir a boca exige emergência.","return":"Retorne se não houver melhora ao longo da semana ou antes diante de agravamento; cumpra o tratamento prescrito.","sources":[{"url":"https://www.nhs.uk/conditions/tonsillitis/","title":"NHS — Tonsillitis","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html","title":"CDC — Clinical guidance for group A streptococcal pharyngitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Fasciolíase em Pediatria","setting":"specialist","aliases":["Fasciolíase"],"general":"Infecção parasitária pode afetar fígado e vias biliares, com manifestações diferentes ao longo do tempo.","diagnosis":"Informe consumo de agrião ou outras plantas aquáticas cruas e viagens. Evite novas exposições e siga exames e tratamento orientados.","expected":"Pode permanecer sem sintomas por períodos prolongados; controle clínico e laboratorial confirma a resposta.","alarm":"Dor abdominal persistente, febre, icterícia ou vômitos exigem reavaliação.","immediate":"Dor intensa com febre, prostração ou piora rápida requer atendimento urgente.","return":"Mantenha seguimento para verificar resolução e complicações biliares; não presuma cura apenas pela melhora inicial.","sources":[{"url":"https://www.cdc.gov/liver-flukes/hcp/clinical-overview-fasciola/index.html","title":"CDC — Clinical Overview of Fasciola","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Fascite necrosante","aliases":[],"setting":"hospital","general":"Procure emergência hospitalar imediatamente diante da suspeita. Informe ferimentos, cirurgia recente, contato com água e a velocidade de expansão dos sintomas.","diagnosis":"É infecção profunda potencialmente fatal, que costuma exigir cirurgia e tratamento sistêmico urgente. Não aguarde aparecimento de pele escura nem resposta a cuidados caseiros.","expected":"Pode progredir rapidamente e precisar de operações repetidas. Recuperação e sequelas dependem da extensão e da rapidez do controle da infecção.","alarm":"Dor muito intensa, inclusive além da vermelhidão, expansão rápida, febre, bolhas, áreas escuras ou secreção são sinais preocupantes.","immediate":"Tontura, confusão, desmaio ou piora da circulação e respiração exigem assistência de emergência, sem aguardar exames eletivos.","return":"Após o tratamento hospitalar, siga rigorosamente revisões cirúrgicas, curativos e reabilitação. Nova dor intensa, febre ou expansão da lesão exige retorno imediato.","sources":[{"url":"https://www.cdc.gov/group-a-strep/about/necrotizing-fasciitis.html","title":"CDC — About necrotizing fasciitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte centrada na forma estreptocócica; orientações de urgência mantidas sem presumir agente ou esquema antimicrobiano.","status":"source-reviewed"},
{"name":"Febre amarela","aliases":[],"setting":"urgent","general":"Procure avaliação médica sem demora e informe viagens, locais de exposição a mosquitos e vacinação. Evite automedicação e siga o local de cuidado indicado.","diagnosis":"A febre amarela pode evoluir rapidamente e comprometer fígado, rins e circulação. Casos graves necessitam de tratamento hospitalar intensivo.","expected":"Algumas pessoas melhoram, mas pode haver agravamento depois de uma melhora inicial. Não considere a redução da febre suficiente para encerrar acompanhamento.","alarm":"Pele ou olhos amarelados, vômitos persistentes, dor abdominal, redução da urina ou sangramento são sinais preocupantes.","immediate":"Sangramento, confusão, desmaio, falta de ar ou urina muito reduzida exigem emergência imediata.","return":"Mantenha retornos e exames determinados pela equipe até recuperação clínica e laboratorial; vacinas e prevenção devem ser revistas após avaliação.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/f/febre-amarela","title":"Ministério da Saúde — Febre amarela","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Febre de Chikungunya","aliases":[],"setting":"home","general":"Após avaliação, ofereça líquidos, repouso relativo e atividade adaptada à dor. Evite novas picadas com medidas de proteção apropriadas à idade.","diagnosis":"A dor e o inchaço nas articulações podem limitar movimentos. Não use medicamentos por conta própria antes de diferenciar outras arboviroses.","expected":"A fase aguda costuma durar dias, mas dores podem persistir ou voltar por semanas a meses; isso exige reavaliação.","alarm":"Observe ingestão, urina, piora da dor, vômitos e novas manifestações fora das articulações.","immediate":"Falta de ar, convulsão, confusão, sangramento, desmaio ou redução importante de urina exigem urgência.","return":"Retorne se a febre ou limitação persistirem; crianças pequenas e casos com comorbidades precisam de acompanhamento mais próximo.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/c/chikungunya","title":"Ministério da Saúde — Chikungunya","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Febre familiar do Mediterrâneo","aliases":[],"setting":"specialist","general":"Mantenha o tratamento preventivo e as consultas, mesmo entre as crises. Registre episódios de febre, duração, locais de dor e interferência nas atividades para discutir com a equipe.","diagnosis":"A febre familiar do Mediterrâneo causa crises inflamatórias recorrentes. Dor nova ou diferente precisa de avaliação; não atribua automaticamente toda febre ou dor abdominal à condição.","expected":"As crises frequentemente duram de horas a poucos dias, mas a frequência varia muito. O controle contínuo também busca prevenir complicações, especialmente deposição de proteínas nos rins.","alarm":"Crises mais prolongadas, mudança do padrão, edema ou alterações urinárias exigem revisão.","immediate":"Dor abdominal ou torácica intensa, falta de ar, desmaio ou alteração de consciência: emergência.","return":"Retorne à reumatologia e cumpra o monitoramento renal e demais exames definidos pelo serviço.","sources":[{"url":"https://medlineplus.gov/genetics/condition/familial-mediterranean-fever/","title":"MedlinePlus Genetics — Familial Mediterranean fever","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Febre Faringoconjuntival","aliases":[],"setting":"home","general":"Mantenha líquidos, higiene das mãos e toalhas individuais. Evite esfregar os olhos e compartilhar objetos pessoais.","diagnosis":"A associação de febre, garganta inflamada e conjuntivite pode ocorrer por adenovírus; sintomas atípicos exigem revisão.","expected":"Muitos casos melhoram com suporte; antibióticos não tratam o vírus. A duração varia.","alarm":"Observe piora geral, dificuldade para beber ou sintomas oculares intensos.","immediate":"Falta de ar, prostração importante, dor ocular forte ou perda visual exige avaliação imediata.","return":"Retorne se piorar ou não houver melhora progressiva. Crianças imunocomprometidas precisam de avaliação mais precoce e orientação específica.","sources":[{"url":"https://www.cdc.gov/adenovirus/about/index.html","title":"CDC — About adenovirus","accessed":"2026-09-26"}],"reviewNotes":"Síndrome clínica associada a adenovírus, sem presumir confirmação etiológica ou substituir avaliação oftalmológica. Revisão médica necessária.","status":"source-reviewed"},
{"name":"Febre maculosa","setting":"urgent","general":"Pode causar febre, cefaleia, mialgia, náuseas e exantema, que pode faltar no início. A gravidade pode aumentar rapidamente.","diagnosis":"Informe exposição recente a carrapatos ou locais com animais, mesmo sem recordar uma picada. Procure avaliação no início dos sintomas; a decisão de tratamento não deve esperar aparecimento de manchas.","expected":"Reconhecimento e tratamento precoces permitem recuperação; atraso pode causar complicações graves, hospitalização e morte.","alarm":"Febre alta, cefaleia intensa, confusão, falta de ar, manchas, vômitos persistentes, sangramento ou desmaio são urgências.","immediate":"Procurar serviço de saúde e informar data, local e possível contato com carrapatos. Não esperar manchas nem automedicar-se.","return":"Cumpra as reavaliações indicadas. Retorne imediatamente se houver piora, sangramento, falta de ar, pouca urina ou alteração de consciência, mesmo após o primeiro atendimento.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/f/febre-maculosa","title":"Ministério da Saúde — Febre Maculosa","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Febre reumática aguda com artrite","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento clínico e cardiológico, mesmo que as dores articulares melhorem. Registre o calendário da prevenção de novos episódios prescrita pela equipe.","diagnosis":"A doença pode afetar coração, articulações, pele e sistema nervoso após infecção estreptocócica. A melhora da artrite não exclui comprometimento cardíaco.","expected":"A dor pode responder ao tratamento, mas o prognóstico depende especialmente da avaliação cardíaca e da prevenção de recorrências.","alarm":"Observe dor no peito, palpitações, falta de ar, inchaço, cansaço crescente ou movimentos involuntários novos.","immediate":"Falta de ar em repouso, desmaio, dor torácica persistente ou piora importante do estado geral exigem pronto atendimento.","return":"Compareça às revisões e exames do coração. Nova dor de garganta ou infecção de pele deve ser avaliada, sem interromper a profilaxia por conta própria.","sources":[{"url":"https://www.cdc.gov/group-a-strep/about/rheumatic-fever.html","title":"CDC — About rheumatic fever","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Febre reumática aguda com cardite","aliases":[],"setting":"urgent","general":"A cardite precisa de avaliação especializada e definição da necessidade de internação. Respeite as limitações de esforço orientadas pela equipe.","diagnosis":"A febre reumática pode afetar válvulas cardíacas após infecção estreptocócica. É importante cumprir o tratamento e a prevenção de novos episódios pelo tempo indicado.","expected":"A inflamação pode melhorar, mas lesões valvares podem persistir. O risco de recorrência torna o seguimento prolongado necessário, mesmo sem dor articular.","alarm":"Observe cansaço, palpitações, falta de ar, inchaço, febre recorrente ou novos movimentos involuntários.","immediate":"Falta de ar em repouso, desmaio, dor torácica importante ou deterioração rápida exigem atendimento de emergência.","return":"Mantenha consultas de cardiologia, controle do plano preventivo e avaliação de novos episódios de dor de garganta ou infecção.","sources":[{"url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/acute-rheumatic-fever.html","title":"CDC — Clinical Guidance for Acute Rheumatic Fever","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Febre Reumática em Pediatria","aliases":[],"setting":"specialist","general":"Mantenha prevenção e seguimento prescritos; não interrompa porque as dores desapareceram.","diagnosis":"A febre reumática pode afetar articulações, coração, pele ou movimentos, após infecção estreptocócica; a avaliação define os órgãos envolvidos.","expected":"A duração dos cuidados varia; lesão valvar pode exigir acompanhamento prolongado mesmo sem sintomas.","alarm":"Informe novas dores articulares, movimentos involuntários, palpitações ou cansaço crescente.","immediate":"Falta de ar importante, desmaio ou deterioração geral exigem pronto atendimento.","return":"Cumpra retornos clínicos e cardíacos; novas infecções de garganta ou pele precisam de avaliação.","sources":[{"url":"https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/acute-rheumatic-fever.html","title":"CDC — Clinical Guidance for Acute Rheumatic Fever","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Título geral; não pressupõe cardite em todos os pacientes.","status":"source-reviewed"},
{"name":"Fenda palatina isolada","aliases":[],"setting":"specialist","general":"Peça orientação prática para alimentação e acompanhe o peso. Use técnicas e dispositivos indicados pela equipe, sem forçar mamadas.","diagnosis":"A fenda palatina pode prejudicar sucção, audição e fala. O cuidado costuma reunir cirurgia, pediatria, nutrição, fonoaudiologia e avaliação auditiva.","expected":"A evolução depende da anatomia e do tratamento; cirurgia e terapias podem melhorar a função, com seguimento ao longo do crescimento.","alarm":"Observe refeições muito demoradas, tosse durante alimentação, baixo ganho de peso e alterações de audição.","immediate":"Engasgo com lábios azulados, dificuldade respiratória ou incapacidade de manter líquidos exige atendimento imediato.","return":"Retorne para monitorar nutrição, audição, linguagem e planejamento cirúrgico; após operação, siga o plano específico fornecido na alta.","sources":[{"url":"https://www.nhs.uk/conditions/cleft-lip-and-palate/","title":"NHS — Cleft lip and palate","accessed":"2026-09-26"}],"reviewNotes":"Aplicado à fenda palatina isolada; não presume fenda labial nem síndrome associada.","status":"source-reviewed"},
{"name":"Fenômeno de Raynaud em Pediatria","aliases":["Fenômeno de Raynaud"],"setting":"specialist","general":"Proteja corpo e extremidades do frio, aqueça mãos gradualmente e evite fumaça. Registre episódios e possíveis desencadeantes para discutir na consulta.","diagnosis":"Mudanças de cor desencadeadas por frio ou estresse podem ocorrer isoladamente ou acompanhar outras doenças; é necessário avaliar o contexto.","expected":"Crises costumam ser reversíveis, mas evolução e seguimento dependem de ser forma primária ou secundária.","alarm":"Dor persistente, feridas, assimetria importante ou sintomas sistêmicos merecem revisão.","immediate":"Dedo muito doloroso, escurecido ou que não recupera a circulação exige atendimento imediato.","return":"Mantenha acompanhamento se os episódios persistirem ou aparecerem sinais de doença associada.","sources":[{"url":"https://www.niams.nih.gov/health-topics/raynauds-phenomenon/diagnosis-treatment-and-steps-to-take","title":"NIAMS — Raynaud’s phenomenon: diagnosis, treatment and steps to take","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Feocromocitoma Pediátrico","aliases":["Feocromocitoma"],"setting":"specialist","general":"Mantenha acompanhamento especializado e informe o diagnóstico antes de anestesia ou qualquer procedimento.","diagnosis":"O tumor pode produzir hormônios que elevam pressão e frequência cardíaca. O preparo para cirurgia deve ser coordenado pela equipe.","expected":"A evolução depende de localização, extensão e características genéticas. O seguimento deve continuar após tratamento.","alarm":"Observe crises de dor de cabeça, palpitações, suor intenso, palidez ou tontura.","immediate":"Dor torácica, desmaio, cefaleia intensa com alteração neurológica ou falta de ar exige emergência.","return":"Cumpra exames e controles pressóricos; não altere o tratamento ou adie revisão diante de novas crises.","sources":[{"url":"https://www.cancer.gov/types/pheochromocytoma/patient/child-pheochromocytoma-treatment-pdq","title":"NCI — Childhood pheochromocytoma and paraganglioma","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Fibrodisplasia Ossificante Progressiva","aliases":["FOP"],"setting":"specialist","general":"Evite traumatismos e alongamentos forçados; qualquer procedimento, injeção intramuscular ou anestesia deve ser discutido com equipe experiente em FOP.","diagnosis":"A formação anormal de osso pode piorar após lesões; caroços não devem ser biopsiados rotineiramente sem avaliação especializada.","expected":"A condição é progressiva e variável; o cuidado procura preservar função e prevenir agravos.","alarm":"Informe inchaço novo, queda, dor importante ou mudança na abertura da boca.","immediate":"Trauma de cabeça ou pescoço, dificuldade para engolir ou respirar exige avaliação imediata especializada.","return":"Mantenha seguimento funcional, odontológico e respiratório com planejamento cuidadoso das intervenções necessárias.","sources":[{"url":"https://www.iccfop.org/guidelines/2-exec-summary","title":"International Clinical Council on FOP — Executive summary","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Fibrose cística","aliases":["Fibrose Cística na Pediatria"],"setting":"specialist","general":"Mantenha o plano de fisioterapia respiratória, alimentação e tratamentos definidos pelo centro de referência. Higienize equipamentos conforme o treinamento e informe a equipe sobre dificuldades na rotina.","diagnosis":"A fibrose cística pode afetar pulmões, digestão, crescimento e outros órgãos. Os cuidados são individualizados; não suspenda tratamento quando a tosse melhorar nem acrescente produtos por conta própria.","expected":"É uma condição crônica com evolução variável. O acompanhamento busca reduzir infecções, manter nutrição e preservar função pulmonar, com ajustes ao longo do crescimento.","alarm":"Aumento de tosse ou secreção, febre, queda da disposição, perda de peso ou dor abdominal precisam de revisão.","immediate":"Falta de ar importante, sangue na tosse, dor intensa ou prostração: emergência.","return":"Mantenha as consultas e exames periódicos e procure a equipe ao primeiro sinal de piora persistente.","sources":[{"url":"https://www.nhs.uk/conditions/cystic-fibrosis/","title":"NHS — Cystic fibrosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Fibrose Hepática Congênita","aliases":[],"setting":"specialist","general":"Mantenha seguimento com hepatologia e avaliação renal quando indicada; leve informações sobre familiares com doenças semelhantes.","diagnosis":"A fibrose hepática congênita pode causar aumento da pressão nas veias do fígado e alterações dos canais biliares.","expected":"A evolução varia conforme complicações hepáticas e doenças associadas; não se presume normalização espontânea.","alarm":"Informe aumento abdominal, febre, icterícia ou desconforto abdominal novo.","immediate":"Vômito com sangue, fezes negras, desmaio ou febre com icterícia exigem atendimento imediato.","return":"Compareça aos exames de vigilância e combine previamente como proceder diante de sangramento ou suspeita de infecção biliar.","sources":[{"url":"https://medlineplus.gov/genetics/condition/congenital-hepatic-fibrosis/","title":"MedlinePlus Genetics — Congenital hepatic fibrosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Fimose","setting":"home","general":"É comum a não retração do prepúcio na infância; não se deve forçar a retração.","diagnosis":"Lave suavemente apenas a região acessível, sem puxar o prepúcio à força. Quando houver retração espontânea e confortável, siga orientação de higiene e recoloque o prepúcio sobre a glande.","expected":"Na infância, a separação costuma acontecer gradualmente e a idade varia. Dor, cicatrização ou dificuldade urinária exigem avaliação para distinguir desenvolvimento normal de estreitamento patológico.","alarm":"Dor importante, vermelhidão ou inchaço, secreção, febre, dificuldade para urinar ou prepúcio retraído que não retorna exigem avaliação urgente.","immediate":"Não force o prepúcio; procure atendimento urgente se não conseguir urinar ou se ele permanecer preso atrás da glande.","return":"Retorne se surgirem sintomas, infecções repetidas ou dificuldade urinária; siga o plano definido pelo profissional.","sources":[{"url":"https://www.nhs.uk/conditions/phimosis/","title":"NHS — Tight foreskin (phimosis)","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Fimose e Parafimose em Pediatria","aliases":["Fimose","Parafimose"],"setting":"urgent","general":"Higienize suavemente a região e nunca force a retração do prepúcio. Se ele estiver preso atrás da glande, procure emergência imediatamente.","diagnosis":"A fimose fisiológica e a parafimose são situações diferentes; a segunda pode comprometer a circulação e não deve ser tratada por manobras caseiras.","expected":"A abertura fisiológica ocorre gradualmente; o prazo depende da idade. Parafimose exige resolução urgente.","alarm":"Observe dor, edema, vermelhidão com febre ou dificuldade para urinar.","immediate":"Glande escura, dor intensa ou incapacidade de urinar exigem atendimento imediato.","return":"Após avaliação, mantenha acompanhamento se houver cicatriz, infecções repetidas ou sintomas urinários.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/the_penis_and_foreskin/","title":"Royal Children’s Hospital — The penis and foreskin","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Título combinado: não equivale fimose fisiológica a urgência; a urgência aplica-se à parafimose, retenção e sinais de isquemia.","status":"source-reviewed"},
{"name":"Fimose fisiológica","aliases":[],"setting":"home","general":"Lave apenas a parte acessível do pênis, sem retração forçada. Não use manobras, instrumentos ou produtos irritantes para tentar abrir o prepúcio.","diagnosis":"Na infância, a impossibilidade de retrair pode ser normal. O diagnóstico de forma fisiológica exige ausência de cicatriz ou outros sinais de doença.","expected":"A abertura pode aumentar com o desenvolvimento. O tempo é variável; dificuldade de retração isolada não implica necessidade automática de cirurgia.","alarm":"Observe dor persistente, inflamações repetidas, jato urinário progressivamente alterado ou aparecimento de anel cicatricial.","immediate":"Incapacidade para urinar, prepúcio preso atrás da glande, grande inchaço ou ponta azulada/escura exige pronto atendimento.","return":"Reavalie se houver sintomas ou dúvida sobre cicatrização. Após retração natural, limpe suavemente e sempre devolva a pele à posição habitual.","sources":[{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/phimosis-and-other-abnormalities-of-the-penile-skin","title":"EAU — Phimosis and other abnormalities of the penile skin","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Fitofotodermatite","aliases":[],"setting":"home","general":"Lave a pele após contato com limão, outras plantas ou frutas e proteja a área da luz solar. Use roupas protetoras e evite nova exposição.","diagnosis":"A reação resulta do contato de substâncias vegetais com a pele seguido de sol; não é necessariamente alergia e não é transmitida entre pessoas.","expected":"A inflamação melhora progressivamente, mas manchas escuras podem permanecer por bastante tempo. Não use clareadores ou receitas caseiras na fase inflamatória.","alarm":"Dor crescente, bolhas extensas, secreção ou acometimento de grande superfície precisam de avaliação.","immediate":"Procure atendimento imediato se houver lesão nos olhos, queimadura extensa, dificuldade para hidratar ou estado geral comprometido.","return":"Retorne se piorar, se houver suspeita de infecção ou se a pigmentação persistente causar preocupação; a proteção solar deve continuar.","sources":[{"url":"https://dermnetnz.org/topics/phytophotodermatitis","title":"DermNet — Phytophotodermatitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Flutter Atrial na Infância","aliases":["Flutter atrial"],"setting":"urgent","general":"Interrompa o esforço e procure avaliação médica quando houver suspeita de ritmo cardíaco muito acelerado. Não tente manobras sem orientação.","diagnosis":"O flutter é uma arritmia que precisa ser identificada no eletrocardiograma; a aparência dos sintomas não define o ritmo.","expected":"A resposta depende da idade, da condição cardíaca e da estabilidade circulatória. A necessidade de observação é individual.","alarm":"Observe palidez, suor, dificuldade para mamar, dor torácica, tontura ou respiração difícil.","immediate":"Desmaio, sonolência anormal, extremidades frias ou dificuldade respiratória exigem atendimento de emergência.","return":"Após estabilização, siga o plano da cardiologia para controle do ritmo e investigação de recorrências.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Supraventricular_Tachycardia_SVT/","title":"RCH — Supraventricular Tachycardia","accessed":"2026-09-26"}],"reviewNotes":"Fonte distingue flutter no diferencial; orientação é de triagem, sem transpor tratamento de outras taquicardias.","status":"source-reviewed"},
{"name":"Fobia social na infância","aliases":[],"setting":"specialist","general":"Escute sem ridicularizar e combine apoio com a escola. Ajude a dividir situações difíceis em passos pequenos, sem exposição humilhante ou forçada.","diagnosis":"A ansiedade social vai além de timidez quando interfere em atividades e relações. A avaliação deve considerar idade, bullying e outras condições emocionais.","expected":"Pode melhorar com tratamento, mas o ritmo varia; evitar todas as situações pode manter as dificuldades.","alarm":"Observe faltas escolares, isolamento, prejuízo do sono ou alimentação e sinais de depressão.","immediate":"Ameaça de autoagressão, ideia suicida ou risco imediato exige atendimento urgente e companhia de adulto protetor.","return":"Retorne com saúde mental para acompanhar metas e participação escolar; informe qualquer piora importante ou efeito adverso do tratamento.","sources":[{"url":"https://www.nhs.uk/mental-health/conditions/social-anxiety/","title":"NHS — Social anxiety","accessed":"2026-09-26"}],"reviewNotes":"Fonte geral inclui início juvenil; intervenções e participação da família requerem adaptação por profissional infantil.","status":"source-reviewed"},
{"name":"Fratura em galho verde do rádio","aliases":[],"setting":"specialist","general":"Proteja o membro imobilizado e siga as instruções para higiene, elevação e atividades. Não introduza objetos no gesso nem permita brincadeiras que possam causar nova queda.","diagnosis":"A fratura em galho verde não é igual à fratura em torus. Localização e alinhamento determinam o tipo de imobilização, eventual redução e controle radiográfico.","expected":"Com tratamento adequado, a consolidação costuma ser boa, mas pode ocorrer perda de alinhamento. Não retire a imobilização porque a dor desapareceu.","alarm":"Dor crescente, gesso apertado, mau cheiro, ferida ou diminuição dos movimentos dos dedos exigem avaliação.","immediate":"Dedos frios, arroxeados, dor intensa persistente ou perda de sensibilidade: emergência imediata.","return":"Compareça ao controle ortopédico precoce; a fonte orienta revisão em até uma semana para fraturas diafisárias, ajustada ao local da fratura.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/fractures/Radialulna_shaft_diaphysis_fractures_Emergency_Department/","title":"Royal Children’s Hospital — Radius-ulna shaft fractures","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Confirmar se a fratura é diafisária ou distal antes de aplicar prazo e imobilização; não extrapolar esquemas de torus.","status":"source-reviewed"},
{"name":"Fratura supracondiliana do úmero","setting":"urgent","general":"É uma fratura próxima ao cotovelo, geralmente após queda, com risco de lesão neurovascular.","diagnosis":"Não tente alinhar o cotovelo. Após atendimento, mantenha a imobilização conforme prescrita e observe cor, temperatura, sensibilidade e movimento dos dedos; proteja o gesso de danos e umidade.","expected":"O tratamento e o tempo de recuperação dependem do desvio e da circulação da mão. Algumas fraturas exigem cirurgia; a retomada de atividades depende da revisão ortopédica.","alarm":"Mão fria, pálida ou azulada, pulso ausente, dor desproporcional, dormência, fraqueza, ferida aberta ou deformidade são sinais de emergência.","immediate":"Mantenha o braço apoiado como encontrado e vá imediatamente à urgência. Mão fria, pálida ou sem movimento precisa de atendimento emergencial.","return":"Reavalie conforme ortopedia; retorne imediatamente se piorarem dor, cor, temperatura, sensibilidade ou movimento dos dedos.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/fractures/supracondylar_fracture_of_the_humerus_emergency_department/","title":"RCH — Supracondylar fracture of the humerus: Emergency Department","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Furunculose","aliases":[],"setting":"home","general":"Lave as mãos, mantenha higiene corporal e cubra lesões que drenam. Não compartilhe toalhas, roupas ou lâminas; lave regularmente roupas de cama e banho.","diagnosis":"Não esprema nem perfure os furúnculos. Lesões múltiplas, recorrentes ou agrupadas exigem avaliação para decidir drenagem e investigar fatores associados.","expected":"A melhora deve ser progressiva; repetição das lesões precisa de plano preventivo individual, e não de uso contínuo de medicamentos sem revisão.","alarm":"Observe aumento de dor, calor e vermelhidão ao redor, febre, calafrios ou surgimento de novas lesões.","immediate":"Lesão no rosto, rápida expansão, criança abatida ou sinais sistêmicos exigem avaliação urgente, especialmente se houver imunodeficiência.","return":"Retorne se não melhorar, se persistir por cerca de duas semanas ou houver recorrência. A equipe pode orientar investigação de contatos e medidas específicas.","sources":[{"url":"https://www.nhs.uk/conditions/boils/","title":"NHS — Boils","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Gastrite por H. pylori","aliases":[],"setting":"specialist","general":"Siga integralmente o esquema prescrito e comunique efeitos adversos ou dificuldade para cumprir horários. Evite iniciar tratamentos por conta própria a partir de um teste isolado.","diagnosis":"Em crianças, investigar a causa dos sintomas é essencial. A presença de H. pylori não explica automaticamente toda dor abdominal; a decisão de tratar deve ser individualizada.","expected":"A melhora da dor não comprova eliminação da bactéria. É necessário confirmar a resposta com teste adequado após o tratamento.","alarm":"Vômitos persistentes, perda de peso, dificuldade para alimentar-se ou dor progressiva exigem reavaliação.","immediate":"Vômito com sangue, fezes negras, desmaio ou dor abdominal intensa súbita exigem emergência.","return":"Programe teste de erradicação, habitualmente seis a oito semanas após terminar, com preparo orientado pela gastroenterologia.","sources":[{"url":"https://naspghan.org/wp-content/uploads/2024/10/J-pediatr-gastroenterol-nutr-2024-Homan-Updated-joint-ESPGHAN-NASPGHAN-guidelines-for-management-of-Helicobacter.pdf","title":"ESPGHAN/NASPGHAN — Guidelines for H. pylori in children (2024)","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Gastroenterite bacteriana por Campylobacter","aliases":[],"setting":"home","general":"Ofereça solução de reidratação em pequenas quantidades frequentes e mantenha alimentação tolerada. Lave mãos e cuide do preparo e cozimento dos alimentos.","diagnosis":"Campylobacter pode causar diarreia com sangue; a indicação de tratamento específico depende da gravidade e fatores de risco.","expected":"Muitas pessoas se recuperam em cerca de uma semana, mas não espere esse prazo se houver piora.","alarm":"Observe sangue nas fezes, febre persistente, dor abdominal importante, pouca urina e boca seca.","immediate":"Prostração, incapacidade de beber, desmaio ou fraqueza/formigamento progressivo nas pernas exigem avaliação imediata.","return":"Retorne se diarreia ou vômitos persistirem, houver sangue ou sinais de desidratação; informe sintomas articulares ou neurológicos após a infecção.","sources":[{"url":"https://www.cdc.gov/campylobacter/signs-symptoms/index.html","title":"CDC — Symptoms of Campylobacter Infection","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/campylobacter/about/index.html","title":"CDC — About Campylobacter infection","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Gastroenterite bacteriana por Salmonella","aliases":[],"setting":"home","general":"Priorize hidratação, oferecendo líquidos de reidratação apropriados em pequenas quantidades repetidas, e mantenha a alimentação tolerada. Lave as mãos após usar o banheiro e antes de preparar comida.","diagnosis":"Salmonella pode causar diarreia, febre e cólicas; o tratamento depende da gravidade e dos fatores de risco. Não use medicamentos para interromper a diarreia sem orientação.","expected":"Muitos quadros melhoram em quatro a sete dias, mas sintomas podem durar mais. Lactentes e pessoas vulneráveis precisam de acompanhamento mais próximo.","alarm":"Sangue nas fezes, febre persistente, vômitos repetidos ou piora da dor abdominal exigem avaliação.","immediate":"Pouca urina, incapacidade de beber, sonolência, desmaio ou desidratação importante: emergência.","return":"Retorne se diarreia ou vômitos persistirem ou houver piora; informe dores articulares e outros sintomas novos após a infecção.","sources":[{"url":"https://www.cdc.gov/salmonella/signs-symptoms/index.html","title":"CDC — Symptoms of Salmonella Infection","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Gastroenterite bacteriana por Shigella","setting":"home","general":"A infecção pode causar diarreia, febre e dor abdominal; sangue nas fezes pode ocorrer.","diagnosis":"Priorize líquidos e alimentação tolerada, seguindo orientação de reidratação. Lave as mãos após trocar fraldas e antes de preparar comida; siga as regras locais para creche e escola.","expected":"Muitos casos melhoram em cerca de uma semana, mas desidratação, sangue nas fezes ou doença prolongada exigem avaliação. Crianças pequenas e pessoas vulneráveis podem ter evolução mais grave.","alarm":"Procure urgência por desidratação, incapacidade de beber, sonolência, sangue nas fezes, dor intensa, febre persistente ou pouca urina.","immediate":"Ofereça líquidos em pequenos volumes e procure avaliação; não use antidiarreicos sem orientação profissional.","return":"Retorne se não melhorar, se houver piora ou sinais de desidratação; cumpra a revisão solicitada após exames.","sources":[{"url":"https://www.cdc.gov/shigella/about/index.html","title":"CDC — About Shigella Infection","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Gastroenterite por Adenovírus entérico","aliases":[],"setting":"home","general":"Ofereça líquidos em pequenas quantidades frequentes e mantenha a alimentação e o aleitamento tolerados. Reforce higiene das mãos após fraldas e antes das refeições.","diagnosis":"O principal cuidado é prevenir desidratação. O vírus não exige antibiótico de rotina; qualquer tratamento adicional deve seguir avaliação, sobretudo em crianças imunossuprimidas.","expected":"A maioria das crianças se recupera com cuidados de suporte. A duração varia; redução da urina ou piora da disposição não deve ser atribuída apenas à diarreia.","alarm":"Observe boca seca, pouca urina, vômitos repetidos, sonolência, dor abdominal crescente ou febre prolongada.","immediate":"Incapacidade de beber, pouca resposta, dificuldade respiratória ou sinais importantes de desidratação exigem pronto atendimento.","return":"Reavalie se a ingestão cair, a diarreia persistir ou surgir sangue nas fezes. Lactentes e imunossuprimidos precisam de acompanhamento mais próximo.","sources":[{"url":"https://www.healthychildren.org/English/health-issues/conditions/infections/Pages/Adenovirus-Infections.aspx","title":"American Academy of Pediatrics — Adenovirus infections in infants and children","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Gastroenterite por Escherichia coli enteropatogênica","aliases":[],"setting":"home","general":"Ofereça líquidos de reidratação conforme o plano e mantenha alimentação e amamentação toleradas. Lave as mãos após trocar fraldas e antes de preparar alimentos.","diagnosis":"A E. coli enteropatogênica é um subtipo específico. A conduta não deve ser copiada de infecções por E. coli produtora de toxina Shiga.","expected":"A evolução varia com hidratação, idade e persistência da diarreia. Nem toda detecção nas fezes exige antibiótico; o médico deve interpretar o resultado.","alarm":"Observe aumento das evacuações, febre, vômitos, perda de peso ou menor quantidade de urina.","immediate":"Sangue nas fezes, prostração, incapacidade para beber ou sinais de desidratação importante exigem avaliação imediata.","return":"Retorne se não melhorar, se a diarreia se prolongar ou se o crescimento for afetado.","sources":[{"url":"https://www.cdc.gov/ecoli/treatment/index.html","title":"CDC — Treatment of E. coli Infection","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/ecoli/about/kinds-of-ecoli.html","title":"CDC — Kinds of E. coli","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Diferenciação de patotipos conferida também em CDC — Kinds of E. coli.","status":"source-reviewed"},
{"name":"Gastroenterite por Norovírus","aliases":[],"setting":"home","general":"Ofereça líquidos e solução de reidratação em porções pequenas e frequentes; mantenha amamentação e alimentação tolerada. Lave mãos com água e sabão.","diagnosis":"Norovírus transmite-se facilmente. Higienize superfícies e roupas contaminadas e evite preparar alimentos para outras pessoas enquanto houver sintomas.","expected":"Vômitos e diarreia geralmente melhoram em poucos dias, mas a transmissão pode continuar após a recuperação.","alarm":"Observe redução de urina, ausência de lágrimas, boca seca e sonolência diferente do habitual.","immediate":"Incapacidade de reter líquidos, prostração intensa, sangue nas fezes ou dor forte exige atendimento imediato.","return":"Retorne se os sintomas não melhorarem ou a hidratação diminuir; confirme o período de afastamento com a orientação sanitária/escolar local.","sources":[{"url":"https://www.cdc.gov/norovirus/about/index.html","title":"CDC — About Norovirus","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Gastroenterite por Rotavírus","aliases":[],"setting":"home","general":"Ofereça reidratação apropriada em pequenas quantidades frequentes e mantenha aleitamento e alimentação conforme aceitação. Lave as mãos após fraldas e banheiro e higienize superfícies de contato.","diagnosis":"O rotavírus causa diarreia aquosa e vômitos, com risco de desidratação, principalmente em lactentes. Não existe tratamento específico que elimine o vírus; a prioridade é repor as perdas e observar a criança.","expected":"Diarreia e vômitos costumam durar de três a oito dias. A evolução precisa ser reavaliada se não houver melhora ou se a ingestão cair.","alarm":"Boca seca, ausência de lágrimas, menos urina e irritabilidade merecem atenção rápida.","immediate":"Sonolência anormal, incapacidade de beber, desmaio ou sinais de desidratação grave: emergência.","return":"Retorne conforme orientação e antecipe se não conseguir hidratar; revise a vacinação no acompanhamento.","sources":[{"url":"https://www.cdc.gov/rotavirus/about/index.html","title":"CDC — About Rotavirus","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Gengivostomatite herpética aguda","setting":"home","general":"Infecção primária pelo herpes simples pode causar febre, irritabilidade, gengivas inflamadas e múltiplas vesículas ou úlceras na boca.","diagnosis":"Ofereça líquidos frios em pequenas quantidades frequentes e alimentos macios conforme tolerância. Evite compartilhar utensílios e contato das lesões com olhos; lave as mãos após cuidados da boca.","expected":"As lesões geralmente cicatrizam em cerca de 10 a 14 dias, podendo durar mais nos casos intensos. A dor costuma melhorar gradualmente; a principal preocupação inicial é manter hidratação.","alarm":"Alarme: pouca urina, incapacidade de ingerir líquidos, letargia, sinais clínicos de desidratação, doença grave ou envolvimento ocular.","immediate":"Oferecer líquidos frios em pequenas quantidades e cuidados de suporte; avaliar hidratação e necessidade de encaminhamento urgente conforme gravidade.","return":"Retornar imediatamente se não conseguir beber, urinar pouco, ficar sonolenta ou piorar; reavaliar se a ingestão não melhorar.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/HSV_Gingivostomatitis/","title":"RCH — HSV Gingivostomatitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Giardíase","aliases":[],"setting":"home","general":"Mantenha hidratação e higiene das mãos. Use água segura e evite contaminar alimentos ao cuidar de fraldas ou usar o banheiro.","diagnosis":"Siga o tratamento definido para os sintomas e condições da criança. Não repita ciclos por conta própria; persistência pode exigir novos exames e investigação de reinfecção.","expected":"Algumas pessoas mantêm desconforto intestinal mesmo após eliminar a infecção. O tempo de recuperação varia com estado nutricional e imunidade.","alarm":"Observe diarreia prolongada, perda de peso, dificuldade para beber, diminuição da urina ou cansaço acentuado.","immediate":"Prostração, incapacidade de manter líquidos ou sinais relevantes de desidratação exigem pronto atendimento.","return":"Retorne se a diarreia persistir ou reaparecer. Informe outros casos no domicílio e qualquer condição que reduza a imunidade, para orientar prevenção e investigação.","sources":[{"url":"https://www.cdc.gov/giardia/treatment/index.html","title":"CDC — Treatment of Giardia infection","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Glomeruloesclerose focal e segmental","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com nefrologia, registre inchaço, peso e urina quando orientado. Alimentação e ingestão de líquidos devem seguir o plano individual.","diagnosis":"A glomeruloesclerose pode ter causas genéticas, primárias ou secundárias. Tratamentos e resposta variam; não utilize automaticamente o esquema de outra síndrome nefrótica.","expected":"Pode haver controle da perda de proteínas ou evolução com dano renal. Exames seriados ajudam a avaliar resposta e efeitos do tratamento.","alarm":"Mais inchaço, urina reduzida, febre, dor abdominal ou pressão elevada precisam de contato rápido com a equipe.","immediate":"Falta de ar, dor torácica, perna dolorosa/inchada, convulsão ou prostração intensa exigem emergência.","return":"Cumpra controle de urina, função renal e pressão arterial; comunique infecções e alterações antes de mudar o tratamento.","sources":[{"url":"https://www.niddk.nih.gov/health-information/kidney-disease/children/nephrotic-syndrome-children","title":"NIDDK — Nephrotic Syndrome in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Fonte sustenta o acompanhamento sindrômico e identifica GESF; prognóstico e terapia dependem da etiologia individual.","status":"source-reviewed"},
{"name":"Glomerulonefrite Difusa Aguda (Pós-estreptocócica)","aliases":["GNDA pós-estreptocócica"],"setting":"specialist","general":"Monitore urina, inchaço e peso conforme orientação; restrições de líquidos e sal devem seguir o plano da equipe.","diagnosis":"A inflamação renal pós-estreptocócica pode provocar sangue na urina, edema e pressão alta após infecção de garganta ou pele.","expected":"A recuperação costuma ser favorável, mas alterações microscópicas da urina podem persistir depois da melhora clínica.","alarm":"Informe aumento do inchaço, pouca urina, dor de cabeça ou vômitos.","immediate":"Falta de ar, ausência de urina, convulsão ou alteração de consciência exigem emergência.","return":"Mantenha controles de pressão e urina e os exames de recuperação programados.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Post-streptococcal_glomerulonephritis_(PSGN)/","title":"RCH — Post-streptococcal glomerulonephritis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Glomerulonefrite difusa aguda pós-estreptocócica","aliases":[],"setting":"urgent","general":"Procure avaliação médica para acompanhar pressão, função renal e urina. Registre inchaço e mudança no volume urinário.","diagnosis":"A inflamação renal pode surgir após infecção de garganta ou pele. Restrições de sal e líquidos devem ser individualizadas pela equipe.","expected":"Muitas crianças recuperam a função renal, mas são necessários controles até resolução e identificação de complicações.","alarm":"Urina escura, inchaço crescente, dor de cabeça e redução da urina precisam de reavaliação.","immediate":"Falta de ar, convulsão, confusão, dor de cabeça intensa ou ausência de urina exigem emergência.","return":"Retorne no prazo definido para pressão e exames. Não aumente líquidos nem use anti-inflamatórios por conta própria diante de inchaço ou pouca urina.","sources":[{"url":"https://www.cdc.gov/group-a-strep/about/post-streptococcal-glomerulonephritis.html","title":"CDC — Post-Streptococcal Glomerulonephritis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Granuloma Glúteo Infantil","aliases":["Granuloma gluteale infantum"],"setting":"specialist","general":"Troque fraldas prontamente, limpe com água suavemente e seque sem fricção. Mantenha períodos sem fralda e a barreira protetora orientada. Leve os produtos utilizados; corticoides potentes e irritantes devem ser revistos, sem acrescentar combinações por conta própria.","diagnosis":"Nódulos avermelhados ou violáceos sobre assadura persistente precisam de exame.","expected":"A regressão é variável, podendo deixar pigmentação ou cicatriz; um relato de melhora rápida não prevê o tempo de recuperação individual.","alarm":"Ulceração, secreção, dor crescente, lesões fora da fralda ou ausência de melhora exigem reavaliação.","immediate":"Febre com abatimento, expansão dolorosa ou sinais sistêmicos justificam atendimento imediato.","return":"Agende dermatologia; persistência ou aparência incomum pode exigir investigação, inclusive biópsia, antes de outro tratamento.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3045094/","title":"Al-Faraidy e Al-Natour — Granuloma gluteale infantum, 2010","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Nappy_rash/","title":"RCH — Nappy rash, 2024","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escopo: reconhecimento, cuidados conservadores e encaminhamento. Não habilita terapias experimentais. Revisão documental, sem homologação humana.","evidenceSummary":"Relato clínico específico e orientações pediátricas institucionais. Lactentes; cuidados de barreira derivados da dermatite irritativa. Doença rara, sem ensaios que definam tratamento ou retorno universais.","decisionSupport":{"summary":"Distinguir apresentação compatível de lesões que sugerem outro diagnóstico.","requirements":["Idade e duração","Distribuição, ulceração e lesões satélites","Produtos e corticoides usados","Febre, crescimento e diarreia"],"branchRequired":true,"branches":[{"id":"ggi-confirmado","label":"Apresentação compatível confirmada","when":"Exame compatível, criança bem e sem achados atípicos.","setting":"home","overrides":{"diagnosis":"Siga cuidados de barreira e retire agravantes identificados pela equipe.","expected":"Pode regredir com alterações residuais.","return":"Revisão dermatológica combinada; antecipar se piorar.","alarm":"Novas úlceras ou secreção.","immediate":"Febre acompanhada de prostração: emergência."}},{"id":"ggi-atipico","label":"Diagnóstico duvidoso ou refratário","when":"Lesões atípicas, persistentes ou associadas a manifestações sistêmicas.","setting":"specialist","overrides":{"diagnosis":"Investigar candidíase, dermatoses e, conforme achados, deficiência nutricional ou histiocitose.","expected":"Depende do diagnóstico confirmado.","return":"Reavaliar antes de intensificar tratamento.","alarm":"Petéquias, diarreia persistente ou crescimento inadequado.","immediate":"Abatimento ou infecção progressiva: atendimento imediato."}}]},"revisedAt":"2026-09-27"},
{"name":"Granuloma Umbilical","aliases":[],"setting":"home","general":"Após confirmação do diagnóstico, mantenha o umbigo limpo e seco e dobre a fralda abaixo dele.","diagnosis":"É um pequeno tecido úmido após queda do cordão; secreção persistente ou aspecto atípico precisa de avaliação para outras causas.","expected":"Pode melhorar após o cuidado orientado, mas ausência de resposta exige revisão.","alarm":"Observe vermelhidão ao redor, inchaço, cheiro desagradável ou maior secreção.","immediate":"Febre, sonolência incomum, irritabilidade importante ou vermelhidão em expansão exige atendimento urgente.","return":"Retorne se não melhorar em poucos dias ou conforme plano. Não aplique substâncias sem orientação nem confunda com infecção umbilical.","sources":[{"url":"https://www.childrens.health.qld.gov.au/health-a-to-z/umbilical-granuloma","title":"Children’s Health Queensland — Umbilical granuloma","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Granulomatose com poliangiite","aliases":[],"setting":"specialist","general":"Mantenha seguimento com a equipe especializada e cumpra tratamento e exames de controle. Informe infecções e efeitos indesejados, sem suspender ou ajustar medicamentos por conta própria.","diagnosis":"A granulomatose com poliangiite pode inflamar vasos de vias aéreas, pulmões, rins, olhos e outros órgãos. O controle depende de avaliar a atividade da doença e os órgãos envolvidos.","expected":"Pode haver períodos de melhora e recaídas. O acompanhamento continua mesmo quando os sintomas desaparecem, pois alterações renais e outras complicações podem precisar de exames.","alarm":"Sangue na urina, edema, tosse persistente, sangramento nasal recorrente ou sintomas oculares exigem contato rápido.","immediate":"Sangue na tosse, falta de ar, perda visual, dor torácica ou pouca urina: emergência.","return":"Mantenha revisões de reumatologia e demais especialistas conforme o acometimento; antecipe em qualquer piora.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/granulomatosis-polyangiitis/","title":"Great Ormond Street Hospital — Granulomatosis with polyangiitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hemangioma da infância","setting":"specialist","general":"É tumor vascular benigno comum da infância; costuma não estar plenamente aparente ao nascer e cresce nos primeiros meses.","diagnosis":"Registre a evolução em fotografias e cumpra as revisões. Lesões próximas aos olhos, nariz, boca ou áreas de atrito merecem avaliação precoce; não espere apenas pelo desaparecimento espontâneo.","expected":"Após a fase proliferativa, muitos estabilizam e involuem lentamente; podem deixar alterações residuais de pele ou tecido.","alarm":"Procure atendimento rápido se a lesão prejudicar visão, respiração ou alimentação, ulcerar ou ficar muito dolorosa. Sangramento persistente exige urgência; múltiplas lesões precisam de avaliação especializada.","immediate":"Se houver sangramento, faça pressão suave e contínua com material limpo. Procure urgência se não parar; dificuldade respiratória ou visual exige atendimento imediato.","return":"Revisar conforme risco e fase de crescimento; retornar antes diante de crescimento acelerado, ulceração, sangramento ou alteração funcional.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/haemangiomas_of_infancy/","title":"RCH — Haemangiomas of infancy","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Hemangioma Infantil","aliases":[],"setting":"specialist","general":"Proteja a lesão de atrito e mantenha unhas curtas. Registre mudanças para mostrar à equipe.","diagnosis":"Muitos hemangiomas não precisam de tratamento, mas localização e complicações mudam a conduta.","expected":"Podem crescer rapidamente nos primeiros meses e regredir gradualmente depois; o ritmo varia.","alarm":"Observe ferida dolorosa, sangramento, prejuízo da visão ou dificuldade para mamar.","immediate":"Respiração ruidosa ou difícil e sangramento persistente apesar de compressão exigem atendimento imediato.","return":"Lesões perto dos olhos ou que interferem na alimentação precisam de avaliação precoce. Mantenha seguimento para decidir observação ou tratamento individual.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/haemangiomas/","title":"GOSH — Haemangiomas","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Hemocromatose Neonatal","aliases":[],"setting":"hospital","general":"Suspeita de insuficiência hepática neonatal requer hospital com neonatologia e hepatologia. Leve informações gestacionais e sobre perdas fetais ou irmãos afetados.","diagnosis":"Hemocromatose neonatal descreve lesão hepática com siderose extra-hepática. Doença hepática aloimune gestacional, ou GALD, é causa importante, mas não sinônimo; ferritina elevada isoladamente não confirma nenhuma delas.","expected":"A evolução varia de recuperação gradual a insuficiência progressiva. Normalização dos exames pode ser lenta; transplante poderá ser avaliado se o suporte não controlar a doença.","alarm":"Informe aumento da icterícia, barriga distendida, inchaço, menor alimentação ou sangramento.","immediate":"Sangramento, dificuldade respiratória, convulsão ou menor responsividade precisam de intervenção imediata.","return":"Após alta formal, seguir função hepática, coagulação, nutrição e desenvolvimento conforme o centro responsável.","sources":[{"url":"https://www.aasld.org/liver-fellow-network/core-series/clinical-pearls/little-livers-big-problems-gestational-alloimmune","title":"AASLD — Little Livers, BIG Problems! Gestational Alloimmune Liver Disease, 2023","accessed":"2026-09-27"},{"url":"https://www.frontiersin.org/journals/pediatrics/articles/10.3389/fped.2021.680730/full","title":"Yeh et al. — Gestational alloimmune liver disease: casos e revisão, 2021","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escopo hospitalar e distinção etiológica. Não transportar condutas da hemocromatose adulta. Revisão documental, sem homologação humana.","evidenceSummary":"Síntese educacional de sociedade e revisão de relatos/séries. Recém-nascidos com GALD, incluindo prematuros. Amostras pequenas, seleção e confundimento; não demonstram eficácia causal nem prognóstico individual.","decisionSupport":{"summary":"Definir a etiologia sem atrasar estabilização e avaliação para insuficiência hepática.","requirements":["Idade, prematuridade e história gestacional","Glicemia e coagulação","Função hepática e siderose extra-hepática","Investigação infecciosa, metabólica e genética"],"branchRequired":true,"branches":[{"id":"gald-sustentada","label":"GALD sustentada pela investigação","when":"Equipe estabelece mecanismo aloimune com avaliação integrada.","setting":"hospital","overrides":{"diagnosis":"Acompanhar lesão hepática e resposta ao tratamento especializado.","expected":"Recuperação e necessidade de transplante variam.","return":"Hepatologia; aconselhamento antes de futuras gestações.","alarm":"Ascite ou coagulação em piora.","immediate":"Sangramento ou alteração de consciência: intervenção imediata."}},{"id":"nh-outra-causa","label":"Etiologia alternativa ou indeterminada","when":"Achados insuficientes para GALD ou suspeita de outra causa.","setting":"hospital","overrides":{"diagnosis":"Investigar infecção, doenças metabólicas/genéticas e outras causas de falência hepática.","expected":"Depende da causa e resposta.","return":"Revisar resultados com equipe especializada.","alarm":"Hipoglicemia ou deterioração hepática.","immediate":"Instabilidade, convulsão ou sangramento: emergência hospitalar."}}]},"revisedAt":"2026-09-27"},
{"name":"Hemofilia A grave","aliases":[],"setting":"specialist","general":"Mantenha contato com o centro de hemofilia, cartão de identificação e plano escrito de urgência. Informe o tratamento atual e presença de inibidores em qualquer atendimento.","diagnosis":"Sangramentos podem ocorrer sem trauma evidente. Use somente medicamentos aprovados pela equipe e comunique procedimentos, cirurgias e cuidados dentários previamente.","expected":"O acompanhamento visa prevenir sangramentos e proteger articulações. Episódios suspeitos precisam de tratamento rápido; melhora inicial não exclui sangramento profundo.","alarm":"Observe dor e inchaço articular, hematomas extensos, sangue na urina/fezes, dor abdominal ou sangramento persistente.","immediate":"Trauma na cabeça, cefaleia nova intensa, vômitos, alteração neurológica, sangramento de pescoço ou dificuldade respiratória exigem emergência imediata.","return":"Contate o centro após qualquer sangramento relevante. Na suspeita grave, a assistência não deve aguardar exames para seguir o plano especializado.","sources":[{"url":"https://www.bleeding.org/healthcare-professionals/guidelines-on-care/masac-documents/masac-document-257-guidelines-for-emergency-department-management-of-individuals-with-hemophilia-and-other-bleeding-disorders","title":"NBDF/MASAC — Emergency department management of hemophilia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Hemofilia B","aliases":[],"setting":"specialist","general":"Tenha um plano escrito para sangramentos e informe hemofilia em todo atendimento e procedimento odontológico. Combine atividades físicas seguras com a equipe especializada.","diagnosis":"Na hemofilia B há deficiência do fator IX. Siga o tratamento individual e não troque produtos nem suspenda prevenção sem orientação do centro de hemofilia.","expected":"O tratamento pode prevenir lesões articulares e permitir atividades habituais, mas o risco de sangramento persiste e varia conforme a gravidade.","alarm":"Dor ou inchaço articular, hematoma crescente, sangue na urina ou sangramento prolongado exigem avaliação rápida.","immediate":"Trauma craniano, dor de cabeça intensa, sangramento importante, dificuldade respiratória ou desmaio exigem emergência imediata.","return":"Mantenha consultas e avaliação de articulações e resposta ao tratamento; organize o plano antes de viagens e procedimentos.","sources":[{"url":"https://www.cdc.gov/hemophilia/living-with/index.html","title":"CDC — Living with Hemophilia","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/hemophilia/about/index.html","title":"CDC — About Hemophilia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Caracterização de hemofilia B conferida em CDC — About Hemophilia.","status":"source-reviewed"},
{"name":"Hemorragia peri-intraventricular grau I","aliases":[],"setting":"specialist","general":"Mantenha seguimento neonatal e do desenvolvimento. Compareça aos exames de imagem e consultas definidos pela equipe, levando o histórico da prematuridade.","diagnosis":"Grau I corresponde a sangramento pequeno na região da matriz germinativa. Não implica automaticamente a evolução dos graus mais graves.","expected":"Muitos bebês evoluem sem problemas atribuíveis ao sangramento, mas prematuridade e outras condições também influenciam o desenvolvimento.","alarm":"Observe alimentação, tônus, interação e movimentos, comunicando alterações persistentes.","immediate":"Pausas respiratórias, convulsão, dificuldade para despertar ou piora súbita da sucção exigem atendimento imediato.","return":"Retorne para acompanhar crescimento da cabeça, desenvolvimento e exames; intervenções precoces devem ser iniciadas quando houver indicação, sem aguardar atraso acentuado.","sources":[{"url":"https://medlineplus.gov/ency/article/007301.htm","title":"MedlinePlus — Intraventricular hemorrhage of the newborn","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Hemorragia peri-intraventricular grau II","aliases":[],"setting":"hospital","general":"Mantenha a observação neonatal e os exames de imagem indicados. Informe mudanças de alimentação, atividade, respiração e movimentos; evite concluir a gravidade apenas pela aparência do bebê.","diagnosis":"O grau II descreve uma hemorragia intraventricular de menor extensão que os graus mais graves. A prematuridade e outras condições influenciam a avaliação e o acompanhamento.","expected":"O prognóstico costuma ser mais favorável que nos graus elevados, mas não garante ausência de dificuldades futuras. O desenvolvimento deve ser acompanhado após a alta.","alarm":"Dificuldade para mamar, alteração do tônus, sonolência incomum ou aumento da cabeça precisam de revisão.","immediate":"Apneia, convulsões, coloração azulada ou pouca resposta: emergência neonatal.","return":"Após alta hospitalar, cumpra o seguimento do prematuro e as avaliações neurológicas e de desenvolvimento recomendadas.","sources":[{"url":"https://medlineplus.gov/ency/article/007301.htm","title":"MedlinePlus — Intraventricular hemorrhage of the newborn","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hemorragia peri-intraventricular grau III","setting":"hospital","general":"É hemorragia da matriz germinativa que se estende aos ventrículos e os distende; gravidade depende de lesão parenquimatosa e evolução ventricular.","diagnosis":"O bebê necessita acompanhamento neonatal e exames seriados. Converse com a equipe sobre crescimento da cabeça, alimentação e avaliação neurológica; mantenha as consultas de desenvolvimento após a alta.","expected":"Pode evoluir com dilatação ventricular pós-hemorrágica e risco neurológico; o desfecho individual não é previsto apenas pelo grau.","alarm":"Alarme: aumento progressivo dos ventrículos, fontanela tensa, aumento acelerado do perímetro cefálico, apneias, convulsões ou deterioração neurológica.","immediate":"Avise imediatamente a equipe diante de pausas respiratórias, convulsões, redução de resposta ou mudança da alimentação. Após a alta, esses sinais exigem emergência; não aguarde a revisão programada.","return":"Seguimento após a alta, com vigilância do perímetro cefálico, desenvolvimento e audição/visão conforme programa neonatal local.","sources":[{"url":"https://medlineplus.gov/ency/article/007301.htm","title":"MedlinePlus — Intraventricular hemorrhage of the newborn","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Hemorragia peri-intraventricular grau IV","aliases":[],"setting":"hospital","general":"O recém-nascido necessita de acompanhamento neonatal especializado, estabilidade respiratória/circulatória e avaliações neurológicas seriadas. Peça à equipe explicação dos exames e do plano de seguimento.","diagnosis":"O grau descrito envolve lesão importante e pode associar-se a acúmulo de líquido no cérebro. Nem todos os bebês terão a mesma evolução.","expected":"O prognóstico depende da prematuridade, extensão da lesão e complicações. O desenvolvimento precisa ser acompanhado ao longo dos anos, sem previsões individuais apenas pelo nome diagnóstico.","alarm":"Comunique pausas respiratórias, convulsões, sucção fraca, sonolência incomum ou alterações de resposta e movimentos.","immediate":"Fora do hospital, crise convulsiva, perda de resposta ou dificuldade respiratória exige emergência; com derivação, febre e sintomas neurológicos também.","return":"Após alta, mantenha neurologia, seguimento do prematuro e intervenção precoce conforme necessidade, além da vigilância para hidrocefalia.","sources":[{"url":"https://medlineplus.gov/ency/article/007301.htm","title":"MedlinePlus — Intraventricular hemorrhage of the newborn","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Hemorragia Pulmonar","aliases":[],"setting":"hospital","general":"Sangramento pulmonar suspeito exige atendimento hospitalar e comunicação imediata à equipe; informe quantidade observada e tratamentos em uso.","diagnosis":"É necessário identificar a origem do sangue e tratar a causa; sangramento de outras regiões pode parecer pulmonar.","expected":"A evolução depende da causa e da gravidade; pode ser necessário suporte respiratório e tratamento intensivo.","alarm":"Sangue nas vias aéreas associado a palidez, queda da oxigenação ou piora súbita preocupa especialmente em recém-nascidos.","immediate":"Falta de ar, sangramento abundante, desmaio ou ausência de resposta exigem emergência imediata.","return":"Após estabilização, o seguimento será definido pela causa e pelas possíveis complicações.","sources":[{"url":"https://pubmed.ncbi.nlm.nih.gov/40246361/","title":"Gipsman et al. — Management of severe acute pulmonary haemorrhage in children, 2025","accessed":"2026-09-26"},{"url":"https://cahs.health.wa.gov.au/-/media/HSPs/CAHS/Documents/Health-Professionals/Neonatology-guidelines/Pulmonary-Haemorrhage.pdf?thn=0","title":"CAHS — Pulmonary Haemorrhage, agosto 2025","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Fonte neonatal aplicada somente aos recém-nascidos; revisão pediátrica fundamenta princípios gerais. Não é protocolo de alta.","status":"source-reviewed"},
{"name":"Hepatite Autoimune em Pediatria","aliases":["Hepatite autoimune"],"setting":"specialist","general":"Siga regularmente o acompanhamento hepatológico e não interrompa o tratamento por conta própria, mesmo quando a criança estiver sem sintomas.","diagnosis":"O diagnóstico combina história, exames e avaliação do fígado; anticorpos isolados não confirmam a doença.","expected":"O controle pode exigir tratamento prolongado. Recaídas e complicações são possíveis, e a evolução depende da resposta.","alarm":"Relate cansaço crescente, icterícia, urina escura, dor abdominal, perda de apetite ou sangramentos.","immediate":"Sonolência diferente, confusão, vômito com sangue ou piora rápida do estado geral exigem emergência.","return":"Mantenha exames e consultas para acompanhar atividade da doença, crescimento e efeitos do tratamento.","sources":[{"url":"https://espghan.info/files/Diagnosis-and-Management-of-Paediatric-Autoimmune-Hepatitis-AIH.-ESPGHAN-Advice-Guide.-2019.-Ver1..pdf","title":"ESPGHAN — Diagnosis and Management of Paediatric Autoimmune Hepatitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Hepatites Virais","aliases":[],"setting":"specialist","general":"Mantenha alimentação e hidratação conforme tolerado e revise todos os produtos usados com a equipe. Não compartilhe objetos com sangue e siga as medidas de higiene e prevenção específicas do vírus.","diagnosis":"Hepatites virais têm diferentes formas de transmissão, tratamento e necessidade de investigação de contatos.","expected":"Algumas infecções são autolimitadas; outras podem tornar-se crônicas. A evolução depende do vírus e do comprometimento hepático.","alarm":"Avise sobre icterícia crescente, vômitos ou dificuldade para se alimentar.","immediate":"Confusão, sonolência anormal, sangramento ou dor intensa exigem emergência.","return":"Realize exames e seguimento até a equipe definir resolução ou acompanhamento prolongado.","sources":[{"url":"https://www.nhs.uk/conditions/hepatitis/","title":"NHS — Hepatitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Título abrange diferentes vírus; orientações de contato, vacinação, duração e seguimento dependem da etiologia confirmada.","status":"source-reviewed"},
{"name":"Hérnia inguinal congênita","aliases":[],"setting":"specialist","general":"Agende avaliação com cirurgia pediátrica mesmo quando o caroço desaparece. Observe sua localização e comportamento, sem apertar ou forçar a redução em casa.","diagnosis":"A hérnia inguinal pode prender parte do intestino. A correção cirúrgica é planejada para reduzir esse risco; cintas e receitas caseiras não corrigem a abertura.","expected":"Após correção adequada, a evolução costuma ser boa. Antes da cirurgia, o fato de a hérnia ser indolor não elimina a possibilidade de encarceramento.","alarm":"Caroço doloroso, endurecido, avermelhado ou que não diminui, associado a vômitos, exige atenção urgente.","immediate":"Vá imediatamente à emergência se houver esses sinais, barriga distendida, prostração ou recusa alimentar importante.","return":"Mantenha consulta cirúrgica e retorne após o procedimento conforme a alta; comunique reaparecimento do abaulamento.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/inguinal_hernia/","title":"RCH — Inguinal hernia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Hérnia umbilical","aliases":[],"setting":"home","general":"Observe a região do umbigo e mantenha acompanhamento pediátrico. Não aplique moedas, faixas apertadas ou curativos para tentar fechar a hérnia.","diagnosis":"A hérnia umbilical costuma formar uma saliência macia, geralmente indolor. Avaliação confirma o diagnóstico e indica se é necessária cirurgia.","expected":"Muitas fecham espontaneamente durante os primeiros anos; persistência, tamanho e sintomas orientam o encaminhamento.","alarm":"Avise se o volume crescer, ficar doloroso, duro ou apresentar mudança na cor da pele.","immediate":"Dor forte persistente, vômitos, barriga distendida ou saliência dolorosa e endurecida exigem emergência.","return":"Retorne nas consultas de rotina e antes se surgirem sintomas; não tente forçar a redução de uma hérnia dolorosa.","sources":[{"url":"https://www.nhs.uk/conditions/umbilical-hernia-repair/","title":"NHS — Umbilical hernia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Herpangina","aliases":[],"setting":"home","general":"Ofereça líquidos em pequenas quantidades frequentes e alimentos macios ou frios; evite alimentos ácidos, muito quentes ou irritantes.","diagnosis":"A herpangina é uma infecção viral com feridas dolorosas na boca e garganta; higiene das mãos ajuda a reduzir transmissão.","expected":"Em geral melhora em cerca de uma semana, mas a dor pode dificultar a ingestão durante os primeiros dias.","alarm":"Observe quanto consegue beber e urinar; dor crescente ou febre prolongada precisam de revisão.","immediate":"Recusa de líquidos, sonolência incomum ou sinais importantes de desidratação exigem atendimento imediato.","return":"Reavalie se febre ou feridas persistirem por mais de cinco dias ou houver piora.","sources":[{"url":"https://medlineplus.gov/ency/article/000969.htm","title":"MedlinePlus — Herpangina","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Herpes Congênita","aliases":[],"setting":"hospital","general":"O recém-nascido com suspeita de herpes necessita avaliação rápida. Informe lesões de pele, dificuldades alimentares e exposição conhecida, mesmo sem história materna.","diagnosis":"Herpes adquirida dentro do útero é rara e pode afetar pele, olhos e sistema nervoso. Deve ser distinguida da aquisição no parto.","expected":"A evolução depende dos órgãos envolvidos e da rapidez do cuidado; sequelas exigem seguimento específico.","alarm":"Observe bolhas, temperatura alterada, recusa alimentar, irritabilidade ou sonolência.","immediate":"Convulsões, dificuldade respiratória, pouca resposta ou piora rápida exigem emergência neonatal.","return":"Após estabilização, acompanhe desenvolvimento, visão, audição e exames conforme a equipe especializada.","sources":[{"url":"https://cps.ca/en/documents/position/prevention-management-neonatal-herpes-simplex-virus-infections","title":"Canadian Paediatric Society — Neonatal herpes simplex virus infections","accessed":"2026-09-26"}],"reviewNotes":"Herpes congênita não foi tratada como sinônimo exato de toda herpes neonatal. Fonte contempla transmissão intrauterina.","status":"source-reviewed"},
{"name":"Herpes Simples em Pediatria","aliases":["Herpes simples"],"setting":"home","general":"Na forma oral avaliada e sem gravidade, ofereça líquidos frequentes e alimentos tolerados. Higienize as mãos e evite contato direto das lesões com outras pessoas.","diagnosis":"O local e a idade mudam o risco: recém-nascidos, acometimento ocular ou sinais neurológicos exigem avaliação urgente.","expected":"Na gengivoestomatite, lesões geralmente cicatrizam em cerca de duas semanas; esse prazo não se aplica às formas graves.","alarm":"Recusa de líquidos, pouca urina, dor ocular ou comportamento diferente são alertas.","immediate":"Sonolência anormal, convulsão ou suspeita de herpes neonatal exigem emergência.","return":"Retorne se não mantiver hidratação ou houver piora.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/HSV_Gingivostomatitis/","title":"Royal Children’s Hospital — HSV gingivostomatitis","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Meningitis_encephalitis/","title":"Royal Children’s Hospital — Meningitis and encephalitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Cuidado domiciliar limitado à forma oral estável. A fonte de gengivoestomatite exclui tratamento neonatal; encaminhamento urgente foi preservado, sem generalizar esquema terapêutico.","status":"source-reviewed"},
{"name":"Herpes simples neonatal","aliases":[],"setting":"hospital","general":"O recém-nascido precisa de avaliação e tratamento hospitalar imediatos. Informe contato com herpes labial ou genital e lave as mãos antes de manuseá-lo.","diagnosis":"A infecção pode atingir pele, olhos, sistema nervoso ou outros órgãos. A ausência de bolhas não exclui doença grave.","expected":"A evolução depende da extensão da infecção e da rapidez do tratamento; podem ser necessários acompanhamento prolongado e avaliações de desenvolvimento.","alarm":"Recusa de mamadas, irritabilidade, febre, lesões na pele/olhos/boca ou pouca urina são sinais preocupantes.","immediate":"Sonolência anormal, dificuldade para despertar, convulsão, gemência, respiração difícil ou flacidez exigem emergência imediata.","return":"Após alta formal, cumpra as revisões e exames definidos. Pessoas com lesões ativas devem evitar beijar o bebê e contato das lesões com ele.","sources":[{"url":"https://www.nhs.uk/conditions/neonatal-herpes/","title":"NHS — Neonatal herpes","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Herpes zóster","aliases":[],"setting":"urgent","general":"Solicite avaliação precoce, principalmente em crianças. Mantenha lesões limpas, evite coçar e siga as orientações para cobri-las.","diagnosis":"Herpes-zóster pode afetar pele, olhos e nervos. Evite contato das lesões com pessoas suscetíveis, especialmente gestantes, recém-nascidos e imunossuprimidos.","expected":"A erupção tende a evoluir para crostas, mas intensidade e duração da dor variam; tratamento oportuno pode ser necessário.","alarm":"Observe lesões perto do olho ou nariz, mudança na visão, audição ou movimento da face.","immediate":"Perda visual, confusão, dor de cabeça intensa, fraqueza ou doença disseminada com prostração exigem urgência.","return":"Retorne se surgirem novas áreas, dor importante ou sinais de infecção; imunossuprimidos precisam de avaliação prioritária.","sources":[{"url":"https://www.nhs.uk/conditions/shingles/","title":"NHS — Shingles","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Hidratação Pediátrica","aliases":[],"setting":"hospital","general":"Informe ingestão, vômitos, diarreia e urina; a equipe deve escolher a via de hidratação e acompanhar o peso.","diagnosis":"Hidratação intravenosa é uma prescrição individual, considerando perdas, exames, doenças associadas e risco de excesso de líquidos.","expected":"O volume precisa de reavaliação ao longo do tratamento; fórmulas iniciais não substituem observação clínica.","alarm":"Comunique inchaço, pouca urina, dor no acesso ou piora respiratória durante a infusão.","immediate":"Sonolência incomum, convulsão, falta de ar ou deterioração circulatória exigem avaliação imediata.","return":"Antes da alta, confirme tolerância à hidratação pela via indicada e o plano para perdas persistentes.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Intravenous_fluids/","title":"RCH — Intravenous fluids","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Recorte hospitalar para fluidos IV; a fonte exclui neonatos e recomenda protocolos próprios para várias comorbidades. Não é receita universal de manutenção.","status":"source-reviewed"},
{"name":"Hidratação Venosa Neonatal","aliases":["Hidratação intravenosa neonatal"],"setting":"hospital","general":"Hidratação pela veia é procedimento assistencial monitorado. Informe mamadas, vômitos, urina e mudanças do inchaço à equipe.","diagnosis":"O volume e a composição dependem de idade gestacional, dia de vida, peso, exames e alimentação recebida.","expected":"A necessidade é revista conforme a evolução e a possibilidade de alimentação; não se prevê duração universal.","alarm":"Observe inchaço, respiração mais rápida, pouca urina ou alteração da pele perto do acesso.","immediate":"Avise imediatamente a equipe se houver dificuldade respiratória, sonolência diferente, acesso inchado ou interrupção da infusão.","return":"A transição para alimentação e a alta exigem estabilidade; siga o plano neonatal de peso e hidratação.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Neonatal_intravenous_fluids/","title":"RCH — Neonatal intravenous fluids","accessed":"2026-09-26"}],"reviewNotes":"Procedimento, não diagnóstico. Fonte se destina a neonatos acima de32 semanas fora de UTI; não extrapolar volumes.","status":"source-reviewed"},
{"name":"Hidrocele","aliases":[],"setting":"specialist","general":"Observe o tamanho e o conforto da bolsa escrotal e mantenha as consultas. Não aperte o inchaço nem tente esvaziá-lo; higiene e roupas confortáveis são suficientes enquanto aguarda avaliação.","diagnosis":"A hidrocele é acúmulo de líquido ao redor do testículo. O médico precisa diferenciá-la de hérnia e outras causas de aumento escrotal, especialmente se houver dor.","expected":"Muitas hidroceles de lactentes diminuem espontaneamente; persistência ou sintomas podem exigir cirurgia. O momento do tratamento é definido individualmente pelo cirurgião.","alarm":"Aumento novo, endurecimento, vermelhidão ou desconforto precisam de reavaliação, sem assumir que todo inchaço é a hidrocele conhecida.","immediate":"Dor súbita intensa na bolsa, vômitos ou inchaço doloroso na virilha: emergência.","return":"Retorne à pediatria ou cirurgia conforme combinado e antes se surgir qualquer alteração dolorosa.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/inguinal-hernias-and-hydroceles/","title":"Great Ormond Street Hospital — Inguinal hernias and hydroceles","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hidrocele comunicante","setting":"specialist","general":"Acúmulo de líquido ao redor do testículo, com comunicação ao abdome; costuma aumentar ao longo do dia ou ao chorar e reduzir em repouso.","diagnosis":"Mantenha seguimento com pediatria ou urologia para distinguir hidrocele de hérnia. Observe variações de volume, sem apertar a bolsa; a decisão de observar ou operar depende da idade e do exame.","expected":"Muitas hidroceles de lactentes diminuem espontaneamente. Persistência, suspeita de hérnia ou alterações testiculares podem mudar a conduta; não é possível definir necessidade de cirurgia apenas pelo volume.","alarm":"Dor súbita, endurecimento, vermelhidão, vômitos ou massa que não reduz sugerem torção ou hérnia encarcerada.","immediate":"Com qualquer sinal de alarme, ir imediatamente à urgência; não tentar apertar ou empurrar a massa.","return":"Manter seguimento especializado conforme orientação; retorno mais rápido se o volume aumentar ou surgir abaulamento na virilha.","sources":[{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/hydrocele","title":"European Association of Urology — Paediatric Urology: Hydrocele","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Hidrocele não comunicante","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento para confirmar que o inchaço corresponde a líquido e não a hérnia ou outra alteração testicular. Evite apertar ou tentar drenar a bolsa.","diagnosis":"Na forma não comunicante, o líquido não se comunica livremente com a cavidade abdominal. Alguns casos adquiridos relacionam-se a inflamação, trauma ou outros problemas que precisam ser investigados.","expected":"Pode desaparecer com observação, conforme idade e causa. Persistência ou suspeita de outra doença pode indicar cirurgia; o prazo deve ser individualizado.","alarm":"Observe dor, aumento rápido, vermelhidão, endurecimento ou mudança inesperada do volume.","immediate":"Dor escrotal súbita, sobretudo com vômitos, exige emergência para excluir torção; não presuma que seja apenas a hidrocele.","return":"Compareça à revisão programada e retorne antes se houver sintomas ou dificuldade para examinar o testículo.","sources":[{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/hydrocele","title":"EAU — Hydrocele","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Hipercalemia em Pediatria","aliases":["Hipercalemia","Hiperpotassemia"],"setting":"urgent","general":"Procure avaliação urgente diante de potássio elevado. Leve exames e informe doenças renais, suplementos e medicamentos utilizados.","diagnosis":"É necessário confirmar o resultado quando apropriado, sem atrasar tratamento de quadro grave. Alterações cardíacas podem ocorrer mesmo sem sintomas.","expected":"A evolução depende da causa e da rapidez da correção; exames e monitorização orientam o cuidado.","alarm":"Observe fraqueza, formigamento, vômitos, palpitações ou dificuldade respiratória.","immediate":"Desmaio, paralisia, falta de ar ou alteração do ritmo exige emergência; não tente corrigir em casa.","return":"Após estabilização, siga revisão do potássio, função renal e fatores que provocaram a alteração.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hyperkalaemia/","title":"RCH — Hyperkalaemia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Hipernatremia em Pediatria","aliases":["Hipernatremia"],"setting":"hospital","general":"Hipernatremia significativa requer correção e monitorização médicas. Informe perdas de líquidos, alimentação e preparo de fórmulas; não tente corrigir rapidamente com água ou misturas caseiras.","diagnosis":"Sódio elevado pode refletir desidratação ou outras causas; a velocidade de correção precisa proteger o cérebro.","expected":"A evolução depende da causa, duração e gravidade, com exames seriados durante o tratamento.","alarm":"Irritabilidade, fraqueza, redução da urina ou alteração do comportamento precisam ser comunicadas.","immediate":"Convulsão, sonolência intensa ou pouca resposta exigem emergência.","return":"Após alta, revise o preparo das refeições e o plano de hidratação e investigação, conforme a causa.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hypernatraemia/","title":"Royal Children’s Hospital — Hypernatraemia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hiperplasia adrenal congênita forma perdedora de sal","aliases":[],"setting":"specialist","general":"Tenha sempre o plano de doença intercorrente e emergência disponível. Informe o diagnóstico à escola e a qualquer profissional de saúde que atenda a criança.","diagnosis":"A forma perdedora de sal pode causar crise adrenal. Siga rigorosamente o tratamento e o plano de ajuste durante febre, cirurgia ou doença, sem improvisar doses.","expected":"Mesmo em tratamento regular, doença e estresse físico podem precipitar crise; estabilidade prévia não elimina o risco.","alarm":"Vômitos, recusa alimentar, diarreia, perda de peso ou fraqueza precisam de orientação imediata da equipe.","immediate":"Incapacidade de reter o tratamento, prostração, desidratação, desmaio ou alteração da consciência exigem emergência imediata e apresentação do plano.","return":"Mantenha seguimento endocrinológico, crescimento e exames; revise o plano com todos os cuidadores.","sources":[{"url":"https://www.nichd.nih.gov/health/topics/cah/conditioninfo/symptoms","title":"NICHD — Symptoms of Congenital Adrenal Hyperplasia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Hiperplasia adrenal congênita forma virilizante simples","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento endocrinológico e tratamento regular. Tenha um plano escrito para doenças intercorrentes e informe a condição à escola e aos serviços de saúde.","diagnosis":"A forma virilizante simples não é sinônimo de forma perdedora de sal, mas ainda requer atenção à produção hormonal e resposta ao estresse.","expected":"Crescimento, puberdade e controle hormonal precisam de acompanhamento continuado; não existe prazo único de encerramento do cuidado.","alarm":"Vômitos, fraqueza, recusa alimentar ou impossibilidade de manter o tratamento exigem contato imediato com a equipe.","immediate":"Desmaio, confusão, convulsão ou prostração intensa podem sinalizar crise e exigem emergência.","return":"Retorne para revisar crescimento, exames e plano para febre/cirurgia; não suspenda ou ajuste hormônios por conta própria.","sources":[{"url":"https://medlineplus.gov/genetics/condition/21-hydroxylase-deficiency/","title":"MedlinePlus — 21-hydroxylase deficiency","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Adrenal_crisis_and_acute_adrenal_insufficiency/","title":"RCH — Adrenal crisis and acute adrenal insufficiency","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Hiperplasia Congênita de Adrenais","aliases":["Hiperplasia adrenal congênita"],"setting":"specialist","general":"Siga o plano da endocrinologia, mantenha identificação médica e instruções para doença, vômitos e procedimentos quando houver insuficiência adrenal.","diagnosis":"As formas clássicas e não clássicas diferem; nem toda hiperplasia necessita o mesmo tratamento ou reposição.","expected":"As formas clássicas geralmente exigem acompanhamento por toda a vida, com monitorização de crescimento e desenvolvimento.","alarm":"Vômitos, perda de peso, fraqueza ou dificuldade de manter o tratamento precisam ser informados prontamente.","immediate":"Em paciente com risco de crise adrenal, prostração, desmaio ou vômitos persistentes exigem emergência e execução do plano previamente fornecido.","return":"Reavalie periodicamente com endocrinologista.","sources":[{"url":"https://www.nichd.nih.gov/health/topics/cah/conditioninfo/treatments","title":"NICHD — What are the treatments for congenital adrenal hyperplasia?","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Orientação condicionada ao subtipo; não pressupõe perda de sal em toda hiperplasia.","status":"source-reviewed"},
{"name":"Hipertensão Arterial em Pediatria","aliases":["Hipertensão arterial","Hipertensão pediátrica"],"setting":"specialist","general":"Mantenha consultas, alimentação equilibrada e atividade física permitida. Se solicitado, registre medidas feitas com aparelho e manguito adequados; não ajuste tratamento por uma leitura isolada.","diagnosis":"A pressão precisa ser interpretada conforme idade e características da criança, com investigação de causas quando indicada.","expected":"O controle depende da causa, da adesão e do acompanhamento; ausência de sintomas não comprova normalização.","alarm":"Avise sobre cefaleia persistente, alteração visual, vômitos ou piora do estado geral.","immediate":"Convulsão, confusão, dor no peito ou falta de ar com pressão elevada exigem emergência.","return":"Retorne com registros e exames no prazo definido.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hypertension/","title":"Royal Children’s Hospital — Hypertension","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hipertensão Pulmonar Idiopática em Pediatria","aliases":["Hipertensão arterial pulmonar idiopática"],"setting":"specialist","general":"Mantenha acompanhamento em centro pediátrico especializado. Combine atividades permitidas e informe qualquer mudança dos sintomas; não interrompa o tratamento por conta própria.","diagnosis":"O diagnóstico idiopático exige excluir causas associadas. Ecocardiografia, avaliação hemodinâmica quando indicada e teste de vasorreatividade orientam decisões diferentes.","expected":"É doença crônica com evolução variável. O objetivo é controlar sintomas e preservar o coração; melhora inicial não garante resposta sustentada.","alarm":"Menor tolerância ao esforço, inchaço, dor torácica, tontura ou ganho de peso inadequado exigem contato com a equipe.","immediate":"Desmaio, coloração azulada, dor persistente ou falta de ar importante exigem emergência.","return":"Cumprir avaliações de risco e exames programados; antecipar retorno diante de piora.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11525338/","title":"Ivy et al. — Embracing the challenges of neonatal and paediatric pulmonary hypertension, 2024","accessed":"2026-09-27"},{"url":"https://site.thoracic.org/advocacy-patients/patient-resources/pulmonary-hypertension-in-children","title":"ATS — Pulmonary Hypertension in Children: Causes and Symptoms","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escopo: HAP idiopática confirmada e estratificação. Outras causas exigem reclassificação. Revisão documental, sem homologação humana.","evidenceSummary":"Consenso pediátrico do 7º simpósio mundial e orientação ATS. Crianças com hipertensão pulmonar; ramos restritos à forma idiopática. Heterogeneidade e poucos ensaios pediátricos; não aplicar esquemas adultos automaticamente.","decisionSupport":{"summary":"Registrar vasorreatividade e risco; instabilidade prevalece sobre qualquer classificação anterior.","requirements":["Etiologia excluída/confirmada","Resultado de vasorreatividade","Sintomas, síncope e saturação","Função ventricular e risco atual"],"branchRequired":true,"branches":[{"id":"hap-reativa","label":"Vasorreativa e estável","when":"Resposta positiva documentada, sem descompensação atual.","setting":"specialist","overrides":{"diagnosis":"Seguir plano definido pelo centro; resposta deve ser reavaliada.","expected":"Resposta pode perder sustentação.","return":"Vigilância especializada contínua.","alarm":"Retorno dos sintomas prévios.","immediate":"Síncope ou dispneia intensa: emergência."}},{"id":"hap-nao-reativa","label":"Não vasorreativa e estável","when":"Teste negativo e ausência de descompensação.","setting":"specialist","overrides":{"diagnosis":"Tratamento depende da estratificação de risco individual.","expected":"Pode requerer intensificação especializada.","return":"Reavaliar resposta e risco.","alarm":"Limitação progressiva ao esforço.","immediate":"Cianose ou desmaio: emergência."}},{"id":"hap-instavel","label":"Descompensação","when":"Síncope recorrente, hipoxemia importante ou insuficiência cardíaca.","setting":"hospital","overrides":{"diagnosis":"Necessita estabilização e centro especializado.","expected":"Há risco de deterioração rápida.","return":"Seguimento após estabilização hospitalar.","alarm":"Piora circulatória ou respiratória.","immediate":"Acionar emergência imediatamente."}}]},"revisedAt":"2026-09-27"},
{"name":"Hipertensão Pulmonar no Recém-nascido","aliases":[],"setting":"hospital","general":"O bebê precisa de suporte e monitorização em unidade neonatal. Informe qualquer alteração de cor, respiração ou resposta.","diagnosis":"A circulação pulmonar precisa ser avaliada por ecocardiograma e em conjunto com a causa da falta de oxigênio.","expected":"A evolução depende da doença associada e da resposta. A retirada dos suportes deve ocorrer sob vigilância.","alarm":"Observe piora da oxigenação, dificuldade respiratória ou redução da atividade, comunicando imediatamente à equipe.","immediate":"Cianose, pausas respiratórias ou pouca resposta exigem atendimento imediato.","return":"A alta e o acompanhamento posterior dependem da estabilidade respiratória e cardíaca; não interrompa suportes por conta própria.","sources":[{"url":"https://cps.ca/en/documents/position/inhaled-nitric-oxide","title":"CPS — Inhaled nitric oxide use in newborns","accessed":"2026-09-26"}],"reviewNotes":"Orientação hospitalar sem presumir a mesma terapia para prematuros, recém-nascidos a termo ou todas as causas. Revisão médica necessária.","status":"source-reviewed"},
{"name":"Hipertireoidismo (Doença de Graves)","aliases":[],"setting":"specialist","general":"Siga o plano da endocrinologia e realize os exames de controle. Informe todos os produtos e suplementos usados; não ajuste nem interrompa o tratamento sem contato com a equipe.","diagnosis":"Na doença de Graves, a tireoide produz hormônios em excesso. A abordagem pediátrica precisa considerar idade, sintomas, exames e efeitos adversos; não aplicar automaticamente esquemas de adultos.","expected":"O controle leva tempo e pode precisar de ajustes. Melhora de tremores ou palpitações não significa que o tratamento terminou.","alarm":"Palpitações persistentes, perda de peso, piora dos olhos ou intolerância importante ao calor exigem revisão.","immediate":"Febre e dor de garganta durante tratamento antitireoidiano exigem contato médico imediato; confusão, desmaio ou falta de ar: emergência.","return":"Mantenha retornos e exames hormonais nas datas orientadas e comunique efeitos indesejados prontamente.","sources":[{"url":"https://www.nhs.uk/conditions/overactive-thyroid-hyperthyroidism/treatment/","title":"NHS — Overactive thyroid: treatment","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Fonte geral de hipertireoidismo; escolha terapêutica, duração e indicação pediátrica não foram extrapoladas.","status":"source-reviewed"},
{"name":"Hipertireoidismo na Infância","aliases":[],"setting":"specialist","general":"Leve exames, medicamentos e suplementos à endocrinologia. Não modifique o plano fora das situações de alerta orientadas.","diagnosis":"Confirmar alteração hormonal e causa; excesso de hormônio não equivale sempre à doença de Graves.","expected":"Controle e possibilidade de remissão dependem da etiologia. Melhora dos sintomas não encerra o acompanhamento.","alarm":"Palpitações persistentes, perda de peso ou piora ocular exigem revisão. Icterícia durante antitireoidiano exige avaliação imediata e exames hepáticos.","immediate":"Durante antitireoidiano, febre ou dor de garganta: suspenda-o e procure avaliação imediata com hemograma. Febre alta com confusão, desmaio ou dificuldade respiratória: emergência.","return":"Manter exames hormonais e retorno individualizados; comunicar efeitos adversos.","sources":[{"url":"https://www.bsped.org.uk/media/ud1d2gaz/etj-etj-21-0073-graves-disease-guildelines-2022.pdf","title":"ETA — Guideline for the management of pediatric Graves’ disease, 2022","accessed":"2026-09-27"},{"url":"https://www.sbp.com.br/fileadmin/user_upload/23886c-DC_Hipertireoidismo_em_Pediatria.pdf","title":"SBP — Hipertireoidismo em Pediatria, 2023","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escolher etiologia antes da orientação específica; crise tireotóxica requer hospital. Revisão documental, sem homologação humana.","evidenceSummary":"Diretriz ETA e documento científico SBP. Crianças/adolescentes; fonte SBP inclui neonatos. ETA não cobre doença fetal/neonatal; causas raras têm evidência limitada.","decisionSupport":{"summary":"Separar produção aumentada, liberação hormonal transitória e doença neonatal.","requirements":["Idade e estabilidade","TSH, T4/T3 e TRAb","Nódulos, dor e exposição hormonal/iodo","História materna e fármacos"],"branchRequired":true,"branches":[{"id":"tireoide-graves","label":"Graves","when":"Autoimunidade estimulante confirmada fora do período neonatal.","setting":"specialist","overrides":{"diagnosis":"Seguir plano prolongado da endocrinologia.","expected":"Remissão não é garantida.","return":"Reavaliar hormônios e segurança.","alarm":"Icterícia durante tratamento.","immediate":"Febre/dor de garganta sob antitireoidiano: suspender e avaliar imediatamente."}},{"id":"tireoide-transitoria","label":"Tireotoxicose destrutiva ou exógena","when":"Tireoidite destrutiva ou exposição confirmada; excluir infecção supurativa.","setting":"specialist","overrides":{"diagnosis":"Conduta depende do mecanismo identificado.","expected":"Pode ser transitória.","return":"Reavaliar função tireoidiana.","alarm":"Dor cervical com febre.","immediate":"Comprometimento respiratório: emergência."}},{"id":"tireoide-autonomia","label":"Autonomia ou causa rara","when":"Nódulo funcionante ou suspeita não autoimune persistente.","setting":"specialist","overrides":{"diagnosis":"Necessita investigação estrutural e etiológica dirigida.","expected":"Depende da causa.","return":"Seguimento multidisciplinar.","alarm":"Crescimento cervical ou compressão.","immediate":"Confusão ou instabilidade: emergência."}},{"id":"tireoide-neonatal","label":"Hipertireoidismo neonatal","when":"Recém-nascido com suspeita ou confirmação.","setting":"urgent","overrides":{"diagnosis":"Avaliação neonatal/endócrina imediata; verificar antecedentes maternos.","expected":"Pode ser transitório ou permanente.","return":"Vigiar crescimento e hormônios.","alarm":"Dificuldade alimentar ou taquicardia.","immediate":"Dispneia ou abatimento: emergência."}}]},"revisedAt":"2026-09-27"},
{"name":"Hipocalcemia neonatal","setting":"hospital","general":"Baixo cálcio no recém-nascido pode ocorrer por prematuridade, doença ou alterações maternas e exige avaliação clínica e laboratorial.","diagnosis":"O bebê precisa de avaliação neonatal e controle laboratorial. Informe dificuldades de alimentação e antecedentes gestacionais; não acrescente suplementos, mude a diluição da fórmula ou interrompa alimentação por conta própria.","expected":"A evolução depende de quando começou e da causa. Algumas formas são transitórias; outras precisam de investigação e acompanhamento mais prolongados, com ajustes guiados pelos exames.","alarm":"Convulsões, apneia, tremores persistentes, letargia, dificuldade respiratória ou alimentação ruim são sinais graves.","immediate":"Sinais clínicos exigem atendimento hospitalar imediato; manter o bebê aquecido e não oferecer suplementos por conta própria.","return":"Após alta, cumprir controles e exames definidos pela equipe; retornar imediatamente se sintomas reaparecerem.","sources":[{"url":"https://www.nationwidechildrens.org/conditions/health-library/hypocalcemia-in-the-newborn","title":"Nationwide Children’s Hospital — Hypocalcemia in the Newborn","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Hipocalemia na Infância","setting":"urgent","aliases":["Hipocalemia","Hipopotassemia"],"general":"Potássio baixo pode alterar músculos e ritmo cardíaco; a gravidade depende do nível, dos sintomas e da causa.","diagnosis":"Cumpra exames e reposição supervisionada. Não use suplementos, substitutos do sal ou ajustes alimentares como correção de emergência.","expected":"A recuperação depende da causa e das perdas persistentes; reposição excessiva também pode ser perigosa.","alarm":"Fraqueza crescente, palpitações, constipação intensa ou dificuldade respiratória são alarmes.","immediate":"Desmaio, paralisia ou falta de ar requerem emergência.","return":"Retorne para controle laboratorial e revisão dos fatores desencadeantes; não interrompa a monitorização apenas por melhora dos sintomas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hypokalaemia/","title":"RCH — Hypokalaemia","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Hipoglicemia neonatal","aliases":[],"setting":"hospital","general":"O bebê precisa de verificação seriada da glicose e apoio para alimentação em ambiente assistido. Mantenha aquecimento e contato pele a pele conforme orientação da equipe.","diagnosis":"Glicose muito baixa pode não produzir sinais claros. O tratamento e a alimentação devem ser definidos pela equipe; não ofereça soluções caseiras ou mel.","expected":"Muitos episódios transitórios melhoram nos primeiros dias, mas valores persistentes ou recorrentes exigem investigação de outras causas e monitorização prolongada.","alarm":"Observe sucção fraca, menor interesse por mamadas, tremores repetidos, bebê muito mole, sonolência incomum ou alteração da cor.","immediate":"Convulsões, dificuldade para despertar, pausas respiratórias ou coloração azulada exigem assistência imediata.","return":"A alta depende de estabilidade e alimentação eficaz. Depois dela, piora das mamadas ou da resposta deve motivar avaliação urgente, sem esperar a próxima consulta.","sources":[{"url":"https://www.cuh.nhs.uk/patient-information/increased-risk-of-low-blood-sugars-after-birth-information-for-parents/","title":"Cambridge University Hospitals — Low blood sugars after birth","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Hipoglicemia Pediátrica","aliases":["Hipoglicemia"],"setting":"urgent","general":"Procure avaliação imediata diante de suspeita de glicose baixa. Informe jejum, vômitos, doenças conhecidas e possíveis exposições a medicamentos.","diagnosis":"A glicose precisa ser verificada e a causa investigada. O cuidado de crianças com diagnóstico metabólico prévio segue seu plano de emergência.","expected":"A recuperação pode ser rápida após correção, mas a causa e o risco de repetição precisam ser esclarecidos.","alarm":"Sudorese, palidez, irritabilidade, fraqueza, confusão e dificuldade de acordar merecem atenção.","immediate":"Convulsão, desmaio ou alteração de consciência exigem emergência; não ofereça nada pela boca nessa situação.","return":"A alta requer alimentação segura, orientação para intercorrências e seguimento conforme a causa.","sources":[{"url":"https://www.childrens.health.qld.gov.au/for-health-professionals/queensland-paediatric-emergency-care-qpec/queensland-paediatric-clinical-guidelines/unexplained-hypoglycaemia","title":"Children’s Health Queensland — Unexplained hypoglycaemia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Hiponatremia na Infância","aliases":["Hiponatremia"],"setting":"urgent","general":"Procure avaliação para definir gravidade e causa. Informe líquidos ingeridos, perdas, doenças e medicamentos.","diagnosis":"Sódio baixo pode decorrer de situações distintas. Não tente corrigir com sal, restrição ou excesso de água por conta própria.","expected":"A recuperação depende da causa e de correção monitorada; correção inadequada ou rápida pode causar dano.","alarm":"Observe náuseas, vômitos, cefaleia ou alteração de comportamento.","immediate":"Convulsão, confusão importante ou redução da consciência exige emergência.","return":"Cumpra controles laboratoriais e o plano de líquidos individual. Prepare fórmulas exatamente como orientado, sem diluição adicional.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Hyponatraemia/","title":"RCH — Hyponatraemia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Hipospádia","aliases":[],"setting":"specialist","general":"Mantenha avaliação com urologia pediátrica. Antes de qualquer circuncisão ou procedimento no prepúcio, confirme o plano com a equipe responsável.","diagnosis":"Na hipospádia, a abertura da uretra está em posição diferente da habitual; anatomia, curvatura e função urinária orientam a conduta.","expected":"A necessidade de correção e a evolução variam; acompanhamento pode continuar após cirurgia para verificar função e complicações.","alarm":"Relate jato muito fraco, esforço para urinar, dor ou alterações após procedimento.","immediate":"Incapacidade de urinar, febre com prostração ou complicação cirúrgica importante exigem atendimento imediato.","return":"Cumpra o seguimento urológico e as instruções pós-operatórias individualizadas.","sources":[{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/hypospadias","title":"European Association of Urology — Paediatric urology: hypospadias","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hipospádia distal","aliases":[],"setting":"specialist","general":"Mantenha higiene habitual sem manipulações forçadas e observe o jato urinário. A avaliação deve ser feita por urologia pediátrica.","diagnosis":"Na hipospádia distal, a abertura urinária fica próxima, mas fora da posição habitual. A necessidade de correção considera localização, curvatura e função urinária.","expected":"Formas muito leves podem não exigir cirurgia; outras são corrigidas conforme o planejamento individual. Não há prazo único que se aplique a todas as crianças.","alarm":"Jato muito fraco, esforço para urinar, dor ou infecções urinárias merecem reavaliação.","immediate":"Incapacidade de urinar, dor intensa, febre com prostração ou complicação importante após cirurgia exigem atendimento imediato.","return":"Mantenha retorno para decisão terapêutica e, se operado, cumpra cuidados e controle da sonda definidos na alta.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Hypospadias/","title":"RCH — Hypospadias","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Hipospádia proximal","aliases":[],"setting":"specialist","general":"Observe o jato urinário e mantenha higiene habitual, sem manipular a abertura. Procure avaliação com urologia pediátrica.","diagnosis":"Na hipospádia proximal, localização da uretra, curvatura e outras características definem o planejamento. Evite decidir procedimentos no prepúcio antes dessa avaliação.","expected":"A correção e eventual necessidade de etapas cirúrgicas variam; a função urinária deve ser acompanhada ao longo do crescimento.","alarm":"Dificuldade de urinar, dor, infecções ou mudanças do jato precisam de revisão.","immediate":"Ausência de urina com desconforto, febre com prostração ou sangramento importante após procedimento exige urgência.","return":"Retorne conforme o plano urológico e leve informação sobre testículos não palpáveis ou outras anomalias; após cirurgia, siga cuidados específicos da sonda e ferida.","sources":[{"url":"https://www.chop.edu/conditions-diseases/hypospadias","title":"CHOP — Hypospadias","accessed":"2026-09-26"}],"reviewNotes":"Não extrapola conduta de hipospádia distal; decisões cirúrgicas e avaliação associada são individualizadas.","status":"source-reviewed"},
{"name":"Hipotireoidismo adquirido","aliases":[],"setting":"specialist","general":"Administre o tratamento exatamente como orientado e mantenha uma rotina que facilite a adesão. Informe suplementos e outros medicamentos à equipe, pois podem interferir no plano terapêutico.","diagnosis":"No hipotireoidismo adquirido, o organismo recebe menos hormônio tireoidiano que necessita. Em crianças, acompanham-se também crescimento, rendimento e desenvolvimento; sintomas isolados não substituem os exames.","expected":"A melhora ocorre com a correção hormonal, mas o acompanhamento pode ser prolongado. A dose precisa de reavaliação durante o crescimento e conforme os resultados.","alarm":"Cansaço persistente, desaceleração do crescimento, palpitações ou sintomas novos durante o tratamento devem ser comunicados.","immediate":"Sonolência profunda, alteração de consciência, dificuldade respiratória ou desmaio exigem emergência.","return":"Compareça aos retornos da endocrinologia e aos exames programados, mesmo que a criança se sinta bem.","sources":[{"url":"https://www.nhs.uk/conditions/underactive-thyroid-hypothyroidism/","title":"NHS — Underactive thyroid","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Hipotireoidismo congênito","setting":"specialist","general":"Deficiência de hormônio tireoidiano presente ao nascimento; muitos bebês parecem normais, por isso a triagem neonatal é essencial.","diagnosis":"Atenda rapidamente à convocação por triagem alterada. Após confirmação, siga rigorosamente o plano e os exames de controle; não suspenda o cuidado porque o bebê parece bem.","expected":"O início precoce e o acompanhamento adequado favorecem crescimento e desenvolvimento. A resposta depende da gravidade e da continuidade do cuidado; exames orientam os ajustes ao longo do crescimento.","alarm":"Sonolência excessiva, dificuldade para mamar, icterícia prolongada, constipação, hipotonia ou baixo ganho de peso exigem avaliação rápida.","immediate":"Não esperar sintomas quando a triagem estiver alterada: contatar imediatamente o serviço indicado para confirmação e início do cuidado.","return":"Comparecer a todos os exames e consultas; retornar antes se houver piora da alimentação, alerta ou desenvolvimento.","sources":[{"url":"https://www.medlineplus.gov/ency/article/001193.htm","title":"MedlinePlus — Neonatal hypothyroidism","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Hipotireoidismo na Infância","aliases":["Hipotireoidismo infantil"],"setting":"specialist","general":"Administre o tratamento prescrito de maneira consistente e mantenha os exames de controle. Não suspenda ou altere a reposição por melhora aparente.","diagnosis":"É necessário distinguir formas congênitas e adquiridas; alterações na triagem neonatal precisam de avaliação rápida.","expected":"O acompanhamento adequado favorece crescimento e desenvolvimento, mas a necessidade de tratamento depende da causa.","alarm":"Relate dificuldade alimentar, sonolência acentuada, regressão do desenvolvimento ou sintomas após mudança da formulação.","immediate":"Pouca resposta, dificuldade respiratória ou deterioração importante exigem atendimento imediato.","return":"Compareça ao seguimento endocrinológico com os exames; crescimento, desenvolvimento e, quando indicado, audição precisam ser acompanhados.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8001676/","title":"ENDO-ERN/ESPE/ESE — Congenital hypothyroidism consensus guideline 2020–2021","accessed":"2026-09-26"},{"url":"https://www.nhs.uk/conditions/underactive-thyroid-hypothyroidism/","title":"NHS — Underactive thyroid","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. O consenso pediátrico fundamenta principalmente a forma congênita; a orientação não presume etiologia nem duração vitalícia para todos os casos.","status":"source-reviewed"},
{"name":"Hipovitaminose D em Pediatria","setting":"specialist","aliases":["Deficiência de vitamina D","Hipovitaminose D"],"general":"Baixos níveis de vitamina D precisam ser interpretados com alimentação, crescimento e possíveis doenças associadas.","diagnosis":"Siga o plano prescrito e mantenha oferta adequada de cálcio pela alimentação orientada. Não some suplementos ou use doses concentradas por conta própria.","expected":"A correção é acompanhada ao longo do tempo; alterações ósseas e causas persistentes podem exigir seguimento prolongado.","alarm":"Dor óssea importante, deformidade, fraqueza ou atraso motor merecem reavaliação.","immediate":"Espasmos, convulsão ou dificuldade respiratória exigem emergência.","return":"Cumpra os exames de controle e revise prevenção após correção, especialmente se permanecerem fatores de risco.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Vitamin_D_deficiency/","title":"RCH — Vitamin D deficiency","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Histoplasmose pulmonar","aliases":[],"setting":"specialist","general":"Informe exposição a cavernas, poeira, solo e fezes de aves ou morcegos. Mantenha acompanhamento, especialmente se houver baixa imunidade ou doença pulmonar prévia.","diagnosis":"A infecção é adquirida do ambiente e não passa habitualmente de pessoa para pessoa. Necessidade de tratamento depende da intensidade, duração e disseminação.","expected":"Quadros leves podem melhorar, mas formas persistentes ou graves podem requerer meses de cuidado. Ausência de resposta a antibiótico comum não exclui a doença.","alarm":"Observe febre persistente, perda de peso, cansaço crescente, dor no peito ou falta de ar.","immediate":"Dificuldade respiratória, confusão, cefaleia intensa com rigidez de nuca ou piora rápida exige pronto atendimento.","return":"Compareça aos exames de acompanhamento e retorne se não melhorar. Imunossuprimidos precisam de avaliação precoce diante de sintomas novos.","sources":[{"url":"https://www.cdc.gov/histoplasmosis/about/index.html","title":"CDC — About histoplasmosis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Icterícia neonatal fisiológica","aliases":[],"setting":"home","general":"Mantenha mamadas frequentes e observe ingestão, urina, fezes e disposição. Procure ajuda se houver dificuldade de alimentação; não substitua avaliação por exposição ao sol ou receitas caseiras.","diagnosis":"Icterícia fisiológica só deve ser considerada após avaliação do momento de início, intensidade e fatores de risco. Bilirrubina pode precisar de medição, e outras causas devem ser excluídas.","expected":"Em muitos recém-nascidos, a coloração melhora nas primeiras semanas; persistência ou aumento exigem revisão, sem assumir que continua fisiológica.","alarm":"Icterícia precoce, progressiva, urina escura, fezes muito claras ou pouca mamada precisam de avaliação rápida.","immediate":"Dificuldade para despertar, choro ou movimentos anormais, febre ou alteração respiratória: emergência neonatal.","return":"Cumpra o retorno e a dosagem de bilirrubina orientados; antecipe se a coloração ou o estado geral piorarem.","sources":[{"url":"https://www.nhs.uk/conditions/jaundice-in-babies/","title":"NHS — Jaundice in babies","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Icterícia por incompatibilidade ABO","setting":"urgent","general":"Icterícia por hemólise imunológica pode surgir nas primeiras 24 horas e evoluir rapidamente; recém-nascidos precisam de avaliação por idade em horas.","diagnosis":"Mantenha a alimentação orientada e observe mamadas e fraldas molhadas. Acompanhe a bilirrubina nos horários definidos, inclusive após alta; cor da pele isolada não substitui a medição profissional.","expected":"A intensidade pode aumentar rapidamente, especialmente no início da vida. A necessidade de fototerapia e outras medidas depende da idade em horas e do risco; alguns bebês precisam de internação.","alarm":"Icterícia no primeiro dia, piora rápida, sonolência, sucção fraca, choro agudo, rigidez ou convulsão são sinais de urgência.","immediate":"Procurar urgência imediatamente diante desses sinais; não usar sol ou tratamentos caseiros e não interromper alimentação sem orientação.","return":"Cumprir rigorosamente a reavaliação de bilirrubina e consulta após a alta indicada pela maternidade.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Jaundice_in_early_infancy/","title":"RCH — Jaundice in early infancy","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Icterícia por incompatibilidade Rh","aliases":[],"setting":"hospital","general":"Mantenha avaliação neonatal e controles de bilirrubina e anemia definidos pela equipe. Observe mamadas e disposição; não substitua tratamento por exposição ao sol.","diagnosis":"A destruição de glóbulos vermelhos pode elevar a bilirrubina e causar anemia. Fototerapia e outros cuidados dependem da idade e dos resultados, não apenas da cor da pele.","expected":"Com tratamento oportuno, muitos bebês evoluem bem. Pode ser necessário acompanhamento após a alta para verificar anemia ou retorno da icterícia.","alarm":"Observe pele mais amarela, palidez, respiração rápida, sonolência crescente ou redução das mamadas.","immediate":"Dificuldade para despertar, recusa alimentar importante, alterações dos movimentos ou dificuldade respiratória exigem pronto atendimento imediato.","return":"Retorne no prazo exato orientado para exames; antecipe com piora da cor ou alimentação. Leve os resultados e informações sobre o grupo sanguíneo.","sources":[{"url":"https://www.nhs.uk/conditions/rhesus-disease-hdfn/","title":"NHS — Haemolytic disease of the fetus and newborn","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Icterícia por leite materno","aliases":[],"setting":"home","general":"Continue amamentando conforme orientação e observe mamadas, peso, urina e fezes. Não interrompa o aleitamento nem ofereça água ou chás por conta própria.","diagnosis":"Icterícia associada ao leite materno é um diagnóstico após avaliação. Não se deve atribuir automaticamente todo amarelamento persistente a essa causa.","expected":"Pode persistir por mais tempo em bebê que cresce bem, mas a necessidade de exame ou tratamento depende da avaliação e dos níveis de bilirrubina.","alarm":"Piora do amarelamento, mamadas insuficientes, pouco ganho de peso, urina escura ou fezes muito claras exigem reavaliação.","immediate":"Sonolência excessiva, dificuldade para despertar, choro anormal, febre ou recusa alimentar exigem emergência.","return":"Mantenha o controle de peso e bilirrubina solicitado; suplementação ou interrupção temporária só devem ocorrer com plano específico.","sources":[{"url":"https://www.cdc.gov/breastfeeding-special-circumstances/hcp/illnesses-conditions/jaundice.html","title":"CDC — Jaundice and Breastfeeding","accessed":"2026-09-26"},{"url":"https://www.nhs.uk/conditions/jaundice-in-babies/","title":"NHS — Jaundice in babies","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Alarme de fezes claras/urina escura requer avaliação de outras causas de icterícia; não assumir etiologia benigna.","status":"source-reviewed"},
{"name":"Impetigo","aliases":["Impetigo em Pediatria"],"setting":"home","general":"Lave as mãos, mantenha unhas curtas e evite compartilhar toalhas e roupas. Siga o tratamento prescrito e evite coçar ou arrancar crostas.","diagnosis":"Impetigo é uma infecção contagiosa da pele; lesões úmidas podem transmitir. Combine com a equipe quando retornar à escola.","expected":"As feridas costumam começar a melhorar após início do tratamento, mas a ausência de resposta exige revisão.","alarm":"Observe novas lesões, expansão da vermelhidão, dor, calor e secreção.","immediate":"Febre com prostração, rápida extensão da inflamação ou envolvimento importante próximo aos olhos exige atendimento imediato.","return":"Retorne se as lesões piorarem durante o tratamento ou voltarem após ele; não compartilhe pomadas nem use sobras de prescrições anteriores.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Impetigo_school_sores/","title":"RCH — Impetigo","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Impetigo bolhoso","aliases":[],"setting":"home","general":"Lave as mãos, mantenha unhas curtas e limpe as lesões com cuidado. Não estoure as bolhas, compartilhe toalhas ou interrompa o tratamento prescrito ao primeiro sinal de melhora.","diagnosis":"No impetigo bolhoso, a avaliação define extensão e necessidade de tratamento específico. Lactentes pequenos, lesões extensas ou sintomas gerais exigem maior atenção e podem precisar de outro nível de cuidado.","expected":"Com tratamento adequado, é esperada melhora em poucos dias; persistência de novas bolhas ou piora deve ser revista. Pode haver mudança temporária na aparência da pele.","alarm":"Aumento da vermelhidão, dor, febre, pus ou novas áreas acometidas exigem avaliação.","immediate":"Prostração, desidratação, pele dolorosa descamando amplamente ou progressão rápida: emergência.","return":"Retorne se não melhorar; confirme com o serviço quando a criança pode voltar à escola ou creche.","sources":[{"url":"https://www.nhs.uk/conditions/impetigo/","title":"NHS — Impetigo","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Impetigo crostoso","setting":"home","general":"Infecção bacteriana superficial e contagiosa, com vesículas que rompem e formam crostas amareladas; higiene reduz transmissão.","diagnosis":"Lave as mãos, mantenha unhas curtas e evite coçar. Não compartilhe toalhas ou roupas; cuide das lesões conforme orientação e cumpra as regras para retorno à escola ou creche.","expected":"Com o cuidado prescrito, as lesões devem regredir gradualmente. Persistência ou aparecimento de novas áreas exige revisão; não repita tratamentos anteriores sem confirmar a causa.","alarm":"Febre, prostração, dor importante, vermelhidão que se espalha, envolvimento ocular ou muitas lesões exigem avaliação no mesmo dia.","immediate":"Lavar suavemente, cobrir lesões e lavar as mãos; buscar atendimento urgente se houver sinais de infecção disseminada.","return":"Reavaliar se não houver melhora com o plano clínico ou se surgirem novas lesões; seguir orientação sobre retorno à escola.","sources":[{"url":"https://www.nhs.uk/conditions/impetigo/","title":"NHS — Impetigo","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Imunodeficiência combinada grave (SCID)","aliases":["SCID"],"setting":"hospital","general":"Procure acompanhamento imediato em imunologia especializada. Siga rigorosamente as orientações de proteção contra infecções e informe o diagnóstico a qualquer equipe que atender o bebê.","diagnosis":"Vacinas vivas e transfusões exigem cuidados especiais; a equipe deve definir vacinação, alimentação e produtos sanguíneos apropriados. Não aplique vacinas sem comunicar a SCID.","expected":"É condição grave, com evolução relacionada ao diagnóstico precoce, controle de infecções e tratamento de reconstituição imunológica adequado ao subtipo.","alarm":"Observe febre, tosse, dificuldade respiratória, diarreia persistente, lesões na boca, pouca alimentação ou ganho de peso insuficiente.","immediate":"Qualquer sinal de infecção ou piora do estado geral deve motivar contato imediato com a equipe; dificuldade respiratória e pouca resposta são emergências.","return":"Mantenha seguimento especializado contínuo e o plano individual antes e depois do tratamento definitivo.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/severe-combined-immunodeficiency-scid/","title":"GOSH — Severe combined immunodeficiency","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Imunodeficiência comum variável","aliases":[],"setting":"specialist","general":"Mantenha seguimento com imunologia e registre infecções, tratamentos e internações. Leve o plano individual a todo atendimento e evite contato próximo com pessoas doentes.","diagnosis":"A deficiência imunológica pode causar infecções respiratórias repetidas e manifestações em outros órgãos. A reposição ou prevenção prescrita deve ser mantida nos intervalos orientados.","expected":"O acompanhamento pode reduzir complicações, mas o quadro é variável e requer cuidado contínuo; ausência de sintomas não encerra a necessidade de vigilância.","alarm":"Febre, tosse persistente, diarreia prolongada, perda de peso ou gânglios que aumentam precisam de avaliação.","immediate":"Falta de ar, confusão, prostração acentuada ou incapacidade de manter hidratação exigem emergência.","return":"Reavalie após infecções e mantenha controle pulmonar, nutricional e das demais manifestações identificadas pela equipe.","sources":[{"url":"https://www.medlineplus.gov/genetics/condition/common-variable-immune-deficiency/","title":"MedlinePlus Genetics — Common variable immune deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Indução em Sequência Rápida na Pediatria","aliases":[],"setting":"hospital","general":"Procedimento para garantir a respiração deve ser realizado por equipe treinada, com monitorização e recursos de emergência; informe alergias e antecedentes relevantes.","diagnosis":"A indução e intubação exigem planejamento de via aérea, circulação e alternativas se houver dificuldade.","expected":"A recuperação depende da doença que motivou o procedimento e das necessidades de ventilação e sedação.","alarm":"Queda da oxigenação, instabilidade circulatória e dificuldade de posicionar ou manter o tubo são situações monitoradas continuamente.","immediate":"A equipe deve intervir imediatamente diante de falha de ventilação ou deterioração; não há orientação domiciliar aplicável.","return":"Acompanhamento e retirada do suporte serão definidos no hospital.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Emergency_airway_management/","title":"RCH — Emergency airway management","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Orientação para familiares sobre procedimento hospitalar; não fornece instruções de execução nem sedativos.","status":"source-reviewed"},
{"name":"Infarto Agudo do Miocárdio na Pediatria","aliases":[],"setting":"hospital","general":"Suspeita de infarto exige atendimento hospitalar imediato. Interrompa esforço e informe cardiopatias, Kawasaki, cirurgias e exposições recentes.","diagnosis":"Dor torácica ou troponina isolada não confirmam infarto. A equipe integra sintomas, eletrocardiograma, marcadores e imagens para estabelecer lesão isquêmica e causa.","expected":"A recuperação depende do território afetado, função cardíaca e mecanismo. Não há prazo universal para alta ou retorno ao esporte.","alarm":"Dor persistente ou ao esforço, palpitações e desmaio preocupam. Lactentes podem apresentar irritabilidade, vômitos ou choque sem dor reconhecível.","immediate":"Dor com falta de ar, perda de consciência ou colapso: acione emergência imediatamente.","return":"Após estabilização, exigir plano de cardiologia, exames, atividade física e prevenção de recorrência individualizados.","sources":[{"url":"https://professional.heart.org/en/science-news/multimodality-approach-to-coronary-ischemic-testing-in-pediatric-patients/top-things-to-know","title":"AHA — Multimodality Approach to Coronary Ischemic Testing for Pediatric Patients, 2026","accessed":"2026-09-27"},{"url":"https://achpccg.com/wp-content/uploads/2024/10/AHA-Scientific-Statement-Diagnosis-Treatment-and-Long-Term-Management-of-Kawasaki-Disease-McCrindle-et-al-2017.pdf","title":"AHA — Diagnosis, Treatment, and Long-Term Management of Kawasaki Disease, 2017","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Chest_pain/","title":"RCH — Chest pain","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escopo de reconhecimento e encaminhamento, sem protocolo de reperfusão. Testes provocativos não substituem avaliação aguda. Revisão documental, sem homologação humana.","evidenceSummary":"Declarações AHA e diretriz institucional pediátrica. Crianças com risco coronariano e dor torácica. Causas raras; evidência frequentemente observacional. Documento Kawasaki antigo não usado para prescrever.","decisionSupport":{"summary":"Todos os ramos exigem avaliação hospitalar; definir mecanismo antes de tratamento específico.","requirements":["Idade e início dos sintomas","Estabilidade e ECG","Marcadores seriados e ecocardiografia","Anatomia coronária e antecedentes"],"branchRequired":true,"branches":[{"id":"iam-trombose","label":"Trombose/aneurisma coronariano","when":"Suspeita de oclusão, particularmente após Kawasaki.","setting":"hospital","overrides":{"diagnosis":"Avaliação urgente de coronárias e possibilidade de reperfusão especializada.","expected":"Depende da extensão isquêmica.","return":"Seguimento coronariano prolongado.","alarm":"Nova dor ou arritmia.","immediate":"Colapso: socorro imediato."}},{"id":"iam-estrutural","label":"Anomalia ou lesão coronária estrutural","when":"Anomalia congênita, cirurgia coronária prévia ou transplante.","setting":"hospital","overrides":{"diagnosis":"Definir anatomia e mecanismo com cardiologia pediátrica.","expected":"Depende da lesão.","return":"Plano específico após estabilização.","alarm":"Sintomas ao esforço.","immediate":"Síncope: emergência."}},{"id":"iam-indeterminado","label":"Lesão miocárdica ainda indeterminada","when":"Investigação não distingue isquemia de outras causas.","setting":"hospital","overrides":{"diagnosis":"Investigar também miocardite e outros diagnósticos.","expected":"Não assumir prognóstico de infarto.","return":"Reclassificar após investigação.","alarm":"Piora cardiorrespiratória.","immediate":"Instabilidade: intervenção imediata."}}]},"revisedAt":"2026-09-27"},
{"name":"Infecção de Trato Urinário em Pediatria","setting":"urgent","aliases":["Infecção urinária","ITU"],"general":"Infecção urinária em crianças pode causar febre, dor ou apenas dificuldade alimentar, sobretudo em bebês.","diagnosis":"Cumpra coleta de urina e tratamento orientados. Ofereça líquidos conforme tolerância e confira o resultado da cultura com a equipe.","expected":"Casos não complicados devem melhorar com cuidado adequado; ausência de resposta exige rever diagnóstico e tratamento.","alarm":"Febre persistente, vômitos, dor lombar, pouca urina ou prostração são alarmes.","immediate":"Bebê pequeno com febre ou criança muito abatida precisa de avaliação urgente.","return":"Retorne para revisar cultura e necessidade de investigação; novas infecções devem ser comunicadas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Urinary_Tract_Infection_Guideline/","title":"RCH — Urinary tract infection","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Infecção do trato urinário alta (Pielonefrite)","aliases":[],"setting":"urgent","general":"Siga o tratamento completo, ofereça líquidos conforme tolerância e observe febre, vômitos e urina. Lactentes e crianças muito abatidas precisam de avaliação prioritária.","diagnosis":"A pielonefrite envolve infecção urinária alta. Cultura e evolução podem exigir ajuste do plano; confirme como receber o resultado.","expected":"A recuperação depende da resposta e de possíveis alterações urinárias. Melhorar não substitui completar o esquema prescrito.","alarm":"Febre persistente, piora da dor, vômitos ou dificuldade de tomar o tratamento precisam de reavaliação.","immediate":"Prostração intensa, pouca urina, desidratação, dificuldade respiratória ou alteração de consciência exigem urgência.","return":"Retorne para conferir cultura e necessidade de imagem/seguimento; não trate novos episódios apenas com sobras de antibiótico.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Urinary_tract_infection_UTI/","title":"RCH — Urinary tract infection","accessed":"2026-09-26"}],"reviewNotes":"Aplicável à ITU alta após avaliação; não usa orientação de cistite para afastar gravidade de pielonefrite.","status":"source-reviewed"},
{"name":"Infecção do trato urinário baixa (Cistite)","aliases":[],"setting":"home","general":"Ofereça líquidos conforme aceitação, incentive urinar sem prender e cumpra o tratamento prescrito. Faça a coleta e os exames de urina do modo indicado, evitando contaminação da amostra.","diagnosis":"Cistite envolve a bexiga. Febre, dor nas costas ou comprometimento do estado geral podem indicar infecção de outro nível e exigem reavaliação, especialmente em lactentes.","expected":"Espera-se melhora com tratamento adequado. Ausência de melhora em até dois dias, piora ou resultado de cultura que exija mudança do esquema precisam ser discutidos com a equipe.","alarm":"Dor persistente, sangue na urina, febre, vômitos ou dificuldade para beber são sinais de alerta.","immediate":"Prostração, desmaio, confusão, pouca urina ou incapacidade de hidratar: emergência.","return":"Retorne para conferir evolução e cultura; infecções repetidas podem exigir investigação adicional.","sources":[{"url":"https://www.nhs.uk/conditions/urinary-tract-infections-utis/","title":"NHS — Urinary tract infections","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Infecção Fúngica no RN","aliases":[],"setting":"urgent","general":"O recém-nascido deve ser examinado para distinguir lesão localizada de doença invasiva. Informe prematuridade, internação, cateteres e quando as lesões começaram.","diagnosis":"Sapinho, dermatite da fralda, candidíase congênita e infecção do sangue não são equivalentes. Confirmar foco e agente; colonização isolada não demonstra invasão.","expected":"A evolução depende do agente, maturidade e órgãos envolvidos. Melhora da pele não exclui infecção disseminada.","alarm":"Menor alimentação, alteração de temperatura, letargia ou respiração diferente exigem reavaliação imediata.","immediate":"Apneia, convulsão, dificuldade para despertar ou desconforto respiratório: emergência.","return":"A equipe define reavaliação e alta; doença invasiva requer seguimento dos órgãos acometidos e desenvolvimento.","sources":[{"url":"https://www.idsociety.org/practice-guideline/candidiasis/","title":"IDSA — Clinical Practice Guideline for Candidiasis: neonatal infection, 2016","accessed":"2026-09-27"},{"url":"https://academic.oup.com/cid/article/64/10/1387/2967977","title":"Kaufman et al. — Congenital Cutaneous Candidiasis, 2017","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Nappy_rash/","title":"RCH — Nappy rash, 2024","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD003953_what-are-benefits-and-harms-different-antifungal-medicines-treat-fungal-infections-newborn-babies","title":"Prasad et al. — Antifungal therapy for newborn infants with invasive fungal infection, Cochrane, 2026","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escopo: localização, gravidade e encaminhamento. Outros fungos exigem identificação e plano próprio. Revisão documental, sem homologação humana.","evidenceSummary":"Diretriz, coorte retrospectiva e revisão Cochrane atualizada em setembro/2026. Neonatos; coorte congênita predominantemente de prematuros. Comparações terapêuticas permanecem muito incertas. Candidíase não representa todas as micoses; associação observacional não prova eficácia.","decisionSupport":{"summary":"Selecionar apresentação; dúvida sobre disseminação impede orientação domiciliar automática.","requirements":["Idade gestacional e dias de vida","Distribuição/início das lesões","Estado geral e alimentação","Culturas, espécie e dispositivos"],"branchRequired":true,"branches":[{"id":"fungo-localizado","label":"Candidíase mucocutânea localizada","when":"Bebê bem, forma adquirida localizada confirmada após exame.","setting":"home","overrides":{"diagnosis":"Cuidado local e tratamento individual indicado pela pediatria.","expected":"Deve melhorar conforme reavaliação clínica.","return":"Rever se persistir ou recidivar.","alarm":"Extensão das lesões.","immediate":"Febre ou prostração: emergência."}},{"id":"fungo-congenito","label":"Suspeita de candidíase congênita","when":"Erupção difusa desde nascimento/primeira semana ou funisite.","setting":"hospital","overrides":{"diagnosis":"Avaliação neonatal e investigação de disseminação.","expected":"Risco maior na prematuridade.","return":"Seguimento após controle documentado.","alarm":"Descamação extensa ou piora clínica.","immediate":"Apneia ou choque: intervenção imediata."}},{"id":"fungo-invasivo","label":"Invasiva ou outro fungo","when":"Sinais sistêmicos, sítio estéril positivo ou etiologia não estabelecida.","setting":"hospital","overrides":{"diagnosis":"Investigar órgãos, espécie e sensibilidade; manejo especializado.","expected":"Depende da extensão e resposta.","return":"Culturas e avaliações dirigidas orientam seguimento.","alarm":"Persistência de sinais sistêmicos.","immediate":"Deterioração: emergência hospitalar."}}]},"revisedAt":"2026-09-27"},
{"name":"Infecções em Imunocomprometidos","aliases":[],"setting":"urgent","general":"Tenha contato da equipe e lista de medicamentos, profilaxias e alergias. Informe sintomas novos prontamente, mesmo discretos. Ausência de febre não exclui gravidade.","diagnosis":"A investigação depende da defesa comprometida, foco e exposições; não existe esquema único para todos os imunocomprometidos.","expected":"Resposta depende do agente, controle da infecção e recuperação imunológica.","alarm":"Febre, calafrios, lesões novas, tosse, diarreia ou alteração do estado geral exigem contato imediato.","immediate":"Confusão, prostração intensa, falta de ar ou deterioração rápida: emergência.","return":"Cumpra reavaliação explícita da equipe; alta exige estabilidade e possibilidade de retorno rápido.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Febrile_Neutropenia/","title":"RCH — Fever and suspected or confirmed neutropenia","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Primary_immunodeficiencies/","title":"RCH — Primary immunodeficiencies, 2021","accessed":"2026-09-27"},{"url":"https://www.frontiersin.org/journals/pediatrics/articles/10.3389/fped.2023.1252495/full","title":"Moghadamnia et al. — Viral infections in pediatric solid organ transplant recipients, 2023","accessed":"2026-09-27"},{"url":"https://clinicalinfo.hiv.gov/en/guidelines/hiv-clinical-guidelines-pediatric-opportunistic-infections/introduction","title":"NIH — Pediatric Opportunistic Infection Guidelines: Introduction, 2024","accessed":"2026-09-27"}],"status":"source-reviewed","reviewNotes":"Escopo sindrômico por tipo de imunocomprometimento; tratamento requer foco/agente e especialista. Revisão documental, sem homologação humana.","evidenceSummary":"Diretrizes institucionais/NIH e revisão pediátrica. Oncologia, imunodeficiências, transplantados e crianças com HIV. Populações heterogêneas; não intercambiar profilaxias, limiares ou tratamentos.","decisionSupport":{"summary":"Escolher condição predominante; sepse ou suspeita de neutropenia febril sobrepõe-se aos demais ramos.","requirements":["Defeito imune, neutrófilos e tratamentos recentes","Transplante/rejeição, cateter e culturas prévias","Foco, estabilidade e exposições","HIV, controle virológico e adesão"],"branchRequired":true,"branches":[{"id":"imuno-neutropenia","label":"Neutropenia febril","when":"Febre com neutropenia conhecida ou suspeita.","setting":"hospital","overrides":{"diagnosis":"Emergência; investigação não deve atrasar tratamento hospitalar.","expected":"Pode deteriorar rapidamente.","return":"Plano oncológico de reavaliação.","alarm":"Qualquer piora clínica.","immediate":"Atendimento hospitalar imediato."}},{"id":"imuno-transplante","label":"Transplante/imunossupressão medicamentosa","when":"Transplante ou imunossupressores, sem critério do ramo anterior.","setting":"urgent","overrides":{"diagnosis":"Equipe ajusta investigação conforme tratamento e exposições.","expected":"Varia com defesa e foco.","return":"Monitorização específica do centro.","alarm":"Sintomas novos ou febre.","immediate":"Instabilidade: emergência."}},{"id":"imuno-inato","label":"Erro inato da imunidade","when":"Imunodeficiência primária conhecida ou suspeita.","setting":"urgent","overrides":{"diagnosis":"Avaliar defeito imune e infecções oportunistas.","expected":"Depende do defeito específico.","return":"Imunologia; suspeita de SCID exige contato imediato.","alarm":"Infecção persistente ou crescimento insuficiente.","immediate":"Prostração: emergência."}},{"id":"imuno-hiv","label":"HIV","when":"HIV confirmado, sem emergência prevalente.","setting":"urgent","overrides":{"diagnosis":"Investigar foco e interações com antirretrovirais.","expected":"Controle viral modifica risco.","return":"Infectologia e adesão ao plano.","alarm":"Piora ou novos sintomas.","immediate":"Dispneia/confusão: emergência."}}]},"revisedAt":"2026-09-27"},
{"name":"Infecções Fúngicas em Prematuros","aliases":["Infecção fúngica neonatal"],"setting":"hospital","general":"A suspeita de infecção fúngica em prematuro requer avaliação neonatal; informe cateteres, nutrição venosa, antimicrobianos prévios e lesões de pele.","diagnosis":"A equipe precisa distinguir colonização, doença localizada e invasão de sangue ou órgãos, identificando o agente quando possível.","expected":"A evolução depende da extensão, da prematuridade e da resposta; não há prazo único de recuperação.","alarm":"Comunique alteração de temperatura, mamadas ou atividade, pausas respiratórias e lesão cutânea em expansão.","immediate":"Avise imediatamente a equipe diante de apneia, coloração azulada, convulsão ou piora rápida; fora do hospital, procure emergência.","return":"A alta depende da estabilização e do plano neonatal; organize avaliação do desenvolvimento e dos órgãos afetados.","sources":[{"url":"https://www.idsociety.org/practice-guideline/candidiasis/","title":"IDSA — Candidiasis guideline, 2016, seção neonatal","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/31158517/","title":"ESCMID-ECMM — Invasive aspergillosis in neonates and children, 2019","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD003953_what-are-benefits-and-harms-different-antifungal-medicines-treat-fungal-infections-newborn-babies","title":"Cochrane CD003953.pub4 — Antifungal therapy for newborn infants with invasive fungal infection, 23/09/2026","accessed":"2026-09-27"},{"url":"https://www.scielo.br/j/jped/a/HDM8pwdcDf8TH4PHckZ9Mwh/","title":"Jornal de Pediatria — Fungal infections in a NICU: historical series, 2024","accessed":"2026-09-27"},{"url":"https://www.scielo.br/j/jped/a/4vf7zgLXt5fhxPRw4XZPdft/?lang=pt","title":"Jornal de Pediatria — Trichosporon neonatal: relato de caso, 2009","accessed":"2026-09-27"}],"reviewNotes":"Escopo: reconhecimento, investigação e destino neonatal. Fungos incomuns exigem identificação e plano específico; nenhum ramo define antifúngico ou dose. Cochrane pub4 conferida: há contagens conflitantes entre resumo leigo e resultados da página; não usadas para decisão. Rascunho sem homologação humana.","status":"source-reviewed","evidenceSummary":"Diretrizes IDSA e ESCMID-ECMM incluem neonatos; Cochrane publicada em 23/09/2026 mantém grande incerteza comparativa. Série brasileira e relato de Trichosporon ilustram heterogeneidade, sem provar eficácia de tratamentos.","decisionSupport":{"summary":"Selecionar a situação confirmada antes de individualizar as orientações.","requirements":["Idade gestacional e estabilidade","Local da coleta e espécie","Sangue, urina, líquor e órgãos afetados","Cateteres e profilaxia prévia"],"branchRequired":true,"branches":[{"id":"local","label":"Achado localizado ou colonização","when":"Equipe documentou ausência de doença invasiva.","setting":"hospital","overrides":{"diagnosis":"Cultura superficial isolada não demonstra disseminação; lesão cutânea no prematuro precisa ser examinada.","expected":"A evolução local não prevê o risco sistêmico.","alarm":"Expansão da lesão ou piora alimentar.","immediate":"Instabilidade clínica exige investigação imediata.","return":"Reavaliar pele e condição geral pela neonatologia."}},{"id":"candida-invasive","label":"Candidíase invasiva","when":"Candida em sangue/urina ou órgão profundo, avaliada pela equipe.","setting":"hospital","overrides":{"diagnosis":"Considerar investigação do sistema nervoso e olhos; persistência de culturas exige busca de focos profundos e revisão dos cateteres.","expected":"Depende de clearance microbiológico e acometimento orgânico.","alarm":"Culturas persistentes ou piora neurológica.","immediate":"Convulsão ou instabilidade: avisar a equipe imediatamente.","return":"Seguimento neonatal e dos órgãos envolvidos."}},{"id":"other-fungus","label":"Outro fungo ou agente indefinido","when":"Suspeita invasiva sem Candida confirmada, incluindo fungos filamentosos.","setting":"hospital","overrides":{"diagnosis":"Solicitar identificação especializada; aspergilose neonatal pode começar na pele. Não reutilizar automaticamente esquema de candidíase.","expected":"Varia com agente e extensão.","alarm":"Lesões ulceradas, necrose ou deterioração.","immediate":"Piora respiratória ou circulatória requer intervenção imediata.","return":"Neonatologia e infectologia definem monitorização."}}]},"revisedAt":"2026-09-27"},
{"name":"Influenza A","setting":"home","general":"Infecção respiratória viral; crianças pequenas e pessoas com condições crônicas têm maior risco de complicações. Repouso e hidratação ajudam.","diagnosis":"Priorize repouso, líquidos e higiene das mãos; cubra tosse e espirros. Evite contato com pessoas vulneráveis durante a doença e procure avaliação cedo se houver condição de maior risco.","expected":"A maioria melhora ao longo de alguns dias, mas cansaço e tosse podem durar mais. Piora após melhora inicial precisa de reavaliação para complicações, especialmente em crianças pequenas.","alarm":"Respiração difícil ou rápida, lábios arroxeados, desidratação, confusão, convulsão ou melhora seguida de piora exigem urgência.","immediate":"Com sinais de alarme, procurar emergência; manter líquidos em pequenos volumes e evitar contato com pessoas vulneráveis.","return":"Reavaliar se febre ou sintomas piorarem, se a criança não beber/urinar, ou conforme orientação clínica; retornar à rotina quando estiver melhor e sem febre conforme regra local.","sources":[{"url":"https://www.nhs.uk/conditions/flu/","title":"NHS — Flu","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Influenza B","aliases":[],"setting":"home","general":"Ofereça líquidos, repouso e alimentação tolerada. Reduza contato com outras pessoas enquanto estiver doente e reforce higiene das mãos e cuidados ao tossir.","diagnosis":"Crianças pequenas e pessoas com condições de risco devem ser avaliadas precocemente. Não use ácido acetilsalicílico ou produtos com salicilatos para tratar influenza infantil.","expected":"Casos sem complicação geralmente melhoram em alguns dias; tosse e cansaço podem persistir mais tempo. Nova piora após melhora inicial precisa de revisão.","alarm":"Observe febre que retorna, dor torácica, dificuldade para beber, pouca urina ou dor muscular que impede caminhar.","immediate":"Esforço respiratório, lábios azulados, convulsões, pouca resposta ou desidratação importante exigem emergência.","return":"Retorne se não houver melhora progressiva ou surgir qualquer complicação. A indicação de tratamento específico deve considerar tempo de sintomas e risco individual.","sources":[{"url":"https://www.cdc.gov/flu/hcp/clinical-signs/","title":"CDC — Clinical signs and symptoms of influenza","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Influenza em Pediatria","aliases":["Influenza","Gripe"],"setting":"home","general":"Se liberada para casa, ofereça líquidos e repouso conforme tolerância. Acompanhe respiração, disposição e capacidade de beber.","diagnosis":"A influenza pode agravar doenças prévias; crianças pequenas e pacientes com condições de risco precisam de avaliação precoce.","expected":"Muitos quadros melhoram em dias, geralmente antes de duas semanas, mas complicações podem alterar essa evolução.","alarm":"Observe febre ou tosse que melhoram e depois pioram, dor muscular intensa ou redução da urina.","immediate":"Falta de ar, arroxeamento, dor torácica, convulsão ou dificuldade de despertar exige emergência.","return":"Retorne diante de piora ou recuperação incompleta, especialmente quando houver doença crônica ou pouca idade.","sources":[{"url":"https://www.cdc.gov/flu/signs-symptoms/index.html","title":"CDC — Signs and Symptoms of Flu","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Ingestão de bateria em botão","aliases":[],"setting":"hospital","general":"Procure emergência imediatamente, mesmo se a criança estiver bem. Leve a embalagem ou aparelho de origem quando isso for possível sem atrasar o atendimento.","diagnosis":"Bateria tipo botão pode causar queimadura grave no esôfago em poucas horas. Não espere aparecer nas fezes nem provoque vômitos.","expected":"A ausência inicial de sintomas não garante segurança. Avaliação por imagem e eventual retirada urgente dependem da localização e do tempo de ingestão.","alarm":"Tosse, engasgos, baba, recusa alimentar, vômitos ou desconforto torácico podem indicar lesão.","immediate":"Qualquer suspeita de ingestão já exige emergência; dificuldade respiratória, sangue no vômito ou desmaio tornam a situação ainda mais crítica.","return":"Após remoção ou alta formal, cumpra rigorosamente o seguimento, pois algumas complicações podem aparecer posteriormente.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Button_batteries/","title":"RCH — Button battery safety","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Ingestão de corpo estranho (moeda)","aliases":[],"setting":"urgent","general":"Confirme com a equipe qual objeto foi ingerido, horário e tamanho aproximado. Se houver dúvida entre moeda e bateria, procure emergência imediatamente.","diagnosis":"A necessidade de radiografia ou retirada depende da localização e dos sintomas. Não provoque vômito nem tente empurrar o objeto com comida.","expected":"Objetos pequenos que passaram sem obstrução podem sair espontaneamente, mas observação domiciliar só cabe após avaliação apropriada.","alarm":"Observe salivação, dificuldade para engolir, dor no pescoço, peito ou barriga e vômitos.","immediate":"Engasgo, falta de ar, sangue no vômito/fezes ou incapacidade de engolir saliva exige emergência.","return":"Retorne conforme o plano de imagem/observação e imediatamente se surgirem sintomas; mantenha moedas e baterias fora do alcance.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Swallowed_ingested_foreign_bodies/","title":"RCH — Swallowed objects","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Insuficiência Adrenal Aguda Infantil (Hospitalar)","aliases":["Crise adrenal"],"setting":"hospital","general":"Acione emergência e informe o diagnóstico, uso de corticoides e plano de doença intercorrente, se existente.","diagnosis":"A crise pode ocorrer durante infecções, lesões ou dificuldade para manter a reposição. Precisa de tratamento hospitalar imediato.","expected":"A recuperação depende da rapidez do cuidado e do fator desencadeante, com monitorização de glicose e eletrólitos.","alarm":"Observe fraqueza intensa, vômitos, dor abdominal, desidratação ou sonolência.","immediate":"Desmaio, convulsão ou redução da resposta exige socorro imediato e execução do plano de resgate previamente ensinado.","return":"Após estabilização, revise prevenção de crises e reposição com endocrinologia; nunca suspenda abruptamente por conta própria.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Adrenal_crisis_and_acute_adrenal_insufficiency/","title":"RCH — Adrenal crisis and acute adrenal insufficiency","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Insuficiência Cardíaca em Pediatria","aliases":["Insuficiência cardíaca"],"setting":"specialist","general":"Siga o plano cardiológico de alimentação, líquidos, atividade e acompanhamento. Registre mudanças de peso e sintomas quando solicitado pela equipe.","diagnosis":"A insuficiência cardíaca pode decorrer de diferentes doenças; o cuidado depende da causa e da capacidade de bombeamento.","expected":"A evolução é variável. Alguns casos precisam de procedimentos ou suporte avançado, além de acompanhamento contínuo.","alarm":"Observe aumento do inchaço, suor ao mamar, cansaço, pouco ganho de peso ou respiração acelerada.","immediate":"Falta de ar em repouso, coloração azulada, desmaio ou redução importante da resposta exigem emergência.","return":"Antecipe a revisão se alimentação, crescimento, inchaço ou tolerância às atividades piorarem.","sources":[{"url":"https://www.chop.edu/conditions-diseases/heart-failure-children","title":"CHOP — Heart Failure in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Insuficiência Hepática Fulminante em Pediatria","setting":"hospital","aliases":["Insuficiência hepática aguda","Falência hepática aguda"],"general":"Falência hepática aguda é uma emergência de evolução imprevisível e requer cuidado hospitalar especializado.","diagnosis":"Informe todos os produtos e medicamentos usados e exposições recentes. A equipe monitorará consciência, coagulação, glicose e demais órgãos.","expected":"Pode haver recuperação, necessidade de transplante ou agravamento rápido; não é possível prever o curso apenas pela cor da pele.","alarm":"Sangramento, sonolência, confusão, vômitos ou piora da icterícia são alarmes.","immediate":"Acione emergência diante de alteração de consciência, convulsão ou sangramento importante.","return":"Após alta, cumpra integralmente o acompanhamento de hepatologia; qualquer piora exige contato imediato.","sources":[{"url":"https://naspghan.org/wp-content/uploads/2022/01/North_American_Society_for_Pediatric.23.pdf","title":"NASPGHAN — Diagnosis and Management of Pediatric Acute Liver Failure","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Insuficiência Mitral em Pediatria","aliases":["Insuficiência mitral","Regurgitação mitral"],"setting":"specialist","general":"Mantenha acompanhamento cardiológico e boa higiene bucal. Confirme com a equipe o plano de atividade física e informe mudanças na tolerância ao esforço.","diagnosis":"A válvula mitral permite refluxo de sangue; sua importância depende da intensidade do vazamento e do efeito sobre o coração.","expected":"Pode permanecer sem sintomas, mas necessita vigilância porque a gravidade pode mudar.","alarm":"Relate cansaço crescente, palpitações, falta de ar ou edema.","immediate":"Falta de ar importante em repouso, desmaio ou piora súbita exigem emergência.","return":"Realize consultas e ecocardiogramas conforme a cardiologia; não aguarde o retorno programado se surgirem sintomas.","sources":[{"url":"https://www.seattlechildrens.org/conditions/mitral-valve-abnormalities/","title":"Seattle Children’s — Mitral valve abnormalities","accessed":"2026-09-26"},{"url":"https://www.leedsth.nhs.uk/patients/resources/mitral-regurgitation/","title":"Leeds Teaching Hospitals NHS — Mitral regurgitation","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Fonte pediátrica específica acrescentada. Estenose e prolapso não foram tratados como sinônimos de insuficiência mitral.","status":"source-reviewed"},
{"name":"Intolerância à lactose primária","aliases":[],"setting":"home","general":"Ajuste a quantidade de lactose com orientação profissional e observe quais porções desencadeiam sintomas. Evite retirar grupos alimentares inteiros sem planejar substituições adequadas para o crescimento.","diagnosis":"Intolerância à lactose é diferente de alergia à proteína do leite. Muitas pessoas toleram alguma quantidade; produtos sem lactose podem ser úteis quando a indicação for realmente intolerância.","expected":"Na forma primária, a capacidade de digerir lactose pode permanecer reduzida. O objetivo é controlar sintomas mantendo uma alimentação nutricionalmente suficiente, sem prometer cura imediata.","alarm":"Perda de peso, sangue nas fezes, febre ou diarreia persistente não devem ser atribuídos automaticamente à lactose.","immediate":"Desidratação importante, dor abdominal intensa ou prostração: atendimento imediato.","return":"Retorne para rever sintomas, crescimento e consumo de cálcio; lactentes e dietas muito restritivas exigem avaliação específica.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/lactose-intolerance/treatment","title":"NIDDK — Treatment for Lactose Intolerance","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Intolerância à lactose secundária","setting":"home","general":"Pode surgir temporariamente após gastroenterite ou doença intestinal, porque a mucosa passa a produzir menos lactase. Não equivale a alergia ao leite.","diagnosis":"Siga o plano nutricional e investigue a doença intestinal desencadeante. Ajuste de lactose deve preservar nutrientes e crescimento; não faça exclusões amplas nem interrompa amamentação por conta própria.","expected":"Gases, distensão, cólicas e diarreia após lactose tendem a melhorar quando a causa é tratada. Evite exclusão prolongada sem orientação, para não prejudicar cálcio e crescimento.","alarm":"Sangue nas fezes, desidratação, perda de peso, dor intensa, febre persistente ou falha de crescimento exigem avaliação rápida.","immediate":"Ofereça líquidos adequados e mantenha alimentação tolerada; não faça dieta restritiva ampla nem use produtos substitutos sem orientação profissional.","return":"Reavalie com pediatria se sintomas persistirem, recorram na reintrodução ou houver preocupação nutricional.","sources":[{"url":"https://www.nhs.uk/conditions/lactose-intolerance/","title":"NHS — Lactose intolerance","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Intoxicação Exógena em Pediatria","aliases":["Intoxicação exógena"],"setting":"urgent","general":"Procure orientação imediata de emergência ou centro de toxicologia. Guarde a embalagem e informe substância, quantidade possível, horário e via de exposição.","diagnosis":"Não provoque vômito nem ofereça remédios caseiros. O risco depende do produto e não apenas da presença inicial de sintomas.","expected":"Algumas intoxicações têm efeitos tardios; ausência de sintomas não garante segurança ou dispensa de observação.","alarm":"Observe sonolência, vômitos, dificuldade respiratória, queimaduras, agitação ou convulsões.","immediate":"Alteração de consciência, respiração anormal ou convulsão exige emergência imediata.","return":"Siga o período de observação e plano de prevenção; exposição intencional requer avaliação de segurança emocional.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Poisoning_initial_management/","title":"RCH — Poisoning: Initial Management","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Intoxicação Infantil por Carbamazepina","aliases":["Intoxicação por carbamazepina"],"setting":"urgent","general":"Procure orientação toxicológica e atendimento imediatamente após suspeita de ingestão excessiva. Leve embalagem, concentração, quantidade estimada e horário; não provoque vômito nem ofereça produtos para neutralizar.","diagnosis":"A intoxicação pode afetar consciência, coração e respiração, com aparecimento tardio de sintomas.","expected":"Estar bem inicialmente não exclui risco; observação e exames dependem da exposição e evolução.","alarm":"Observe sonolência, desequilíbrio, vômitos ou comportamento diferente.","immediate":"Convulsão, desmaio, dificuldade respiratória ou pouca resposta exigem SAMU 192.","return":"A alta depende de avaliação toxicológica; depois, revise armazenamento seguro e o plano preventivo adequado à circunstância.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Carbamazepine_poisoning/","title":"Royal Children’s Hospital — Carbamazepine poisoning","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Intoxicação Infantil por Hipoglicemiantes","setting":"urgent","aliases":["Intoxicação por hipoglicemiantes"],"general":"Suspeita de ingestão de medicamento para diabetes precisa de orientação imediata, mesmo se a criança estiver bem.","diagnosis":"Identifique o produto, quantidade possível e horário; leve a embalagem. Não provoque vômito e mantenha medicamentos fora do alcance.","expected":"O risco e o tempo de observação variam por substância; algumas causam hipoglicemia tardia ou prolongada.","alarm":"Suor, palidez, tremor, vômitos, sonolência ou comportamento estranho são alarmes.","immediate":"Convulsão, desmaio ou redução de consciência exigem emergência; não ofereça nada pela boca.","return":"Alta depende da avaliação toxicológica e monitorização indicada; sintomas após alta exigem retorno imediato.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Oral_Hypoglycaemic_Poisoning/","title":"RCH — Oral Hypoglycaemic Poisoning","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Intoxicação por Etanol em Pediatria","aliases":["Intoxicação por etanol"],"setting":"urgent","general":"Procure avaliação imediata e leve embalagem ou informação do produto, quantidade possível e horário da exposição.","diagnosis":"Crianças pequenas podem apresentar hipoglicemia, hipotermia e coma mesmo com pequenas quantidades; outros álcoois têm toxicidade diferente.","expected":"A evolução depende da exposição e de outras substâncias ou traumas associados. Não presuma que basta dormir.","alarm":"Observe vômitos, desequilíbrio, sonolência ou comportamento incomum.","immediate":"Dificuldade para despertar, convulsão ou respiração anormal exige emergência.","return":"Alta depende de avaliação e recuperação clínica. Depois, revise armazenamento seguro e investigue exposição intencional quando pertinente.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Ethanol_Posioning/","title":"RCH — Ethanol poisoning","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Intoxicação por ferro","aliases":[],"setting":"hospital","general":"Busque atendimento imediatamente se houver ingestão excessiva ou quantidade desconhecida. Leve a embalagem, informe horário e quantidade possível e outros produtos acessíveis.","diagnosis":"A toxicidade depende do ferro elementar, que varia entre apresentações. Não provoque vômitos nem administre soluções caseiras; a avaliação deve ser feita com apoio toxicológico.","expected":"Pode haver aparente melhora antes de toxicidade grave. O desaparecimento dos vômitos não permite concluir que o risco passou.","alarm":"Observe dor abdominal, vômitos, diarreia, sangue, sonolência, palidez, respiração anormal ou alteração da consciência.","immediate":"Qualquer sintoma após ingestão suspeita, quantidade desconhecida ou exposição intencional exige pronto atendimento; não espere evolução em casa.","return":"Após alta formal, siga os controles indicados. Dor e vômitos tardios também merecem avaliação, pois podem ocorrer complicações intestinais ou hepáticas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/iron_poisoning/","title":"RCH — Iron poisoning","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Intoxicação por Inibidores de Monoaminoxidase","aliases":["Intoxicação por IMAO"],"setting":"hospital","general":"Procure emergência e leve embalagem, horário, quantidade possível e lista de medicamentos ou substâncias associados. Não aguarde sintomas para buscar avaliação.","diagnosis":"IMAO podem causar alterações neurológicas, cardiovasculares e térmicas; combinações serotoninérgicas acrescentam risco, mas não explicam toda intoxicação.","expected":"Na fenelzina, sintomas podem ser discretos nas primeiras 12 horas e atingir maior intensidade em 24–48 horas; isso não estabelece prazo universal de alta.","alarm":"Agitação, cefaleia intensa, tremor, rigidez, sudorese ou palpitações devem ser comunicados imediatamente.","immediate":"Convulsão, febre alta, desmaio, confusão ou dificuldade respiratória exigem socorro e monitorização hospitalar.","return":"Toxicologia define observação e alta. Após estabilização, revisar armazenamento e interações; ingestão intencional exige avaliação de saúde mental.","sources":[{"url":"https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=fa041652-fdde-4794-a8d2-279dd309e075","title":"DailyMed — Phenelzine sulfate, seção Overdosage","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Serotonin_toxicity/","title":"Royal Children’s Hospital — Serotonin toxicity","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23791433/","title":"Gahr et al. — Intoxications with tranylcypromine, 2013","accessed":"2026-09-27"}],"reviewNotes":"Bula usada para fenelzina, sem generalizar sua latência para todos os IMAO. Não adotar observação mínima genérica de síndrome serotoninérgica como critério de alta de overdose por IMAO. Rascunho sem homologação humana.","status":"source-reviewed","evidenceSummary":"Bula regulatória e diretriz pediátrica sustentam monitorização. Revisão de relatos de tranilcipromina envolve sobretudo adultos, com viés de publicação; não oferece limiar pediátrico seguro por quantidade ingerida.","decisionSupport":{"summary":"Selecionar a situação confirmada antes de individualizar as orientações.","requirements":["Produto e formulação exatos","Dose possível, horário e intenção","Coingestões e mudança recente de tratamento","Consciência, temperatura, pressão, ECG"],"branchRequired":true,"branches":[{"id":"exposure","label":"Exposição sem sintomas atuais","when":"Ingestão suspeita/confirmada ou quantidade desconhecida, ainda sem manifestações.","setting":"hospital","overrides":{"diagnosis":"A ausência inicial de sintomas não exclui toxicidade tardia. Contatar toxicologia para avaliação do produto.","expected":"Pode haver deterioração após período aparentemente normal.","alarm":"Qualquer alteração neurológica ou térmica.","immediate":"Novo sintoma deve ser comunicado imediatamente.","return":"Permanecer em observação pelo período definido pela equipe."}},{"id":"symptomatic","label":"Intoxicação sintomática ou interação grave","when":"Alteração clínica, clônus/rigidez, hipertermia ou instabilidade cardiovascular.","setting":"hospital","overrides":{"diagnosis":"Avaliar toxicidade serotoninérgica e efeitos cardiovasculares; suporte intensivo pode ser necessário.","expected":"Depende de complicações e resposta ao suporte.","alarm":"Piora da rigidez, consciência ou circulação.","immediate":"Hipertermia importante, convulsão ou choque: emergência intensiva.","return":"Monitorizar até recuperação clínica e critérios toxicológicos de alta."}}]},"revisedAt":"2026-09-27"},
{"name":"Intoxicação por ISRS em Pediatria","aliases":[],"setting":"urgent","general":"Informe nome, quantidade, horário e outros produtos ingeridos; leve embalagens e solicite orientação imediata da toxicologia ou serviço de urgência.","diagnosis":"Intoxicação por ISRS pode causar efeitos neurológicos e cardíacos; alguns antidepressivos pertencem a outras classes e têm riscos diferentes.","expected":"O tempo de observação depende do produto, da quantidade e dos sintomas; ausência inicial de sintomas não libera automaticamente.","alarm":"Observe tremor, agitação, vômitos, sonolência, palpitações ou febre.","immediate":"Convulsão, desmaio, rigidez importante ou alteração de consciência exige emergência.","return":"Alta requer avaliação clínica; ingestão intencional também exige avaliação de segurança e seguimento em saúde mental.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Selective_Serotonin_Re-uptake_Inhibitors_SSRIs_Poisoning/","title":"RCH — Selective serotonin re-uptake inhibitors poisoning","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Intoxicação por Organofosforados em Pediatria","aliases":["Intoxicação por organofosforados"],"setting":"hospital","general":"Afaste a criança da fonte sem expor outras pessoas. A equipe orientará retirada de roupas contaminadas e descontaminação segura.","diagnosis":"Exposição a organofosforados pode comprometer respiração, músculos e consciência. Informe produto e horário, levando a embalagem protegida quando possível.","expected":"Os efeitos podem surgir ou reaparecer depois da exposição; observação hospitalar é necessária conforme avaliação toxicológica.","alarm":"Observe excesso de saliva, suor, vômitos, diarreia, pupilas pequenas, fraqueza e dificuldade respiratória.","immediate":"Qualquer suspeita relevante, sobretudo com sintomas, exige emergência; não provoque vômito nem atrase o transporte.","return":"Após estabilização, siga orientação de observação e retorno por fraqueza ou sintomas neurológicos tardios.","sources":[{"url":"https://www.austin.org.au/Assets/Files/Organophoshate%20Guideline.May2023%5B1%5D.pdf","title":"Austin Clinical Toxicology Service — Organophosphorus Insecticides","accessed":"2026-09-26"}],"reviewNotes":"Diretriz com revisão prevista em2026; usada para triagem e necessidade de observação, sem posologia.","status":"source-reviewed"},
{"name":"Intoxicação por paracetamol","aliases":[],"setting":"hospital","general":"Procure atendimento imediatamente após suspeita de excesso de paracetamol. Leve embalagens e informe horário, quantidade aproximada e todos os produtos utilizados.","diagnosis":"A intoxicação pode ocorrer em dose única ou por doses repetidas acima do recomendado. Sintomas iniciais leves ou ausentes não excluem lesão hepática.","expected":"O risco depende de dose, tempo, formulação e exames. Tratamento precoce melhora a chance de boa evolução; não espere aparecer icterícia.","alarm":"Vômitos, dor abdominal, sonolência ou mal-estar devem ser comunicados, mas sua ausência não autoriza observação em casa.","immediate":"Toda suspeita relevante exige avaliação urgente; confusão, desmaio, sangramento ou dificuldade respiratória exigem emergência imediata.","return":"Só retorne para casa após liberação formal e cumpra exames de controle; ingestão intencional requer também avaliação de saúde mental.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/paracetamol_poisoning/","title":"RCH — Paracetamol poisoning","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Intoxicação por Salicilatos","aliases":["Intoxicação por salicilato"],"setting":"urgent","general":"Procure atendimento e orientação toxicológica após suspeita de exposição excessiva. Leve o produto e informe horário e quantidade; não provoque vômito nem tente neutralização doméstica.","diagnosis":"Salicilatos podem causar alterações metabólicas e neurológicas graves; sintomas iniciais discretos não excluem toxicidade.","expected":"A piora pode ser tardia, exigindo observação e exames repetidos conforme a equipe.","alarm":"Vômitos, zumbido, respiração rápida, sudorese ou confusão são alertas.","immediate":"Convulsão, desmaio, dificuldade respiratória ou pouca resposta exigem emergência.","return":"Após alta, siga as recomendações de controle e revise o acesso a medicamentos para prevenir nova exposição.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Salicylates_Posioning/","title":"Royal Children’s Hospital — Salicylates poisoning","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Intoxicação por saneantes domésticos","aliases":[],"setting":"urgent","general":"Afaste a exposição com segurança e peça orientação toxicológica imediatamente. Tenha a embalagem ou fotografia do rótulo e informe horário, quantidade e via de contato.","diagnosis":"Não provoque vômito, não tente neutralizar o produto e não ofereça misturas caseiras. A conduta depende da composição, não apenas do nome comercial.","expected":"Os efeitos podem ser imediatos ou tardios; ausência inicial de sintomas não permite garantir segurança.","alarm":"Observe tosse, salivação, dor ao engolir, queimaduras, vômitos, irritação ocular ou sonolência.","immediate":"Falta de ar, convulsão, desmaio ou queimadura importante exige emergência.","return":"Após avaliação, cumpra o período de observação e retorno indicado. Armazene produtos fechados, na embalagem original e fora do alcance infantil.","sources":[{"url":"https://www.gov.br/anvisa/pt-br/centraisdeconteudo/publicacoes/saneantes/guias-e-manuais/cartilha-de-orientacao-para-os-consumidores-de-saneantes/@@download/file","title":"ANVISA — Orientações para consumidores de saneantes","accessed":"2026-09-26"}],"reviewNotes":"Encaminhamento toxicológico; não estabelece protocolo único para substâncias corrosivas, hidrocarbonetos e outros saneantes.","status":"source-reviewed"},
{"name":"Intussuscepção intestinal","aliases":[],"setting":"urgent","general":"Dor abdominal em crises, palidez ou vômitos com suspeita de invaginação exigem avaliação hospitalar imediata. Não espere aparecer sangue nas fezes nem ofereça alimentos enquanto aguarda orientação.","diagnosis":"Uma parte do intestino entra dentro de outra e pode obstruir a passagem e comprometer a circulação. A criança pode parecer bem entre as crises; isso não exclui o problema.","expected":"O resultado costuma ser melhor com diagnóstico e tratamento rápidos. A conduta depende do local, estabilidade e exames; algumas situações precisam de cirurgia.","alarm":"Vômitos verdes, barriga distendida, sangue nas fezes ou sonolência são sinais importantes.","immediate":"Dor intensa contínua, criança muito mole, desmaio ou piora rápida: emergência.","return":"Após tratamento e alta, volte imediatamente se as crises reaparecerem e cumpra a revisão indicada pelo serviço.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/intussusception/","title":"Royal Children’s Hospital — Intussusception","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Invaginação Intestinal","aliases":["Intussuscepção intestinal"],"setting":"urgent","general":"Dor abdominal em crises com palidez, vômitos ou sonolência incomum precisa de avaliação urgente; não espere aparecer sangue nas fezes.","diagnosis":"Na invaginação, uma parte do intestino entra em outra, podendo comprometer a circulação intestinal.","expected":"A equipe decide a redução por procedimento ou cirurgia; o resultado depende do tempo e de complicações.","alarm":"A criança pode parecer bem entre crises; isso não exclui a doença. Vômitos verdes ou distensão preocupam.","immediate":"Vá imediatamente ao pronto atendimento se houver suspeita, especialmente com abatimento intenso ou sangue nas fezes.","return":"Após tratamento, siga a observação indicada e retorne prontamente se os sintomas reaparecerem.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/intussusception/","title":"RCH — Intussusception","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Kernicterus","aliases":[],"setting":"hospital","general":"Icterícia com sinais neurológicos no recém-nascido é emergência. Não espere clarear espontaneamente nem utilize exposição ao sol como tratamento.","diagnosis":"Bilirrubina muito elevada pode lesar o cérebro. É preciso distinguir encefalopatia aguda da lesão neurológica persistente chamada kernicterus.","expected":"O atendimento precoce busca evitar progressão; lesões estabelecidas podem deixar sequelas e exigem acompanhamento contínuo.","alarm":"Observe choro muito agudo, dificuldade para alimentar, corpo excessivamente mole ou rígido e movimentos oculares anormais.","immediate":"Arqueamento do corpo, convulsão ou dificuldade de despertar exige atendimento imediato.","return":"Após a fase aguda, acompanhe audição, visão, movimento e desenvolvimento conforme as necessidades.","sources":[{"url":"https://archive.cdc.gov/www_cdc_gov/ncbddd/jaundice/facts.html","title":"CDC — What are Jaundice and Kernicterus?","accessed":"2026-09-26"},{"url":"https://www.aap.org/en/patient-care/hyperbilirubinemia/frequently-asked-questions-about-the-2022-aap-guideline-on-the-management-of-hyperbilirubinemia/","title":"AAP — Hyperbilirubinemia guideline FAQ","accessed":"2026-09-26"}],"reviewNotes":"Página oficial arquivada usada para sinais; diretriz AAP atual consultada como complemento.","status":"source-reviewed"},
{"name":"Lábio leporino com fenda palatina","aliases":["Fissura labiopalatina"],"setting":"specialist","general":"Siga o plano da equipe de fissuras para alimentação, crescimento e cirurgias. Use posição e utensílios orientados individualmente; registre dificuldades e ganho de peso.","diagnosis":"A fissura do palato pode dificultar a sucção e permitir saída de leite pelo nariz. A avaliação inclui alimentação, audição, fala e saúde dos dentes.","expected":"A correção ocorre em etapas. O desenvolvimento da fala e da alimentação varia e pode exigir apoio continuado durante o crescimento.","alarm":"Observe mamadas muito demoradas, cansaço, engasgos repetidos, pouca urina, perda de peso ou dificuldade para ouvir.","immediate":"Engasgo com dificuldade respiratória, coloração azulada ou incapacidade de se alimentar exige atendimento imediato.","return":"Mantenha consultas de fonoaudiologia, audição e odontologia conforme o plano. Antecipe a avaliação se alimentação, peso ou comunicação estiverem prejudicados.","sources":[{"url":"https://www.nhs.uk/conditions/cleft-lip-and-palate/treatment/","title":"NHS — Cleft lip and palate: treatment","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Laringotraqueobronquite aguda (Crupe viral)","setting":"urgent","general":"Infecção viral causa tosse rouca, voz alterada e ruído ao inspirar, frequentemente pior à noite. Mantenha a criança calma, na posição em que respire com mais conforto.","diagnosis":"Observe a respiração em repouso e ofereça líquidos se estiver confortável. Evite agitação e exame forçado da garganta; não use vapor quente, que não tem benefício comprovado e pode causar queimadura.","expected":"Quadros leves costumam melhorar em poucos dias, embora a tosse possa persistir. A intensidade pode oscilar, sobretudo à noite; piora respiratória exige reavaliação imediata.","alarm":"Estridor em repouso, retrações, lábios arroxeados, sonolência, baba ou dificuldade para engolir são sinais de gravidade.","immediate":"Com dificuldade respiratória, chame emergência e não force a criança a deitar, comer ou beber. Não examine a garganta à força.","return":"Retorne imediatamente se o ruído ocorrer em repouso ou a respiração piorar; procure avaliação se não houver melhora.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Croup_Laryngotracheobronchitis/","title":"RCH — Croup (Laryngotracheobronchitis)","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Larva migrans cutânea","aliases":["Bicho geográfico","Larva Migrans Cutânea em Pediatria"],"setting":"home","general":"Evite contato direto da pele com areia ou solo contaminados. Use calçados e proteção para sentar; recolha fezes dos animais e mantenha acompanhamento veterinário.","diagnosis":"As lesões geralmente causam coceira e caminhos avermelhados na pele. Não corte, queime ou aplique substâncias irritantes para tentar retirar a larva.","expected":"Sem tratamento, os sintomas podem durar semanas; tratamento específico pode abreviar o quadro. Persistência exige confirmar o diagnóstico e possíveis reinfecções.","alarm":"Observe aumento de dor, secreção, vermelhidão ao redor, febre ou lesões fora do padrão habitual.","immediate":"Febre com rápida expansão da inflamação, olho afetado, falta de ar ou importante piora geral exige avaliação urgente.","return":"Retorne se as lesões continuarem surgindo ou não responderem ao tratamento. Crianças pequenas exigem seleção terapêutica apropriada à idade e peso.","sources":[{"url":"https://www.cdc.gov/zoonotic-hookworm/about/index.html","title":"CDC — About zoonotic hookworm","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Larva migrans visceral","aliases":[],"setting":"specialist","general":"Reforce higiene das mãos e evite ingestão de terra e de carnes cruas ou malcozidas. Informe contato com solo contaminado e animais à equipe.","diagnosis":"A larva migrans visceral pode atingir fígado, pulmões e outros órgãos. O diagnóstico combina sintomas, exposição e exames; sorologia positiva isolada não define toda a conduta.","expected":"A evolução depende dos órgãos acometidos e da intensidade da inflamação. O tempo para melhora deve ser acompanhado individualmente.","alarm":"Tosse, chiado, dor abdominal, febre ou perda de peso persistentes exigem reavaliação.","immediate":"Alteração visual, olho doloroso, falta de ar importante, convulsão ou mudança da consciência exigem atendimento imediato.","return":"Mantenha revisão clínica e laboratorial; sintomas oculares ou neurológicos exigem avaliação específica, sem presumir que sejam apenas da forma visceral.","sources":[{"url":"https://www.cdc.gov/toxocariasis/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of Toxocariasis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Leishmaniose tegumentar americana","aliases":[],"setting":"specialist","general":"Procure serviço de referência para confirmar o diagnóstico e orientar o tratamento. Mantenha repouso relativo, alimentação adequada e cuidados locais prescritos.","diagnosis":"A leishmaniose tegumentar pode afetar pele e mucosas; não trate a ferida apenas como infecção superficial nem use produtos caseiros.","expected":"A cicatrização e o seguimento dependem da forma e da resposta; melhora da lesão não dispensa controle.","alarm":"Observe novas feridas, obstrução ou sangramento nasal, rouquidão e dor ao engolir.","immediate":"Dificuldade para respirar, sangramento importante ou incapacidade de engolir líquidos exige atendimento imediato.","return":"Retorne para acompanhar lesões e tolerância ao tratamento. Reforce proteção contra picadas, especialmente ao entardecer e à noite em áreas de transmissão.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/l/lt","title":"Ministério da Saúde — Leishmaniose Tegumentar","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Leishmaniose visceral (Calazar)","aliases":[],"setting":"urgent","general":"Procure avaliação e tratamento em serviço de referência, levando exames e registros de febre. Não adie o atendimento esperando que a fraqueza e o aumento abdominal desapareçam sozinhos.","diagnosis":"A leishmaniose visceral pode causar anemia e comprometimento sistêmico. O diagnóstico e a indicação de tratamento consideram sintomas e exames; resultado sorológico isolado não define doença ativa.","expected":"Existe tratamento, mas a recuperação e o acompanhamento dependem da gravidade e da resposta. O seguimento é necessário mesmo após melhora clínica.","alarm":"Febre persistente, palidez acentuada, sangramento, perda de peso ou piora da força precisam de avaliação rápida.","immediate":"Falta de ar, desmaio, sangramento importante, confusão ou pouca resposta: emergência.","return":"Compareça às revisões e exames definidos; retorno da febre ou de sintomas após o tratamento requer nova avaliação.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/l/leishmaniose-visceral","title":"Ministério da Saúde — Leishmaniose Visceral","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Leptospirose em Pediatria","aliases":[],"setting":"urgent","general":"Procure avaliação cedo após febre ou dores depois de enchente, lama ou possível contato com urina de animais; informe a exposição.","diagnosis":"Leptospirose pode começar como outras infecções, com dor de cabeça e nas panturrilhas, e evoluir para complicações graves.","expected":"Casos leves e graves têm manejos diferentes; a equipe não deve aguardar exames se houver indicação clínica de tratamento.","alarm":"Observe olhos ou pele amarelados, redução da urina, sangramentos e piora respiratória.","immediate":"Falta de ar, sangue na tosse, pouca urina ou deterioração geral exigem hospital imediatamente.","return":"Siga a reavaliação indicada e evite nova exposição a água contaminada.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/l/leptospirose","title":"Ministério da Saúde — Leptospirose","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Leptospirose icterohemorrágica","setting":"hospital","general":"Forma grave da leptospirose, frequentemente após contato com água ou lama contaminada por urina de animais, pode causar icterícia e insuficiência renal.","diagnosis":"Permaneça sob acompanhamento hospitalar para vigiar rins, pulmões, sangramento e circulação. Informe exposição a enchentes ou lama e medicamentos usados; siga as restrições de líquidos se a equipe as indicar.","expected":"Pode evoluir com comprometimento renal, pulmonar e circulatório; necessita monitorização e tratamento definidos pela equipe. Não é condição para manejo doméstico.","alarm":"Confusão, pouca urina, sangramento, falta de ar, palidez intensa, pressão baixa ou piora da icterícia são emergências.","immediate":"Vá imediatamente ao pronto-socorro e informe exposição à água de enchente, roedores e a data do início. Não aguarde confirmação laboratorial.","return":"Após a alta, cumpra o seguimento indicado e retorne imediatamente diante de redução da urina, falta de ar, sangramento ou piora geral.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/l/leptospirose","title":"Ministério da Saúde — Leptospirose","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Leucemia linfoide aguda (LLA)","aliases":["LLA","Leucemia linfoblástica aguda"],"setting":"specialist","general":"Mantenha tratamento e exames com oncologia pediátrica, seguindo o plano de cada fase. Tenha contatos de urgência e informe todos os medicamentos utilizados.","diagnosis":"O tratamento é individualizado pelo subtipo e risco. Não omita ou ajuste doses por conta própria; comunique dificuldades, efeitos adversos e doses perdidas à equipe.","expected":"A resposta depende de características da doença e do tratamento. Mesmo com remissão, é necessário completar as etapas e manter seguimento.","alarm":"Observe febre, sangramento, novas manchas roxas, palidez acentuada, dor óssea, perda de disposição ou dificuldade alimentar.","immediate":"Febre durante tratamento, sangramento persistente, falta de ar ou alteração neurológica exige contato imediato com a oncologia/pronto atendimento.","return":"Compareça às revisões programadas e mantenha vigilância de efeitos tardios. Não espere a próxima consulta com sintomas novos ou sinais de infecção.","sources":[{"url":"https://www.cancer.gov/types/leukemia/patient/child-all-treatment-pdq","title":"NCI — Childhood acute lymphoblastic leukemia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Leucemia mieloide aguda (LMA)","aliases":[],"setting":"hospital","general":"O cuidado deve ser coordenado por hematologia/oncologia pediátrica. Tenha contato da equipe e siga as orientações individualizadas para alimentação, higiene e prevenção de infecções.","diagnosis":"A leucemia mieloide aguda exige definição do subtipo e do plano terapêutico. Tratamento e suporte são ajustados pelos exames e pelas complicações.","expected":"A resposta e o prognóstico variam conforme características da doença e tratamento; não há previsão universal de cura ou duração.","alarm":"Febre, sangramento, palidez intensa, dor crescente, dificuldade para alimentar-se ou problemas no cateter precisam ser comunicados prontamente.","immediate":"Febre durante tratamento com risco de neutropenia, falta de ar, confusão, sangramento importante ou desmaio exigem emergência imediata.","return":"Cumpra retornos e exames mesmo entre ciclos; não use suplementos ou medicamentos novos sem conferir com a oncologia.","sources":[{"url":"https://www.cancer.gov/types/leukemia/patient/child-aml-treatment-pdq","title":"National Cancer Institute — Childhood Acute Myeloid Leukemia Treatment","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Leucomalácia periventricular","aliases":[],"setting":"specialist","general":"Mantenha consultas de desenvolvimento e neurologia pediátrica. Observe alimentação, movimentos, visão, audição e aquisição de habilidades.","diagnosis":"A leucomalácia periventricular é uma lesão da substância branca, mais associada à prematuridade; o cuidado busca apoiar desenvolvimento e tratar repercussões.","expected":"A evolução varia. Alterações motoras ou de aprendizagem podem aparecer com o crescimento, mesmo quando não são claras no início.","alarm":"Comunique rigidez, assimetria, dificuldade alimentar ou atraso/perda de habilidades.","immediate":"Convulsão, pausa respiratória, dificuldade para despertar ou engasgo com cianose exige atendimento imediato.","return":"Compareça ao seguimento e às terapias indicadas; não espere que o atraso se torne importante para solicitar reavaliação e apoio ao desenvolvimento.","sources":[{"url":"https://medlineplus.gov/ency/article/007232.htm","title":"MedlinePlus — Periventricular leukomalacia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Linfadenomegalia em Pediatria","aliases":["Linfadenomegalia","Linfadenopatia"],"setting":"home","general":"Após avaliação de baixo risco, observe os gânglios sem apertar ou manipular. Registre crescimento, dor, febre e sintomas associados.","diagnosis":"Gânglios aumentados podem acompanhar infecções comuns, mas localização, evolução e exame definem a necessidade de investigação.","expected":"A duração varia conforme a causa; persistência não confirma câncer, mas exige reavaliação quando acompanhada de sinais preocupantes.","alarm":"Relate aumento progressivo, gânglio duro, perda de peso, suor noturno, palidez ou hematomas.","immediate":"Dificuldade para respirar ou engolir, prostração ou aumento doloroso rápido exige pronto atendimento.","return":"Retorne no prazo combinado ou antes se surgirem novos sinais; não prolongue observação indefinidamente.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/cervical_lymphadenopathy/","title":"RCH — Cervical lymphadenopathy","accessed":"2026-09-26"}],"reviewNotes":"Fonte focada em gânglios cervicais; outras localizações requerem avaliação específica.","status":"source-reviewed"},
{"name":"Linfangite","aliases":[],"setting":"urgent","general":"Procure avaliação médica para vermelhidão dolorosa que avança em faixa pela pele, especialmente com febre. Mantenha a região limpa e não esprema feridas.","diagnosis":"A linfangite pode acompanhar infecção cutânea e exige avaliação da extensão e de complicações.","expected":"A melhora depende do controle da infecção; expansão ou piora apesar do plano exige revisão.","alarm":"Observe dor crescente, febre, pus, inchaço ou extensão rápida da vermelhidão.","immediate":"Prostração importante, dor desproporcional, bolhas, pele escurecida ou instabilidade exigem emergência.","return":"Após avaliação, siga o tratamento e a reavaliação combinados, retornando antes se o quadro se ampliar.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Cellulitis_and_other_bacterial_skin_infections/","title":"Royal Children’s Hospital — Cellulitis and other bacterial skin infections","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Fonte inclui linfangite como sinal de alerta em infecção cutânea; não pressupõe etiologia ou necessidade de tratamento domiciliar.","status":"source-reviewed"},
{"name":"Linfo-histiocitose Hemofagocítica","aliases":["HLH"],"setting":"hospital","general":"Mantenha assistência especializada hospitalar e informe rapidamente alterações de resposta, respiração ou sangramento.","diagnosis":"Uma resposta inflamatória descontrolada pode comprometer órgãos. Há formas genéticas e formas desencadeadas por outras doenças.","expected":"A evolução depende da causa, gravidade e resposta; exames repetidos orientam o cuidado.","alarm":"Observe febre persistente, aumento abdominal, manchas, cansaço intenso ou alterações neurológicas.","immediate":"Redução da resposta, falta de ar, convulsão ou sangramento exige ação imediata da equipe.","return":"Após estabilização, mantenha hematologia e exames. Recorrência de febre ou deterioração exige contato precoce, sem aguardar retorno.","sources":[{"url":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/hlh-patient-information-page","title":"UCLH — HLH patient information","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Linfoma de Hodgkin","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento oncológico e leve um resumo do tratamento aos atendimentos. Siga as instruções escritas para febre, alimentação, higiene e efeitos adversos; tenha o contato da equipe disponível.","diagnosis":"O tratamento depende do subtipo, extensão e resposta da doença. A prescrição oncológica não pode ser substituída por um esquema geral ou suspensa após diminuição dos gânglios.","expected":"Muitas pessoas alcançam remissão, mas isso não permite garantir um resultado individual. O acompanhamento continua após o tratamento para detectar recaída e efeitos tardios.","alarm":"Febre durante o tratamento, sangramento, novos gânglios ou piora importante do cansaço exigem contato rápido.","immediate":"Falta de ar, desmaio, confusão ou sangramento intenso: emergência.","return":"Cumpra consultas e exames nas datas previstas e procure a equipe antes do retorno diante de sintomas novos.","sources":[{"url":"https://www.nhs.uk/conditions/hodgkin-lymphoma/treatment/","title":"NHS — Treatment for Hodgkin lymphoma","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Orientação geral de suporte; estadiamento e protocolo pediátrico dependem de oncologia especializada.","status":"source-reviewed"},
{"name":"Linfoma não-Hodgkin Burkitt","setting":"hospital","general":"É um câncer de crescimento muito rápido de linfócitos, raro na infância. Pode aparecer como massa abdominal, aumento de gânglios ou doença na face, conforme o subtipo.","diagnosis":"O encaminhamento à oncologia pediátrica deve ser rápido. Organize exames e cumpra o plano de acompanhamento; avise a equipe antes de novos tratamentos ou suplementos e peça orientações para intercorrências.","expected":"A resposta depende da extensão, da biologia da doença e do tratamento. É possível controle com terapia especializada, mas não há prognóstico individual garantido; o início do cuidado exige vigilância de complicações.","alarm":"Falta de ar, fraqueza súbita, confusão, vômitos persistentes, abdome muito distendido ou pouca urina exigem emergência.","immediate":"Procure hospital com oncologia pediátrica; leve exames prévios e relate crescimento rápido da massa, febre, perda de peso ou suores noturnos.","return":"Mantenha todas as consultas e retorne ao hospital conforme orientação; durante investigação ou tratamento, qualquer piora aguda requer emergência.","sources":[{"url":"https://www.cancer.gov/types/lymphoma/patient/child-nhl-treatment-pdq","title":"NCI — Childhood Non-Hodgkin Lymphoma Treatment","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Lipidoses","aliases":[],"setting":"specialist","general":"Leve laudos, história familiar e plano atual ao centro metabólico. Registre mudanças de alimentação, movimento e desenvolvimento; adaptações nutricionais e de mobilidade devem ser individualizadas.","diagnosis":"Definir doença, subtipo e estágio; triagem alterada ou enzima baixa isolada nem sempre confirma doença. A orientação selecionada precisa corresponder à investigação clínica.","expected":"Evolução e resposta variam pelo subtipo; não existe prazo único de recuperação. Melhora visceral não garante recuperação neurológica.","alarm":"Comunique engasgos, perda de habilidades, dor óssea, hematomas ou redução do crescimento.","immediate":"Convulsão, dificuldade respiratória, sangramento importante ou alteração de consciência exige emergência.","return":"Mantenha seguimento em centro especializado, com frequência definida pela doença, pelos órgãos afetados e pela resposta ao plano.","sources":[{"url":"https://www.ninds.nih.gov/health-information/disorders/lipid-storage-diseases","title":"NINDS — Lipid Storage Diseases","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/22772880/","title":"Kaplan et al. — Revised recommendations for Gaucher disease in children, 2013","accessed":"2026-09-27"},{"url":"https://link.springer.com/article/10.1186/s13023-023-02686-6","title":"Consensus clinical management guidelines for ASMD, 2023","accessed":"2026-09-27"},{"url":"https://onlinelibrary.wiley.com/doi/10.1002/jimd.70185","title":"2025 Consensus Clinical Management Guidelines for Niemann-Pick C, publicado em 2026","accessed":"2026-09-27"},{"url":"https://www.scielo.br/j/jbn/a/w4dPBHwvcPQRTbzHCz5QNLw/?lang=en","title":"Comdora-SBN — Recomendações para diagnóstico e manejo de Fabry pediátrico, 2022","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK1292/","title":"GeneReviews — Fabry Disease","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK164500/","title":"GeneReviews — GLB1-Related Disorders, seção gangliosidose GM1","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK1218/","title":"GeneReviews — HEXA Disorders","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK579484/","title":"GeneReviews — Sandhoff Disease","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK583219/","title":"GeneReviews — GM2 Activator Deficiency","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK1238/","title":"GeneReviews — Krabbe Disease, atualizado em 08/09/2026","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK1130/","title":"GeneReviews — Arylsulfatase A Deficiency","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/38613540/","title":"Adang et al. — Consensus guidelines for monitoring and management of MLD, 2024","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK305870/?report=reader","title":"GeneReviews — Lysosomal Acid Lipase Deficiency","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK488189/","title":"GeneReviews — ASAH1-Related Disorders","accessed":"2026-09-27"}],"reviewNotes":"Escopo ampliado aos subtipos nomeados nos ramos, com distinção de investigação inicial, estágio clínico e seguimento. O ramo de diagnóstico ainda indefinido é uma via de investigação dirigida, não autorização para atribuir prognóstico ou terapia de outro subtipo. Enzima baixa pode refletir pseudodeficiência em algumas doenças. GeneReviews contém recomendações especializadas, frequentemente sem ensaios; MLD inclui consenso de opinião. Não importa aprovação estrangeira de terapia para o Brasil. Rascunho sem homologação humana.","status":"source-reviewed","evidenceSummary":"Consensos pediátricos/mistos e capítulos especializados sustentam cuidados por doença. Fabry pediátrico tem consenso brasileiro; MLD, consenso de especialistas; GeneReviews resume fenótipos e vigilância de doenças raras com evidência frequentemente observacional. Os ramos GM2 compartilham somente cuidados de suporte documentados em HEXA, HEXB e GM2A, sem equiparar diagnóstico ou prognóstico. Não há terapia universal nem promessa de cura.","decisionSupport":{"summary":"Selecionar doença e estágio; ramos de diagnóstico recente em Krabbe/MLD e LAL-D infantil têm prioridade de avaliação. Suspeita sem classificação usa investigação dirigida, nunca a terapia de outro subtipo.","requirements":["Doença confirmada, gene/enzima e subtipo; distinguir triagem de confirmação","Idade de início e estágio: recém-identificado, pré-sintomático ou seguimento estabelecido","Deglutição, nutrição, regressão, crises e mobilidade","Baço, fígado, pulmões, sangue, ossos, coração e rins conforme subtipo","Plano do centro metabólico e orientação para familiares em risco"],"branchRequired":true,"branches":[{"id":"gaucher","label":"Gaucher confirmado","when":"Confirmação diagnóstica, com classificação tipo 1, 2 ou 3.","setting":"specialist","overrides":{"diagnosis":"Acompanhar crescimento, hemograma, órgãos abdominais, ossos e exame neurológico; distinguir formas neuronopáticas.","expected":"O tipo e o envolvimento neurológico alteram o prognóstico.","alarm":"Dor óssea forte ou sangramento.","immediate":"Fratura suspeita ou hemorragia importante: urgência.","return":"Retorno metabólico e avaliação óssea programados."}},{"id":"asmd","label":"Deficiência de esfingomielinase ácida","when":"ASMD confirmada; distinguir formas neuronopática e não neuronopática.","setting":"specialist","overrides":{"diagnosis":"Acompanhar função hepática, pulmões e sangramento; avaliar deglutição quando há doença neurológica.","expected":"Evolução visceral e neurológica pode divergir.","alarm":"Engasgos, infecções respiratórias ou sangramento.","immediate":"Falta de ar ou hemorragia: emergência.","return":"Plano respiratório, nutricional e metabólico individual."}},{"id":"npc","label":"Niemann-Pick tipo C","when":"NPC confirmado, distinto de ASMD.","setting":"specialist","overrides":{"diagnosis":"Monitorizar deglutição, nutrição, movimentos, cognição e crises com equipe multidisciplinar.","expected":"Doença progressiva, com velocidade variável.","alarm":"Engasgos recorrentes ou perda funcional.","immediate":"Aspiração com dificuldade respiratória ou convulsão: emergência.","return":"Rever funcionalidade e segurança alimentar regularmente."}},{"id":"fabry","label":"Fabry confirmado","when":"Doença por GLA confirmada; registrar forma clássica ou de início tardio e órgãos envolvidos.","setting":"specialist","overrides":{"diagnosis":"Vigiar rim e coração mesmo sem queixas. Registrar crises dolorosas, sudorese e sintomas digestivos; meninas também podem apresentar doença relevante.","expected":"A ausência de sintomas não exclui lesão orgânica.","alarm":"Dor crescente, palpitações ou mudança urinária.","immediate":"Desmaio, dor torácica intensa ou déficit neurológico súbito: emergência.","return":"Seguimento metabólico, renal e cardíaco individualizado; avaliar familiares em risco."}},{"id":"gm1","label":"Gangliosidose GM1","when":"GM1 por GLB1 confirmada; não confundir com Morquio B, também relacionado a GLB1.","setting":"specialist","overrides":{"diagnosis":"Rever deglutição, nutrição, crises e mobilidade; acompanhar coração, olhos e esqueleto. Avisar o diagnóstico antes de sedação/anestesia.","expected":"Progressão depende da forma infantil, juvenil ou tardia.","alarm":"Engasgos, perda de habilidades ou dor com movimento.","immediate":"Aspiração com falta de ar, convulsão prolongada ou fraqueza súbita: emergência.","return":"Reavaliar alimentação, funcionalidade e estabilidade cervical conforme a equipe."}},{"id":"gm2","label":"Gangliosidose GM2","when":"Tay-Sachs/HEXA, Sandhoff/HEXB ou deficiência GM2A confirmada e fenótipo identificado.","setting":"specialist","overrides":{"diagnosis":"Planejar alimentação com menor risco de aspiração, hidratação, controle de crises, comunicação e prevenção de quedas/contraturas.","expected":"Formas infantis e tardias têm trajetórias diferentes; não estimar sobrevida apenas pelo nome GM2.","alarm":"Engasgos, crises mais frequentes ou sonolência excessiva.","immediate":"Crise prolongada, dificuldade respiratória ou impossibilidade de despertar: emergência.","return":"Avaliações multidisciplinares periódicas, antecipadas diante de perda funcional."}},{"id":"krabbe-new","label":"Krabbe: triagem ou identificação recente","when":"Triagem alterada, recém-nascido em risco familiar ou diagnóstico recente ainda sem avaliação de elegibilidade terapêutica.","setting":"urgent","overrides":{"diagnosis":"Contatar imediatamente centro de leucodistrofias; confirmar GALC, psicossina e genética conforme especialista, sem esperar regressão.","expected":"A fase pré-sintomática pode mudar as opções; enzima baixa isolada não define prognóstico.","alarm":"Irritabilidade intensa, dificuldade alimentar ou mudança do tônus.","immediate":"Perda rápida de habilidades ou dificuldade respiratória: emergência.","return":"Avaliação especializada urgente e cronograma explícito de vigilância."}},{"id":"krabbe-follow","label":"Krabbe: seguimento estabelecido","when":"Diagnóstico e estágio já classificados, com plano do centro especializado.","setting":"specialist","overrides":{"diagnosis":"Rever deglutição/aspiração, nutrição, secreções respiratórias, dor, crises, visão e apoio à mobilidade.","expected":"Velocidade de progressão varia com idade de início e estágio.","alarm":"Novo engasgo, perda motora ou piora visual.","immediate":"Apneia, aspiração com falta de ar ou crise prolongada: emergência.","return":"Revisões neurológicas e de reabilitação conforme evolução."}},{"id":"mld-new","label":"Leucodistrofia metacromática: identificação recente","when":"Suspeita/triagem ou confirmação recente de MLD sem avaliação especializada de estágio.","setting":"urgent","overrides":{"diagnosis":"Encaminhar rapidamente para confirmar bioquímica/genética e estágio; não aguardar declínio motor para discutir opções. Enzima baixa isolada pode ser pseudodeficiência.","expected":"A janela de intervenção depende do subtipo e do comprometimento já presente.","alarm":"Quedas novas, perda escolar ou mudança comportamental.","immediate":"Perda funcional rápida, convulsão ou dificuldade respiratória: emergência.","return":"Contato célere com centro de leucodistrofias e plano de monitorização."}},{"id":"mld-follow","label":"Leucodistrofia metacromática: seguimento","when":"MLD confirmada com estágio e plano definidos.","setting":"specialist","overrides":{"diagnosis":"Acompanhar marcha, dor, contraturas, comunicação, visão/audição e segurança da alimentação; adaptar equipamentos conforme necessidade.","expected":"Pode alternar estabilidade e declínio; não prometer recuperação dos déficits.","alarm":"Engasgos, quedas ou mudança importante de comportamento.","immediate":"Aspiração com falta de ar ou crise prolongada: emergência.","return":"Neurologia, reabilitação e nutrição; rever piora após infecções."}},{"id":"lal-infant","label":"Deficiência de lipase ácida: forma infantil","when":"LAL-D infantil/Wolman suspeita ou confirmada, com sintomas precoces.","setting":"hospital","overrides":{"diagnosis":"É uma emergência metabólica. Avaliar vômitos, diarreia, desnutrição e fígado; intervenção nutricional precisa de supervisão especializada.","expected":"Pode progredir rapidamente; cuidado precoce muda a evolução.","alarm":"Distensão abdominal, perda de peso ou diarreia persistente.","immediate":"Desidratação, sangramento, sonolência ou piora rápida: emergência.","return":"Manter acompanhamento hospitalar e metabólico até estabilização."}},{"id":"lal-later","label":"Deficiência de lipase ácida: início posterior","when":"LAL-D de início na infância posterior/adulto, sem descompensação aguda.","setting":"specialist","overrides":{"diagnosis":"Acompanhar fígado/fibrose, lipídios, crescimento e absorção intestinal. Dieta deve ser individualizada, sem restrição improvisada.","expected":"Risco hepático e metabólico persiste mesmo com poucos sintomas.","alarm":"Icterícia, distensão crescente ou perda ponderal.","immediate":"Vômito com sangue, fezes negras ou alteração de consciência: emergência.","return":"Revisar exames hepáticos, hemograma, lipídios e nutrição no centro."}},{"id":"farber","label":"Farber: fenótipo articular/laríngeo","when":"Deficiência ASAH1/ceramidase ácida com quadro de Farber classificado.","setting":"specialist","overrides":{"diagnosis":"Vigiar voz e via aérea, alimentação, dor e mobilidade articular; envolvimento neurológico modifica o plano.","expected":"As formas variam em gravidade; melhora articular não define evolução neurológica.","alarm":"Rouquidão progressiva, engasgos ou dor limitante.","immediate":"Ruído respiratório com esforço, falta de ar ou incapacidade de engolir: emergência.","return":"Rever nutrição, respiração, articulações e desenvolvimento em cada avaliação."}},{"id":"asah1-neuromuscular","label":"ASAH1: fenótipo neuromuscular","when":"Doença ASAH1 classificada como atrofia muscular com ou sem epilepsia, distinta do Farber clássico.","setting":"specialist","overrides":{"diagnosis":"Monitorizar força, respiração, deglutição, escoliose, audição e crises; adaptar comunicação e dispositivos de mobilidade.","expected":"Fraqueza e epilepsia podem evoluir em ritmos diferentes.","alarm":"Piora da tosse eficaz, quedas ou aumento de crises.","immediate":"Falta de ar, engasgo grave ou crise prolongada: emergência.","return":"Seguimento neuromuscular e funcional regular."}},{"id":"unclassified","label":"Lipidose em investigação","when":"Ainda sem classificação confirmada ou resultados que exigem correlação especializada.","setting":"specialist","overrides":{"diagnosis":"Organizar idade de início, evolução, história familiar e órgãos envolvidos. Genética/metabolismo define testes enzimáticos e moleculares dirigidos; não concluir doença por resultado isolado.","expected":"Permanece dependente do diagnóstico e estágio, sem prazo de cura.","alarm":"Regressão, falha de crescimento ou novos órgãos acometidos.","immediate":"Deterioração neurológica, respiratória ou circulatória aguda: emergência.","return":"Revisar resultados e plano de vigilância em consulta definida; aconselhamento genético após interpretação."}}]},"revisedAt":"2026-09-27"},
{"name":"Lúpus eritematoso sistêmico juvenil","aliases":[],"setting":"specialist","general":"Use proteção solar, mantenha descanso e atividade orientada e evite fumaça. Leve a lista completa dos tratamentos às consultas e comunique efeitos adversos.","diagnosis":"O lúpus pode atingir diferentes órgãos. O plano precisa considerar atividade da doença e exames; não suspenda tratamento por melhora aparente.","expected":"Podem alternar fases de controle e exacerbação. O objetivo é preservar órgãos, crescimento e participação escolar, sem prometer evolução igual para todos.","alarm":"Febre, mais cansaço, novas lesões de pele, inchaço, urina diferente ou dor persistente devem ser avaliados.","immediate":"Falta de ar, dor torácica, convulsão, confusão, redução importante da urina ou fraqueza súbita exigem emergência.","return":"Mantenha consultas e controles de sangue, urina e pressão arterial; febre pode representar infecção e não somente atividade do lúpus.","sources":[{"url":"https://www.niams.nih.gov/health-topics/lupus/diagnosis-treatment-and-steps-to-take","title":"NIAMS — Systemic Lupus Erythematosus: Treatment","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Lúpus Eritematoso Sistêmico Pediátrico","setting":"specialist","aliases":["Lúpus eritematoso sistêmico","LES"],"general":"Doença autoimune pode afetar diferentes órgãos e alternar atividade e controle.","diagnosis":"Use proteção solar e siga consultas, exames e atividade física individualizada. Discuta vacinação e novos produtos com a equipe.","expected":"A evolução varia e o controle não significa cura; função renal e outras complicações podem precisar vigilância mesmo sem sintomas.","alarm":"Febre, inchaço, urina alterada, dor torácica ou piora importante do cansaço exigem avaliação.","immediate":"Convulsão, confusão ou dificuldade respiratória requerem emergência.","return":"Mantenha reumatologia e demais especialidades; não interrompa o tratamento durante fases de melhora.","sources":[{"url":"https://www.gov.br/conitec/pt-br/midias/protocolos/20221109_pcdt_lupus.pdf/@@download/file","title":"Ministério da Saúde — PCDT do Lúpus Eritematoso Sistêmico","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Malária em Pediatria","setting":"urgent","aliases":["Malária"],"general":"Febre após permanência em área de transmissão requer investigação rápida, mesmo sem o padrão clássico de calafrios.","diagnosis":"Informe destino, datas da viagem e tratamentos prévios. Cumpra o esquema orientado e proteja-se de novas picadas.","expected":"A evolução depende da espécie e da rapidez do cuidado; crianças podem apresentar doença grave.","alarm":"Vômitos persistentes, palidez intensa, prostração, sangramento ou falta de ar são alarmes.","immediate":"Convulsão, alteração de consciência ou dificuldade respiratória exigem emergência imediatamente.","return":"Faça controle conforme o serviço e retorne se a febre persistir ou voltar, sem repetir tratamento sozinho.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/m/malaria","title":"Ministério da Saúde — Malária","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Malária por Plasmodium falciparum","aliases":[],"setting":"urgent","general":"Procure atendimento sem demora e informe viagens ou residência em área de transmissão. O tratamento deve ser iniciado e acompanhado por serviço habilitado.","diagnosis":"A malária por P. falciparum pode evoluir rapidamente para gravidade. A conduta depende da confirmação, intensidade e condições da criança.","expected":"Há possibilidade de cura com tratamento correto, mas o risco aumenta se a avaliação ou o tratamento atrasarem.","alarm":"Observe febre, vômitos, dificuldade de beber, fraqueza, urina escura e redução de urina.","immediate":"Confusão, convulsão, falta de ar, desmaio ou prostração intensa exigem emergência e provável cuidado hospitalar.","return":"Retorne para controle clínico e parasitológico conforme o serviço; complete o esquema e mantenha proteção contra mosquitos.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/m/malaria","title":"Ministério da Saúde — Malária","accessed":"2026-09-26"}],"reviewNotes":"Orientação de avaliação urgente para falciparum; não presume gravidade apenas pela espécie nem autoriza alta automática.","status":"source-reviewed"},
{"name":"Malária por Plasmodium vivax","aliases":[],"setting":"urgent","general":"Procure diagnóstico e tratamento rapidamente e informe viagens, local de moradia e episódios prévios. Cumpra o esquema prescrito e não interrompa o acompanhamento quando a febre baixar.","diagnosis":"A identificação de Plasmodium vivax orienta um plano específico, incluindo prevenção de recaídas quando apropriada. Idade, peso e condições individuais precisam ser avaliados pela equipe.","expected":"A malária tem tratamento, mas pode agravar e voltar se o cuidado não for adequado. O acompanhamento confirma a resposta; não existe garantia de cura apenas pela melhora inicial.","alarm":"Vômitos repetidos, icterícia, urina escura, fraqueza acentuada ou persistência de febre exigem avaliação.","immediate":"Convulsão, confusão, falta de ar, desmaio ou pouca urina: emergência.","return":"Retorne para os controles definidos e imediatamente se os sintomas voltarem, informando o diagnóstico e o tratamento anteriores.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/m/malaria","title":"Ministério da Saúde — Malária","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Mancha mongólica","setting":"home","general":"É uma marca azul-acinzentada plana, comum ao nascimento, sobretudo em nádegas ou lombar, causada por pigmento mais profundo da pele. Não é hematoma.","diagnosis":"Peça ao pediatra que registre localização e aspecto no prontuário. Cuide da pele normalmente; a marca típica não precisa de remoção ou produtos clareadores, e lesões atípicas merecem avaliação.","expected":"Não dói nem exige tratamento; costuma clarear gradualmente durante a infância, embora possa persistir. Não esfregue, cubra ou aplique produtos.","alarm":"Peça avaliação se surgir depois do nascimento, mudar rapidamente, doer, inchar, sangrar ou tiver aspecto diferente de uma mancha plana típica.","immediate":"Cuide normalmente da pele e mencione a marca em consultas. Não atribua automaticamente novas manchas ou lesões a mancha mongólica.","return":"Retorne na consulta pediátrica habitual ou antes se houver mudança; procure urgência se houver lesão dolorosa com doença ou trauma associado.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Congenital_dermal_melanocytosis/","title":"RCH — Congenital dermal melanocytosis","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Mastoidite em Pediatria","aliases":["Mastoidite"],"setting":"hospital","general":"Procure hospital diante de dor ou inchaço atrás da orelha, sobretudo com febre ou orelha deslocada. Não tente drenar ou manipular a região.","diagnosis":"Mastoidite pode complicar infecção do ouvido e exige avaliação otorrinolaringológica, com tratamento e possível procedimento definidos pela equipe.","expected":"A recuperação depende da extensão e de complicações; não deve ser acompanhada como otite simples sem reavaliação.","alarm":"Relate febre persistente, dor crescente, secreção ou aumento do edema.","immediate":"Cefaleia intensa, rigidez de nuca, fraqueza facial, sonolência ou convulsão exigem emergência.","return":"Após alta, mantenha acompanhamento do ouvido e retorne imediatamente se houver piora.","sources":[{"url":"https://idmp.ucsf.edu/content/mastoiditis","title":"UCSF Infectious Diseases Management Program — Mastoiditis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Fonte distingue mastoidite aguda de doença crônica; não transforma ambas em um esquema único.","status":"source-reviewed"},
{"name":"Meduloblastoma","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com neuro-oncologia pediátrica e siga o plano de exames, tratamento e reabilitação. Informe mudanças de comportamento, movimento, visão ou rendimento escolar.","diagnosis":"A localização, disseminação e características do tumor orientam o tratamento. O plano deve considerar idade e efeitos sobre crescimento e desenvolvimento.","expected":"A evolução varia conforme o grupo de risco e a resposta. O término do tratamento não encerra a necessidade de exames e acompanhamento.","alarm":"Observe cefaleia crescente, vômitos, piora do equilíbrio, visão dupla, fraqueza ou sonolência fora do habitual.","immediate":"Convulsão, dificuldade para despertar, perda súbita de força ou rápida piora neurológica exige emergência.","return":"Retorne no calendário definido pela equipe e antecipe diante de sintomas novos. Solicite apoio para necessidades de aprendizagem, mobilidade e comunicação.","sources":[{"url":"https://www.cancer.gov/types/brain/patient/child-cns-embryonal-treatment-pdq","title":"NCI — Childhood medulloblastoma and other CNS embryonal tumors","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Megacólon congênito (Doença de Hirschsprung)","aliases":[],"setting":"specialist","general":"Mantenha seguimento com cirurgia pediátrica e registre evacuações, distensão abdominal e alimentação. Faça lavagens retais ou cuidados de estoma somente como ensinados pela equipe.","diagnosis":"A doença de Hirschsprung requer tratamento especializado e geralmente cirúrgico. Mesmo após operação, pode haver constipação, dificuldade de continência ou enterocolite.","expected":"A maioria melhora após cirurgia, mas o intestino pode precisar de acompanhamento prolongado; a evolução varia conforme o segmento afetado e as complicações.","alarm":"Barriga progressivamente inchada, vômitos, dificuldade para evacuar ou redução do ganho de peso exigem revisão.","immediate":"Febre com distensão, diarreia importante, sangue nas fezes, vômito verde ou prostração exige emergência por risco de enterocolite/obstrução.","return":"Compareça aos retornos cirúrgicos e nutricionais e peça revisão se o padrão intestinal mudar.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/hirschsprung-disease/treatment","title":"NIDDK — Treatment for Hirschsprung Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Meningite Asséptica em Pediatria","aliases":["Meningite asséptica"],"setting":"hospital","general":"Suspeita de meningite exige avaliação hospitalar; não presuma que seja benigna por ser chamada asséptica. Informe sintomas, tratamentos recentes e condições de imunidade.","diagnosis":"O termo não confirma causa viral nem exclui todas as infecções bacterianas; exames e evolução orientam a investigação.","expected":"A evolução depende do agente e do estado clínico, e a alta requer estabilidade e plano de acompanhamento.","alarm":"Avise sobre piora da dor de cabeça, vômitos, rigidez de nuca ou sonolência.","immediate":"Convulsão, confusão ou déficit neurológico exigem atendimento imediato.","return":"Após alta médica, siga as orientações específicas e retorne se houver deterioração.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Meningitis_encephalitis/","title":"Royal Children’s Hospital — Meningitis and encephalitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Meningite bacteriana","aliases":[],"setting":"hospital","general":"Meningite bacteriana é emergência hospitalar. Procure atendimento imediatamente; não aguarde aparecimento de rigidez de nuca ou manchas na pele.","diagnosis":"Em bebês, os sinais podem ser pouco específicos, como recusa alimentar, irritabilidade ou pouca reação. A equipe define exames e tratamento urgente.","expected":"A recuperação varia e pode exigir acompanhamento de audição, neurologia e desenvolvimento após a internação.","alarm":"Observe febre, dor de cabeça, vômitos, fontanela abaulada, sonolência e convulsão.","immediate":"Alteração de consciência, convulsão, dificuldade respiratória ou piora rápida exige socorro imediato.","return":"Após a alta, compareça aos retornos e avaliações indicadas. A necessidade de medidas para contatos depende do agente e da vigilância, sem compartilhar medicamentos.","sources":[{"url":"https://www.cdc.gov/meningitis/about/index.html","title":"CDC — About Meningitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Meningite meningocócica sorogrupo B","aliases":[],"setting":"hospital","general":"Meningite meningocócica exige atendimento hospitalar imediato. Informe sintomas e contatos próximos à equipe; familiares não devem iniciar medicamentos por conta própria nem esperar resultado de exame para buscar assistência.","diagnosis":"O sorogrupo B pode causar meningite e infecção do sangue. A equipe definirá tratamento, isolamento, medidas para contatos e avaliação de vacinação conforme o contexto.","expected":"A doença pode piorar rapidamente. A evolução depende da gravidade e do início do tratamento; após a recuperação, podem ser necessários controles de audição e desenvolvimento.","alarm":"Febre com dor de cabeça intensa, rigidez de nuca, vômitos ou manchas arroxeadas é sinal de alerta.","immediate":"Sonolência, confusão, convulsões, falta de ar ou extremidades frias: emergência imediata.","return":"Após alta, cumpra o acompanhamento e comunique sequelas ou sintomas novos; contatos devem seguir as orientações recebidas.","sources":[{"url":"https://www.cdc.gov/meningococcal/about/index.html","title":"CDC — About Meningococcal Disease","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Fonte abrange doença meningocócica, inclusive sorogrupo B; profilaxia e calendário vacinal precisam seguir o serviço brasileiro.","status":"source-reviewed"},
{"name":"Meningite meningocócica sorogrupo C","setting":"hospital","general":"Infecção invasiva por meningococo pode causar meningite e sepse rapidamente. O sorogrupo C é prevenível por vacinação, mas a vacina não exclui emergência.","diagnosis":"Procure hospital imediatamente. Informe conviventes e contatos próximos à equipe para avaliação pela vigilância; siga orientações de prevenção sem compartilhar tratamentos. Não espere resultado laboratorial para buscar assistência.","expected":"A evolução pode ser rápida e grave. Recuperação e possíveis sequelas variam; após a alta, são importantes revisões de audição, desenvolvimento e demais necessidades definidas pela equipe.","alarm":"Manchas roxas, extremidades frias, respiração rápida, confusão, convulsão, dificuldade para acordar ou piora súbita são sinais de emergência.","immediate":"Chame emergência e informe suspeita de meningococo; não espere aparecer todos os sinais nem tente cuidar em casa.","return":"Após atendimento, siga rigorosamente infectologia e vigilância; retorne imediatamente por qualquer piora, convulsão ou alteração de consciência.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/m/meningite","title":"Ministério da Saúde — Meningite","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Meningite neonatal","aliases":[],"setting":"hospital","general":"O recém-nascido precisa de avaliação e tratamento hospitalar imediato. Informe mudanças nas mamadas, atividade, temperatura e choro, mesmo que pareçam discretas.","diagnosis":"Bebês podem não apresentar rigidez de nuca. A investigação e o tratamento dependem do agente e da condição clínica; não aguarde todos os sinais aparecerem.","expected":"A recuperação depende da causa, gravidade e rapidez do tratamento. Pode haver alterações auditivas ou neurológicas que precisam de acompanhamento.","alarm":"Observe sucção fraca, irritabilidade, choro incomum, pouca resposta, moleira abaulada ou alteração da respiração.","immediate":"Suspeita de meningite em recém-nascido já exige emergência; convulsões, dificuldade para despertar ou respiração anormal reforçam a urgência.","return":"Após alta formal, mantenha revisões de audição e desenvolvimento conforme o plano. Nova redução das mamadas ou atividade deve ser avaliada imediatamente.","sources":[{"url":"https://www.who.int/news-room/fact-sheets/detail/meningitis","title":"OMS — Meningitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte geral inclui apresentação em recém-nascidos e lactentes. Não extrapola esquemas de adultos; seguimento neonatal deve ser individualizado. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Meningite pneumocócica","aliases":[],"setting":"hospital","general":"É uma emergência que exige avaliação e tratamento hospitalar imediatos. Informe vacinação, início dos sintomas e tratamentos já recebidos.","diagnosis":"A meningite pneumocócica pode comprometer consciência, circulação e audição. Não espere surgir rigidez de nuca, especialmente em bebês, para buscar ajuda.","expected":"A recuperação depende da gravidade e da rapidez do tratamento. Mesmo com melhora, podem ocorrer sequelas que precisam de acompanhamento.","alarm":"Febre, dor de cabeça intensa, vômitos, sensibilidade à luz, recusa alimentar ou sonolência anormal são sinais importantes.","immediate":"Convulsão, confusão, dificuldade para despertar, falta de ar ou deterioração rápida exigem emergência imediata.","return":"Após a alta formal, mantenha revisão pediátrica e avaliação de audição e desenvolvimento; retorno de febre ou alterações neurológicas requer reavaliação imediata.","sources":[{"url":"https://www.cdc.gov/pneumococcal/signs-symptoms/","title":"CDC — Pneumococcal Disease Symptoms and Complications","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Meningite por Haemophilus influenzae b","aliases":[],"setting":"hospital","general":"Procure atendimento hospitalar imediato. Mantenha informações sobre vacinação, início dos sintomas e contatos próximas disponíveis para a equipe.","diagnosis":"A meningite por Hib é uma infecção grave. O nome da bactéria não significa gripe; tratamento e medidas para contatos são específicos.","expected":"Mesmo após melhora, podem ser necessárias avaliações de audição e desenvolvimento. O prognóstico depende da gravidade e rapidez do cuidado.","alarm":"Febre, pouca interação, recusa alimentar, vômitos, rigidez de nuca ou convulsão são sinais preocupantes.","immediate":"Sonolência difícil de interromper, convulsão, falta de ar ou piora rápida exigem emergência.","return":"Após alta, mantenha seguimento e revisão vacinal; contatos só devem receber prevenção medicamentosa quando indicada pelo serviço/vigilância.","sources":[{"url":"https://www.cdc.gov/hi-disease/about/index.html","title":"CDC — About Haemophilus influenzae Disease","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/meningitis/about/index.html","title":"CDC — About Meningitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Meningite tuberculosa","aliases":[],"setting":"hospital","general":"A suspeita de meningite tuberculosa precisa de avaliação hospitalar urgente. Leve informações sobre contato com tuberculose, exames anteriores e medicamentos; não aguarde evolução para sintomas mais típicos.","diagnosis":"O início pode ser gradual, com febre, irritabilidade e dificuldade alimentar. O tratamento é prolongado e pode começar pela suspeita clínica, conforme decisão da equipe.","expected":"A recuperação varia e pode exigir acompanhamento neurológico e reabilitação. A melhora inicial não autoriza interromper o esquema; complicações ou recaídas precisam de vigilância.","alarm":"Dor de cabeça progressiva, vômitos, mudança de comportamento, pouca alimentação ou alteração dos movimentos são sinais relevantes.","immediate":"Convulsão, alteração de consciência, dificuldade respiratória ou fraqueza nova: emergência imediata.","return":"Após alta, cumpra todas as consultas, exames e etapas do tratamento, com revisão de tolerância e desenvolvimento.","sources":[{"url":"https://medlineplus.gov/ency/article/000650.htm","title":"MedlinePlus — Meningitis, tuberculous","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Meningite viral por Enterovírus","setting":"urgent","general":"Infecção das membranas ao redor do cérebro; enterovírus são causa comum. Exige avaliação médica, pois os sinais podem se sobrepor aos da meningite bacteriana.","diagnosis":"A suspeita exige avaliação imediata para excluir outras meningites. Após diagnóstico e eventual alta, siga repouso, hidratação e retorno programado; lave as mãos cuidadosamente, sobretudo após usar banheiro ou trocar fraldas.","expected":"Casos leves confirmados frequentemente melhoram em cerca de uma semana a dez dias. Recém-nascidos e pessoas imunocomprometidas podem ter doença mais grave; o curso individual depende da avaliação clínica.","alarm":"Emergência se houver dificuldade para acordar, confusão, convulsão, dificuldade respiratória, manchas que não desaparecem à pressão ou piora rápida.","immediate":"Procure pronto atendimento imediatamente diante de suspeita; não espere aparecer uma erupção. Mantenha a criança acompanhada e informe início e evolução dos sintomas.","return":"Retorne imediatamente se houver qualquer alarme ou piora; siga a revisão definida pela equipe após o diagnóstico.","sources":[{"url":"https://www.cdc.gov/meningitis/about/viral-meningitis.html","title":"CDC — About Viral Meningitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Meningoencefalite em Pediatria","aliases":["Meningoencefalite"],"setting":"hospital","general":"Procure emergência hospitalar imediatamente e informe o início dos sintomas, exposições e alterações de comportamento.","diagnosis":"Inflamação das meninges e do cérebro pode ter causas diferentes. Em crianças pequenas, febre e rigidez de nuca podem estar ausentes.","expected":"A evolução depende do agente, da gravidade e do início do cuidado. Não é quadro para observar em casa.","alarm":"Observe sonolência incomum, irritabilidade, vômitos, cefaleia ou confusão.","immediate":"Convulsão, dificuldade para despertar, fraqueza nova ou piora rápida exige assistência imediata.","return":"Após alta, cumpra seguimento neurológico, auditivo e do desenvolvimento conforme as alterações encontradas.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Meningitis_encephalitis/","title":"RCH — Meningitis and encephalitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Micobacteriose Atípica em Pediatria","aliases":[],"setting":"specialist","general":"Não esprema nem drene lesões por conta própria. Leve exames e informe imunossupressão, doença pulmonar, procedimentos e contato com água ou solo.","diagnosis":"Micobactérias não tuberculosas produzem doenças diferentes; confirmar localização e distinguir infecção, colonização e tuberculose antes do plano.","expected":"A recuperação pode ser prolongada e varia com espécie, local, imunidade e estratégia escolhida.","alarm":"Comunique febre persistente, perda de peso, aumento da lesão, secreção ou piora respiratória.","immediate":"Falta de ar, prostração intensa ou deterioração rápida exige atendimento imediato.","return":"Infectologia e especialistas do órgão envolvido devem acompanhar resposta e eventuais efeitos adversos até resolução ou controle.","sources":[{"url":"https://www.bapo.co.uk/wp-content/uploads/2024/05/NTMCL-guideline-BAPO-May-2024-final.pdf","title":"BAPO — NTM cervical lymphadenitis guideline, 2024","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/36764081/","title":"IPOG — Consensus on NTM cervicofacial lymphadenitis, 2023","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/nontuberculous-mycobacteria/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of NTM, 2024","accessed":"2026-09-27"},{"url":"https://clinicalinfo.hiv.gov/es/node/9349","title":"NIH — Mycobacterium avium Complex: Pediatric Opportunistic Infections","accessed":"2026-09-27"},{"url":"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0147513","title":"Tebruegge et al. — NTM disease in children at a tertiary center, 2016","accessed":"2026-09-27"}],"reviewNotes":"BAPO e IPOG divergem na preferência por antibióticos para linfadenite; preservar decisão especializada, sem proibição universal. NIH refere-se a MAC em HIV; não extrapolar sua terapêutica. Rascunho sem homologação humana.","status":"source-reviewed","evidenceSummary":"Consensos pediátricos para linfadenite; CDC cobre formas clínicas; NIH orienta MAC em crianças com HIV. Coorte pediátrica confirma heterogeneidade. Evidência comparativa é limitada e seleção do tratamento permanece individual.","decisionSupport":{"summary":"Selecionar a situação confirmada antes de individualizar as orientações.","requirements":["Local e extensão","Espécie, cultura/PCR e susceptibilidade quando indicadas","Imunidade/HIV e doença pulmonar","Risco cirúrgico e diagnóstico diferencial"],"branchRequired":true,"branches":[{"id":"cervical","label":"Linfadenite cervical localizada","when":"Criança imunocompetente com doença cervical isolada avaliada por especialista.","setting":"specialist","overrides":{"diagnosis":"Discutir observação, excisão e tratamento selecionado; proximidade do nervo facial e extensão alteram a escolha.","expected":"Observação pode exigir muitos meses.","alarm":"Nova febre ou progressão atípica.","immediate":"Dificuldade para respirar ou engolir: urgência.","return":"Acompanhar até resolução clínica."}},{"id":"pulmonary","label":"Doença pulmonar","when":"Sintomas e investigação compatíveis; isolamento respiratório isolado não basta.","setting":"specialist","overrides":{"diagnosis":"Correlacionar culturas, imagem e doença pulmonar prévia com pneumologia/infectologia.","expected":"Resposta e duração variam por espécie.","alarm":"Piora da tosse ou emagrecimento.","immediate":"Dispneia importante ou deterioração rápida: emergência.","return":"Reavaliar sintomas e microbiologia."}},{"id":"localized-extra","label":"Pele, partes moles ou osso","when":"Foco extrapulmonar localizado, sem sinais de disseminação.","setting":"specialist","overrides":{"diagnosis":"Avaliar amostra do foco, extensão e necessidade de procedimento especializado.","expected":"Cicatrização pode ser lenta.","alarm":"Aumento da dor, secreção ou limitação.","immediate":"Febre com deterioração ou progressão rápida: urgência.","return":"Rever ferida e função do membro afetado."}},{"id":"disseminated","label":"Suspeita de disseminação","when":"Febre/perda ponderal sistêmica, múltiplos órgãos ou sítio estéril, sobretudo com imunossupressão.","setting":"hospital","overrides":{"diagnosis":"Investigar extensão e imunidade; envolver infectologia pediátrica.","expected":"Depende também da recuperação imune.","alarm":"Diarreia persistente, anemia ou dor abdominal.","immediate":"Instabilidade ou alteração de consciência: emergência.","return":"Seguimento prolongado após estabilização."}}]},"revisedAt":"2026-09-27"},
{"name":"Micoses Cutâneas na Infância","aliases":["Micoses cutâneas","Micoses superficiais"],"setting":"home","general":"Mantenha a pele limpa e seca e evite compartilhar toalhas, roupas e objetos. Siga o cuidado orientado para a região afetada.","diagnosis":"O local e o tipo de fungo modificam o tratamento. Lesões no couro cabeludo não devem ser tratadas como micose corporal simples.","expected":"A melhora pode exigir semanas; duração e necessidade de revisão variam conforme o diagnóstico e a extensão.","alarm":"Observe expansão das lesões, dor, secreção, perda de cabelo ou falha da melhora.","immediate":"Febre com prostração, vermelhidão dolorosa extensa ou imunossupressão com piora exige avaliação rápida.","return":"Reavalie se não houver resposta, para confirmar o diagnóstico e possíveis fontes de reinfecção.","sources":[{"url":"https://cps.ca/en/documents/position/antifungal-agents-common-infections","title":"Canadian Paediatric Society — Antifungal agents for common outpatient paediatric infections","accessed":"2026-09-26"}],"reviewNotes":"Orientação geral para infecções superficiais; não se aplica à micose invasiva.","status":"source-reviewed"},
{"name":"Micoses superficiais (Tinea capitis)","aliases":["Tinea capitis","Tinha do couro cabeludo"],"setting":"home","general":"Não compartilhe pentes, escovas, bonés, toalhas ou roupas de cama. Higienize esses objetos e procure avaliação se familiares ou animais apresentarem lesões.","diagnosis":"Micose no couro cabeludo costuma exigir tratamento específico por via oral; produto tópico isolado pode ser insuficiente. Não interrompa o esquema apenas porque a coceira melhorou.","expected":"A melhora da pele e o crescimento do cabelo são graduais. Falhas persistentes ou novas lesões exigem reavaliação do diagnóstico e da transmissão.","alarm":"Observe aumento da inflamação, dor, secreção ou áreas muito inchadas no couro cabeludo.","immediate":"Inflamação intensa com febre ou piora geral precisa de avaliação urgente.","return":"Retorne para verificar a resposta e a duração necessária do tratamento. O retorno à escola deve seguir a orientação médica e as regras locais após início do cuidado.","sources":[{"url":"https://www.nhs.uk/conditions/ringworm/","title":"NHS — Ringworm","accessed":"2026-09-26"}],"reviewNotes":"Fonte distingue micose do couro cabeludo das micoses corporais. Síntese documental para revisão médica.","status":"source-reviewed"},
{"name":"Micropênis","aliases":[],"setting":"specialist","general":"Procure endocrinologia ou urologia pediátrica. Evite comparações, constrangimento e uso de hormônios sem indicação especializada.","diagnosis":"O diagnóstico exige medida correta e referência apropriada; pênis embutido pode parecer pequeno sem ser micropênis.","expected":"A evolução depende da causa e da fase de desenvolvimento. O tratamento, quando indicado, deve ser individualizado.","alarm":"Informe alterações testiculares, problemas urinários, crescimento inadequado ou outros sinais hormonais.","immediate":"Dificuldade para urinar ou bebê com pouca resposta e alimentação ruim exige avaliação urgente, sem atribuir tudo ao tamanho peniano.","return":"Mantenha investigação e monitorização de crescimento e puberdade conforme o especialista.","sources":[{"url":"https://www.sbp.com.br/pediatria-para-familias/cuidados-com-a-saude/crescimento-do-penis/","title":"SBP — Crescimento do pênis","accessed":"2026-09-26"}],"reviewNotes":"Usados diagnóstico diferencial e necessidade de avaliação especializada; não reproduz referências métricas potencialmente inconsistentes da página nem doses. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Mielomeningocele","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento multidisciplinar e os cuidados de pele, mobilidade, bexiga e intestino ensinados pela equipe. Uma lesão aberta ao nascimento exige proteção e atendimento hospitalar imediato.","diagnosis":"A mielomeningocele pode comprometer nervos, continência e circulação do líquido cerebral. Cirurgia e reabilitação dependem das alterações presentes; não substituem o seguimento contínuo.","expected":"O desenvolvimento e a autonomia variam conforme o nível da lesão e as complicações. Metas funcionais devem ser revistas durante o crescimento.","alarm":"Observe mudanças na força, continência, pele, tamanho da cabeça, alimentação ou desempenho habitual.","immediate":"Vômitos com sonolência, convulsão, piora neurológica, dificuldade respiratória ou de deglutição exigem emergência, especialmente quando há derivação cerebral.","return":"Mantenha revisões de neurocirurgia, urologia, ortopedia e reabilitação conforme o plano individual.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/myelomeningocele/","title":"Great Ormond Street Hospital — Myelomeningocele","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Miocardite em Pediatria","setting":"hospital","aliases":["Miocardite"],"general":"Inflamação do músculo cardíaco pode comprometer rapidamente o bombeamento e o ritmo do coração.","diagnosis":"A avaliação inicial deve ocorrer em serviço capaz de monitorização cardíaca. Após alta, evite esporte até liberação cardiológica.","expected":"Algumas crianças recuperam a função; outras precisam de suporte prolongado. A melhora dos sintomas não confirma recuperação completa.","alarm":"Palpitações, dor torácica, desmaio, cansaço intenso ou dificuldade alimentar são alarmes.","immediate":"Procure emergência diante de desmaio, falta de ar ou piora súbita.","return":"Cumpra revisões de função cardíaca e ritmo; retome atividades apenas pelo plano definido pela equipe.","sources":[{"url":"https://professional.heart.org/en/science-news/diagnosis-and-management-of-myocarditis-in-children/top-things-to-know","title":"AHA — Diagnosis and Management of Myocarditis in Children","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Miosite infecciosa","aliases":[],"setting":"urgent","general":"Procure avaliação para definir causa e gravidade. Evite exercício intenso e observe capacidade de andar, hidratação e aspecto da urina.","diagnosis":"Miosite infecciosa inclui quadros diferentes: dor muscular após virose não é equivalente a infecção bacteriana com abscesso. O tratamento depende dessa distinção.","expected":"Formas virais benignas podem melhorar em poucos dias; formas bacterianas podem exigir internação e procedimentos, sem prazo único de recuperação.","alarm":"Febre persistente, dor localizada crescente, inchaço, fraqueza ou recusa de andar precisam de revisão.","immediate":"Urina escura com pouca urina, prostração, falta de ar ou dor intensa desproporcional exige urgência.","return":"Retorne no prazo definido e para controle de exames quando indicados; não retome atividade vigorosa antes da melhora.","sources":[{"url":"https://pubmed.ncbi.nlm.nih.gov/40994529/","title":"Alghamdi et al. 2025 — Benign acute childhood myositis: retrospective cohort","accessed":"2026-09-26"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11319086/","title":"Weber et al. 2024 — Children and Adolescents Hospitalized With Pyomyositis","accessed":"2026-09-26"}],"reviewNotes":"Fontes pediátricas distintas para miosite viral benigna e miosite bacteriana/piomiosite. Orientação de triagem condicional; exige definir etiologia antes de qualquer plano terapêutico.","status":"source-reviewed"},
{"name":"Miosite Viral Aguda","aliases":["Miosite viral","Miosite aguda benigna da infância"],"setting":"home","general":"Após confirmação de quadro benigno, ofereça hidratação e repouso relativo. Não force caminhada ou exercício doloroso; observe urina e recuperação da mobilidade.","diagnosis":"Dor nas panturrilhas após virose pode corresponder a miosite, mas fraqueza verdadeira e outras causas de dificuldade para andar precisam ser excluídas.","expected":"A maioria dos quadros típicos melhora espontaneamente; duração e necessidade de exames dependem da avaliação.","alarm":"Dor crescente, pouca ingestão ou dificuldade persistente para caminhar exigem revisão.","immediate":"Urina escura ou reduzida, fraqueza progressiva ou prostração exigem atendimento imediato.","return":"Retorne conforme combinado, especialmente se não houver melhora ou se ocorrerem novos episódios.","sources":[{"url":"https://www.frontiersin.org/journals/pediatrics/articles/10.3389/fped.2025.1653651/full","title":"Frontiers in Pediatrics — Benign acute childhood myositis: retrospective cohort study, 2025","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Coorte primária de crianças com miosite benigna: não demonstra benignidade de toda dor muscular nem exclui rabdomiólise individualmente.","status":"source-reviewed"},
{"name":"Molusco contagioso","aliases":[],"setting":"home","general":"Evite coçar, espremer ou retirar as lesões. Lave as mãos, não compartilhe toalhas e mantenha as áreas cobertas quando houver contato próximo ou atividades que favoreçam a transmissão.","diagnosis":"Molusco é uma infecção viral da pele. Crianças saudáveis muitas vezes podem apenas ser acompanhadas; lesões genitais, imunidade reduzida ou dúvidas diagnósticas exigem avaliação específica.","expected":"As lesões geralmente desaparecem ao longo de meses, às vezes mais de um ano. O aparecimento de novas lesões não significa necessariamente falha de tratamento.","alarm":"Vermelhidão progressiva, dor, pus ou coceira intensa precisam de revisão para avaliar complicações.","immediate":"Febre com lesão rapidamente progressiva, prostração ou importante comprometimento ocular: atendimento imediato.","return":"Retorne se houver complicações, muitas lesões ou sofrimento; confirme com o pediatra os cuidados em escola e piscina.","sources":[{"url":"https://www.cdc.gov/molluscum-contagiosum/about/index.html","title":"CDC — About Molluscum Contagiosum","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Monilíase em Pediatria","setting":"home","aliases":["Candidíase mucocutânea","Sapinho"],"general":"Monilíase precisa ser localizada: boca e área da fralda exigem cuidados distintos; não equivale automaticamente a infecção invasiva.","diagnosis":"Mantenha higiene dos objetos usados na alimentação e cuidados suaves da fralda. Não raspe placas da boca nem aplique produtos caseiros.","expected":"Quadros superficiais costumam responder ao cuidado dirigido; recorrência ou persistência pede revisão do diagnóstico.","alarm":"Dor que impede alimentação, lesões extensas ou repetidas precisam de avaliação.","immediate":"Bebê com febre, prostração ou incapacidade de beber deve ir à urgência.","return":"Retorne se não melhorar com o plano ou se houver recorrências frequentes.","sources":[{"url":"https://cps.ca/en/documents/position/antifungal-agents-common-infections","title":"Canadian Paediatric Society — Antifungal agents for common outpatient paediatric infections","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Escopo: candidíase mucocutânea da boca e área da fralda em criança estável. Não representa candidemia ou infecção sistêmica; recorrência/extensão exige investigação. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Mononucleose infecciosa (EBV)","setting":"home","general":"Doença geralmente causada pelo vírus Epstein-Barr e transmitida pela saliva. Avaliação é necessária para distinguir outras causas de febre e dor de garganta.","diagnosis":"Priorize repouso e líquidos e evite compartilhar utensílios ou contato com saliva. Suspenda esportes de contato, esforço intenso e atividades com impacto até liberação profissional, pelo risco relacionado ao baço.","expected":"Cansaço pode persistir após os demais sintomas. Repouso, líquidos e alimentação conforme tolerância ajudam; evite compartilhar utensílios e contato com saliva.","alarm":"Procure urgência para dificuldade de respirar ou engolir, dor abdominal intensa, desmaio, confusão ou incapacidade de manter líquidos.","immediate":"Busque avaliação se os sintomas forem intensos ou persistentes. Evite esportes e atividades com risco de impacto enquanto a equipe orientar, por possível aumento do baço.","return":"Retorne se piorar, desidratar ou surgirem sinais de alarme; confirme com o profissional quando retomar atividades físicas.","sources":[{"url":"https://www.nhs.uk/conditions/glandular-fever/","title":"NHS — Glandular fever","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Mononucleose Infecciosa em Pediatria","aliases":[],"setting":"home","general":"Ofereça líquidos em pequenas quantidades, descanso conforme tolerância e evite compartilhar copos ou objetos com saliva.","diagnosis":"Confirmar se o quadro é mononucleose por EBV, outra infecção ou síndrome ainda não esclarecida; teste heterófilo negativo não exclui EBV em crianças.","expected":"Na forma habitual por EBV, a melhora costuma ocorrer em semanas; cansaço pode durar mais.","alarm":"Dor ao engolir com redução da ingestão, febre persistente, icterícia ou piora geral exigem reavaliação.","immediate":"Incapacidade de engolir saliva, dificuldade respiratória importante ou dor abdominal intensa exige emergência.","return":"Reavaliar evolução e retorno às atividades. Evitar esportes de contato e esforço intenso até liberação clínica pelo risco esplênico.","sources":[{"url":"https://www.cdc.gov/epstein-barr/about/mononucleosis.html","title":"CDC — About Infectious Mononucleosis, 2024","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/epstein-barr/php/laboratories/index.html","title":"CDC — Laboratory Testing for EBV, 2024","accessed":"2026-09-27"},{"url":"https://www.nhs.uk/conditions/glandular-fever/","title":"NHS — Glandular fever","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/cytomegalovirus/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of CMV, 2024","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD004402_steroids-short-term-symptom-control-infectious-mononucleosis-glandular-fever","title":"Cochrane CD004402 — Steroids for infectious mononucleosis","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD011487_antiviral-medication-treatment-infectious-mononucleosis-glandular-fever","title":"Cochrane CD011487 — Antiviral medication for infectious mononucleosis","accessed":"2026-09-27"}],"reviewNotes":"Especificar etiologia e imunidade. As revisões não sustentam tratamento adicional rotineiro do EBV não complicado; doença grave tem avaliação própria. Não atribuir duração do EBV a todas as causas. Sem homologação humana.","status":"source-reviewed","evidenceSummary":"CDC/NHS orientam reconhecimento, testes e cuidados; Cochrane encontrou evidência insuficiente ou incerta para benefício rotineiro de esteroides/antivirais. Estudos heterogêneos, predominantemente adolescentes/adultos jovens, não representam todos os subtipos pediátricos.","decisionSupport":{"summary":"Selecionar a situação confirmada antes de individualizar as orientações.","requirements":["Idade, duração e imunidade","EBV provável/confirmado ou causa alternativa","Deglutição, hidratação, baço e fígado","Complicações e intenção de retomar esporte"],"branchRequired":true,"branches":[{"id":"ebv-uncomplicated","label":"EBV não complicado","when":"Avaliação compatível com EBV, boa hidratação e ausência de comprometimento importante.","setting":"home","overrides":{"diagnosis":"Manter suporte; antibiótico não trata o EBV e tratamento adicional não é automático.","expected":"Melhora habitual em 2–4 semanas, com fadiga possivelmente mais longa.","alarm":"Piora da ingestão ou icterícia.","immediate":"Dor abdominal intensa ou falta de ar: emergência.","return":"Rever se não melhorar ou antes do esporte."}},{"id":"other-or-uncertain","label":"CMV ou etiologia não esclarecida","when":"EBV não estabelecido, apresentação atípica ou investigação aponta outra causa.","setting":"specialist","overrides":{"diagnosis":"Investigar conforme história/exposições; CMV adquirido em imunocompetente costuma requerer suporte.","expected":"Depende da causa confirmada.","alarm":"Febre prolongada ou novos órgãos acometidos.","immediate":"Deterioração clínica exige atendimento imediato.","return":"Revisar resultados e sintomas persistentes."}},{"id":"complicated","label":"Imunossupressão ou complicação","when":"Imunodeficiência, transplante ou comprometimento respiratório, hematológico ou visceral relevante.","setting":"hospital","overrides":{"diagnosis":"Avaliação hospitalar e infectológica; não aplicar plano domiciliar da forma habitual.","expected":"Depende do órgão afetado e da imunidade.","alarm":"Sangramento, icterícia progressiva ou prostração.","immediate":"Obstrução respiratória ou alteração de consciência: emergência.","return":"Seguimento definido após estabilização."}}]},"revisedAt":"2026-09-27"},
{"name":"Náusea e Vômito Induzidos por QT Infantil","aliases":["Náusea e vômito induzidos por quimioterapia infantil"],"setting":"specialist","general":"Siga o plano preventivo da oncologia, ofereça pequenas refeições e líquidos conforme tolerância e reduza odores que desencadeiam náusea.","diagnosis":"A náusea pode ocorrer durante ou depois da quimioterapia; sintomas novos também precisam de avaliação de outras causas.","expected":"A intensidade varia conforme o tratamento; o controle pode exigir ajustes, sem garantir ausência completa de sintomas.","alarm":"Registre vômitos, ingestão e urina; comunique dificuldade para manter líquidos ou tratamentos orais.","immediate":"Vômitos persistentes com desidratação, sangue ou prostração exigem contato imediato com a equipe ou pronto atendimento.","return":"Reavalie o plano antes do próximo ciclo e diante de controle insuficiente.","sources":[{"url":"https://www.cancer.gov/about-cancer/treatment/side-effects/nausea-vomiting","title":"NCI — Nausea and Vomiting and Cancer Treatment","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. QT significa quimioterapia neste título; não síndrome do QT cardíaco.","status":"source-reviewed"},
{"name":"Neuroblastoma retroperitoneal","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento em oncologia pediátrica e leve exames anteriores. Comunique aumento abdominal, dor, alterações para caminhar, evacuar ou urinar.","diagnosis":"A localização atrás do abdome não define sozinha o risco. A avaliação precisa considerar extensão, idade e características biológicas do tumor.","expected":"A evolução é muito variável. A necessidade e a intensidade do tratamento dependem da classificação individual e da resposta, sem previsão única de cura.","alarm":"Observe dor crescente, barriga mais volumosa, dificuldade respiratória, fraqueza, sangramentos ou perda importante de disposição.","immediate":"Fraqueza súbita ou paralisia, dificuldade respiratória ou rápida deterioração exige atendimento imediato, com contato com a oncologia.","return":"Cumpra o calendário de exames mesmo com melhora. Durante tratamento, siga o plano de urgência da equipe para febre e outros sintomas novos.","sources":[{"url":"https://www.cancer.gov/types/neuroblastoma/patient/neuroblastoma-treatment-pdq","title":"NCI — Neuroblastoma treatment","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Neurofibromatose tipo 1","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento regular e registre alterações na pele, visão, aprendizagem e desenvolvimento. Compartilhe com a escola as necessidades de apoio identificadas.","diagnosis":"A neurofibromatose tipo 1 pode afetar diferentes órgãos, com intensidade muito variável. Manchas isoladas não permitem prever todas as manifestações futuras.","expected":"Muitas pessoas têm manifestações leves, mas novos problemas podem surgir durante o crescimento. A vigilância permite identificar complicações sem presumir que todas ocorrerão.","alarm":"Dor persistente, crescimento rápido de um nódulo, mudança da consistência, dificuldade escolar nova ou alteração visual precisam de avaliação.","immediate":"Perda visual súbita, convulsão, fraqueza nova ou dor de cabeça intensa com vômitos exigem emergência.","return":"Cumpra as avaliações periódicas, incluindo visão e pressão arterial; procure revisão antecipada se houver mudança importante.","sources":[{"url":"https://www.nhs.uk/conditions/neurofibromatosis-type-1/","title":"NHS — Neurofibromatosis type 1","accessed":"2026-09-26"},{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK1109/","title":"GeneReviews — Neurofibromatosis 1","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Neutropenia congênita grave","aliases":[],"setting":"specialist","general":"Mantenha seguimento hematológico e o plano para febre sempre acessível. Cuide da higiene das mãos, boca e pele e comunique infecções precocemente.","diagnosis":"A baixa quantidade de neutrófilos favorece infecções desde a infância. Mesmo sintomas discretos podem precisar de avaliação rápida.","expected":"O cuidado costuma ser prolongado, com controle de infecções e monitorização da medula e de outras complicações.","alarm":"Observe febre, calafrios, feridas na boca, dor de garganta, tosse e lesões de pele.","immediate":"Febre ou suspeita de infecção deve motivar contato urgente conforme o plano; prostração, falta de ar ou alteração de consciência exige emergência.","return":"Retorne para hemogramas e revisões programadas, mesmo quando bem. Não ajuste tratamento nem use antibióticos remanescentes por conta própria.","sources":[{"url":"https://medlineplus.gov/genetics/condition/severe-congenital-neutropenia/","title":"MedlinePlus — Severe congenital neutropenia","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Neutropenia Febril em Pediatria","setting":"hospital","aliases":["Neutropenia febril"],"general":"Febre em criança com neutropenia conhecida ou possível é emergência, mesmo sem aparência de doença grave.","diagnosis":"Procure imediatamente o serviço indicado pela oncologia ou hematologia. Leve o cartão de tratamento e informe a última terapia recebida.","expected":"A evolução depende do agente infeccioso e da recuperação das defesas; a avaliação não deve aguardar exames ambulatoriais.","alarm":"Calafrios, prostração, dor, dificuldade respiratória ou mudanças no acesso venoso aumentam a preocupação.","immediate":"Acione emergência diante de confusão, desmaio ou dificuldade respiratória; não espere a febre baixar.","return":"Retorno e alta dependem da equipe responsável, com plano explícito para nova febre.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Febrile_Neutropenia/","title":"RCH — Fever and suspected or confirmed neutropenia","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Obesidade infantojuvenil","aliases":[],"setting":"specialist","general":"Envolva a família em hábitos sustentáveis: alimentação variada, atividade prazerosa, sono regular e redução de bebidas açucaradas. Evite punições, comentários humilhantes e dietas restritivas sem acompanhamento.","diagnosis":"O peso infantil deve ser interpretado com idade, crescimento e contexto clínico. A avaliação busca saúde e desenvolvimento, incluindo possíveis condições associadas, sem reduzir a criança a um número.","expected":"Mudanças consistentes levam tempo. As metas são individualizadas e podem envolver melhorar a trajetória de crescimento, sem exigir perda rápida de peso.","alarm":"Ronco importante, dificuldade para atividades, dor persistente ou sofrimento emocional merecem avaliação.","immediate":"Falta de ar intensa, desmaio, dor no peito ou risco imediato de autoagressão: atendimento urgente.","return":"Mantenha acompanhamento pediátrico e nutricional para revisar metas, crescimento e bem-estar; evite comparações com outras crianças.","sources":[{"url":"https://www.nhs.uk/live-well/healthy-weight/childrens-weight/advice-for-parents-overweight-children/","title":"NHS — Advice for parents of overweight children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Onfalite","setting":"urgent","general":"Infecção do umbigo e da pele ao redor, especialmente importante em recém-nascidos. É potencialmente grave e requer avaliação presencial urgente.","diagnosis":"Mantenha o umbigo limpo e seco, sem espremer ou aplicar substâncias caseiras. Procure avaliação no mesmo dia; a presença de vermelhidão que se espalha ou bebê abatido aumenta a urgência.","expected":"A resposta depende da extensão da infecção e do estado do bebê. Quadros selecionados podem seguir cuidado ambulatorial após avaliação, mas infecção disseminada exige internação e monitorização.","alarm":"Febre ou temperatura baixa, prostração, dificuldade para mamar, respiração anormal, pele pálida/manchada, vermelhidão que se espalha ou piora são alarmes.","immediate":"Leve o recém-nascido ao pronto atendimento imediatamente. Não aplique substâncias no umbigo nem tente espremer secreção; mantenha-o limpo e seco até ser avaliado.","return":"Reavalie conforme a equipe; retorne imediatamente diante de piora ou qualquer alarme. Não use instruções de alta sem plano profissional.","sources":[{"url":"https://www.kingstonandrichmond.nhs.uk/services/healthcare-professionals/how-refer/paediatric-referrals/umbilical-disorders-children","title":"NHS Kingston and Richmond — Umbilical disorders in children","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Onfalocele e Gastrosquise","setting":"hospital","aliases":["Onfalocele","Gastrosquise"],"general":"São defeitos distintos da parede abdominal que exigem assistência neonatal e cirúrgica especializada.","diagnosis":"Não pressione ou tente recolocar órgãos expostos. Alimentação e proteção da região devem seguir a equipe; o tratamento depende do defeito e de condições associadas.","expected":"A recuperação intestinal pode ser lenta, com suporte nutricional temporário e internação prolongada.","alarm":"Vômitos verdes, distensão, alteração de cor da região ou piora geral são alarmes.","immediate":"No nascimento, solicite assistência hospitalar imediata; após alta, vômito verde exige urgência.","return":"Mantenha cirurgia pediátrica e revisões de alimentação, crescimento e complicações.","sources":[{"url":"https://www.evelinalondon.nhs.uk/resources/patient-information/gastroschisis-and-exomphalos.pdf","title":"Evelina London — Gastroschisis and exomphalos","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Osteogênese imperfeita tipo I","aliases":["Osteogênese imperfeita leve"],"setting":"specialist","general":"Combine atividades e exercícios com a equipe de reabilitação. Adapte o ambiente para reduzir quedas e aprenda formas seguras de apoiar e transportar a criança.","diagnosis":"O tipo I costuma ser mais leve, mas ainda pode causar fraturas com pequenos traumas. Imobilidade desnecessária também prejudica força e autonomia.","expected":"A condição é duradoura e variável. O cuidado busca diminuir fraturas, preservar mobilidade e acompanhar possíveis alterações de coluna, dentes e audição.","alarm":"Observe dor nova, inchaço, deformidade, recusa para apoiar um membro ou redução da capacidade habitual.","immediate":"Dor intensa após trauma, deformidade importante, perda de movimento ou dificuldade respiratória exige atendimento imediato.","return":"Mantenha consultas ortopédicas e de reabilitação. Solicite avaliação precoce de suspeita de fratura e siga o plano individual de recuperação das atividades.","sources":[{"url":"https://www.niams.nih.gov/health-topics/osteogenesis-imperfecta","title":"NIAMS — Osteogenesis imperfecta: types and symptoms","accessed":"2026-09-26"},{"url":"https://www.niams.nih.gov/health-topics/osteogenesis-imperfecta/diagnosis-treatment-and-steps-to-take","title":"NIAMS — Osteogenesis imperfecta: diagnosis, treatment and steps to take","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Osteomielite aguda do fêmur","aliases":[],"setting":"hospital","general":"A suspeita de infecção do fêmur exige avaliação urgente. Evite forçar apoio ou caminhada e informe febre, duração da dor, traumas e tratamentos prévios.","diagnosis":"A osteomielite pode acompanhar infecção articular ou formar coleção. O tratamento depende de exames, agente provável e necessidade de procedimento, frequentemente com acompanhamento hospitalar inicial.","expected":"A dor, a febre e a capacidade de movimentar devem melhorar com o tratamento adequado, mas a duração é individual e pode ser prolongada.","alarm":"Persistência da febre, dor crescente, inchaço ou recusa para usar o membro precisam de revisão.","immediate":"Prostração intensa, confusão, dificuldade respiratória, extremidades frias ou piora rápida exigem emergência imediata.","return":"Após alta formal, complete o plano prescrito e mantenha controle de resposta, mobilidade e possíveis alterações de crescimento.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Bone_and_joint_infection/","title":"RCH — Bone and joint infection","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Osteomielite crônica","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com ortopedia e infectologia e siga o tratamento completo. Respeite orientações de apoio do membro e cuidados da ferida.","diagnosis":"A infecção óssea crônica pode exigir exames, cultura e procedimentos além de medicamento. Não esprema fístulas nem tente drenar secreções em casa.","expected":"A recuperação pode ser longa e ocorrer recaída; melhora da dor não garante resolução da infecção.","alarm":"Observe retorno de febre, secreção, vermelhidão, dor crescente ou dificuldade de movimentar o membro.","immediate":"Prostração importante, falta de ar, dor intensa ou piora rápida do inchaço exige atendimento imediato.","return":"Retorne nas datas combinadas e antes se houver novos sintomas; leve resultados, histórico de cirurgias e tratamentos anteriores.","sources":[{"url":"https://www.nhs.uk/conditions/osteomyelitis/","title":"NHS — Osteomyelitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte inclui infecção persistente com dano ósseo; duração terapêutica e necessidade cirúrgica não foram generalizadas.","status":"source-reviewed"},
{"name":"Osteomielite em Pediatria","aliases":["Osteomielite"],"setting":"urgent","general":"Procure avaliação urgente para dor óssea, febre ou recusa de apoiar o membro. Não force movimentos.","diagnosis":"A infecção óssea pode ocorrer sem febre, especialmente nos pequenos; exames orientam a extensão.","expected":"A recuperação depende do foco, agente e resposta ao tratamento; alguns casos exigem procedimento.","alarm":"Observe inchaço, dor crescente ou perda de movimento.","immediate":"Prostração, alteração da consciência ou piora rápida exige emergência.","return":"Cumpra o acompanhamento e tratamento completos. Retorno à atividade deve considerar dor, função e orientação da equipe.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Bone_and_joint_infection/","title":"RCH — Bone and joint infection","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Osteoporose em Pediatria","aliases":["Osteoporose"],"setting":"specialist","general":"Converse com a equipe sobre atividade segura, nutrição e prevenção de quedas. Não restrinja toda atividade nem inicie suplementos por conta própria.","diagnosis":"O diagnóstico infantil considera fraturas e contexto clínico; um resultado isolado de densitometria não basta.","expected":"A saúde óssea depende do crescimento e da causa da fragilidade. O acompanhamento avalia fraturas, dor e evolução.","alarm":"Relate dor nas costas, perda de altura, limitação funcional ou fratura após trauma pequeno.","immediate":"Dor intensa, deformidade ou incapacidade de apoiar um membro exigem avaliação imediata.","return":"Mantenha seguimento especializado; exames repetidos devem ser indicados conforme risco e utilidade clínica.","sources":[{"url":"https://iscd.org/text-pediatric-positions/","title":"ISCD — Official Pediatric Positions","accessed":"2026-09-26"},{"url":"https://www.chop.edu/conditions-diseases/juvenile-osteoporosis","title":"CHOP — Juvenile Osteoporosis","accessed":"2026-09-26"}],"reviewNotes":"ISCD fundamenta critérios pediátricos; CHOP2026 complementa sintomas, prevenção de fraturas, atividade e nutrição individualizadas.","status":"source-reviewed"},
{"name":"Osteossarcoma","aliases":[],"setting":"specialist","general":"Mantenha atendimento em centro oncológico e siga as restrições de apoio e atividade do membro afetado. Evite impacto e leve exames, laudos e lista de tratamentos às consultas.","diagnosis":"O osteossarcoma necessita definição de extensão e plano especializado, que pode incluir tratamento sistêmico e cirurgia. Dor óssea persistente não deve ser atribuída apenas ao crescimento.","expected":"O prognóstico depende de localização, disseminação, possibilidade de tratamento e resposta. A reabilitação e o acompanhamento continuam após o tratamento, sem prazo único de recuperação.","alarm":"Aumento de dor ou volume, limitação nova, febre durante tratamento ou dificuldade de manter alimentação exigem contato rápido.","immediate":"Dor súbita com incapacidade de apoiar, falta de ar, sangramento importante ou prostração: emergência.","return":"Cumpra revisões, exames e reabilitação; sintomas novos precisam ser relatados mesmo entre consultas.","sources":[{"url":"https://www.cancer.gov/types/bone/patient/osteosarcoma-treatment-pdq","title":"National Cancer Institute — Osteosarcoma Treatment, Patient Version","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Otite média aguda","setting":"home","general":"Infecção atrás do tímpano, frequentemente após resfriado, causando dor e às vezes febre. Crianças pequenas devem ser examinadas para confirmar o diagnóstico.","diagnosis":"Siga o plano de conforto e tratamento definido após exame. Não introduza objetos no ouvido nem aplique produtos sem orientação; observe alimentação, sono e sinais atrás da orelha.","expected":"Muitos casos começam a melhorar em poucos dias, embora desconforto ou audição abafada possam persistir. Falta de melhora em cerca de três dias ou piora requer reavaliação.","alarm":"Procure urgência se houver inchaço ou vermelhidão atrás da orelha, orelha projetada, rigidez de nuca, sonolência intensa, piora importante ou criança muito doente.","immediate":"Solicite avaliação se dor ou febre forem importantes, se a criança for muito pequena ou se houver secreção. Não introduza objetos no ouvido.","return":"Retorne se não melhorar, piorar, houver secreção persistente ou alteração auditiva; cumpra a revisão indicada pelo profissional.","sources":[{"url":"https://www.nhs.uk/conditions/ear-infections/","title":"NHS — Ear infections","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Otite Média na Criança","setting":"home","aliases":["Otite média"],"general":"Dor de ouvido precisa de exame para distinguir infecção aguda de líquido residual sem infecção.","diagnosis":"Siga o plano de conforto e cuidado prescrito; não introduza objetos ou aplique produtos sem orientação.","expected":"Muitos quadros agudos melhoram espontaneamente; alteração auditiva por líquido pode durar mais e precisa de seguimento se persistente.","alarm":"Inchaço atrás da orelha, orelha projetada, secreção ou criança muito abatida exigem avaliação.","immediate":"Rigidez de nuca, sonolência intensa ou piora rápida requerem emergência.","return":"Retorne se não melhorar no prazo orientado, se piorar ou se persistir dificuldade auditiva.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Acute_otitis_media/","title":"RCH — Acute otitis media","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Capítulo inclui distinção entre otite média aguda e efusão. Não são sinônimos terapêuticos; instruções e acompanhamento devem respeitar o diagnóstico confirmado. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Pan-hipopituitarismo","aliases":["Panhipopituitarismo"],"setting":"specialist","general":"Mantenha reposições e exames exatamente conforme endocrinologia. Leve identificação do diagnóstico e um plano escrito para doenças, vômitos, cirurgias e emergências.","diagnosis":"A falta de vários hormônios pode comprometer crescimento, puberdade, glicose e resposta ao estresse. A reposição depende das deficiências demonstradas.","expected":"O acompanhamento costuma ser prolongado, com ajustes durante o crescimento. A evolução depende da causa e de outras alterações associadas.","alarm":"Observe fraqueza acentuada, vômitos, pouca alimentação, sonolência incomum ou sinais de glicose baixa.","immediate":"Desmaio, convulsão, dificuldade para despertar ou incapacidade de manter a reposição oral em quem tem deficiência de cortisol exige emergência e aplicação do plano previamente ensinado.","return":"Avise a equipe durante intercorrências e mantenha revisões de crescimento e hormônios. Não suspenda reposição por melhora aparente.","sources":[{"url":"https://medlineplus.gov/genetics/condition/combined-pituitary-hormone-deficiency/","title":"MedlinePlus Genetics — Combined pituitary hormone deficiency","accessed":"2026-09-26"},{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/medicines-information/medicines-directory/emergency-pack-children-cortisol-deficiency/","title":"GOSH — Emergency pack for children with cortisol deficiency","accessed":"2026-09-26"}],"reviewNotes":"Deficiência combinada pode ser congênita ou adquirida; alerta de crise condicionado à deficiência de cortisol. Síntese para revisão médica.","status":"source-reviewed"},
{"name":"Panarício herpético","aliases":[],"setting":"home","general":"Após confirmação médica, mantenha a lesão limpa e coberta. Não fure, esprema ou tente drenar as bolhas e lave as mãos após tocar no curativo.","diagnosis":"O panarício herpético é viral e pode transmitir herpes pelo contato. Evite tocar olhos e outras pessoas com o dedo afetado, sobretudo recém-nascidos.","expected":"O episódio costuma melhorar em duas a três semanas, mas pode voltar. O tratamento e o momento de iniciá-lo dependem da avaliação clínica.","alarm":"Dor ou inchaço crescentes, febre, secreção diferente ou lesões que não melhoram exigem reavaliação; imunodeficiência requer atenção adicional.","immediate":"Comprometimento dos olhos, disseminação importante ou prostração com febre exigem avaliação urgente.","return":"Retorne se a evolução não for favorável ou houver recorrências; não confunda com abscesso bacteriano que necessita outra abordagem.","sources":[{"url":"https://www.nhs.uk/conditions/herpetic-whitlow/","title":"NHS — Herpetic whitlow","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"PAPA","aliases":["Síndrome PAPA"],"setting":"specialist","general":"Mantenha seguimento com reumatologia e dermatologia. Registre crises articulares e alterações da pele para discutir com a equipe.","diagnosis":"PAPA é uma síndrome inflamatória rara, associada a artrite e lesões cutâneas; não se confirma apenas pela aparência de pus.","expected":"As crises podem reaparecer e o controle é individual. Estudos pequenos não permitem garantir resposta ou prazo de remissão.","alarm":"Relate articulação quente e dolorosa, dificuldade para andar e feridas progressivas.","immediate":"Febre com prostração ou dor articular intensa exige avaliação urgente para excluir infecção, mesmo com diagnóstico prévio.","return":"Combine seguimento da atividade inflamatória, mobilidade, pele e segurança do tratamento.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4599684/","title":"Finetti et al. — Long-term efficacy of IL-1 blockers in PAPA patients","accessed":"2026-09-26"}],"reviewNotes":"Série pequena; não fundamenta tratamento universal. Preservada necessidade de excluir infecção.","status":"source-reviewed"},
{"name":"Paracoccidioidomicose em Pediatria","aliases":[],"setting":"specialist","general":"Complete o tratamento e mantenha avaliação nutricional e clínica; evite exposição a poeira de solo e escavações.","diagnosis":"A forma juvenil pode progredir com gânglios aumentados e acometimento de vários órgãos; não se transmite entre pessoas.","expected":"O tratamento é prolongado, frequentemente por meses, e depende da gravidade; sequelas e recaídas exigem acompanhamento.","alarm":"Informe febre persistente, emagrecimento, aumento abdominal, gânglios com secreção ou piora da alimentação.","immediate":"Falta de ar, alteração de consciência, sangramento ou deterioração acentuada exigem atendimento hospitalar.","return":"Mantenha os controles até critérios de resposta definidos pela equipe e o seguimento posterior.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/p/pcm","title":"Ministério da Saúde — Paracoccidioidomicose","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/p/pcm/tratamento","title":"Ministério da Saúde — Tratamento da paracoccidioidomicose","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Paracoccidioidomicose forma juvenil","aliases":[],"setting":"urgent","general":"Procure serviço especializado sem demora e mantenha alimentação e acompanhamento nutricional. Informe exposições a solo e atividades rurais.","diagnosis":"A forma juvenil pode progredir rapidamente e afetar gânglios, fígado, baço, intestino e outros órgãos; requer avaliação da extensão da doença.","expected":"A evolução depende dos órgãos afetados e da resposta ao tratamento, que precisa de seguimento prolongado.","alarm":"Observe perda de peso, febre persistente, aumento de gânglios, distensão da barriga e dificuldade de se alimentar.","immediate":"Falta de ar, prostração, sangramento, dor abdominal intensa ou alteração de consciência exige emergência.","return":"Retorne para monitorar resposta e tolerância ao tratamento; não interrompa por melhora inicial e não trate lesões isoladamente sem o plano sistêmico.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/p/pcm","title":"Ministério da Saúde — Paracoccidioidomicose","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Paralisia cerebral discinética","aliases":[],"setting":"specialist","general":"Mantenha a rotina de reabilitação, posicionamento e comunicação indicada para a criança. Adapte atividades e alimentação às habilidades e ao plano da equipe, respeitando conforto e participação.","diagnosis":"Na forma discinética, movimentos involuntários e variações do tônus podem interferir na postura e nas tarefas. As necessidades são individuais; não presuma deficiência intelectual pelo padrão motor.","expected":"O acompanhamento é contínuo e pode precisar de ajustes durante o crescimento. Ganhos funcionais variam; perda de habilidades ou piora súbita precisa de investigação.","alarm":"Engasgos, dificuldade alimentar, dor, mudanças no sono ou movimentos que impeçam cuidados devem ser comunicados.","immediate":"Dificuldade respiratória, convulsão prolongada, pouca resposta ou incapacidade de engolir: emergência.","return":"Mantenha seguimento multidisciplinar e antecipe a consulta diante de novas limitações, dor ou dificuldade para nutrir.","sources":[{"url":"https://www.nhs.uk/conditions/cerebral-palsy/symptoms/","title":"NHS — Cerebral palsy: symptoms","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Paralisia cerebral espástica diplégica","setting":"specialist","general":"Forma de paralisia cerebral em que a espasticidade afeta sobretudo as pernas, interferindo no movimento e na postura. Não é uma infecção contagiosa.","diagnosis":"Siga o plano de reabilitação e adaptações que favoreçam participação e autonomia. Observe conforto, pele e mobilidade; órteses e alongamentos devem ser individualizados, sem forçar movimentos dolorosos.","expected":"A lesão cerebral não progride, mas suas repercussões podem mudar com crescimento. Habilidades e necessidades variam; acompanhamento de mobilidade, quadris, alimentação e comunicação deve ser contínuo.","alarm":"Procure avaliação urgente para perda súbita de habilidades, convulsão prolongada, dificuldade respiratória, engasgos recorrentes ou dor intensa nova.","immediate":"Marque avaliação com pediatria especializada e reabilitação; promova participação segura e siga o plano individual, sem forçar movimentos dolorosos.","return":"Mantenha acompanhamentos regulares e retorne se surgirem novas dificuldades de mobilidade, alimentação, comunicação, sono ou dor.","sources":[{"url":"https://www.cdc.gov/cerebral-palsy/about/index.html","title":"CDC — About Cerebral Palsy","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Paralisia cerebral espástica quadriplégica","aliases":["Paralisia cerebral espástica tetraplégica"],"setting":"specialist","general":"Siga um plano individual de posicionamento, mobilidade, comunicação, alimentação e cuidados diários. Peça treinamento para transferências e para os equipamentos utilizados.","diagnosis":"O comprometimento dos quatro membros pode exigir apoio amplo, mas as habilidades e necessidades variam. Engasgos ou dificuldades alimentares precisam de avaliação específica.","expected":"O cuidado é contínuo e busca conforto, participação e autonomia possível. As necessidades mudam com o crescimento, sem prazo único de recuperação.","alarm":"Observe dor nova, piora da rigidez, redução da mobilidade, engasgos, perda de peso ou tosse durante as refeições.","immediate":"Dificuldade respiratória, engasgo com mudança de cor ou redução importante da resposta exige emergência.","return":"Mantenha seguimento multidisciplinar e reavalie dor, nutrição, sono e equipamentos. Não atribua automaticamente sintomas novos à paralisia cerebral.","sources":[{"url":"https://www.nhs.uk/conditions/cerebral-palsy/treatment/","title":"NHS — Cerebral palsy: treatment","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Paralisia de Bell","setting":"urgent","aliases":["Paralisia facial periférica de Bell"],"general":"Fraqueza súbita de um lado do rosto precisa de avaliação para excluir outras causas.","diagnosis":"Se o olho não fechar, siga imediatamente o plano de proteção ocular dado pela equipe; evite ressecamento e lesão.","expected":"A maioria das crianças recupera-se, por vezes ao longo de meses; a recuperação não é igual em todos os casos.","alarm":"Dor intensa, alteração visual, fraqueza de membros ou outros sintomas neurológicos são alarmes.","immediate":"Fraqueza fora do rosto, fala alterada ou redução de consciência requerem emergência.","return":"Mantenha revisão da função facial e do olho; retorne antes se houver piora ou ausência da evolução esperada.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Facial_weakness_and_Bells_palsy/","title":"RCH — Facial weakness and Bell palsy","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Paralisia do plexo braquial neonatal","aliases":[],"setting":"specialist","general":"Proteja e apoie o braço afetado ao carregar o bebê. Não puxe o membro e realize somente os movimentos e posicionamentos ensinados pela fisioterapia.","diagnosis":"A lesão do plexo braquial pode reduzir movimento e sensibilidade. O exame precisa distinguir esse quadro de fraturas e outras causas de pouca movimentação.","expected":"A recuperação varia conforme a extensão da lesão. Algumas crianças melhoram progressivamente; outras precisam de avaliação especializada e eventualmente de cirurgia.","alarm":"Observe ausência de progresso, rigidez, assimetria persistente, dor ou dificuldade para vestir e higienizar o braço.","immediate":"Braço subitamente pálido ou frio, inchaço importante, dor nova intensa ou dificuldade respiratória exigem atendimento urgente.","return":"Mantenha as revisões precoces e a reabilitação; não espere meses sem reavaliar um membro que continua pouco móvel.","sources":[{"url":"https://www.hey.nhs.uk/patient-leaflet/obstetric-brachial-plexus-injury-erbs-palsy/","title":"Hull University Teaching Hospitals NHS — Obstetric brachial plexus injury","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Parasitoses Intestinais em Pediatria","aliases":["Parasitoses intestinais"],"setting":"home","general":"Após avaliação, mantenha água segura, higiene das mãos e dos alimentos. Em caso de diarreia, acompanhe ingestão de líquidos e urina.","diagnosis":"Parasitoses são doenças diferentes; o agente suspeito, a idade e os exames determinam o cuidado e a necessidade de avaliar contatos.","expected":"A resposta varia por parasita; reinfecção pode ocorrer. Sintomas persistentes não significam automaticamente resistência ao tratamento.","alarm":"Observe perda de peso, diarreia prolongada, dor importante ou sinais de desidratação.","immediate":"Procure pronto atendimento se houver pouca urina, prostração, vômitos persistentes ou dor abdominal intensa.","return":"Retorne se os sintomas persistirem ou voltarem, para revisar diagnóstico e exposição.","sources":[{"url":"https://www.cdc.gov/giardia/hcp/clinical-care/index.html","title":"CDC — Patient Care for Giardia Infection","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/pinworm/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of Pinworm Infection","accessed":"2026-09-26"}],"reviewNotes":"Orientação geral condicional; não há esquema único para todas as parasitoses. Fonte complementar de prevenção por oxiúros incluída.","status":"source-reviewed"},
{"name":"Parotidite infecciosa (Caxumba)","aliases":[],"setting":"home","general":"Após avaliação, ofereça líquidos e alimentos macios conforme tolerância, repouso e cuidados de higiene. Evite compartilhar copos e talheres.","diagnosis":"A inflamação das glândulas pode tornar mastigação e deglutição dolorosas. Confirme com o serviço o período de afastamento e orientações aos contatos.","expected":"A maioria dos casos evolui bem, mas complicações podem surgir, especialmente após o início da puberdade.","alarm":"Observe piora da dor, recusa de líquidos, dor abdominal ou dor e inchaço nos testículos.","immediate":"Dor de cabeça intensa com vômitos, rigidez de nuca, confusão, convulsão ou dor testicular importante exige avaliação imediata.","return":"Retorne se houver agravamento ou dificuldade de hidratação; revise vacinação e informe novos sintomas auditivos.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/c/caxumba","title":"Ministério da Saúde — Caxumba","accessed":"2026-09-26"}],"reviewNotes":"Sem prazo fixo de isolamento: fonte brasileira e protocolos locais podem divergir; equipe deve individualizar orientação sanitária.","status":"source-reviewed"},
{"name":"Pé cavo","aliases":[],"setting":"specialist","general":"Use calçados confortáveis e os apoios prescritos. Observe áreas de pressão, calos, instabilidade e dificuldades nas atividades.","diagnosis":"O arco alto pode ter causas estruturais ou neurológicas; a avaliação da marcha e da força ajuda a definir o tratamento.","expected":"A evolução depende da causa. Alguns casos se estabilizam; outros progridem e podem precisar de procedimentos, sem indicação cirúrgica automática.","alarm":"Observe quedas, entorses repetidas, piora da dor ou pé que começa a arrastar.","immediate":"Fraqueza súbita, perda de sensibilidade, incapacidade aguda de apoiar após trauma ou mudança de cor do pé exige urgência.","return":"Retorne com ortopedia e neurologia quando indicado; leve os calçados habituais e informe mudanças da marcha ao longo do crescimento.","sources":[{"url":"https://www.chop.edu/conditions-diseases/cavus-foot","title":"CHOP — Cavus Foot","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Pé plano fisiológico","aliases":[],"setting":"home","general":"Permita atividades confortáveis e calçados adequados ao tamanho do pé. Observe se há dor ou limitação; não force exercícios ou compre palmilhas apenas para criar um arco.","diagnosis":"Pé plano flexível e sem dor é comum na infância. O arco aparece quando a criança fica na ponta dos pés ou sem apoiar; o exame confirma se esse padrão é fisiológico.","expected":"Muitas crianças desenvolvem arco com o crescimento, e algumas mantêm pés planos sem prejuízo. Não é necessário tratar somente a aparência.","alarm":"Dor, rigidez, assimetria ou dificuldade para caminhar não são características a ignorar e justificam revisão.","immediate":"Dor aguda com incapacidade de apoiar, trauma importante ou febre com inchaço: avaliação imediata.","return":"Retorne se surgirem sintomas; o profissional decidirá se há necessidade de ortopedia ou investigação.","sources":[{"url":"https://www.rch.org.au/ortho/for_health_professionals/Flat_feet/","title":"Royal Children’s Hospital — Flat feet","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Pé torto congênito","setting":"specialist","general":"Deformidade presente ao nascimento, geralmente tratável com método ortopédico precoce. O pé pode parecer virado para dentro e para baixo.","diagnosis":"Inicie acompanhamento ortopédico precocemente e cumpra o esquema de gessos e órteses indicado. Verifique pele e dedos conforme orientação; não interrompa a órtese porque o pé aparenta estar corrigido.","expected":"Sem tratamento, a deformidade pode dificultar apoio e marcha. Com tratamento especializado, muitas crianças desenvolvem função e mobilidade satisfatórias.","alarm":"Procure avaliação urgente se houver pé frio, pálido ou azulado, inchaço importante, ferida, dor intensa ou alteração após imobilização.","immediate":"Encaminhe para ortopedia pediátrica; não tente endireitar ou manipular o pé em casa e não use calçados ou talas improvisados.","return":"Mantenha todas as consultas e revisões de gesso, órtese e crescimento; retorne antes com dor, ferida, deslizamento ou dedos alterados.","sources":[{"url":"https://www.nhs.uk/conditions/club-foot/","title":"NHS — Clubfoot","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Pediculose","aliases":["Pediculose em Pediatria"],"setting":"home","general":"Examine o couro cabeludo e utilize pente fino e tratamento conforme a orientação recebida. Verifique contatos próximos e trate quem tiver infestação ativa; não associe piolhos à falta de higiene.","diagnosis":"Confirme a presença de piolhos vivos, pois lêndeas isoladas não comprovam atividade. Evite inseticidas domésticos, querosene, produtos veterinários e misturas caseiras.","expected":"Pode ser necessário repetir o cuidado conforme o método escolhido para alcançar piolhos recém-nascidos. Persistência exige rever aplicação e possível reinfestação, não aumentar doses por conta própria.","alarm":"Feridas, pus, dor no couro cabeludo ou coceira persistente após tratamento pedem revisão.","immediate":"Reação importante ao produto, dificuldade respiratória ou intoxicação acidental: atendimento imediato.","return":"Reexamine conforme o calendário do método prescrito e procure orientação se continuarem aparecendo piolhos vivos.","sources":[{"url":"https://www.nhs.uk/conditions/head-lice-and-nits/","title":"NHS — Head lice and nits","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Pediculose do couro cabeludo","setting":"home","general":"Infestação por piolhos vivos no couro cabeludo, transmitida principalmente por contato cabeça a cabeça. Não significa falta de higiene.","diagnosis":"Confirme encontrando piolho vivo com pente fino; lêndeas isoladas podem ser antigas. Verifique contatos próximos, sem compartilhar pentes, escovas, bonés ou toalhas.","expected":"Coceira pode continuar por algum tempo após eliminar os piolhos. Siga exatamente um método aprovado localmente e repita-o somente conforme suas instruções.","alarm":"Procure avaliação se houver feridas extensas, pus, dor importante, febre, reação ao produto ou dúvida diagnóstica, especialmente em criança pequena.","immediate":"Comece a remoção com pente fino em cabelo úmido e informe a escola conforme regras locais. Não use produtos inadequados, inseticidas domésticos ou combinações.","return":"Reavalie o couro cabeludo após o tratamento e retorne se ainda houver piolhos vivos ou irritação; trate contatos apenas quando confirmados.","sources":[{"url":"https://www.nhs.uk/conditions/head-lice-and-nits/","title":"NHS — Head lice and nits","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Pelagra em Pediatria","aliases":["Pelagra"],"setting":"specialist","general":"Procure avaliação nutricional e investigação de ingestão, absorção e possíveis doenças associadas. Proteja a pele sensível ao sol.","diagnosis":"A deficiência de niacina ou de seus precursores pode afetar pele, intestino e sistema nervoso.","expected":"A melhora depende da reposição supervisionada e correção da causa; quadros avançados podem ser graves.","alarm":"Observe diarreia persistente, lesões cutâneas, menor ingestão ou mudanças de comportamento.","immediate":"Confusão, prostração importante ou incapacidade de manter hidratação exige atendimento imediato.","return":"Cumpra seguimento clínico e nutricional, com revisão da alimentação e resposta; não substitua avaliação por suplementos isolados.","sources":[{"url":"https://medlineplus.gov/ency/article/000342.htm","title":"MedlinePlus — Pellagra","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Persistência do canal arterial","aliases":["PCA","Canal arterial patente"],"setting":"specialist","general":"Mantenha acompanhamento cardiológico e observe alimentação, crescimento e respiração. Em prematuros, siga o plano da equipe neonatal.","diagnosis":"A importância do canal depende do tamanho, repercussão e presença de outras cardiopatias. A necessidade de fechamento deve ser definida pelo cardiologista.","expected":"Canais pequenos podem fechar espontaneamente ou não causar sintomas. Outros precisam de intervenção; a evolução depende da circulação e das condições associadas.","alarm":"Observe cansaço ou suor durante mamadas, baixo ganho de peso, respiração rápida ou dificuldade crescente para se alimentar.","immediate":"Falta de ar importante, coloração azulada, desmaio ou bebê pouco responsivo exige atendimento imediato.","return":"Compareça aos exames programados, mesmo se a criança parecer bem. Antecipe o retorno com alteração respiratória ou alimentar e siga orientações específicas após eventual procedimento.","sources":[{"url":"https://medlineplus.gov/ency/article/001560.htm","title":"MedlinePlus — Patent ductus arteriosus","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Picada de escorpião Tityus serrulatus","aliases":[],"setting":"hospital","general":"Leve a criança imediatamente a um serviço de urgência. Lave o local com água e sabão; não faça torniquete, cortes, sucção ou aplicação de substâncias caseiras.","diagnosis":"Acidentes com escorpião-amarelo podem evoluir rapidamente, sobretudo em crianças. A necessidade de soro e observação depende da avaliação hospitalar, sem aguardar sintomas em casa.","expected":"A evolução inicial pode mudar em minutos ou horas. Dor local isolada no começo não garante que o envenenamento permanecerá leve.","alarm":"Vômitos, suor intenso, salivação, agitação, tremores ou alteração dos batimentos devem ser informados imediatamente.","immediate":"Qualquer picada suspeita em criança exige avaliação imediata; falta de ar, sonolência, convulsão ou desmaio são sinais críticos.","return":"Siga o período de observação e só deixe o serviço após liberação e orientações formais.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/a/animais-peconhentos/acidentes-por-escorpioes","title":"Ministério da Saúde — Acidentes por escorpiões","accessed":"2026-09-26"},{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/a/animais-peconhentos/acidentes-por-escorpioes/faq/faq/o-que-devo-fazer-no","title":"Ministério da Saúde — O que fazer em acidente com escorpião","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Pitiríase rósea de Gilbert","aliases":[],"setting":"home","general":"Faça higiene suave e evite produtos que irritem a pele. Use cuidados para coceira apenas conforme orientação e evite esfregar as lesões.","diagnosis":"A pitiríase rósea costuma causar placas descamativas; outras doenças podem parecer semelhantes. O diagnóstico deve ser conferido se o aspecto for atípico.","expected":"Geralmente melhora espontaneamente ao longo de semanas a poucos meses; mudanças de cor podem durar mais tempo.","alarm":"Observe coceira intensa, lesões diferentes do padrão, febre importante ou sinais de infecção.","immediate":"Bolhas extensas, lesões de mucosas, falta de ar ou prostração não são evolução habitual e exigem avaliação imediata.","return":"Retorne se persistir por cerca de três meses, houver dúvida diagnóstica ou coceira não controlada.","sources":[{"url":"https://www.nhs.uk/conditions/Pityriasis-rosea/","title":"NHS — Pityriasis rosea","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Pitiríase versicolor","aliases":[],"setting":"home","general":"Use o tratamento apenas nas áreas e pelo período orientados, mantendo higiene suave e evitando produtos irritantes. Não aplique misturas clareadoras ou descamativas para tentar igualar rapidamente a cor.","diagnosis":"A pitiríase versicolor decorre do crescimento de um fungo que pode estar normalmente na pele. Manchas claras ou escuras têm outras causas; confirme o diagnóstico antes de repetir tratamentos.","expected":"A cor pode levar meses para normalizar mesmo após o controle do fungo, e recorrências são possíveis. Cor residual isolada não exige prolongar o tratamento.","alarm":"Dor, secreção, inflamação importante, extensão incomum ou ausência de resposta justificam revisão.","immediate":"Reação extensa ao produto com bolhas, inchaço de face ou dificuldade respiratória: atendimento imediato.","return":"Retorne se as lesões reaparecerem ou houver dúvida; prevenção e manutenção devem ser individualizadas.","sources":[{"url":"https://www.nhs.uk/conditions/pityriasis-versicolor/","title":"NHS — Pityriasis versicolor","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Pneumonia adquirida na comunidade por Streptococcus pneumoniae","setting":"urgent","general":"Infecção pulmonar bacteriana que pode causar febre, tosse e dificuldade respiratória; em criança, avaliação clínica é necessária.","diagnosis":"Após avaliação, cumpra o plano indicado e ofereça líquidos e alimentação tolerada. A necessidade de internação depende da respiração e do estado geral; evite fumaça e exposição a irritantes.","expected":"Febre e disposição devem melhorar progressivamente com cuidado adequado; a tosse pode durar mais. O tempo de recuperação depende da gravidade, e piora ou ausência de resposta exige revisão.","alarm":"Respiração muito difícil ou rápida, lábios arroxeados, pausas respiratórias, sonolência incomum, desidratação ou piora exigem emergência.","immediate":"Procure atendimento hospitalar imediatamente diante de sinais de gravidade; mantenha a criança acompanhada e não force líquidos se estiver muito sonolenta ou com falta de ar.","return":"Reavalie conforme orientação da equipe e retorne imediatamente se qualquer sinal de alarme surgir ou se o estado geral piorar.","sources":[{"url":"https://www.cdc.gov/pneumonia/about/index.html","title":"CDC — About Pneumonia","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Pneumonia Comunitária na Criança","aliases":["Pneumonia comunitária"],"setting":"home","general":"Após definição de cuidado domiciliar, ofereça líquidos em pequenas quantidades frequentes, repouso e ambiente sem fumaça.","diagnosis":"Pneumonia pode ser viral ou bacteriana. Siga o tratamento indicado; a tosse isolada não justifica acrescentar antitussígeno.","expected":"A melhora deve ser progressiva, mas a tosse pode durar mais que a febre. A evolução varia conforme a causa.","alarm":"Observe piora da respiração, vômitos ou menor ingestão de líquidos.","immediate":"Dificuldade respiratória crescente, gemência ou dificuldade para despertar exige emergência.","return":"Cumpra retorno orientado e antecipe avaliação se houver piora, falta de melhora ou preocupação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Pneumonia/","title":"RCH — Pneumonia","accessed":"2026-09-26"}],"reviewNotes":"Orientação para casos liberados após avaliação. Página revisada em 2018 aguarda revisão rotineira; manter conferência médica das recomendações. Não autoriza manejo domiciliar de doença grave.","status":"source-reviewed"},
{"name":"Pneumonia Congênita","aliases":[],"setting":"hospital","general":"Suspeita de pneumonia presente desde o nascimento exige avaliação neonatal hospitalar. Informe gestação, parto, infecções maternas e resultados do pré-natal.","diagnosis":"Respiração difícil pode resultar de infecção ou outras doenças neonatais; exame, oxigenação e história obstétrica precisam ser interpretados em conjunto.","expected":"A evolução depende de prematuridade, agente e órgãos acometidos; não existe duração universal de internação.","alarm":"Comunique gemência, recusa alimentar, mudança da temperatura, icterícia precoce ou menor resposta.","immediate":"Apneia, coloração azulada, convulsão ou choque exigem intervenção imediata da equipe.","return":"Alta somente após avaliação neonatal, com seguimento de alimentação, crescimento e eventuais sequelas conforme a etiologia.","sources":[{"url":"https://www.nice.org.uk/guidance/ng195/chapter/risk-factors-and-clinical-indicators-early-onset-neonatal-infection","title":"NICE NG195 — Early-onset neonatal infection, atualizado em 2026","accessed":"2026-09-27"},{"url":"https://pubmed.ncbi.nlm.nih.gov/30455344/","title":"AAP — Early-onset bacterial sepsis in preterm neonates, 2018","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/cytomegalovirus/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of Congenital CMV, 2024","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/std/treatment-guidelines/congenital-syphilis.htm","title":"CDC — Congenital Syphilis Treatment Guidelines","accessed":"2026-09-27"}],"reviewNotes":"Escopo: investigação e destino hospitalar; “congênita” não determina agente nem equivale a qualquer pneumonia neonatal. Outros agentes e diagnósticos alternativos exigem protocolo neonatal próprio. Não contém receita ou critério automático de alta; sem homologação humana.","status":"source-reviewed","evidenceSummary":"NICE aborda infecção bacteriana precoce; AAP destaca limitações dos exames isolados em prematuros. CDC fornece critérios próprios para CMV e sífilis congênitos. Essas fontes não justificam painel indiferenciado nem tratamento etiológico universal.","decisionSupport":{"summary":"Selecionar a situação confirmada antes de individualizar as orientações.","requirements":["Idade gestacional e início dos sinais","História materna, bolsas e parto","Oxigenação, culturas e órgãos afetados","Evidências específicas de transmissão congênita"],"branchRequired":true,"branches":[{"id":"bacterial-perinatal","label":"Infecção bacteriana perinatal suspeita","when":"Sinais desde o nascimento associados a avaliação de infecção precoce.","setting":"hospital","overrides":{"diagnosis":"Rever riscos maternos e investigar sepse; sinais de gravidade não permitem esperar resultados para instituir cuidado.","expected":"Resposta deve ser acompanhada clínica e microbiologicamente.","alarm":"Piora respiratória, térmica ou alimentar.","immediate":"Apneia ou choque: intervenção imediata.","return":"Plano neonatal após estabilização."}},{"id":"cmv","label":"Suspeita de CMV congênito","when":"Achados/exposição e avaliação neonatal direcionam investigação de CMV.","setting":"hospital","overrides":{"diagnosis":"Confirmação laboratorial deve ocorrer nas primeiras 2–3 semanas; sorologia isolada não confirma infecção congênita.","expected":"Pode exigir vigilância auditiva e do desenvolvimento prolongada.","alarm":"Convulsões ou piora neurológica.","immediate":"Instabilidade ou dificuldade respiratória: emergência.","return":"Programar audição, visão e desenvolvimento se confirmado."}},{"id":"syphilis","label":"Suspeita de sífilis congênita","when":"História materna ou achados clínicos/laboratoriais compatíveis.","setting":"hospital","overrides":{"diagnosis":"Rever tratamento materno e comparar testes não treponêmicos materno/neonatal; investigar órgãos conforme avaliação.","expected":"Depende de extensão e resposta ao tratamento dirigido.","alarm":"Novas lesões, icterícia ou dificuldade alimentar.","immediate":"Deterioração sistêmica: intervenção imediata.","return":"Seguimento clínico e sorológico específico."}},{"id":"other-or-unknown","label":"Outra etiologia ou causa indefinida","when":"Nenhum dos ramos anteriores foi sustentado pela avaliação.","setting":"hospital","overrides":{"diagnosis":"Prosseguir investigação neonatal dirigida; não atribuir causa bacteriana, CMV ou sífilis somente pelo título.","expected":"Indeterminada até esclarecer a causa.","alarm":"Persistência ou progressão dos sinais.","immediate":"Instabilidade requer intervenção imediata.","return":"Plano neonatal individual antes da alta."}}]},"revisedAt":"2026-09-27"},
{"name":"Pneumonia estafilocócica","aliases":[],"setting":"hospital","general":"Procure avaliação hospitalar e mantenha o tratamento definido pela equipe. Informe duração da febre, piora após infecção respiratória e dificuldades para respirar ou beber.","diagnosis":"Pode ser uma pneumonia grave e evoluir com líquido ou pus ao redor do pulmão. Exames e necessidade de drenagem dependem da situação individual.","expected":"A melhora depende da extensão da infecção e das complicações. Febre persistente ou nova piora durante tratamento precisa de reavaliação.","alarm":"Observe esforço respiratório, dor torácica crescente, prostração, febre persistente ou pouca ingestão de líquidos.","immediate":"Dificuldade respiratória, coloração azulada, confusão ou redução da resposta exige emergência.","return":"Após alta formal, cumpra o tratamento e retorno definido. Antecipe a revisão se febre, dor ou respiração piorarem, mesmo antes do prazo combinado.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/pleural_effusion_and_empyema/","title":"RCH — Pleural effusion and empyema","accessed":"2026-09-26"}],"reviewNotes":"Fonte cita S. aureus entre os principais agentes do empiema. Orientações de complicações são condicionais; não presume empiema em toda pneumonia estafilocócica. Revisão médica individual necessária.","status":"source-reviewed"},
{"name":"Pneumonia neonatal","aliases":[],"setting":"hospital","general":"Pneumonia no recém-nascido exige avaliação hospitalar. Informe idade em dias, prematuridade, internações, mamadas e mudanças de respiração ou comportamento.","diagnosis":"A equipe deve investigar infecção sistêmica e causas alternativas de desconforto respiratório; ausência de febre não exclui gravidade.","expected":"A recuperação varia com agente, idade gestacional, complicações e resposta ao suporte.","alarm":"Gemência, respiração rápida, alteração das mamadas, temperatura anormal ou menor atividade exigem comunicação imediata.","immediate":"Apneia, coloração azulada, dificuldade para despertar ou convulsão são emergências.","return":"Após alta formal, cumprir revisão neonatal. Piora respiratória, alimentar ou do estado de alerta exige retorno imediato, sem aguardar consulta marcada.","sources":[{"url":"https://www.nice.org.uk/guidance/ng195/chapter/risk-factors-and-clinical-indicators-early-onset-neonatal-infection","title":"NICE NG195 — Early-onset neonatal infection, atualizado em 2026","accessed":"2026-09-27"},{"url":"https://www.nice.org.uk/guidance/ng195/chapter/risk-factors-and-clinical-indicators-late-onset-neonatal-infection","title":"NICE NG195 — Late-onset neonatal infection","accessed":"2026-09-27"},{"url":"https://www.ncbi.nlm.nih.gov/books/NBK610594/","title":"WHO — Serious bacterial infections in infants aged 0–59 days, executive summary, 2024","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD013864_antibiotics-hospital-acquired-pneumonia-newborns-and-children","title":"Cochrane CD013864 — Hospital-acquired pneumonia in newborns and children","accessed":"2026-09-27"}],"reviewNotes":"Ramos por momento e aquisição, sem inferir agente somente pela idade. Documento para reconhecimento, investigação e seguimento; não autoriza tratamento domiciliar neonatal nem escolhe antimicrobiano. Sem homologação humana.","status":"source-reviewed","evidenceSummary":"NICE distingue infecção precoce/tardia e fatores hospitalares; OMS inclui pneumonia em lactentes pequenos. Cochrane sobre pneumonia hospitalar encontrou evidência muito incerta e não estabelece superioridade de um esquema; microbiologia local importa.","decisionSupport":{"summary":"Selecionar a situação confirmada antes de individualizar as orientações.","requirements":["Idade e início dos sinais","Aquisição comunitária ou hospitalar","Ventilação, cateteres e procedimentos","Oxigenação, estabilidade, culturas e resposta"],"branchRequired":true,"branches":[{"id":"early","label":"Início precoce","when":"Sinais nas primeiras 72 horas de vida, conforme classificação neonatal local.","setting":"hospital","overrides":{"diagnosis":"Rever fatores obstétricos e infecção materna; investigar sepse associada.","expected":"Depende da gravidade e da confirmação etiológica.","alarm":"Alteração de temperatura ou mamadas.","immediate":"Apneia, choque ou convulsão: intervenção imediata.","return":"Seguimento neonatal após estabilização."}},{"id":"late-community","label":"Início tardio, vindo de casa","when":"Quadro iniciado após período neonatal inicial, sem contexto de aquisição hospitalar.","setting":"hospital","overrides":{"diagnosis":"Avaliar infecção sistêmica, contatos e foco; o bebê previamente saudável também pode deteriorar rapidamente.","expected":"Melhora depende da causa e do suporte.","alarm":"Menor resposta, desidratação ou gemência.","immediate":"Cianose ou dificuldade para despertar: emergência.","return":"Revisar respiração, alimentação e crescimento após alta."}},{"id":"hospital-acquired","label":"Associada à assistência ou ventilação","when":"Exposição hospitalar com suspeita de infecção adquirida na unidade.","setting":"hospital","overrides":{"diagnosis":"Rever dispositivos, culturas e resistência local; integrar achados respiratórios e sistêmicos antes de atribuir pneumonia.","expected":"Pode prolongar suporte; prazo não é previsível pelo título.","alarm":"Aumento da necessidade de oxigênio ou instabilidade.","immediate":"Piora ventilatória ou circulatória requer intervenção imediata.","return":"Equipe neonatal acompanha resposta e necessidades pós-alta."}}]},"revisedAt":"2026-09-27"},
{"name":"Pneumonia pneumocócica","aliases":[],"setting":"home","general":"Após avaliação e liberação, cumpra o tratamento indicado, ofereça líquidos e repouso. Observe respiração, ingestão, febre e interação.","diagnosis":"A pneumonia pneumocócica é bacteriana; o esquema depende da idade, gravidade e resposta. Não troque ou interrompa o tratamento por conta própria.","expected":"A melhora deve ser progressiva, mas tosse e cansaço podem durar além da febre; piora exige nova avaliação.","alarm":"Observe febre persistente, dor torácica, recusa alimentar e aumento do esforço respiratório.","immediate":"Lábios azulados, dificuldade intensa para respirar, prostração ou pouca urina exige emergência.","return":"Retorne no prazo estabelecido e antes se houver piora. Confirme vacinação pneumocócica e necessidade de revisão de resultados ou complicações.","sources":[{"url":"https://www.cdc.gov/pneumococcal/about/index.html","title":"CDC — About Pneumococcal Disease","accessed":"2026-09-26"}],"reviewNotes":"Orientação inicial condicionada à liberação médica. Não presume etiologia pneumocócica somente por sintomas ou radiografia.","status":"source-reviewed"},
{"name":"Pneumonia por aspiração","aliases":[],"setting":"urgent","general":"Procure avaliação respiratória e da segurança da alimentação. Informe episódios de engasgo, vômito, sedação ou dificuldade prévia para engolir.","diagnosis":"A aspiração pode provocar inflamação química ou infecção; o diagnóstico e o tratamento não são iguais para todos os episódios.","expected":"A recuperação depende da extensão pulmonar e das condições de base; recorrência exige investigação do mecanismo da aspiração.","alarm":"Observe febre, tosse após refeições, secreção diferente, dificuldade para engolir e respiração acelerada.","immediate":"Engasgo com falta de ar, lábios azulados, confusão ou prostração intensa exige emergência.","return":"Retorne para reavaliar pulmões e deglutição. Siga posicionamento, consistência e via alimentar definidos pela equipe; não force líquidos em criança sonolenta.","sources":[{"url":"https://medlineplus.gov/ency/article/000121.htm","title":"MedlinePlus — Aspiration pneumonia","accessed":"2026-09-26"}],"reviewNotes":"Fonte geral; medidas e via alimentar precisam de adaptação pediátrica e avaliação de deglutição. Não equivale pneumonite química a infecção.","status":"source-reviewed"},
{"name":"Pneumonia por Chlamydia","aliases":[],"setting":"urgent","general":"Procure avaliação da gravidade; observe respiração, alimentação e urina. Não inicie tratamento apenas pelo nome do catálogo.","diagnosis":"É indispensável identificar a espécie ou hipótese etiológica fundamentada pelo profissional.","expected":"A recuperação depende da espécie, idade e resposta; ausência de febre não exclui pneumonia no lactente.","alarm":"Piora respiratória, dificuldade alimentar ou pouca urina exigem reavaliação.","immediate":"Apneia, cianose, grande esforço respiratório ou pouca resposta: emergência.","return":"Cumpra revisão precoce, antecipando-a se piorar.","sources":[{"url":"https://www.cdc.gov/std/treatment-guidelines/chlamydia.htm","title":"CDC — Chlamydial infections: infant pneumonia","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/cpneumoniae/hcp/clinical-overview/index.html","title":"CDC — Clinical overview of C. pneumoniae","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/psittacosis/hcp/clinical-overview/index.html","title":"CDC — Clinical overview of psittacosis","accessed":"2026-09-27"}],"reviewNotes":"Revisão documental concluída por ramificação etiológica; requer decisão médica, sem homologação humana ou novas doses.","status":"source-reviewed","evidenceSummary":"CDC: diretriz para pneumonia por C. trachomatis em lactentes e orientações oficiais para C. pneumoniae/psittaci. A idade e a exposição orientam investigação, sem confirmar isoladamente a espécie.","decisionSupport":{"summary":"Selecionar explicitamente a espécie/hipótese médica antes do preenchimento; espécie indefinida exige esclarecimento individual.","requirements":["Idade; gravidade respiratória; ingestão e diurese.","Espécie/teste ou justificativa clínica; exposição perinatal, respiratória ou a aves."],"branchRequired":true,"branches":[{"id":"trachomatis","label":"C. trachomatis","when":"Hipótese perinatal fundamentada; tipicamente 1–3 meses.","setting":"urgent","overrides":{"diagnosis":"Pneumonia subaguda do lactente; investigar exposição perinatal.","expected":"Pode persistir ou não resolver inicialmente.","return":"Confirmar resolução; orientar avaliação materna e parceiros pela equipe.","alarm":"Piora da alimentação ou vômitos persistentes.","immediate":"Apneia, cianose ou prostração: emergência."}},{"id":"pneumoniae","label":"C. pneumoniae","when":"Hipótese respiratória fundamentada, sobretudo escolares.","setting":"urgent","overrides":{"diagnosis":"Transmissão respiratória; não presumir transmissão perinatal.","expected":"Frequentemente leve; complicações são possíveis.","return":"Reavaliar evolução e resposta clínica.","alarm":"Piora da tosse ou esforço respiratório.","immediate":"Cianose, exaustão ou pouca resposta: emergência."}},{"id":"psittaci","label":"C. psittaci / psitacose","when":"Hipótese fundamentada e exposição epidemiológica compatível.","setting":"urgent","overrides":{"diagnosis":"Investigar contato com aves; evitar poeira de excretas.","expected":"Gravidade variável, com possíveis complicações sistêmicas.","return":"Seguir avaliação clínica; ave suspeita requer veterinário.","alarm":"Febre persistente ou piora geral.","immediate":"Falta de ar importante ou confusão: emergência."}}]},"revisedAt":"2026-09-27"},
{"name":"Pneumonia por Chlamydophila pneumoniae","setting":"urgent","general":"Pneumonia bacteriana respiratória, frequentemente de início gradual, cuja causa específica requer avaliação profissional; sintomas podem se sobrepor a outras infecções.","diagnosis":"Siga o tratamento e o retorno prescritos; evite fumaça, cubra a tosse e lave as mãos. Observe respiração e hidratação, sem presumir que toda tosse prolongada tenha a mesma causa.","expected":"A melhora costuma ser gradual e a tosse pode persistir por semanas. Nova febre, falta de ar ou piora geral exigem reavaliação; persistência de tosse deve ser discutida no retorno.","alarm":"Falta de ar, respiração trabalhosa, coloração azulada, confusão, incapacidade de beber, sinais de desidratação ou piora rápida são alarmes.","immediate":"Busque urgência imediatamente com qualquer alarme. Enquanto aguarda avaliação, mantenha repouso e ofereça líquidos apenas se a respiração permitir.","return":"Siga a revisão marcada pelo profissional; retorne antes se a tosse, febre, respiração ou estado geral piorarem.","sources":[{"url":"https://www.cdc.gov/cpneumoniae/about/index.html","title":"CDC — About Chlamydia pneumoniae Infection","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Pneumonia por Mycoplasma","aliases":["Pneumonia por Mycoplasma pneumoniae"],"setting":"home","general":"Após avaliação médica e liberação para casa, mantenha hidratação, repouso conforme disposição e higiene das mãos. Cubra tosse e espirros para reduzir transmissão.","diagnosis":"A aparência relativamente boa não exclui pneumonia. A necessidade de tratamento específico deve ser avaliada; não use sobras de antibióticos.","expected":"Tosse e cansaço podem persistir por semanas, mas deve haver melhora progressiva. Piora ou sintomas novos pedem reavaliação.","alarm":"Observe chiado, febre persistente, dificuldade para beber, palidez acentuada ou bolhas e feridas extensas na pele ou boca.","immediate":"Falta de ar, redução da resposta, convulsão ou lesões que impeçam ingerir líquidos exigem atendimento imediato.","return":"Retorne se não houver melhora ou se houver piora durante o tratamento. Crianças com doença pulmonar ou baixa imunidade precisam de vigilância mais próxima.","sources":[{"url":"https://www.cdc.gov/mycoplasma/about/index.html","title":"CDC — About Mycoplasma pneumoniae infection","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Pneumonia por Mycoplasma pneumoniae","aliases":[],"setting":"home","general":"Se a avaliação permitir cuidado domiciliar, ofereça líquidos e repouso conforme tolerância e evite fumaça. Reforce higiene das mãos e etiqueta da tosse.","diagnosis":"A pneumonia por Mycoplasma pode começar gradualmente e causar tosse persistente. O tratamento depende da avaliação; o diagnóstico não justifica adicionar vários medicamentos automaticamente.","expected":"A tosse e o cansaço podem durar semanas, mas a respiração, hidratação e estado geral devem evoluir favoravelmente. Piora não deve ser atribuída apenas à tosse residual.","alarm":"Febre persistente ou que retorna, menor ingestão, dor torácica ou piora do cansaço precisam de revisão.","immediate":"Falta de ar, lábios azulados, confusão, desidratação importante ou bolhas e feridas extensas em mucosas exigem urgência.","return":"Retorne conforme o plano clínico e antes se houver piora ou ausência de melhora do estado geral.","sources":[{"url":"https://www.cdc.gov/mycoplasma/hcp/clinical-signs/index.html","title":"CDC — Clinical Signs and Symptoms of Mycoplasma pneumoniae Infection","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Pneumonia viral por Adenovírus","aliases":[],"setting":"home","general":"Após avaliação que permita cuidado em casa, ofereça líquidos e alimentação conforme tolerância e observe respiração e disposição. Lave as mãos e evite compartilhar utensílios e contato próximo durante o adoecimento.","diagnosis":"Adenovírus pode causar pneumonia e outros sintomas. Não há tratamento antiviral específico aprovado para uso rotineiro; o suporte e a necessidade de hospitalização dependem da gravidade e das condições da criança.","expected":"A recuperação varia. Não use o diagnóstico viral para ignorar piora, especialmente em crianças com imunidade reduzida ou doença cardíaca ou respiratória.","alarm":"Febre persistente, respiração mais rápida, pouca ingestão ou redução da urina exigem reavaliação.","immediate":"Grande esforço respiratório, apneia, coloração azulada ou sonolência anormal: emergência.","return":"Retorne conforme o plano clínico e antes se piorar; sintomas respiratórios persistentes após recuperação precisam de revisão.","sources":[{"url":"https://www.cdc.gov/adenovirus/about/index.html","title":"CDC — About Adenovirus","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Pneumonia viral por Influenza","setting":"urgent","general":"Pneumonia é uma possível complicação da influenza e pode ser grave, especialmente em crianças pequenas ou com doenças crônicas. Precisa de avaliação clínica e definição do local de cuidado.","diagnosis":"Cumpra o plano definido após avaliação, com repouso e líquidos conforme tolerância. Observe a respiração em repouso e reduza transmissão por higiene das mãos e proteção ao tossir.","expected":"A recuperação depende da gravidade e de outras complicações. Tosse e cansaço podem durar mais que a febre; piora após melhora inicial exige nova avaliação para complicações associadas.","alarm":"Respiração difícil, retrações, lábios azulados, dor torácica, desidratação, convulsão, confusão, ausência de alerta ou piora após melhora exigem emergência.","immediate":"Procure urgência imediatamente diante de alarme; mantenha a criança em ambiente ventilado e evite contato próximo com pessoas vulneráveis.","return":"Retorne imediatamente se a respiração ou hidratação piorar; faça acompanhamento conforme orientação clínica, pois complicações podem surgir após a fase inicial.","sources":[{"url":"https://www.cdc.gov/flu/signs-symptoms/index.html","title":"CDC — Signs and Symptoms of Flu","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Pneumotórax espontâneo","aliases":[],"setting":"urgent","general":"Dor torácica súbita ou falta de ar exige avaliação urgente. Mantenha repouso enquanto recebe ajuda e informe episódios anteriores ou doença pulmonar.","diagnosis":"O acúmulo de ar ao redor do pulmão pode precisar de observação ou drenagem. A gravidade clínica importa mais que apenas o tamanho na imagem.","expected":"A evolução depende da estabilidade e da causa. Pode haver recorrência, inclusive depois de melhora do primeiro episódio.","alarm":"Observe aumento da dor ou falta de ar, respiração rápida, palidez ou piora da disposição.","immediate":"Falta de ar intensa, coloração azulada, desmaio ou rápida piora exige emergência imediata.","return":"Se houver alta após observação médica, retorne em 24–48 horas conforme combinado. Dor ou dificuldade respiratória nova exige retorno imediato, sem aguardar a consulta.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Primary_spontaneous_pneumothorax/","title":"RCH — Primary spontaneous pneumothorax","accessed":"2026-09-26"}],"reviewNotes":"Fonte diferencia forma primária da secundária e recomenda especialista quando há doença pulmonar. Não libera automaticamente alta ou atividades. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Poliarterite Nodosa em Pediatria","aliases":["Poliarterite nodosa"],"setting":"specialist","general":"Mantenha reumatologia pediátrica e as avaliações dos órgãos envolvidos. Registre sintomas e compareça às verificações de pressão arterial.","diagnosis":"Formas limitadas à pele e doença sistêmica têm riscos diferentes; o diagnóstico exige investigação especializada.","expected":"A evolução pode alternar atividade e controle, com acompanhamento prolongado conforme a extensão.","alarm":"Observe dor abdominal, manchas dolorosas, sangue na urina, fraqueza ou febre persistente.","immediate":"Convulsão, déficit neurológico, falta de ar ou dor abdominal intensa exige emergência.","return":"Cumpra exames de vigilância e plano individual. Sintomas novos não devem ser presumidos como simples manifestação cutânea.","sources":[{"url":"https://www.printo.it/pediatric-rheumatology/BR/info/9/Vasculite-sist%C3%A9mica-prim%C3%A1ria-juvenil-rara","title":"PRINTO — Vasculite sistêmica primária juvenil rara","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Policitemia neonatal","aliases":[],"setting":"hospital","general":"Mantenha acompanhamento neonatal e informe alimentação, atividade, respiração e quantidade de urina. Não tente corrigir o resultado do sangue oferecendo água ao recém-nascido.","diagnosis":"A policitemia precisa ser interpretada com a origem da amostra, sintomas e condições do bebê. Uma medida capilar isolada não define automaticamente necessidade de procedimento.","expected":"Alguns bebês não apresentam sintomas; outros precisam de monitorização e intervenção. A evolução depende das manifestações e das causas associadas.","alarm":"Recusa alimentar, vômitos, distensão, tremores, sonolência, respiração alterada ou redução da urina exigem avaliação.","immediate":"Apneia, convulsão, dificuldade para despertar, cianose ou prostração importante exigem emergência imediata.","return":"Após liberação, cumpra a revisão neonatal e o plano de alimentação e exames definido pela equipe, sem repetir intervenções por conta própria.","sources":[{"url":"https://medconnection.ucsfbenioffchildrens.org/polycythemia-guidelines","title":"UCSF — Consensus Guidelines for Partial Exchange Transfusion for Polycythemia in Neonates","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Diretriz de consenso aborda recém-nascidos com idade gestacional de pelo menos 34 semanas; prematuros menores requerem protocolo especializado.","status":"source-reviewed"},
{"name":"Prescrição Pediátrica no Perioperatório","setting":"hospital","aliases":["Cuidados perioperatórios pediátricos"],"general":"Cuidados perioperatórios dependem da cirurgia, anestesia e condições da criança; precisam de plano individual.","diagnosis":"Siga rigorosamente instruções de jejum, alimentação e medicamentos. Após alta autorizada, mantenha supervisão de adulto e repouso orientado.","expected":"Sonolência e menor disposição podem ocorrer após anestesia; recuperação e restrições variam com o procedimento.","alarm":"Dor crescente, vômitos persistentes, sangramento ou secreção na ferida exigem contato com a equipe.","immediate":"Dificuldade respiratória, dificuldade para despertar ou sangramento importante requerem emergência.","return":"Cumpra a revisão cirúrgica e use o contato fornecido na alta para dúvidas ou mudanças clínicas.","sources":[{"url":"https://www.cuh.nhs.uk/patient-information/information-for-children-having-had-general-anaesthesia/","title":"Cambridge University Hospitals — Information for children having had general anaesthesia","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Analgesia_and_sedation/","title":"RCH — Acute pain management","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Tema perioperatório exige prescrição e instruções individuais; recomendações após anestesia só se aplicam após alta autorizada e não substituem restrições da cirurgia. Mantido setting hospital. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Prurigo Estrófulo","aliases":["Urticária papular"],"setting":"home","general":"Reduza novas picadas com telas, roupas protetoras e medidas ambientais. Use repelentes apenas conforme idade e orientação do produto; cuide de eventuais pulgas dos animais com orientação veterinária.","diagnosis":"As lesões representam reação às picadas; evite coçar e mantenha unhas curtas e pele limpa.","expected":"Novos surtos podem ocorrer enquanto houver exposição, e manchas residuais podem durar mais que a coceira.","alarm":"Dor crescente, pus, calor ou vermelhidão em expansão sugerem infecção.","immediate":"Procure atendimento imediato se houver febre com rápida piora da pele ou prostração.","return":"Retorne se o controle ambiental não reduzir os surtos ou o diagnóstico permanecer incerto.","sources":[{"url":"https://pedsderm.net/site/assets/files/1028/spd_papular_urticaria_bw_pub.pdf","title":"Society for Pediatric Dermatology — Papular urticaria","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Pseudotumor cerebral","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento com neurologia e oftalmologia e registre dor de cabeça e alterações visuais. Leve a lista completa de medicamentos.","diagnosis":"O aumento da pressão intracraniana precisa de investigação; o diagnóstico idiopático pressupõe exclusão de outras causas. A proteção da visão é prioridade.","expected":"O curso varia e pode haver recorrência; melhora da dor não dispensa exame visual.","alarm":"Observe visão embaçada, escurecimentos transitórios, visão dupla, vômitos e piora da cefaleia.","immediate":"Perda visual, dor súbita intensa, fraqueza, confusão ou redução de consciência exige atendimento imediato.","return":"Retorne no calendário de controle visual e antes se os sintomas mudarem. Não suspenda medicamentos nem inicie medidas para perda de peso infantil sem plano supervisionado.","sources":[{"url":"https://www.nhs.uk/conditions/intracranial-hypertension/","title":"NHS — Intracranial hypertension","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Psoríase vulgar infantil","aliases":[],"setting":"specialist","general":"Mantenha hidratação da pele com o produto indicado e use os tratamentos somente nas áreas e períodos prescritos. Evite fricção, coçar e mudanças por conta própria, especialmente em face e dobras.","diagnosis":"Psoríase não é contagiosa. A intensidade, o local das placas e a idade orientam o plano; produtos usados por adultos não devem ser transferidos automaticamente para a criança.","expected":"É uma condição com fases de melhora e piora, sem promessa de cura definitiva. O objetivo é controlar sintomas e preservar qualidade de vida.","alarm":"Dor ou inchaço articular, piora extensa, efeitos adversos ou prejuízo emocional justificam revisão.","immediate":"Vermelhidão extensa com febre, pele muito dolorosa, pustulação disseminada ou prostração: atendimento imediato.","return":"Mantenha acompanhamento dermatológico e antecipe se o tratamento não controlar o quadro ou interferir na rotina.","sources":[{"url":"https://www.nhs.uk/conditions/psoriasis/","title":"NHS — Psoriasis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Ptiríase","aliases":[],"setting":"specialist","general":"Confirme o diagnóstico escrito por extenso e evite tratamentos caseiros. “Ptiríase” não identifica uma doença única.","diagnosis":"Não distinguir apenas pelo nome: examinar distribuição, descamação, prurido e presença de parasitas.","expected":"O prognóstico depende do ramo confirmado.","alarm":"Dor, pus, febre ou lesões progressivas exigem revisão.","immediate":"Comprometimento ocular, prostração ou piora rápida exigem avaliação urgente.","return":"Sem diagnóstico esclarecido, retornar para avaliação antes da orientação específica.","sources":[{"url":"https://www.cdc.gov/lice/about/pubic-lice.html","title":"CDC — Pubic lice","accessed":"2026-09-27"},{"url":"https://www.nhs.uk/conditions/pityriasis-rosea/","title":"NHS — Pityriasis rosea","accessed":"2026-09-27"},{"url":"https://www.nhs.uk/conditions/pityriasis-versicolor/","title":"NHS — Pityriasis versicolor","accessed":"2026-09-27"},{"url":"https://www.stgeorges.nhs.uk/wp-content/uploads/2019/12/Diagnosis-and-treatment-tips-in-Dermatology-Nov-2019.pdf","title":"St George’s NHS — Dermatology tips, pityriasis alba","accessed":"2026-09-27"},{"url":"https://www.cochrane.org/evidence/CD005068_treatments-pityriasis-rosea","title":"Cochrane — Treatments for pityriasis rosea","accessed":"2026-09-27"}],"reviewNotes":"Ambiguidade preservada e controlada por seleção obrigatória; revisão documental, não homologação clínica. Não renomear o cadastro para ocultar a lacuna.","status":"source-reviewed","evidenceSummary":"CDC/NHS e materiais pediátricos NHS distinguem parasitose e dermatoses. Cochrane incluiu 761 participantes de 2–60 anos para rósea; limitações terapêuticas não autorizam extrapolar eficácia pediátrica.","decisionSupport":{"summary":"Exigir seleção explícita após diagnóstico; não converter automaticamente “Ptiríase” em nenhuma das opções. Outra interpretação exige individualização.","requirements":["Diagnóstico por extenso; idade; localização; exame da pele/pelos.","Acometimento ocular; contatos; contexto de proteção da criança."],"branchRequired":true,"branches":[{"id":"ftiriase","label":"Ftiríase / pediculose pubiana","when":"Parasita compatível identificado.","setting":"specialist","overrides":{"diagnosis":"Não compartilhar roupas; avaliar contatos e proteção infantil sem presumir abuso.","expected":"Não desaparece espontaneamente.","return":"Verificar erradicação e reexposição.","alarm":"Escoriações infectadas ou parasitas nos cílios.","immediate":"Dor ocular ou alteração visual: urgência."}},{"id":"rosea","label":"Pitiríase rósea","when":"Dermatose confirmada clinicamente.","setting":"home","overrides":{"diagnosis":"Evitar irritantes; não equivale a infestação.","expected":"Geralmente resolve em semanas a meses.","return":"Reavaliar persistência além de três meses.","alarm":"Prurido incapacitante ou apresentação atípica.","immediate":"Doença geral importante: avaliação urgente."}},{"id":"versicolor","label":"Pitiríase versicolor","when":"Micose superficial confirmada.","setting":"home","overrides":{"diagnosis":"Seguir cuidados específicos; não presumir falha pela cor residual.","expected":"Repigmentação pode demorar meses; recidivas ocorrem.","return":"Reavaliar recorrência ou dúvida diagnóstica.","alarm":"Dor ou secreção são atípicas.","immediate":"Comprometimento geral: avaliação urgente."}},{"id":"alba","label":"Pitiríase alba","when":"Dermatite hipopigmentada confirmada.","setting":"home","overrides":{"diagnosis":"Manter hidratação cutânea e fotoproteção.","expected":"Melhora gradualmente; não é vitiligo.","return":"Reavaliar manchas progressivas ou diferentes.","alarm":"Inflamação intensa ou mudança do padrão.","immediate":"Doença geral associada: avaliação urgente."}}]},"revisedAt":"2026-09-27"},
{"name":"Puberdade precoce central","aliases":[],"setting":"specialist","general":"Mantenha seguimento com endocrinologia pediátrica e converse com a criança de maneira adequada à idade. Registre início e progressão das mudanças corporais.","diagnosis":"A avaliação considera crescimento, desenvolvimento puberal, idade óssea e exames hormonais. Nem toda puberdade adiantada necessita do mesmo tratamento.","expected":"O objetivo é proteger crescimento e bem-estar, conforme a evolução individual. A resposta e o momento de encerrar eventual tratamento precisam de revisão periódica.","alarm":"Avise sobre progressão rápida, sangramento inesperado, sofrimento emocional ou efeitos do tratamento.","immediate":"Cefaleia intensa com vômitos ou alterações visuais novas merece avaliação urgente e não deve ser atribuída simplesmente à puberdade.","return":"Compareça às consultas e exames previstos. Antecipe o retorno se as mudanças acelerarem ou surgirem sintomas novos que possam exigir investigação da causa.","sources":[{"url":"https://www.nichd.nih.gov/health/topics/puberty/conditioninfo/treatments","title":"NICHD — Treatments for problems of puberty","accessed":"2026-09-26"},{"url":"https://www.nichd.nih.gov/health/topics/puberty/conditioninfo/diagnosed","title":"NICHD — Diagnosis of precocious puberty","accessed":"2026-09-26"}],"reviewNotes":"Orientação de tratamento baseada em NICHD; sinais neurológicos requerem investigação individual da causa. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Puberdade precoce periférica","aliases":[],"setting":"specialist","general":"Registre quando surgiram os sinais puberais e leve medidas anteriores de altura. Informe medicamentos, suplementos e possível contato com cremes hormonais de familiares.","diagnosis":"A puberdade precoce periférica pode ter diferentes causas ovarianas, testiculares, adrenais ou externas. O tratamento depende da causa e não é automaticamente o mesmo da forma central.","expected":"A evolução do crescimento e da maturação varia conforme o diagnóstico e a resposta ao tratamento. Não use hormônios ou bloqueadores sem investigação especializada.","alarm":"Progressão rápida, sangramento genital, aumento assimétrico dos testículos ou massa abdominal precisam de avaliação antecipada.","immediate":"Dor abdominal ou testicular súbita e intensa, desmaio ou sangramento importante exigem urgência.","return":"Mantenha seguimento com endocrinologia pediátrica, acompanhamento da velocidade de crescimento e exames individualizados.","sources":[{"url":"https://www.nichd.nih.gov/health/topics/factsheets/puberty","title":"NICHD — Puberty and Precocious Puberty","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Púrpura de Henoch-Schönlein","aliases":["Vasculite por IgA","Púrpura de Henoch Schonlein"],"setting":"home","general":"Após avaliação, mantenha repouso conforme dor e ingestão habitual de líquidos. Observe urina, fezes, inchaço e capacidade para caminhar.","diagnosis":"A inflamação pode atingir pele, articulações, intestino e rins. Alterações renais podem surgir mesmo quando as manchas já desapareceram.","expected":"Muitos episódios melhoram em algumas semanas, mas podem ocorrer recaídas. O desaparecimento das lesões não encerra a necessidade de acompanhamento.","alarm":"Observe dor abdominal crescente, sangue na urina ou fezes, inchaço e redução da urina.","immediate":"Dor abdominal forte ou persistente, vômitos repetidos, sangramento importante ou criança muito abatida exige urgência. Febre com manchas novas não deve ser presumida como simples recaída.","return":"Mantenha controles de pressão e urina pelo período definido, geralmente por meses. Antecipe a revisão com qualquer alteração urinária ou piora da dor.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Henoch_Schonlein_Purpura_HSP/","title":"RCH — Henoch-Schönlein purpura","accessed":"2026-09-26"}],"reviewNotes":"Página informa revisão de rotina pendente; não foram incorporadas afirmações controversas sobre prevenção de nefrite com corticoide. Síntese para revisão médica.","status":"source-reviewed"},
{"name":"Púrpura trombocitopênica imune aguda","aliases":[],"setting":"specialist","general":"Siga o plano de hematologia e evite atividades com risco de colisão ou trauma na cabeça. Informe a condição antes de procedimentos ou de usar novos medicamentos.","diagnosis":"A conduta considera principalmente o sangramento e o estado clínico, além da contagem de plaquetas. Uma contagem baixa isolada não define o mesmo tratamento para todas as crianças.","expected":"Muitos episódios melhoram, mas o tempo é variável e pode haver persistência ou recorrência; mantenha o acompanhamento mesmo quando as manchas diminuírem.","alarm":"Sangramento nasal prolongado, sangue na urina ou nas fezes e sangramento de mucosas requerem avaliação.","immediate":"Qualquer trauma na cabeça, cefaleia intensa, vômitos neurológicos, convulsão ou hemorragia importante exige emergência.","return":"Cumpra o retorno e hemograma programados e procure revisão antes se o padrão de sangramento mudar.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Immune_thrombocytopenic_purpura/","title":"RCH — Immune thrombocytopenic purpura","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Púrpura trombocitopênica imune crônica","aliases":[],"setting":"specialist","general":"Mantenha seguimento hematológico e ajuste atividades ao risco de trauma definido pela equipe. Informe a condição antes de procedimentos e novos medicamentos.","diagnosis":"Na PTI crônica, decisões dependem do sangramento e do contexto, não apenas da contagem de plaquetas. Evite automedicação que possa aumentar sangramento.","expected":"A contagem pode oscilar e o acompanhamento é prolongado; não aplicar a previsão de melhora rápida da PTI aguda a todos os casos.","alarm":"Observe sangramento de boca/nariz, sangue na urina ou fezes e aumento de manchas.","immediate":"Trauma craniano, dor de cabeça intensa, vômitos, sonolência ou sangramento que não cessa exige emergência.","return":"Retorne conforme os hemogramas programados e antes diante de novo sangramento ou mudança clínica.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Idiopathic_thrombocytopenic_purpura_ITP/","title":"RCH — Idiopathic thrombocytopenic purpura","accessed":"2026-09-26"}],"reviewNotes":"Fonte inclui persistência; prognóstico da forma aguda não foi aplicado à PTI crônica.","status":"source-reviewed"},
{"name":"Quadros de Psiquiatria em Emergência Pediátrica","aliases":["Emergência psiquiátrica pediátrica"],"setting":"urgent","general":"Mantenha ambiente calmo e seguro, com supervisão. Retire acesso a meios de lesão sem confronto e informe comportamentos e exposições recentes.","diagnosis":"Agitação, confusão ou risco de autoagressão exigem avaliação; causas clínicas, intoxicação e dor também devem ser consideradas.","expected":"A estabilização depende da causa e do risco. O plano de segurança e a continuidade do cuidado são essenciais.","alarm":"Observe ameaças, autoagressão, perda de contato com a realidade, intoxicação ou incapacidade de manter segurança.","immediate":"Risco imediato de lesão, alteração de consciência ou comportamento incontrolável exige emergência.","return":"Após atendimento, siga plano escrito de segurança, supervisão e seguimento de saúde mental.","sources":[{"url":"https://psychiatryonline.org/doi/full/10.1176/appi.focus.23022005","title":"AAEP/AACAP — BETA consensus for agitated children and adolescents","accessed":"2026-09-26"}],"reviewNotes":"Tema amplo, orientação de triagem e segurança; não substitui avaliação psiquiátrica nem presume causa exclusivamente mental.","status":"source-reviewed"},
{"name":"Queimadura de 1º grau por insolação","aliases":[],"setting":"home","general":"Retire a criança do sol, resfrie suavemente a pele e ofereça líquidos. Use roupas leves e proteja a área até cicatrizar; não aplique gelo diretamente nem arranque pele descamando.","diagnosis":"Queimadura solar superficial causa vermelhidão e dor. Bolhas, área extensa ou sintomas gerais podem indicar maior gravidade; insolação com alteração do estado geral é uma situação diferente e urgente.","expected":"A pele costuma melhorar em cerca de uma semana e pode descamar durante a recuperação. Evite nova exposição até estar recuperada.","alarm":"Dor intensa, bolhas, febre, tontura, pouca urina ou queimadura em bebê precisam de avaliação.","immediate":"Confusão, desmaio, vômitos persistentes ou criança muito quente e prostrada: emergência.","return":"Retorne se piorar, se houver sinais de infecção ou se não houver melhora progressiva.","sources":[{"url":"https://www.nhs.uk/conditions/sunburn/","title":"NHS — Sunburn","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Queimadura de 2º grau por escaldadura","setting":"urgent","general":"Queimadura por líquido quente pode causar dor, vermelhidão e bolhas. Crianças devem ser avaliadas, sobretudo quando extensa ou em áreas especiais.","diagnosis":"Após avaliação, siga o curativo e proteja a área de atrito; não rompa bolhas nem retire pele. Mantenha as revisões porque a profundidade pode precisar ser reavaliada nos dias seguintes.","expected":"O tempo de cicatrização varia com profundidade e extensão. Queimaduras mais profundas podem deixar cicatrizes ou exigir procedimentos; não é possível prometer recuperação em prazo único.","alarm":"Emergência se atingir face ou via aérea, for extensa/profunda, circundar membro, envolver áreas especiais, ou houver dificuldade respiratória, choque ou alteração da consciência.","immediate":"Afaste da fonte, retire roupas não aderidas e resfrie com água corrente fresca por 20 minutos; não use gelo, cremes, manteiga nem estoure bolhas. Cubra frouxamente e procure urgência.","return":"Retorne imediatamente com dor crescente, vermelhidão que se espalha, pus, febre, mau cheiro, desidratação ou piora; cumpra revisões da equipe.","sources":[{"url":"https://www.nhs.uk/conditions/burns-and-scalds/","title":"NHS — Burns and scalds","accessed":"2026-09-26"}],"reviewNotes":"Fonte aberta e conteúdo sintetizado para revisão médica individual. Não equivale a homologação clínica nem substitui definição do plano assistencial.","aliases":[],"status":"source-reviewed"},
{"name":"Queimadura de 3º grau por chama","aliases":["Queimadura de espessura total por chama"],"setting":"hospital","general":"Acione socorro e afaste a criança da fonte de calor com segurança. Resfrie a área com água corrente fresca, evitando esfriar todo o corpo.","diagnosis":"Queimaduras profundas precisam de avaliação especializada, mesmo quando doem pouco. Informe exposição em ambiente fechado e possível inalação de fumaça.","expected":"A profundidade pode ficar mais evidente nos primeiros dias. Pode ser necessário tratamento cirúrgico e reabilitação prolongada para cicatrizes e movimento.","alarm":"Observe rouquidão, tosse com fuligem, inchaço da face, dificuldade respiratória ou extremidade fria além da queimadura.","immediate":"Toda queimadura de terceiro grau exige atendimento imediato; sintomas respiratórios ou alteração de consciência são emergência.","return":"O seguimento é definido pelo centro de queimados. Não use gelo ou produtos caseiros. Após alta formal, retorne conforme plano de curativos e antecipe diante de piora clínica.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/burns/","title":"RCH — Burns: acute management","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Queimaduras em Pediatria","aliases":["Queimaduras"],"setting":"urgent","general":"Resfrie a área com água corrente fresca por vinte minutos, evitando esfriar o restante do corpo. Não aplique cremes caseiros nem rompa bolhas.","diagnosis":"A gravidade depende da profundidade, extensão, local e agente. Tecidos aderidos não devem ser arrancados.","expected":"Lesões pequenas podem cicatrizar em semanas; profundas podem exigir procedimentos e acompanhamento prolongado.","alarm":"Procure avaliação se houver dúvida sobre gravidade, dor crescente ou dificuldade no cuidado.","immediate":"Queimadura extensa, profunda, elétrica, química ou em face exige emergência.","return":"Cumpra revisões de curativo e cicatrização. O cuidado domiciliar só deve seguir orientação após classificação da lesão.","sources":[{"url":"https://www.nhs.uk/conditions/burns-and-scalds/","title":"NHS — Burns and scalds","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Queixas Genitais em Meninas Pré-púberes","aliases":[],"setting":"specialist","general":"Faça higiene externa suave; evite irritantes, umidade e roupas apertadas. Não introduza produtos na vagina.","diagnosis":"Queixa genital não define etiologia; candidíase é incomum dos 2 anos até a puberdade.","expected":"Irritação pode melhorar com cuidados; persistência exige investigação.","alarm":"Corrimento fétido, sangue, dor urinária ou recorrência merecem avaliação.","immediate":"Trauma, sangramento importante, dor intensa ou risco de violência exigem atendimento e proteção imediatos.","return":"Não realizar exame ou coleta vaginal interna de rotina em pré-púberes.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Vulval_and_Vaginal_Conditions/","title":"RCH — Vulval and vaginal conditions","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/vulvovaginitis/","title":"RCH — Vulvovaginitis","accessed":"2026-09-27"}],"reviewNotes":"Revisão documental sindrômica; ramo não substitui exame nem presume infecção ou violência. Requer revisão médica individual.","status":"source-reviewed","evidenceSummary":"Diretriz pediátrica RCH e orientação familiar do serviço: diagnóstico diferencial, exame externo e seguimento. Recomendações de prática clínica, não ensaios que confirmem etiologia pela descrição isolada.","decisionSupport":{"summary":"Selecionar o quadro após avaliação; sintomas não esclarecidos exigem diagnóstico ou encaminhamento antes de orientação etiológica automática.","requirements":["Idade/puberdade; duração; prurido noturno; corrimento/sangramento.","Exame externo; disúria/febre; constipação; trauma, proteção e recorrência."],"branchRequired":true,"branches":[{"id":"irritativa","label":"Vulvovaginite inespecífica","when":"Avaliação compatível, sem sinais preocupantes.","setting":"home","overrides":{"diagnosis":"Reduzir irritantes e umidade.","expected":"Pode recorrer, melhorando com cuidados.","return":"Rever se persistir.","alarm":"Febre, sangue ou dor urinária.","immediate":"Dor intensa ou prostração: urgência."}},{"id":"oxiuriase","label":"Suspeita de oxiuríase","when":"Prurido/dor perineal noturnos avaliados.","setting":"home","overrides":{"diagnosis":"Investigar verminose e higiene familiar.","expected":"Depende de confirmação e controle da reinfestação.","return":"Reavaliar persistência.","alarm":"Sintomas diferentes do padrão noturno.","immediate":"Dor intensa ou prostração: urgência."}},{"id":"sangramento_corrimento","label":"Sangramento ou corrimento fétido","when":"Causa ainda não explicada.","setting":"urgent","overrides":{"diagnosis":"Investigar corpo estranho e outras causas; não retirar em casa.","expected":"Depende da causa identificada.","return":"Avaliação presencial antes de emissão específica.","alarm":"Sangramento ou secreção persistentes.","immediate":"Trauma ou risco de violência: proteção imediata."}},{"id":"dermatose_dor","label":"Dermatose ou dor persistente","when":"Lesões específicas ou sintomas recorrentes.","setting":"specialist","overrides":{"diagnosis":"Avaliar dermatoses, aderências e vulvodínia.","expected":"Curso variável conforme diagnóstico.","return":"Seguimento pediátrico/ginecológico individualizado.","alarm":"Novas lesões ou dificuldade miccional.","immediate":"Retenção urinária ou dor intensa: urgência."}}]},"revisedAt":"2026-09-27"},
{"name":"Rabdomiólise em Pediatria","aliases":[],"setting":"urgent","general":"Procure avaliação diante de dor muscular intensa, fraqueza ou urina escura, especialmente após esforço, doença ou exposição medicamentosa.","diagnosis":"A rabdomiólise libera conteúdo muscular e pode comprometer rins e eletrólitos; exames e avaliação da hidratação orientam a gravidade.","expected":"A melhora depende da causa e da função renal; a liberação para casa exige critérios clínicos e laboratoriais.","alarm":"Informe redução da urina, dor progressiva, dificuldade para caminhar ou incapacidade de beber.","immediate":"Ausência de urina, prostração ou piora importante exige emergência.","return":"Após alta autorizada, cumpra revisão e repetição de exames; suspenda esforço intenso até orientação médica.","sources":[{"url":"https://www.connecticutchildrens.org/sites/default/files/2025-07/rhabdomyolysis-7.17.25.pdf","title":"Connecticut Children’s — Rhabdomyolysis Clinical Pathway, julho 2025","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Fluxograma clínico efetivamente lido por captura da primeira página; retorno em 24–48 horas e restrição de atividade individualizáveis.","status":"source-reviewed"},
{"name":"Raquitismo","aliases":[],"setting":"specialist","general":"Mantenha avaliação pediátrica e nutricional. Use somente a suplementação definida pela equipe; não administre megadoses por conta própria.","diagnosis":"Raquitismo pode ter causas nutricionais, renais ou hereditárias. A investigação orienta o tratamento e avalia cálcio e saúde óssea.","expected":"A recuperação e a correção das deformidades dependem da causa, idade e gravidade; não há prazo único.","alarm":"Relate dor óssea, fraqueza, piora da marcha ou novas deformidades.","immediate":"Espasmos, convulsão, dificuldade respiratória ou suspeita de fratura exigem atendimento imediato.","return":"Retorne com os exames solicitados para verificar resposta, crescimento e necessidade de investigação especializada.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Vitamin_D_deficiency/","title":"Royal Children’s Hospital — Vitamin D deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Fonte utilizada para raquitismo nutricional e sinais de hipocalcemia; outras etiologias permanecem condicionadas à investigação especializada.","status":"source-reviewed"},
{"name":"Raquitismo carencial","aliases":[],"setting":"specialist","general":"Mantenha alimentação e suplementação exatamente como orientadas, com acompanhamento do crescimento. Não ofereça megadoses nem associe produtos vitamínicos por conta própria.","diagnosis":"O raquitismo carencial envolve mineralização óssea inadequada, frequentemente relacionada à vitamina D ou cálcio. Exames ajudam a confirmar a causa e afastar outras formas de raquitismo.","expected":"Dor e força podem melhorar antes das deformidades. O ritmo de recuperação depende da gravidade, crescimento e correção efetiva da deficiência.","alarm":"Dor óssea persistente, fraqueza, piora da marcha, deformidade progressiva ou ausência de ganho de crescimento exigem revisão.","immediate":"Convulsão, espasmos importantes, dificuldade respiratória ou suspeita de fratura exigem avaliação urgente.","return":"Compareça aos controles clínicos e laboratoriais; ajuste a reposição somente com a equipe responsável e reavalie a dieta.","sources":[{"url":"https://www.nhs.uk/conditions/rickets-and-osteomalacia/","title":"NHS — Rickets and osteomalacia","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Vitamin_D_deficiency/","title":"RCH — Vitamin D deficiency","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Refluxo Vesicoureteral (RVU)","aliases":["Refluxo vesicoureteral"],"setting":"specialist","general":"Mantenha acompanhamento e informe febre ou alterações urinárias; trate constipação conforme o plano.","diagnosis":"O refluxo permite retorno de urina para os ureteres; o grau, as infecções e a função renal orientam o cuidado.","expected":"Alguns refluxos melhoram com o crescimento; outros precisam de tratamento prolongado ou procedimento.","alarm":"Observe febre, vômitos, dor lombar ou recusa alimentar, inclusive durante medidas preventivas.","immediate":"Procure atendimento imediato se a criança estiver muito abatida, não conseguir beber ou apresentar pouca urina.","return":"Cumpra exames e retornos; suspeita de infecção urinária exige avaliação precoce.","sources":[{"url":"https://www.niddk.nih.gov/health-information/urologic-diseases/hydronephrosis-newborns/vesicoureteral-reflux","title":"NIDDK — Vesicoureteral Reflux in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Abrange RVU geral; não equivale automaticamente a grau V.","status":"source-reviewed"},
{"name":"Refluxo vesicoureteral grau I","aliases":[],"setting":"specialist","general":"Estimule idas regulares ao banheiro, hidratação habitual e tratamento da constipação. Mantenha seguimento urológico/pediátrico e observe sintomas urinários.","diagnosis":"No grau I, a urina reflui para o ureter sem alcançar o rim. O plano depende de idade, infecções e avaliação do trato urinário.","expected":"Graus baixos podem desaparecer com o crescimento, mas o acompanhamento protege contra infecção e possíveis danos.","alarm":"Observe febre sem causa clara, dor ao urinar, dor abdominal, vômitos ou alteração da urina.","immediate":"Febre com prostração, recusa de líquidos, pouca urina ou vômitos repetidos exige avaliação imediata.","return":"Retorne com os exames e após qualquer ITU; não iniciar nem manter prevenção medicamentosa automaticamente apenas pelo grau.","sources":[{"url":"https://www.chop.edu/conditions-diseases/vesicoureteral-reflux-vur","title":"CHOP — Vesicoureteral Reflux","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Refluxo vesicoureteral grau II","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento e exames indicados, incentive hábitos urinários regulares e informe constipação. Não suspenda medidas preventivas prescritas sem discutir com a equipe.","diagnosis":"No refluxo vesicoureteral, a urina retorna da bexiga em direção aos ureteres. O grau II não define sozinho a conduta; infecções, função renal e funcionamento da bexiga também importam.","expected":"Alguns casos melhoram com o crescimento, mas é preciso acompanhamento para confirmar evolução e proteger os rins. Não há prazo garantido para resolução.","alarm":"Febre sem causa evidente, ardor ao urinar, novos escapes ou dor abdominal devem ser avaliados prontamente.","immediate":"Febre com prostração, vômitos persistentes, dor lombar ou dificuldade para hidratar: atendimento imediato.","return":"Cumpra retornos de nefrologia ou urologia e procure avaliação de urina quando orientado diante de suspeita de infecção.","sources":[{"url":"https://www.niddk.nih.gov/health-information/urologic-diseases/hydronephrosis-newborns/vesicoureteral-reflux","title":"NIDDK — Vesicoureteral Reflux","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Refluxo vesicoureteral grau III","setting":"specialist","general":"Mantenha acompanhamento com urologia ou nefrologia pediátrica e leve os resultados de imagem a cada revisão.","diagnosis":"O refluxo aumenta o risco de infecção urinária. Relate constipação, escapes de urina e dificuldade de esvaziar a bexiga; o plano deve considerar estes problemas.","expected":"O refluxo primário pode melhorar com o crescimento, mas o grau III exige vigilância individual; não existe prazo garantido de resolução.","alarm":"Febre sem causa clara, dor ao urinar, dor lombar ou piora do estado geral precisam de avaliação rápida.","immediate":"Procure pronto atendimento com febre e prostração, vômitos repetidos, pouca urina ou incapacidade de beber.","return":"Cumpra controles de crescimento, pressão, função renal e imagem quando indicados; não interrompa seguimento por ausência de sintomas.","sources":[{"url":"https://www.niddk.nih.gov/health-information/urologic-diseases/hydronephrosis-newborns/vesicoureteral-reflux","title":"NIDDK — Vesicoureteral Reflux","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Refluxo vesicoureteral grau IV","aliases":["RVU grau IV"],"setting":"specialist","general":"Mantenha acompanhamento com urologia e, quando indicado, nefrologia. Incentive micções regulares e comunique constipação ou dificuldade para esvaziar a bexiga.","diagnosis":"O grau IV exige avaliação do risco de infecção e da saúde dos rins. A conduta depende também da idade, função vesical e infecções anteriores.","expected":"Pode haver melhora com crescimento, mas isso não é garantido. Acompanhamento ou intervenção devem ser individualizados para preservar os rins.","alarm":"Observe febre, dor ao urinar, dor lombar, vômitos ou alteração importante das mamadas em bebês.","immediate":"Febre com prostração, vômitos persistentes ou pouca urina exige avaliação urgente; não espere o retorno agendado.","return":"Procure avaliação precoce de febre para investigar infecção urinária. Mantenha exames de imagem, pressão arterial e função renal conforme indicação, sem interromper prevenção prescrita por conta própria.","sources":[{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/vesicoureteric-reflux","title":"EAU — Vesicoureteric reflux","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Refluxo vesicoureteral grau V","aliases":[],"setting":"specialist","general":"Mantenha seguimento com urologia e nefrologia pediátricas. Estimule micções regulares nas crianças continentes e trate constipação conforme orientação; hidratação deve respeitar o plano individual.","diagnosis":"No refluxo vesicoureteral grau V, a urina retorna com dilatação importante. A escolha entre acompanhamento, prevenção e procedimento considera infecções, função renal e anatomia.","expected":"Refluxos de alto grau têm menor chance de resolução espontânea que os leves. Não é possível prever cura ou necessidade cirúrgica apenas pela idade.","alarm":"Febre, dor ao urinar, dor lombar, vômitos ou recusa alimentar devem motivar avaliação precoce para infecção.","immediate":"Prostração, desidratação, dificuldade para despertar ou febre em bebê pequeno exigem emergência.","return":"Cumpra exames e retornos; informe rapidamente qualquer nova infecção urinária para prevenir complicações renais.","sources":[{"url":"https://www.niddk.nih.gov/health-information/urologic-diseases/hydronephrosis-newborns/vesicoureteral-reflux","title":"NIDDK — Vesicoureteral Reflux in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Resfriado comum","aliases":["Resfriado Comum em Pediatria"],"setting":"home","general":"Ofereça líquidos, mantenha amamentação e repouso conforme necessidade. Higienize mãos, ventile ambientes e evite exposição à fumaça.","diagnosis":"O resfriado é viral. A cor da secreção isoladamente não confirma bactéria nem justifica antibiótico.","expected":"Os sintomas costumam piorar nos primeiros dias e depois melhorar; tosse pode continuar por mais tempo. A evolução deve ser progressiva.","alarm":"Observe febre persistente, dor de ouvido, piora após melhora inicial e menor aceitação de líquidos.","immediate":"Falta de ar, lábios azulados, dificuldade de despertar ou desidratação exige atendimento imediato; febre em lactente pequeno requer avaliação prioritária.","return":"Retorne se houver agravamento, sintomas prolongados ou interferência importante no sono/alimentação; use sintomáticos somente conforme idade e prescrição.","sources":[{"url":"https://www.cdc.gov/common-cold/about/index.html","title":"CDC — About Common Cold","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Retinopatia da prematuridade","aliases":[],"setting":"specialist","general":"Compareça a todos os exames oftalmológicos nas datas marcadas, inclusive após alta neonatal. Se não conseguir ir, avise o serviço imediatamente para reorganizar o acompanhamento.","diagnosis":"A retinopatia da prematuridade pode piorar sem sinais percebidos em casa. O exame da retina determina estágio e necessidade de tratamento; aparência normal dos olhos não substitui a avaliação.","expected":"Formas leves podem regredir, enquanto outras progridem e precisam de intervenção para preservar a visão. O prognóstico depende do estágio e do tratamento oportuno.","alarm":"Dificuldade para acompanhar objetos, movimentos oculares anormais ou mudança na aparência dos olhos precisam de revisão.","immediate":"Perda visual aparente ou alteração ocular súbita exige avaliação imediata; não espere o retorno de rotina.","return":"Mantenha seguimento prolongado porque outros problemas visuais podem aparecer, mesmo após controle da fase inicial.","sources":[{"url":"https://www.nei.nih.gov/eye-health-information/eye-conditions-and-diseases/retinopathy-prematurity","title":"National Eye Institute — Retinopathy of Prematurity","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Retocolite ulcerativa","setting":"specialist","general":"Mantenha hidratação e alimentação equilibrada, acompanhadas por gastroenterologia e nutrição pediátrica. Anote evacuações, sangue nas fezes e peso.","diagnosis":"Não exclua grupos alimentares indiscriminadamente. O plano deve acompanhar crescimento, anemia e manifestações fora do intestino.","expected":"A doença pode alternar atividade e remissão; a duração e intensidade das crises variam. Melhora dos sintomas não dispensa acompanhamento.","alarm":"Aumento do sangramento, perda de peso, febre, palidez ou redução da alimentação exigem contato antecipado com a equipe.","immediate":"Vá imediatamente ao hospital com grande sangramento, desmaio, desidratação, dor abdominal intensa ou abdome distendido com febre.","return":"Siga as revisões clínicas e exames programados; antecipe o retorno se as evacuações aumentarem ou o estado geral piorar.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/ulcerative-colitis/definition-facts","title":"NIDDK — Ulcerative Colitis","accessed":"2026-09-26"},{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/ulcerative-colitis/eating-diet-nutrition","title":"NIDDK — Nutrition for ulcerative colitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":["Retocolite Ulcerativa em Pediatria"],"status":"source-reviewed"},
{"name":"Rinite Alérgica em Pediatria","aliases":["Rinite alérgica"],"setting":"home","general":"Identifique e reduza exposição aos fatores que desencadeiam sintomas, conforme orientação. Evite fumaça e siga a técnica correta dos cuidados nasais.","diagnosis":"A rinite alérgica pode afetar nariz, olhos e sono; não é contagiosa e pode coexistir com asma.","expected":"O controle varia conforme exposição e adesão. Sintomas persistentes exigem revisão, não uma promessa de cura definitiva.","alarm":"Relate prejuízo do sono, rendimento escolar, obstrução persistente ou surgimento de chiado.","immediate":"Dificuldade para respirar ou falar e esforço respiratório importante exigem pronto atendimento.","return":"Reavalie se o plano não controlar os sintomas ou houver dúvida sobre os fatores desencadeantes.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Hay_fever/","title":"RCH — Hay fever","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Rinite alérgica intermitente leve","aliases":[],"setting":"home","general":"Observe desencadeantes e reduza exposição aos comprovadamente relacionados, como poeira, mofo ou pelos. Higienize o ambiente sem irritantes e mantenha ventilação adequada.","diagnosis":"Espirros, coceira e secreção nasal podem variar conforme exposição. Use apenas o tratamento adequado à idade e à técnica ensinada.","expected":"O controle costuma melhorar os sintomas, mas novas exposições podem provocar recaídas. Persistência ou maior impacto pode mudar a classificação inicialmente leve.","alarm":"Observe sono prejudicado, dificuldade nas atividades, chiado ou sintomas que não respondem ao plano.","immediate":"Dificuldade respiratória importante ou inchaço de boca e garganta exige urgência e não deve ser atribuído apenas à rinite.","return":"Retorne se o controle for insuficiente, se houver dúvida sobre o desencadeante ou piora da asma. Evite prolongar descongestionantes sem avaliação.","sources":[{"url":"https://www.nhs.uk/conditions/allergic-rhinitis/","title":"NHS — Allergic rhinitis","accessed":"2026-09-26"}],"reviewNotes":"Fonte geral de rinite alérgica; subtipo leve/intermitente pressupõe classificação clínica confirmada. Não inclui doses. Revisão médica necessária.","status":"source-reviewed"},
{"name":"Rinite alérgica persistente moderada-grave","aliases":[],"setting":"home","general":"Reduza exposição aos alérgenos identificados e à fumaça. Siga a técnica dos tratamentos nasais ensinada pela equipe e registre impacto no sono, escola e atividades.","diagnosis":"A rinite persistente moderada-grave necessita controle regular e revisão da resposta. Obstrução importante não deve ser atribuída automaticamente à alergia sem avaliar outras causas.","expected":"O controle costuma melhorar com uso correto e contínuo do plano, mas depende da exposição e adesão. A avaliação de resposta pode exigir semanas.","alarm":"Sintomas persistentes apesar do plano, secreção unilateral com mau cheiro ou sangue, dor facial importante ou ronco com pausas exigem revisão.","immediate":"Dificuldade respiratória intensa, inchaço doloroso ao redor dos olhos ou alteração visual exigem atendimento urgente.","return":"Reavalie técnica, adesão e diagnóstico se não houver controle; considere encaminhamento especializado conforme a equipe.","sources":[{"url":"https://www.rch.org.au/Persistent_nasal_discharge_rhinosinusitis/.aspx","title":"RCH — Rhinitis and rhinosinusitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Rinossinusite Aguda em Pediatria","aliases":["Rinossinusite aguda"],"setting":"home","general":"Mantenha hidratação e higiene nasal conforme orientação. Observe duração e padrão dos sintomas e evite automedicação com descongestionantes ou antibióticos.","diagnosis":"A maioria dos quadros agudos é viral; persistência ou piora pode exigir investigação de infecção bacteriana e outras causas.","expected":"A recuperação varia com a causa; secreção colorida isolada não confirma necessidade de antibiótico.","alarm":"Febre persistente, piora após melhora inicial ou dor facial crescente precisam de reavaliação.","immediate":"Inchaço ao redor do olho, alteração visual, cefaleia intensa ou sinais neurológicos exigem emergência.","return":"Retorne no prazo combinado se os sintomas não melhorarem ou se agravarem.","sources":[{"url":"https://www.rch.org.au/Persistent_nasal_discharge_rhinosinusitis/.aspx","title":"Royal Children’s Hospital — Rhinitis and rhinosinusitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Título inclui formas virais e bacterianas; não é sinônimo exclusivo de sinusite bacteriana aguda.","status":"source-reviewed"},
{"name":"Rubéola","aliases":[],"setting":"home","general":"Avise o serviço antes da consulta e evite contato com gestantes. Siga orientações de isolamento e da vigilância em saúde.","diagnosis":"A aparência da erupção não confirma rubéola; avaliação e exames podem ser necessários para distinguir outras infecções.","expected":"O quadro frequentemente é leve, com manchas por poucos dias, mas a transmissão pode ocorrer antes e depois delas.","alarm":"Observe sangramentos, manchas arroxeadas, cefaleia intensa ou mudança do comportamento.","immediate":"Convulsão, alteração de consciência ou sangramento importante exigem pronto atendimento.","return":"Combine confirmação diagnóstica e orientação aos contatos; mantenha afastamento pelo período recomendado, usualmente sete dias após início das manchas.","sources":[{"url":"https://www.cdc.gov/rubella/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of Rubella","accessed":"2026-09-26"}],"reviewNotes":"Rubéola adquirida; não confundir com rubéola congênita.","status":"source-reviewed"},
{"name":"Rubéola congênita","aliases":[],"setting":"specialist","general":"Mantenha cuidado integrado pediátrico, cardiológico, auditivo e oftalmológico. Registre crescimento, alimentação e aquisição de habilidades.","diagnosis":"A rubéola congênita pode afetar vários órgãos e exige avaliação mesmo quando algumas alterações não são visíveis ao nascimento.","expected":"A evolução depende das repercussões; problemas auditivos, visuais e do desenvolvimento podem necessitar apoio prolongado.","alarm":"Observe dificuldade para mamar, cansaço, perda de resposta aos sons, alterações visuais e mudanças neurológicas.","immediate":"Lábios azulados, dificuldade respiratória, convulsão, prostração ou sangramento importante exige emergência.","return":"Retorne para exames e intervenção precoce. Siga a orientação da vigilância sobre prevenção de transmissão e contato com gestantes, sem usar o prazo de isolamento da rubéola adquirida.","sources":[{"url":"https://www.cdc.gov/surv-manual/php/table-of-contents/chapter-15-congenital-rubella-syndrome.html","title":"CDC — Congenital Rubella Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síndrome congênita, distinta da rubéola adquirida. Sinais de gravidade traduzem possíveis comprometimentos orgânicos; plano depende das manifestações.","status":"source-reviewed"},
{"name":"Sangramento Digestivo","aliases":["Hemorragia digestiva"],"setting":"urgent","general":"Procure avaliação médica para sangue no vômito ou nas fezes. Informe quantidade, cor, duração e produtos utilizados; não atribua sangramento persistente apenas à alimentação.","diagnosis":"O sangramento pode ter origem e gravidade diferentes; a avaliação busca identificar a causa e o impacto na circulação.","expected":"A evolução depende da origem e do controle da perda; melhora visual não exclui anemia.","alarm":"Fezes negras, vômito com sangue, palidez, tontura ou cansaço crescente precisam de atenção.","immediate":"Sangramento volumoso, desmaio, falta de ar ou pouca resposta exigem emergência.","return":"Após avaliação, cumpra exames e retorne se o sangramento reaparecer.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/gastrointestinal-bleeding/symptoms-causes","title":"NIDDK — Symptoms and causes of gastrointestinal bleeding","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Sangramento no Neonato","aliases":[],"setting":"hospital","general":"Sangramento neonatal exige avaliação hospitalar rápida. Informe início, local, quantidade, parto, prevenção com vitamina K e produtos maternos.","diagnosis":"Investigar deficiência vitamínica, plaquetas, coagulação, infecção e lesões; aparência saudável não exclui doença relevante.","expected":"Gravidade depende da causa/local; hemorragia interna pode ser pouco evidente.","alarm":"Palidez, manchas ou sangue em umbigo, vômito e fezes são alertas.","immediate":"Convulsão, pouca resposta, dificuldade respiratória ou sangramento persistente exigem emergência.","return":"Após estabilização, cumprir investigação e seguimento; não tratar presumindo causa única.","sources":[{"url":"https://www.clinicalguidelines.scot.nhs.uk/ggc-paediatric-guidelines/ggc-paediatric-guidelines/neonatology/haematology-guideline-neonates/","title":"NHS GGC — Haematology guideline, neonates","accessed":"2026-09-27"},{"url":"https://www.cdc.gov/vitamin-k-deficiency/about/index.html","title":"CDC — Vitamin K deficiency bleeding","accessed":"2026-09-27"}],"reviewNotes":"Lacuna de abrangência suprida por diretriz neonatal. Ramos organizam investigação, não diagnóstico automático; revisão médica continua necessária.","status":"source-reviewed","evidenceSummary":"NHS neonatal abrange investigação de hemorragia em recém-nascidos e alerta para coagulopatias com exames iniciais normais. CDC detalha deficiência de vitamina K. Diretrizes clínicas; não classificam a causa sem exame/testes.","decisionSupport":{"summary":"Seleção etiológica pelo profissional após avaliação, sem atrasar estabilização. Nenhum ramo autoriza alta domiciliar automática.","requirements":["Idades gestacional/pós-natal; estabilidade; local e volume.","Vitamina K; história materna/familiar; hemograma/plaquetas e coagulação interpretados pela idade; infecção/trauma."],"branchRequired":true,"branches":[{"id":"vitamina_k","label":"Deficiência de vitamina K","when":"Suspeita clínica/laboratorial fundamentada.","setting":"hospital","overrides":{"diagnosis":"Pode haver sangramento interno sem aviso.","expected":"Depende do local e tratamento precoce.","return":"Verificar causa e prevenção após estabilização.","alarm":"Icterícia, palidez ou vômitos.","immediate":"Convulsão ou sonolência excessiva: emergência."}},{"id":"plaquetas_coagulacao","label":"Distúrbio plaquetário/coagulação","when":"Investigação hematológica compatível.","setting":"hospital","overrides":{"diagnosis":"História familiar ausente não exclui doença hereditária.","expected":"Varia com o defeito identificado.","return":"Hematologia define exames e plano.","alarm":"Petéquias ou sangramento em punções.","immediate":"Sangramento ativo ou sinais neurológicos: emergência."}},{"id":"doenca_lesao","label":"Doença sistêmica ou lesão","when":"Infecção, doença hepática ou trauma suspeitos.","setting":"hospital","overrides":{"diagnosis":"Investigar e tratar a causa subjacente.","expected":"Depende do comprometimento associado.","return":"Plano neonatal após estabilização.","alarm":"Piora geral ou distensão abdominal.","immediate":"Instabilidade, apneia ou pouca resposta: emergência."}}]},"revisedAt":"2026-09-27"},
{"name":"Sangramento Uterino Anormal em Pediatria","aliases":["Sangramento uterino anormal"],"setting":"specialist","general":"Registre dias de sangramento, intensidade e sintomas associados. A avaliação deve respeitar privacidade e oferecer apoio à adolescente.","diagnosis":"O sangramento pode ter causas hormonais, hematológicas ou outras; não deve ser atribuído automaticamente à irregularidade da adolescência.","expected":"O controle depende da causa e da intensidade. A recuperação da anemia, quando presente, requer acompanhamento.","alarm":"Observe cansaço, palidez, tontura, falta de ar ou sangramento que aumenta.","immediate":"Desmaio, fraqueza intensa ou sangramento volumoso persistente exigem pronto atendimento.","return":"Reavalie o controle do sangramento e os exames conforme o plano; antecipe se houver piora ou resposta insuficiente.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Adolescent_Gynaecology_Menorrhagia/","title":"RCH — Adolescent gynaecology: heavy menstrual bleeding","accessed":"2026-09-26"}],"reviewNotes":"Fonte focada em adolescentes; sangramento pré-puberal exige avaliação etiológica própria.","status":"source-reviewed"},
{"name":"Sarampo","aliases":[],"setting":"urgent","general":"Avise o serviço antes de comparecer para que organize atendimento e prevenção de transmissão. Evite contato com pessoas suscetíveis, especialmente bebês, gestantes e imunocomprometidos, e siga o afastamento orientado.","diagnosis":"Sarampo é altamente contagioso e precisa de avaliação e notificação. O plano de cuidado inclui suporte e avaliação das complicações; não acrescente vitaminas ou outros medicamentos sem prescrição.","expected":"Muitos casos se recuperam, mas pneumonia e complicações neurológicas podem ocorrer. Piora após melhora inicial ou febre persistente não deve ser ignorada.","alarm":"Dificuldade para beber, redução da urina, dor de ouvido ou tosse com piora respiratória exigem revisão.","immediate":"Falta de ar, convulsões, sonolência intensa ou desidratação: emergência.","return":"Retorne conforme a equipe e mantenha os contatos orientados sobre avaliação de vacinação e exposição.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/s/sarampo","title":"Ministério da Saúde — Sarampo","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Schistossomose mansoni","setting":"specialist","general":"Evite contato com água doce de locais com transmissão e utilize água segura e saneamento adequado. Informe onde e quando houve exposição.","diagnosis":"A infecção não passa pelo contato habitual com outra pessoa. Faça a avaliação e os exames indicados, mesmo quando os sintomas forem discretos.","expected":"O curso depende da fase e do comprometimento dos órgãos; formas avançadas podem necessitar internação. Não se deve presumir cura apenas pela melhora.","alarm":"Sangue nas fezes, aumento abdominal, emagrecimento ou fraqueza progressiva exigem reavaliação.","immediate":"Procure emergência se houver sangramento importante, desmaio, falta de ar, alteração de consciência ou deterioração rápida.","return":"Retorne para avaliar resposta e exames de controle definidos pela equipe; mantenha acompanhamento especializado se houver doença hepática ou outras complicações.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/e/esquistossomose","title":"Ministério da Saúde — Esquistossomose","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Sepse em Pediatria","aliases":["Sepse"],"setting":"hospital","general":"Suspeita de sepse exige atendimento hospitalar imediato. Informe infecção recente, tratamentos e doenças prévias; não aguarde resposta a medidas domiciliares.","diagnosis":"Sepse é infecção associada a comprometimento de órgãos. Febre isolada não a define, e pressão normal não exclui gravidade.","expected":"A evolução pode ser rápida e depende da resposta ao tratamento e dos órgãos afetados.","alarm":"Comunique piora da respiração, redução da urina, pele manchada ou mudança do comportamento.","immediate":"Pouca resposta, convulsão, extremidades frias ou dificuldade respiratória intensa exigem SAMU 192.","return":"Após alta, siga o plano de recuperação e retorne imediatamente diante de nova deterioração.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/SEPSIS_assessment_and_management/","title":"Royal Children’s Hospital — Sepsis – assessment and management","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Sepse Neonatal","aliases":["Sepse do recém-nascido"],"setting":"hospital","general":"Suspeita de sepse neonatal exige atendimento imediato; informe intercorrências do parto e mudanças na alimentação ou comportamento.","diagnosis":"A infecção pode manifestar-se com alteração da temperatura, pouca sucção ou movimentos reduzidos, mesmo sem febre evidente.","expected":"Tratamento precoce melhora as perspectivas; evolução e duração dependem do agente e complicações.","alarm":"Observe respiração diferente, barriga distendida, vômitos, icterícia ou sonolência incomum.","immediate":"Dificuldade respiratória, convulsão ou dificuldade para despertar exigem emergência hospitalar.","return":"A equipe definirá alta e seguimento; não interrompa cuidados pela melhora das mamadas.","sources":[{"url":"https://medlineplus.gov/ency/article/007303.htm","title":"MedlinePlus — Neonatal sepsis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Abrange reconhecimento neonatal; não iguala os critérios operacionais de sepse precoce e tardia.","status":"source-reviewed"},
{"name":"Sepse neonatal precoce","aliases":["Sepse neonatal de início precoce"],"setting":"hospital","general":"O recém-nascido precisa de assistência hospitalar e monitorização. Informe antecedentes do parto, resultados maternos e qualquer mudança na alimentação, temperatura ou respiração.","diagnosis":"A infecção pode evoluir rapidamente e os primeiros sinais serem discretos. Observação de bebê apenas em risco não equivale a tratamento de sepse confirmada.","expected":"A recuperação depende da gravidade, agente e resposta ao tratamento. O tempo de internação deve ser definido pela evolução e pelos exames.","alarm":"Observe pouca atividade, irritabilidade incomum, mamadas reduzidas, temperatura baixa ou elevada, menos fraldas molhadas ou alteração de cor.","immediate":"Pausas respiratórias, lábios azulados, convulsão ou dificuldade para despertar exigem emergência imediata; não espere febre.","return":"Após alta formal, cumpra revisões propostas. Nova alteração de mamadas, atividade, temperatura ou respiração exige reavaliação urgente, mesmo após tratamento concluído.","sources":[{"url":"https://www.cuh.nhs.uk/patient-information/for-babies-at-risk-of-infection/","title":"CUH — Infection in newborn babies: information for parents and carers","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Sepse neonatal tardia","aliases":[],"setting":"hospital","general":"Sepse neonatal é emergência hospitalar. Informe idade, prematuridade, internações recentes, dispositivos, início dos sintomas e mudanças nas mamadas ou na atividade.","diagnosis":"A infecção pode provocar sinais pouco específicos, inclusive temperatura baixa em vez de febre. Não espere exames ambulatoriais ou aparecimento de todos os sintomas para buscar atendimento.","expected":"A evolução depende da rapidez do tratamento, do agente e dos órgãos afetados. A melhora inicial não permite suspender o cuidado ou encurtar o plano prescrito.","alarm":"Pouca atividade, recusa alimentar, vômitos, barriga distendida, gemência e alteração de temperatura são sinais relevantes.","immediate":"Pausas respiratórias, coloração azulada, convulsão, dificuldade para despertar ou deterioração rápida exigem emergência imediata.","return":"Após alta formal, cumpra revisões neonatais e acompanhamento do crescimento e desenvolvimento, especialmente quando houver complicações.","sources":[{"url":"https://www.medlineplus.gov/ency/article/007303.htm","title":"MedlinePlus — Neonatal sepsis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Não fixa limiar entre sepse precoce e tardia; definições temporais variam entre protocolos.","status":"source-reviewed"},
{"name":"Sífilis Congênita","aliases":[],"setting":"specialist","general":"Leve os registros maternos e infantis às consultas. Siga o tratamento e o seguimento estabelecidos, mesmo se o bebê parecer bem.","diagnosis":"A avaliação depende dos exames, do tratamento materno e dos achados da criança; exame físico normal não exclui infecção.","expected":"A resposta é acompanhada clinicamente e por exames de sangue seriados; melhora aparente não substitui esse controle.","alarm":"Observe dificuldade alimentar, febre, lesões de pele, icterícia, fraqueza ou alterações de movimento.","immediate":"Convulsão, dificuldade respiratória, pouca resposta ou piora rápida exige emergência.","return":"Compareça às coletas e avaliações de desenvolvimento, audição e visão indicadas; comunique interrupções do tratamento.","sources":[{"url":"https://www.cdc.gov/std/treatment-guidelines/congenital-syphilis.htm","title":"CDC — Congenital Syphilis: STI Treatment Guidelines","accessed":"2026-09-26"}],"reviewNotes":"Não equivale automaticamente a sífilis congênita tardia; avaliação por faixa etária e cenário de exposição.","status":"source-reviewed"},
{"name":"Sífilis congênita precoce","aliases":[],"setting":"specialist","general":"Garanta avaliação e tratamento imediatos do bebê, mesmo sem sintomas. Leve exames e registros do pré-natal e mantenha acompanhamento familiar sem julgamentos.","diagnosis":"A ausência de sinais ao nascer não afasta infecção. O esquema e a necessidade de internação dependem da avaliação do bebê e do histórico materno.","expected":"Tratamento oportuno reduz complicações, mas é necessário comprovar resposta e acompanhar desenvolvimento, visão e audição quando indicado.","alarm":"Observe lesões na pele, icterícia, palidez, dificuldade alimentar, pouca movimentação de membros ou alterações de resposta.","immediate":"Convulsão, dificuldade respiratória, bebê pouco responsivo ou piora rápida exige emergência imediata.","return":"Não falte aos exames de seguimento e consultas, mesmo com melhora. Os responsáveis devem manter o cuidado materno e dos parceiros para evitar novas infecções em futuras gestações.","sources":[{"url":"https://www.cdc.gov/syphilis/about/about-congenital-syphilis.html","title":"CDC — About congenital syphilis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Sífilis congênita tardia","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento pediátrico especializado e leve registros maternos, tratamentos anteriores e exames da criança. O esquema de avaliação deve considerar idade e manifestações atuais.","diagnosis":"A sífilis congênita tardia pode afetar audição, visão, sistema nervoso e outros órgãos. É necessário confirmar a classificação e distinguir outras possibilidades de exposição.","expected":"O tratamento controla a infecção, mas alterações já estabelecidas podem persistir. A resposta precisa ser acompanhada por avaliação clínica e exames, não somente pela melhora dos sintomas.","alarm":"Mudança de audição ou visão, dor óssea, dificuldade de marcha ou alterações de desenvolvimento precisam de revisão antecipada.","immediate":"Perda visual aguda, convulsão, confusão ou fraqueza nova exigem emergência.","return":"Cumpra o seguimento sorológico e as avaliações oftalmológica, auditiva e neurológica indicadas, sem encerrar o cuidado após a primeira melhora.","sources":[{"url":"https://www.cdc.gov/std/treatment-guidelines/congenital-syphilis.htm","title":"CDC — Congenital Syphilis Treatment Guidelines","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. Diretriz contempla crianças além do período neonatal; plano individual para manifestações tardias obrigatório.","status":"source-reviewed"},
{"name":"Síncope na Pediatria","aliases":["Síncope"],"setting":"urgent","general":"Após um desmaio, procure avaliação para esclarecer a causa e descreva contexto, duração e recuperação.","diagnosis":"Muitos episódios são vasovagais, mas causas cardíacas precisam ser consideradas; desmaio durante exercício merece atenção especial.","expected":"A evolução depende da causa. Recuperar rapidamente não exclui doença cardíaca.","alarm":"Informe palpitações, dor torácica, recorrência ou história familiar de morte súbita precoce.","immediate":"Persistência da inconsciência, falta de ar ou desmaio associado a sintomas cardíacos exige emergência.","return":"Após investigação, siga medidas de prevenção e retorno definidos. Episódios recorrentes ou diferentes do habitual precisam de revisão.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Syncope/","title":"RCH — Syncope","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome congênita pelo Zika vírus","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento de desenvolvimento, visão, audição, nutrição e neurologia. Realize terapias e adaptações indicadas, com apoio aos cuidadores.","diagnosis":"A síndrome pode envolver cérebro, olhos, deglutição e mobilidade; cada criança tem necessidades próprias, mesmo sem microcefalia inicial.","expected":"O curso é variável e pode exigir cuidado prolongado. Avaliações periódicas ajudam a reconhecer alterações que aparecem com o crescimento.","alarm":"Observe engasgos, alimentação insuficiente, movimentos incomuns, rigidez e perda ou dificuldade de adquirir habilidades.","immediate":"Convulsão prolongada, engasgo com cianose, falta de ar ou dificuldade para despertar exige emergência.","return":"Retorne para rastreios e intervenções mesmo quando o bebê aparentar estar bem; registre mudanças e dificuldades práticas de alimentação e cuidado.","sources":[{"url":"https://www.cdc.gov/zika/czs/index.html","title":"CDC — Congenital Zika Syndrome and Other Birth Defects","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Síndrome da angústia respiratória do recém-nascido","aliases":[],"setting":"hospital","general":"O recém-nascido precisa de cuidados hospitalares e monitorização da respiração. A alimentação e o contato com a família serão organizados pela equipe conforme a estabilidade do bebê.","diagnosis":"A síndrome do desconforto respiratório neonatal está relacionada à imaturidade pulmonar e falta de surfactante, sobretudo em prematuros. A necessidade de suporte respiratório é avaliada continuamente.","expected":"A evolução varia com prematuridade, gravidade e complicações. Não é possível definir tempo de internação apenas pelo diagnóstico; alguns bebês necessitam suporte prolongado.","alarm":"Aumento do esforço respiratório, gemência, pausas ou dificuldade alimentar precisam de comunicação imediata à equipe.","immediate":"Coloração azulada, ausência de respiração ou pouca resposta exigem emergência neonatal.","return":"Após alta autorizada, cumpra seguimento do prematuro, crescimento e respiração; procure atendimento imediatamente se surgirem sinais respiratórios.","sources":[{"url":"https://www.nhs.uk/conditions/neonatal-respiratory-distress-syndrome/","title":"NHS — Newborn respiratory distress syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome da hipoplasia do coração esquerdo","setting":"hospital","general":"Trata-se de cardiopatia crítica que exige equipe especializada. O recém-nascido com suspeita deve ser encaminhado imediatamente ao hospital.","diagnosis":"Alimentação, suporte respiratório e intervenções precisam de plano da cardiologia. Depois da alta, siga rigorosamente a monitorização e as orientações fornecidas.","expected":"As intervenções não representam cura definitiva; necessidades e prognóstico dependem da anatomia e da evolução. O seguimento cardiológico é permanente.","alarm":"Piora da coloração, cansaço para mamar, respiração acelerada e menor ingestão devem ser comunicados rapidamente.","immediate":"Acione emergência diante de coloração azulada intensa, dificuldade respiratória, desmaio, pouca resposta ou sinais de colapso.","return":"Mantenha revisões e exames cardíacos programados; não aguarde consulta de rotina quando ocorrer mudança em respiração, alimentação ou estado geral.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/hypoplastic-left-heart-syndrome.html","title":"CDC — Hypoplastic Left Heart Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Síndrome da Pele Escaldada","setting":"hospital","aliases":["Síndrome estafilocócica da pele escaldada","SSSS"],"general":"Infecção com desprendimento superficial da pele pode causar perda de líquidos e requer internação.","diagnosis":"Evite esfregar ou retirar pele solta. A equipe definirá proteção das áreas, controle da dor e hidratação.","expected":"Com reconhecimento e cuidado precoces, a recuperação costuma ser boa; a extensão determina necessidades de suporte.","alarm":"Dor intensa, bolhas extensas, pouca urina, febre ou prostração são alarmes.","immediate":"Leve a criança ao hospital imediatamente; não trate como assadura ou queimadura simples.","return":"Após alta, cumpra revisão da pele e retorne por piora, novas áreas, febre ou dificuldade para beber.","sources":[{"url":"https://pch.health.wa.gov.au/For-health-professionals/Emergency-Department-Guidelines/Staphylococcal-scalded-skin-syndrome","title":"Perth Children's Hospital — Staphylococcal scalded skin syndrome","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Síndrome da pele escaldada estafilocócica","aliases":["SSSS"],"setting":"hospital","general":"Procure atendimento hospitalar. Manuseie a criança e a pele com delicadeza, evitando fricção, retirada de pele solta ou aplicação de substâncias caseiras.","diagnosis":"Toxinas bacterianas provocam bolhas e descolamento superficial. A perda de pele pode causar desidratação e facilitar infecções, exigindo controle de dor e líquidos.","expected":"Com tratamento precoce, a recuperação costuma ser favorável e a pele geralmente cicatriza sem marcas importantes. A extensão e a condição clínica determinam o cuidado.","alarm":"Observe expansão da vermelhidão dolorosa, bolhas, febre, pouca ingestão de líquidos ou urina reduzida.","immediate":"Descamação extensa, prostração, dificuldade para beber ou rápida piora exige emergência imediata.","return":"Após alta formal, siga os cuidados de pele e o retorno combinado. Procure reavaliação se surgirem novas bolhas, febre ou piora da dor.","sources":[{"url":"https://www.bad.org.uk/pils/staphylococcal-scalded-skin-syndrome","title":"British Association of Dermatologists — Staphylococcal scalded skin syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome de abstinência neonatal","aliases":[],"setting":"hospital","general":"O bebê precisa de avaliação e observação neonatal conforme a exposição. Mantenha ambiente calmo e participe dos cuidados orientados pela equipe.","diagnosis":"Informe todas as substâncias e medicamentos usados na gestação, sem omitir tratamentos prescritos. A alimentação e possibilidade de amamentar precisam de avaliação individual.","expected":"Os sintomas podem aparecer após alguns dias e durar períodos variáveis; alta depende de alimentação, sono, conforto e estabilidade.","alarm":"Observe tremores, choro difícil de consolar, vômitos, diarreia, alimentação insuficiente e pouco ganho de peso.","immediate":"Convulsão, dificuldade respiratória, desidratação ou dificuldade para despertar exige atendimento imediato.","return":"Após alta, mantenha consultas de peso e desenvolvimento, suporte familiar e plano escrito de retorno; não ofereça sedativos por conta própria.","sources":[{"url":"https://medlineplus.gov/ency/article/007313.htm","title":"MedlinePlus — Neonatal abstinence syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Síndrome de Alagille","setting":"specialist","aliases":["Alagille"],"general":"Síndrome genética pode afetar fígado, coração, rins e outros órgãos, com intensidade variável.","diagnosis":"Siga plano nutricional individual e consultas das especialidades indicadas. Não use suplementos ou produtos para o fígado sem orientação.","expected":"O curso varia entre pessoas; crescimento, coceira e função dos órgãos precisam de acompanhamento continuado.","alarm":"Piora da icterícia, crescimento insuficiente, inchaço ou coceira incapacitante exigem revisão.","immediate":"Sangramento, desmaio, confusão ou falta de ar requerem emergência.","return":"Mantenha exames e revisões mesmo em fases estáveis; antecipe consulta diante de mudança alimentar, urinária ou do estado geral.","sources":[{"url":"https://www.niddk.nih.gov/health-information/liver-disease/alagille-syndrome","title":"NIDDK — Alagille Syndrome","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Síndrome de Amplificação Dolorosa","aliases":[],"setting":"specialist","general":"Reconheça que a dor é real e siga o plano de reabilitação, apoio psicológico e recuperação gradual das atividades escolares e sociais.","diagnosis":"A amplificação dolorosa deve ser identificada por avaliação clínica; exames e história ajudam a considerar outras condições.","expected":"A função pode melhorar antes de a dor desaparecer; o progresso varia e precisa ser acompanhado.","alarm":"Informe perda persistente de função, isolamento, piora do humor ou sintomas novos diferentes do padrão já avaliado.","immediate":"Risco de autoagressão ou deterioração clínica aguda exige avaliação imediata, sem atribuir tudo à dor crônica.","return":"Retorne à equipe para revisar metas, dificuldades e resposta funcional.","sources":[{"url":"https://www.childrens.com/specialties-services/conditions/amplified-musculoskeletal-pain-syndrome-amps","title":"Children’s Health — Pediatric amplified musculoskeletal pain syndrome","accessed":"2026-09-26"},{"url":"https://cps.ca/en/documents/position/anxiety-in-children-and-youth-diagnosis","title":"Canadian Paediatric Society — Anxiety in children and youth: diagnosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Novo quadro agudo requer avaliação própria; não equivale automaticamente a fibromialgia ou toda dor musculoesquelética.","status":"source-reviewed"},
{"name":"Síndrome de Angelman","aliases":[],"setting":"specialist","general":"Mantenha rotina previsível, apoio à comunicação e terapias de desenvolvimento. Siga as orientações de alimentação, sono e segurança para mobilidade e crises epilépticas.","diagnosis":"A síndrome de Angelman envolve necessidades variadas de comunicação, coordenação, aprendizagem e controle de convulsões. Um plano compartilhado com cuidadores e escola ajuda a continuidade do cuidado.","expected":"É uma condição de longo prazo; novas habilidades podem ser adquiridas com suporte, mas o ritmo e a autonomia variam. Não se espera cura em prazo determinado.","alarm":"Mudança do padrão de crises, dificuldade para engolir, perda de habilidades ou alteração persistente do sono exigem avaliação.","immediate":"Crise prolongada conforme o plano de emergência, dificuldade respiratória, engasgo importante ou alteração da consciência exigem urgência.","return":"Revise periodicamente objetivos funcionais e acompanhamento neurológico, nutricional, ortopédico e de comunicação.","sources":[{"url":"https://www.nhs.uk/conditions/angelman-syndrome/","title":"NHS — Angelman syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome de aspiração de mecônio","aliases":[],"setting":"hospital","general":"O recém-nascido com dificuldade respiratória após aspiração de mecônio precisa de avaliação e cuidado hospitalar. A equipe orientará alimentação, contato e participação da família conforme a estabilidade.","diagnosis":"A presença de mecônio no líquido não significa necessariamente aspiração. Quando há comprometimento pulmonar, podem ser necessários suporte respiratório e investigação de complicações associadas.","expected":"Muitos bebês melhoram, mas a duração e intensidade do cuidado dependem da gravidade. Quadros importantes podem exigir seguimento respiratório posterior; não se deve prometer alta em prazo fixo.","alarm":"Respiração acelerada, gemência, cansaço para alimentar ou pausas precisam ser comunicados imediatamente.","immediate":"Coloração azulada, apneia ou pouca resposta são emergências neonatais.","return":"Após alta formal, cumpra a revisão pediátrica e retorne imediatamente se houver piora da respiração, alimentação ou estado geral.","sources":[{"url":"https://medlineplus.gov/ency/article/001596.htm","title":"MedlinePlus — Meconium aspiration syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome de Aspiração Meconial","aliases":["Aspiração meconial","Síndrome de aspiração de mecônio"],"setting":"hospital","general":"A síndrome de aspiração meconial necessita avaliação e suporte neonatal hospitalar. A família deve informar mudanças de respiração, cor e alimentação à equipe.","diagnosis":"Mecônio nas vias respiratórias pode causar comprometimento pulmonar; a presença de líquido meconial isolada não confirma a síndrome.","expected":"A evolução depende da intensidade da lesão e de complicações associadas, sem prazo único de recuperação.","alarm":"Respiração acelerada, esforço para respirar, coloração azulada ou pouca resposta são alertas.","immediate":"Pausa respiratória, piora súbita ou dificuldade importante exigem intervenção imediata.","return":"Após alta, siga acompanhamento pediátrico e retorne urgentemente se reaparecerem dificuldade respiratória ou recusa alimentar.","sources":[{"url":"https://www.safercare.vic.gov.au/best-practice-improvement/clinical-guidance/neonatal/meconium-aspiration-syndrome","title":"Safer Care Victoria — Meconium aspiration syndrome","accessed":"2026-09-26"},{"url":"https://medlineplus.gov/ency/article/001596.htm","title":"MedlinePlus — Meconium aspiration syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Equivalência terminológica com “Síndrome de aspiração de mecônio”. A página de Safer Care Victoria alerta que parte do manejo pode estar desatualizada; usada apenas para quadro clínico e monitorização, sem copiar parâmetros de suporte ou reanimação.","status":"source-reviewed"},
{"name":"Síndrome de Ativação Macrofágica em Pediatria","aliases":["Síndrome de ativação macrofágica","SAM"],"setting":"hospital","general":"Procure assistência hospitalar especializada e comunique mudanças clínicas imediatamente. Leve informações da doença reumatológica e dos tratamentos.","diagnosis":"É uma complicação de inflamação excessiva que pode comprometer múltiplos órgãos e coexistir com infecção.","expected":"A resposta varia; o tratamento e a monitorização precisam ser ajustados à causa e à gravidade.","alarm":"Observe febre persistente, prostração, manchas, sangramento ou alteração neurológica.","immediate":"Confusão, dificuldade respiratória, convulsão ou deterioração rápida exige emergência.","return":"Após controle, mantenha reumatologia e exames de vigilância. Febre nova ou sinais semelhantes exigem contato precoce, sem presumir simples recaída articular.","sources":[{"url":"https://www.uclh.nhs.uk/patients-and-visitors/patient-information-pages/hlh-patient-information-page","title":"UCLH — HLH and macrophage activation syndrome","accessed":"2026-09-26"}],"reviewNotes":"Fonte descreve sobreposição com HLH secundária. SAM e todas as formas de HLH não são tratadas como equivalentes terapêuticos; requer revisão reumatológica pediátrica.","status":"source-reviewed"},
{"name":"Síndrome de Beckwith-Wiedemann","setting":"specialist","aliases":["Beckwith-Wiedemann"],"general":"Síndrome genética de manifestações variáveis exige plano de acompanhamento individualizado.","diagnosis":"Cumpra a vigilância de tumores e crescimento definida pela genética. Observe alimentação, respiração durante o sono e diferenças entre os membros.","expected":"Muitas crianças evoluem bem, mas riscos e necessidades mudam com a idade e o subtipo molecular.","alarm":"Dificuldade alimentar, aumento abdominal, massa nova ou sinais de glicose baixa exigem avaliação.","immediate":"Convulsão, sonolência intensa ou dificuldade respiratória requerem emergência.","return":"Mantenha exames programados mesmo sem sintomas; antecipe revisão diante de novas alterações e não substitua rastreamento por observação domiciliar.","sources":[{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK1394/","title":"GeneReviews — Beckwith-Wiedemann Syndrome","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Síndrome de Bernard-Soulier","aliases":["Bernard-Soulier"],"setting":"specialist","general":"Mantenha acompanhamento hematológico e informe o diagnóstico antes de procedimentos ou extrações dentárias. Evite traumas e produtos que possam aumentar sangramento sem consulta à equipe.","diagnosis":"A síndrome compromete a função das plaquetas; o plano para sangramentos deve estar disponível à família.","expected":"A tendência hemorrágica é persistente, com intensidade variável; não desaparece porque a criança está sem sintomas.","alarm":"Relate sangramento nasal repetido, hematomas extensos ou menstruação muito intensa.","immediate":"Trauma na cabeça, sangramento difícil de controlar, sangue nas fezes ou desmaio exigem emergência.","return":"Revise periodicamente hemograma, episódios de sangramento e planejamento de procedimentos.","sources":[{"url":"https://medlineplus.gov/genetics/condition/bernard-soulier-syndrome/","title":"MedlinePlus Genetics — Bernard-Soulier syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome de DiGeorge","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento multidisciplinar e leve um resumo das alterações cardíacas, imunológicas, hormonais e do desenvolvimento já identificadas.","diagnosis":"A síndrome de DiGeorge tem manifestações muito variáveis. Vacinação, procedimentos e novos tratamentos devem considerar a avaliação imunológica individual.","expected":"O crescimento e as necessidades podem mudar; não se pode prever evolução apenas pelo nome do diagnóstico.","alarm":"Observe infecções recorrentes, dificuldade alimentar, cansaço, alterações de fala ou aprendizagem e movimentos sugestivos de convulsão.","immediate":"Convulsão, falta de ar, cianose, febre com prostração ou alteração de consciência exige atendimento imediato.","return":"Retorne para revisar cálcio, imunidade, coração, audição e desenvolvimento conforme indicação; procure apoio escolar quando houver dificuldade funcional.","sources":[{"url":"https://medlineplus.gov/genetics/condition/22q112-deletion-syndrome/","title":"MedlinePlus — 22q11.2 deletion syndrome","accessed":"2026-09-26"}],"reviewNotes":"A deleção 22q11.2 é contexto frequente; não presume confirmação genética nem imunodeficiência grave em todos os pacientes.","status":"source-reviewed"},
{"name":"Síndrome de Down (Trissomia do 21)","aliases":[],"setting":"specialist","general":"Estimule comunicação, brincadeiras e autonomia com adaptações às habilidades da criança. Compartilhe objetivos com família, escola e profissionais, respeitando seu ritmo e evitando comparações.","diagnosis":"A trissomia 21 envolve necessidades variadas. O acompanhamento pediátrico e avaliações de visão, audição, linguagem e movimento ajudam a identificar apoios e condições associadas, sem presumir que todas estejam presentes.","expected":"O desenvolvimento é individual e pode continuar com apoio adequado. Não existe evolução única; mudanças ou perda de habilidades precisam ser avaliadas.","alarm":"Dificuldade alimentar, engasgos, mudanças de audição ou visão e novas limitações merecem revisão.","immediate":"Falta de ar, coloração azulada, alteração de consciência ou dificuldade importante para engolir: emergência.","return":"Mantenha os controles de saúde e reabilitação indicados e antecipe o retorno diante de mudanças funcionais.","sources":[{"url":"https://www.nhs.uk/conditions/downs-syndrome/how-to-help-children-and-young-people/","title":"NHS — Down’s syndrome: helping children and young people","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome de Edwards (Trissomia do 18)","setting":"specialist","general":"O cuidado deve respeitar as necessidades da criança e as decisões compartilhadas com a família. Mantenha um plano escrito de assistência.","diagnosis":"Organize acompanhamento multidisciplinar para alimentação, respiração, coração, desenvolvimento e conforto, com apoio genético e psicossocial.","expected":"A evolução varia entre trissomia completa, parcial e mosaico e conforme as malformações; o diagnóstico isolado não permite prever a evolução individual.","alarm":"Mudanças na alimentação, dor, respiração, alerta ou tolerância às atividades habituais justificam contato com a equipe.","immediate":"Na presença de dificuldade respiratória, cianose, convulsão ou redução importante de resposta, acione o atendimento previsto no plano de urgência.","return":"Compareça às revisões e ajuste o plano conforme crescimento, sintomas e prioridades familiares; inclua cuidados paliativos quando adequados às necessidades.","sources":[{"url":"https://www.nhs.uk/conditions/edwards-syndrome/","title":"NHS — Edwards' syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Síndrome de Evans","aliases":[],"setting":"specialist","general":"Mantenha os controles de sangue e as consultas, mesmo quando a criança parecer bem; comunique novos sintomas precocemente.","diagnosis":"A síndrome de Evans envolve destruição imune de células sanguíneas, geralmente hemácias e plaquetas, podendo incluir neutrófilos.","expected":"Pode alternar melhora e recaídas; a resposta e a duração do tratamento variam entre pacientes.","alarm":"Observe palidez, cansaço, manchas roxas, sangramento nasal, icterícia ou febre, principalmente se houver neutropenia.","immediate":"Sangramento que não cessa, desmaio, falta de ar importante ou febre com abatimento exigem pronto atendimento.","return":"Reavalie regularmente com hematologia, incluindo investigação de condições associadas e efeitos do tratamento.","sources":[{"url":"https://my.clevelandclinic.org/health/diseases/evans-syndrome","title":"Cleveland Clinic — Evans Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Fonte institucional inclui diferentes idades; seguimento pediátrico precisa individualização.","status":"source-reviewed"},
{"name":"Síndrome de Guillain-Barré em Pediatria","aliases":[],"setting":"hospital","general":"Fraqueza que progride, especialmente após infecção, necessita avaliação urgente; informe dificuldade para caminhar, engolir ou movimentar o rosto.","diagnosis":"A síndrome de Guillain-Barré pode afetar nervos dos membros, músculos respiratórios e controle dos batimentos cardíacos.","expected":"Os sintomas podem piorar inicialmente; a recuperação frequentemente exige meses e reabilitação, com grande variação individual.","alarm":"Observe progressão da fraqueza, voz diferente, engasgos, palpitações ou incapacidade de ficar em pé.","immediate":"Dificuldade para respirar ou engolir e piora rápida exigem emergência hospitalar.","return":"Após estabilização, mantenha reabilitação e seguimento neurológico; alta e retorno às atividades precisam ser individualizados.","sources":[{"url":"https://www.nhs.uk/conditions/guillain-barre-syndrome/","title":"NHS — Guillain-Barré syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome de Hiper-IgD","setting":"specialist","aliases":["Hiper-IgD","Deficiência de mevalonato quinase","HIDS"],"general":"Condição genética autoinflamatória causa crises recorrentes de febre; os episódios não são contagiosos.","diagnosis":"Registre duração e sintomas das crises e siga o plano da equipe. Não atribua automaticamente toda febre à síndrome.","expected":"As crises podem ficar menos frequentes com o crescimento, mas o curso varia e requer acompanhamento.","alarm":"Crise diferente do habitual, desidratação, dor intensa ou febre durante imunossupressão exigem avaliação.","immediate":"Prostração importante, confusão ou dificuldade respiratória requerem emergência.","return":"Mantenha reumatologia e monitorização de inflamação e complicações; combine apoio escolar para ausências recorrentes.","sources":[{"url":"https://rheumatology.org/patients/hyperimmunoglobulin-d-syndrome-hids-mevalonate-kinase-deficiency-mkd-juvenile","title":"ACR — HIDS / Mevalonate Kinase Deficiency","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Síndrome de Hyper-IgE","aliases":["Síndrome hiper-IgE"],"setting":"specialist","general":"Mantenha acompanhamento com imunologia, higiene cuidadosa da pele e atenção a sintomas respiratórios. Informe infecções repetidas, fraturas e alterações dentárias.","diagnosis":"Há diferentes condições genéticas com IgE elevada; o subtipo precisa ser esclarecido. Um resultado isolado de IgE não estabelece este diagnóstico.","expected":"É uma condição de acompanhamento prolongado. O risco e o tratamento dependem do defeito imunológico e de complicações, sem previsão única de evolução.","alarm":"Observe novos abscessos, lesões infectadas, tosse persistente, febre ou piora da disposição.","immediate":"Falta de ar, rápida expansão de infecção ou importante prostração exige avaliação imediata, com informação do diagnóstico imunológico.","return":"Procure atendimento precoce para cada nova infecção e mantenha as revisões especializadas. Não modifique medidas preventivas prescritas sem discutir com a equipe.","sources":[{"url":"https://www.medlineplus.gov/ency/article/001311.htm","title":"MedlinePlus — Hyperimmunoglobulin E syndrome","accessed":"2026-09-26"}],"reviewNotes":"Fonte foca predominantemente síndrome relacionada a STAT3. Não extrapola prognóstico, transplante ou terapias para todos os defeitos genéticos; subtipo deve ser confirmado. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"Síndrome de Insensibilidade Androgênica","aliases":[],"setting":"specialist","general":"Mantenha equipe especializada e comunicação respeitosa, adequada à idade, sobre o corpo e o desenvolvimento.","diagnosis":"As formas completa e parcial têm características diferentes. Exames, tratamento e decisões devem ser individualizados e compartilhados.","expected":"O acompanhamento inclui puberdade, saúde física e apoio psicológico ao longo do desenvolvimento.","alarm":"Comunique dor genital ou inguinal, mudanças inesperadas e sofrimento emocional.","immediate":"Dor intensa de início súbito ou risco imediato à própria segurança exige avaliação urgente.","return":"Mantenha retornos regulares e oportunidade de esclarecer dúvidas. Não use hormônios nem decida procedimentos apenas pelo nome do diagnóstico.","sources":[{"url":"https://www.nhs.uk/conditions/androgen-insensitivity-syndrome/","title":"NHS — Androgen insensitivity syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome de Klinefelter (47,XXY)","aliases":["Síndrome de Klinefelter"],"setting":"specialist","general":"Mantenha acompanhamento do crescimento, aprendizagem e puberdade. Ofereça apoio escolar, de linguagem e emocional conforme as necessidades, evitando expectativas iguais para todas as crianças.","diagnosis":"Na síndrome de Klinefelter, os efeitos podem ser discretos ou envolver desenvolvimento e função hormonal. Tratamentos e discussões sobre fertilidade devem ser individualizados e adequados à idade.","expected":"Muitas pessoas têm vida saudável e independente com acompanhamento. As necessidades podem mudar na adolescência; não se prevê a evolução apenas pelo cariótipo.","alarm":"Atraso puberal, dificuldade escolar persistente, fadiga importante ou sofrimento emocional justificam revisão antecipada.","immediate":"O diagnóstico estável não costuma gerar emergência específica; desmaio, dor torácica ou risco imediato de autoagressão exigem atendimento por suas próprias causas.","return":"Mantenha revisões com pediatria/endocrinologia e equipe de apoio, sem iniciar hormônios por conta própria.","sources":[{"url":"https://www.nhs.uk/conditions/klinefelters-syndrome/","title":"NHS — Klinefelter syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome de Lennox-Gastaut","aliases":[],"setting":"specialist","general":"Mantenha o plano de crises acessível aos cuidadores e à escola. Proteja contra quedas e supervisione banho e atividades de risco conforme orientação.","diagnosis":"A síndrome pode causar diferentes tipos de crise e dificuldades de desenvolvimento. Registre episódios e não modifique o tratamento sem neurologia.","expected":"O controle pode ser difícil e necessitar ajustes continuados; as metas incluem reduzir crises, lesões e impacto funcional.","alarm":"Observe aumento de quedas, crises em sequência, sonolência diferente e dificuldade de engolir.","immediate":"Crise com cinco minutos, repetição sem recuperação, trauma importante ou dificuldade respiratória exige emergência.","return":"Retorne para revisar controle e desenvolvimento. Durante crises, afaste perigos, proteja a cabeça e não coloque nada na boca.","sources":[{"url":"https://medlineplus.gov/genetics/condition/lennox-gastaut-syndrome/","title":"MedlinePlus — Lennox-Gastaut syndrome","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/epilepsy/first-aid-for-seizures/index.html","title":"CDC — First Aid for Seizures","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Síndrome de Majeed","aliases":[],"setting":"specialist","general":"Mantenha reumatologia e hematologia pediátricas, com acompanhamento de crescimento, dor, mobilidade e anemia.","diagnosis":"Inflamação óssea recorrente e anemia podem fazer parte da síndrome; a intensidade varia entre pessoas.","expected":"É condição de evolução prolongada, com períodos de melhora e recaída; não há prazo único de recuperação.","alarm":"Observe febre, dor óssea nova, articulações inchadas, palidez ou cansaço crescente.","immediate":"Falta de ar, prostração importante ou incapacidade súbita de usar um membro exige avaliação urgente.","return":"Retorne no calendário definido e antecipe quando o padrão mudar; não atribua automaticamente toda febre à doença.","sources":[{"url":"https://medlineplus.gov/genetics/condition/majeed-syndrome/","title":"MedlinePlus Genetics — Majeed syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome de Mallory-Weiss","aliases":[],"setting":"urgent","general":"Procure avaliação diante de vômito com sangue e informe vômitos ou tosse intensos anteriores.","diagnosis":"Uma lesão na junção do esôfago com o estômago pode sangrar. A confirmação e gravidade dependem da avaliação.","expected":"Muitas lesões cicatrizam, mas sangramento significativo pode exigir endoscopia e suporte hospitalar.","alarm":"Observe sangue vivo, fezes negras, palidez, tontura ou fraqueza.","immediate":"Sangramento volumoso, desmaio, falta de ar ou pouca resposta exige emergência imediata.","return":"Após alta formal, siga tratamento da causa dos vômitos e orientações de retorno. Novo sangue exige reavaliação, mesmo que o primeiro episódio tenha parado.","sources":[{"url":"https://medlineplus.gov/ency/article/000269.htm","title":"MedlinePlus — Mallory-Weiss tear","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome de Muckle-Wells","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento reumatológico e os controles de audição e função renal indicados; registre episódios inflamatórios e seus gatilhos.","diagnosis":"Muckle-Wells é uma síndrome autoinflamatória que pode causar febre, erupção cutânea e dores articulares.","expected":"A evolução é variável; o controle da inflamação procura reduzir crises e complicações, sem prazo único de cura.","alarm":"Informe perda auditiva, inchaço ou alteração urinária, além de febre fora do padrão habitual.","immediate":"Prostração intensa, pouca urina, dificuldade respiratória ou sinais de infecção importante exigem atendimento imediato.","return":"Não atribua toda febre automaticamente à síndrome; retorne conforme a vigilância renal e auditiva planejada.","sources":[{"url":"https://medlineplus.gov/genetics/condition/cryopyrin-associated-periodic-syndromes/","title":"MedlinePlus Genetics — Cryopyrin-associated periodic syndromes","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Recorte específico Muckle-Wells; não equivale aos demais fenótipos CAPS.","status":"source-reviewed"},
{"name":"Síndrome de Nelson","aliases":[],"setting":"specialist","general":"Mantenha endocrinologia pediátrica e equipe hipofisária, levando exames e registros da adrenalectomia. Não interrompa a reposição prescrita; mantenha acessível o plano de emergência adrenal.","diagnosis":"A síndrome requer progressão ou nova identificação de tumor corticotrófico após adrenalectomia bilateral por doença de Cushing; ACTH elevado isolado não basta.","expected":"Evolução depende de crescimento, extensão e tratamento; o risco exige vigilância prolongada, inclusive na transição para acompanhamento adulto.","alarm":"Informe hiperpigmentação crescente, cefaleia diferente, alteração visual ou falha na tomada da reposição.","immediate":"Perda visual súbita, alteração de consciência, colapso ou vômitos impedindo a reposição exigem emergência e aplicação do plano individual de crise adrenal.","return":"Combine retornos, ACTH e ressonância com a equipe; confirme também crescimento, puberdade, demais funções hipofisárias e possibilidade de suporte psicossocial.","sources":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8060870/","title":"Reincke et al. — Corticotroph progression: consensus 2021","accessed":"2026-09-27"},{"url":"https://journals.plos.org/plosone/article?id=10.1371%2Fjournal.pone.0226033","title":"Pasternak-Pietrzak et al. — Childhood Cushing: long-term follow-up","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Adrenal_crisis_and_acute_adrenal_insufficiency/","title":"RCH — Adrenal crisis","accessed":"2026-09-27"}],"reviewNotes":"Revisão documental de acompanhamento, não homologação. Intervalos adultos e regimes terapêuticos não foram transpostos; limitações pediátricas explicitadas.","status":"source-reviewed","evidenceSummary":"Consenso 2021: definição radiológica e vigilância, evidência sobretudo adulta. Coorte pediátrica PLoS 2019: 29 tratados na infância, apenas três adrenalectomizados e um caso de Nelson; não estima com precisão risco ou intervalo infantil. RCH fundamenta a segurança adrenal.","decisionSupport":{"summary":"Confirmar diagnóstico documentado e planos de tumor e insuficiência adrenal; o título não exige subtipos para estas orientações gerais.","requirements":["Adrenalectomia bilateral por Cushing e datas; imagens seriadas e evolução do ACTH.","Visão, cefaleia, crescimento/puberdade; reposição, tolerância oral e plano de emergência.","Responsável pelo seguimento; calendário individual de exames e revisão multidisciplinar."],"branchRequired":false,"branches":[]},"revisedAt":"2026-09-27"},
{"name":"Síndrome de Noonan","aliases":[],"setting":"specialist","general":"Mantenha acompanhamento coordenado e leve os exames aos profissionais envolvidos. Informe o diagnóstico antes de procedimentos e avise sobre sangramento fácil ou antecedentes cardíacos.","diagnosis":"A síndrome de Noonan pode afetar coração, crescimento, coagulação e desenvolvimento, com grande variação individual. A equipe definirá quais exames e apoios são necessários; não presuma todas as manifestações.","expected":"Muitas pessoas têm boa qualidade de vida com seguimento. A evolução depende principalmente dos órgãos comprometidos e não pode ser prevista apenas pelo nome da síndrome.","alarm":"Palpitações, cansaço novo, sangramento fora do habitual, dificuldade alimentar ou perda de habilidades exigem avaliação.","immediate":"Desmaio, dor no peito, falta de ar importante ou sangramento intenso: emergência.","return":"Mantenha controles de cardiologia, crescimento e desenvolvimento conforme o plano, inclusive quando não houver sintomas aparentes.","sources":[{"url":"https://www.nhs.uk/conditions/noonan-syndrome/","title":"NHS — Noonan syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome de Patau (Trissomia do 13)","aliases":["Trissomia 13","Síndrome de Patau"],"setting":"specialist","general":"Construa com a equipe um plano individual de alimentação, conforto, acompanhamento e atendimento em intercorrências. Peça apoio psicológico e aconselhamento genético.","diagnosis":"As alterações associadas e sua intensidade variam, inclusive entre formas completas, mosaico e parciais. As decisões devem considerar necessidades da criança e objetivos compartilhados com a família.","expected":"A condição pode ser grave, mas a evolução individual não deve ser prevista apenas pelo nome. Não há prazo único de sobrevida ou recuperação.","alarm":"Observe dificuldades alimentares, dor, piora respiratória, menor resposta ou alteração do padrão habitual.","immediate":"Dificuldade respiratória, convulsão ou redução acentuada da resposta exige contato imediato com a equipe e execução do plano de emergência acordado.","return":"Mantenha revisões proporcionais às necessidades, incluindo suporte à família. Reavalie o plano quando houver mudanças clínicas ou dos objetivos de cuidado.","sources":[{"url":"https://www.nhs.uk/conditions/pataus-syndrome/","title":"NHS — Patau syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome de PFAPA","setting":"specialist","general":"Registre datas, duração da febre, aftas, dor de garganta e gânglios. Ofereça líquidos e acompanhe a disposição durante os episódios.","diagnosis":"A síndrome não é contagiosa. Novas febres precisam ser comparadas ao padrão habitual; uma criança com PFAPA também pode adquirir infecções.","expected":"É comum estar bem e crescer normalmente entre episódios. As crises costumam tornar-se menos frequentes com o tempo, mas podem persistir.","alarm":"Febre diferente do padrão, sintomas entre crises, perda de peso ou crescimento inadequado exigem reavaliação do diagnóstico.","immediate":"Procure pronto atendimento diante de dificuldade respiratória, prostração intensa, desidratação, convulsão ou outros sinais de doença grave.","return":"Mantenha seguimento com pediatria/reumatologia e discuta crises frequentes ou incapacitantes; não altere o plano de controle por conta própria.","sources":[{"url":"https://rheumatology.org/patients/periodic-fever-aphthous-stomatitis-pharyngitis-adenitis-syndrome-pfapa-juvenile","title":"American College of Rheumatology — PFAPA","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Síndrome de Potter","aliases":["Sequência de Potter"],"setting":"hospital","general":"O cuidado deve ser planejado com neonatologia, nefrologia e a família. As decisões consideram conforto, função respiratória e possibilidades de suporte.","diagnosis":"A sequência de Potter reúne alterações relacionadas à falta de líquido amniótico, frequentemente associadas a doença renal ou urinária.","expected":"O prognóstico depende principalmente do desenvolvimento dos pulmões e da função renal; não é igual em todas as causas.","alarm":"Observe dificuldade respiratória, coloração azulada e ausência ou redução importante da urina.","immediate":"Alteração respiratória ou pouca resposta requer avaliação imediata da equipe neonatal.","return":"Quando houver condições de alta, o plano deve especificar suporte renal, respiratório, nutrição e acompanhamento familiar.","sources":[{"url":"https://www.jstage.jst.go.jp/article/jjspnm/60/1/60_122/_article/-char/en","title":"Sumi et al. — Perinatal palliative care in Potter sequence","accessed":"2026-09-26"}],"reviewNotes":"Relato primário sustenta variabilidade e cuidado multidisciplinar; não presume fatalidade universal nem alta possível.","status":"source-reviewed"},
{"name":"Síndrome de Prader-Willi","aliases":[],"setting":"specialist","general":"Organize refeições e acesso a alimentos conforme plano nutricional, com rotina previsível e atividade adaptada. Lactentes podem precisar de apoio à alimentação antes da fase de apetite excessivo.","diagnosis":"A síndrome de Prader-Willi exige cuidado multidisciplinar de crescimento, peso, sono, hormônios, desenvolvimento e comportamento. Evite punições ou mudanças bruscas de rotina para controlar a alimentação.","expected":"É uma condição permanente, com necessidades que mudam conforme a idade. Apoio contínuo pode melhorar saúde e autonomia, sem prometer evolução uniforme.","alarm":"Ganho rápido de peso, ronco com pausas, feridas infectadas ou mudanças importantes de comportamento precisam de avaliação.","immediate":"Pausa respiratória, dificuldade para despertar, engasgo ou alteração mental aguda com risco de segurança exigem urgência.","return":"Revise periodicamente nutrição, sono, desenvolvimento e saúde mental com a equipe responsável.","sources":[{"url":"https://www.nhs.uk/conditions/prader-willi-syndrome/living-with/","title":"NHS — Living with Prader-Willi syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome de Ramsay Hunt","aliases":["Herpes-zóster ótico"],"setting":"urgent","general":"Procure avaliação assim que notar fraqueza facial, dor e bolhas perto do ouvido. Proteja o olho conforme instrução profissional se não fechar.","diagnosis":"A síndrome está relacionada à reativação do vírus da varicela e pode comprometer audição e equilíbrio.","expected":"A recuperação é variável e pode ser incompleta; acompanhamento ajuda a reconhecer sequelas e necessidades de reabilitação.","alarm":"Observe dor ocular, visão alterada, piora da audição, vertigem ou dificuldade para engolir.","immediate":"Alteração visual, incapacidade de proteger o olho ou novos sinais neurológicos exigem atendimento imediato.","return":"Mantenha seguimento de face, audição e olhos conforme os déficits identificados.","sources":[{"url":"https://www.med.unc.edu/ent/facialnervecenter/conditions/2567-2/","title":"UNC Facial Nerve Center — Ramsay Hunt Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Fonte institucional geral; orientações de proteção e avaliação, sem extrapolar posologia adulta.","status":"source-reviewed"},
{"name":"Síndrome de Rett","aliases":["Rett"],"setting":"specialist","general":"Mantenha acompanhamento multidisciplinar e o plano de comunicação, alimentação, mobilidade e prevenção de complicações. Observe mudanças no padrão habitual da criança.","diagnosis":"A síndrome pode afetar desenvolvimento, movimento, respiração e controle de crises; necessidades variam entre pessoas e fases da vida.","expected":"A evolução é prolongada e variável, sem prazo de cura; apoio e reabilitação buscam preservar conforto e participação.","alarm":"Relate dificuldade para engolir, perda de peso, piora da mobilidade ou novas crises.","immediate":"Crise prolongada, engasgo com dificuldade respiratória ou pouca resposta exigem emergência.","return":"Cumpra seguimento neurológico, nutricional e ortopédico conforme as necessidades.","sources":[{"url":"https://www.nhs.uk/conditions/rett-syndrome/","title":"NHS — Rett syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome de Shwachman-Diamond","aliases":["Shwachman-Diamond"],"setting":"specialist","general":"Mantenha seguimento com hematologia e equipe nutricional, observando crescimento, evacuações e infecções. Siga o plano individual de reposição e prevenção.","diagnosis":"A síndrome pode afetar medula óssea, pâncreas e ossos; febre merece atenção especial quando há neutropenia.","expected":"As manifestações variam e podem mudar com a idade; a melhora digestiva não elimina a necessidade de vigilância hematológica.","alarm":"Relate perda de peso, diarreia gordurosa, hematomas, palidez ou infecções recorrentes.","immediate":"Febre em criança neutropênica, prostração, dificuldade respiratória ou sangramento importante exigem avaliação imediata.","return":"Cumpra exames e revisões para nutrição, crescimento e alterações da medula.","sources":[{"url":"https://medlineplus.gov/genetics/condition/shwachman-diamond-syndrome/","title":"MedlinePlus Genetics — Shwachman-Diamond syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome de Sjögren em Pediatria","aliases":["Síndrome de Sjögren"],"setting":"specialist","general":"Siga cuidados de boca e olhos orientados e mantenha avaliações odontológicas. Relate sintomas mesmo quando não houver ressecamento evidente.","diagnosis":"A apresentação infantil pode diferir da adulta. A avaliação identifica inflamação das glândulas e possível comprometimento de outros órgãos.","expected":"A condição é crônica, com intensidade variável; o objetivo é controlar sintomas e prevenir danos.","alarm":"Observe aumento persistente de glândulas, dor ocular, visão alterada, cansaço importante ou sintomas respiratórios.","immediate":"Dor ocular com redução da visão, dificuldade respiratória ou sintomas neurológicos novos exigem atendimento imediato.","return":"Mantenha seguimento reumatológico, oftalmológico e odontológico, com revisão do plano conforme as manifestações.","sources":[{"url":"https://doi.org/10.1093/rheumatology/keae152","title":"BSR — Management of adult and juvenile onset Sjögren disease","accessed":"2026-09-26"}],"reviewNotes":"Diretriz inclui início juvenil; recomendações adultas não foram convertidas em doses pediátricas.","status":"source-reviewed"},
{"name":"Síndrome de Tourette","aliases":["Síndrome de Tourette na Criança"],"setting":"specialist","general":"Explique aos cuidadores e à escola que tiques são involuntários. Evite repreender, ridicularizar ou exigir que a criança os suprima continuamente.","diagnosis":"Registre o impacto em aprendizagem, sono, relações e atividades; o tratamento é individualizado conforme prejuízo e condições associadas.","expected":"Os tiques podem mudar de tipo e intensidade, melhorar na adolescência ou persistir; não existe trajetória única.","alarm":"Observe dor, lesões por movimentos, sofrimento, bullying ou dificuldade importante para participar das atividades.","immediate":"Autoagressão, risco suicida, lesão importante ou dificuldade para respirar/engolir exige atendimento imediato.","return":"Retorne se houver prejuízo funcional ou mudança marcante; discuta intervenções comportamentais e apoio escolar, sem atribuir todo comportamento à síndrome.","sources":[{"url":"https://www.cdc.gov/tourette-syndrome/about/index.html","title":"CDC — About Tourette Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Síndrome de Turner (45,X)","aliases":["Síndrome de Turner"],"setting":"specialist","general":"Mantenha as consultas e exames programados e compartilhe o plano com a escola quando houver necessidade de apoio. Não inicie hormônios ou suplementos sem orientação especializada.","diagnosis":"A síndrome de Turner 45,X exige avaliação individual de crescimento, puberdade e possíveis condições associadas. Alterações do coração, pressão, rins, tireoide e audição precisam ser investigadas conforme a equipe.","expected":"É uma condição permanente, com tratamentos e apoios que podem melhorar saúde e qualidade de vida. O acompanhamento muda conforme a idade e os achados.","alarm":"Mudanças na capacidade de exercício, pressão elevada, perda auditiva ou sintomas urinários merecem avaliação.","immediate":"Dor súbita no peito ou costas, desmaio, falta de ar intensa ou alteração neurológica: emergência.","return":"Mantenha endocrinologia e demais controles indicados; ausência de sintomas não dispensa vigilância cardiovascular.","sources":[{"url":"https://www.nhs.uk/conditions/turner-syndrome/","title":"NHS — Turner syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. Orientação geral da síndrome; frequência de exames e recomendações cardiovasculares precisam ser individualizadas conforme cardiologia e fenótipo.","status":"source-reviewed"},
{"name":"Síndrome de West","setting":"urgent","general":"Espasmos em séries, especialmente ao despertar, precisam de avaliação neurológica urgente. Não espere uma consulta distante para mostrar novos episódios.","diagnosis":"Se possível, registre vídeo sem atrasar atendimento. A investigação costuma incluir eletroencefalograma urgente e avaliação do desenvolvimento.","expected":"O resultado depende da causa e da resposta ao cuidado; o controle precoce é importante, mas não permite garantir recuperação do desenvolvimento.","alarm":"Novos espasmos, perda de habilidades, menor interação ou aumento das séries exigem comunicação imediata.","immediate":"Vá ao hospital na suspeita de novos espasmos; acione emergência se houver dificuldade respiratória, cianose ou ausência de recuperação da consciência.","return":"Após atendimento, mantenha neurologia, exames e plano de intercorrências escritos. A alta não significa que o seguimento ou tratamento possa ser interrompido.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Infantile_Spasms/","title":"RCH — Infantile spasms","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Síndrome de Williams","aliases":["Síndrome de Williams-Beuren"],"setting":"specialist","general":"Mantenha acompanhamento do coração, pressão arterial, crescimento e desenvolvimento. Informe o diagnóstico antes de qualquer sedação, anestesia ou procedimento.","diagnosis":"Alterações cardiovasculares, de cálcio, audição e aprendizagem podem ocorrer, mas variam entre crianças. O plano de exames deve ser individualizado.","expected":"O acompanhamento é duradouro e busca prevenir complicações e apoiar participação e aprendizagem. Não há um prazo único de evolução ou de aquisição de habilidades.","alarm":"Observe cansaço novo, dor no peito, redução da tolerância ao esforço, problemas alimentares ou mudança da disposição.","immediate":"Desmaio, dor torácica importante, dificuldade respiratória ou redução de resposta exige atendimento imediato.","return":"Compareça às revisões cardiológicas e demais avaliações indicadas. Comunique dificuldades escolares ou sensoriais para adaptar apoio e não atribua automaticamente sintomas novos à síndrome.","sources":[{"url":"https://www.medlineplus.gov/genetics/condition/williams-syndrome/","title":"MedlinePlus Genetics — Williams syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome de Wiskott-Aldrich","aliases":[],"setting":"specialist","general":"Mantenha seguimento com imunologia e hematologia e leve o plano individual a outros serviços. Observe infecções, sangramentos e alterações da pele, informando tratamentos em uso.","diagnosis":"A síndrome de Wiskott-Aldrich combina alterações imunológicas e das plaquetas, frequentemente com eczema. Vacinas, procedimentos e medicamentos novos precisam ser conferidos com a equipe.","expected":"A gravidade varia e pode exigir terapias especializadas. A melhora de uma infecção ou do eczema não encerra a vigilância para sangramento e outras complicações.","alarm":"Febre, tosse persistente, diarreia, novas manchas roxas ou sangramento de mucosas exigem contato médico rápido.","immediate":"Sangramento importante, trauma craniano, falta de ar, prostração acentuada ou alteração da consciência exigem emergência imediata.","return":"Cumpra retornos e exames e atualize o plano de atendimento após internações ou mudanças do tratamento.","sources":[{"url":"https://medlineplus.gov/genetics/condition/wiskott-aldrich-syndrome/","title":"MedlinePlus Genetics — Wiskott-Aldrich syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome do Anticorpo Antifosfolípideo (SAF) em Pediatria","aliases":["Síndrome antifosfolípide","Síndrome do anticorpo antifosfolípideo"],"setting":"specialist","general":"Siga o plano de prevenção de trombose e acompanhamento especializado. Informe todos os tratamentos antes de procedimentos e atividades com risco de trauma.","diagnosis":"A síndrome exige contexto clínico e anticorpos persistentes; um exame positivo isolado não equivale automaticamente ao diagnóstico.","expected":"O risco de novos eventos e o seguimento variam conforme trombose prévia e doenças associadas.","alarm":"Observe inchaço doloroso de um membro, falta de ar, dor torácica ou sintomas neurológicos.","immediate":"Falta de ar súbita, desmaio, fraqueza de um lado ou sangramento importante exigem emergência.","return":"Mantenha controle com hematologia e reumatologia conforme o caso e revisão da segurança terapêutica.","sources":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28473426/","title":"SHARE — European recommendations for paediatric antiphospholipid syndrome","accessed":"2026-09-26"}],"reviewNotes":"Recomendações pediátricas reconhecem evidência limitada; não aplicar automaticamente critérios ou tratamento de adulto.","status":"source-reviewed"},
{"name":"Síndrome do Bebê Chiador","setting":"specialist","aliases":["Sibilância recorrente do lactente","Bebê chiador"],"general":"Chiado recorrente em lactentes é uma descrição clínica, não uma causa única nem confirmação automática de asma.","diagnosis":"Evite fumaça e siga o plano individual. Registre episódios, gatilhos e alimentação; técnicas de dispositivos devem ser revistas quando prescritos.","expected":"Algumas crianças melhoram com a idade; persistência ou início muito precoce exige investigar outras causas.","alarm":"Dificuldade para mamar, baixo ganho de peso, chiado contínuo ou crises frequentes precisam de revisão.","immediate":"Pausas respiratórias, coloração azulada ou esforço intenso exigem emergência.","return":"Mantenha pediatria e reavalie o diagnóstico e o plano após cada piora relevante.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Preschool_asthma_(1-5_years)/","title":"RCH — Preschool asthma (1–5 years)","accessed":"2026-09-26"},{"url":"https://cps.ca/en/documents/position/bronchiolitis","title":"Canadian Paediatric Society — Bronchiolitis","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Bebê chiador é uma síndrome, não sinônimo automático de asma. Fonte de asma cobre 1–5 anos; fonte de bronquiolite complementa lactentes. Início precoce, baixo ganho e sintomas persistentes exigem investigação individual. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Síndrome do bebê sacudido","aliases":["Traumatismo craniano abusivo"],"setting":"hospital","general":"Suspeita de sacudida violenta ou lesão precisa de emergência imediata e proteção da criança. Relate o ocorrido com clareza; não sacuda para tentar acordá-la.","diagnosis":"Pode haver lesão grave sem marcas externas. A investigação deve avaliar o conjunto clínico e outras causas, sem concluir autoria por um sinal isolado.","expected":"A evolução depende da lesão e da rapidez do cuidado; podem existir sequelas que exigem reabilitação e acompanhamento prolongado.","alarm":"Observe vômitos, irritabilidade intensa, recusa alimentar, sonolência ou mudança de comportamento após o episódio.","immediate":"Convulsão, dificuldade respiratória, perda de consciência ou pouca resposta exige socorro imediato; não ofereça nada pela boca enquanto aguarda orientação.","return":"Após estabilização, siga o plano de proteção, neurologia e desenvolvimento. Para prevenir novos episódios, nunca sacuda e peça ajuda quando estiver sobrecarregado.","sources":[{"url":"https://medlineplus.gov/ency/article/007578.htm","title":"MedlinePlus — Shaken baby syndrome","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/child-abuse-neglect/about/about-abusive-head-trauma.html","title":"CDC — About abusive head trauma","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome do Choque Tóxico","aliases":["Choque tóxico"],"setting":"hospital","general":"Acione assistência de emergência. Informe feridas, procedimentos recentes e uso de produtos intravaginais quando aplicável.","diagnosis":"É uma infecção grave que pode evoluir rapidamente com comprometimento de múltiplos órgãos e requer tratamento hospitalar.","expected":"A resposta depende da rapidez do atendimento e do controle da infecção; não aguarde melhora espontânea.","alarm":"Observe febre, erupção cutânea, vômitos, diarreia ou dores musculares intensas.","immediate":"Confusão, dificuldade respiratória, desmaio ou pele azulada, muito pálida ou manchada exige emergência imediata.","return":"Após alta, mantenha revisão e as medidas preventivas individualizadas; recorrência de sintomas exige avaliação urgente.","sources":[{"url":"https://www.nhs.uk/conditions/toxic-shock-syndrome/","title":"NHS — Toxic shock syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome do intestino irritável","aliases":[],"setting":"home","general":"Mantenha rotina de alimentação, sono e atividades, registrando sintomas sem restringir muitos alimentos por conta própria. Apoio psicológico pode ajudar no controle da dor e na participação escolar.","diagnosis":"A síndrome do intestino irritável relaciona dor ao hábito intestinal. O diagnóstico exige avaliação de sinais que indiquem outras doenças; a dor não deve ser desconsiderada.","expected":"Os sintomas podem oscilar e exigir ajustes de tratamento. A meta é melhorar conforto e funcionamento, sem prometer desaparecimento imediato ou permanente.","alarm":"Perda de peso, crescimento insuficiente, febre, diarreia noturna, vômitos persistentes ou sangue nas fezes exigem reavaliação do diagnóstico.","immediate":"Dor abdominal intensa progressiva, sangramento importante, desmaio ou desidratação exigem urgência.","return":"Retorne se o plano não ajudar ou se surgirem sinais novos; mudanças dietéticas devem preservar a nutrição.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/irritable-bowel-syndrome-children/treatment","title":"NIDDK — Treatment for Irritable Bowel Syndrome in Children","accessed":"2026-09-26"},{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/irritable-bowel-syndrome-children/diagnosis","title":"NIDDK — Diagnosis of Irritable Bowel Syndrome in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome do QT Longo Pediátrico","aliases":["Síndrome do QT longo"],"setting":"specialist","general":"Siga o plano cardiológico e consulte a equipe antes de usar medicamentos ou suplementos. Atividades físicas exigem orientação individual.","diagnosis":"A alteração elétrica pode provocar arritmias mesmo sem sintomas frequentes. A avaliação familiar pode ser indicada.","expected":"O acompanhamento é contínuo; o risco depende da causa, exames e histórico individual.","alarm":"Informe palpitações, desmaios, convulsões aparentes ou perdas de consciência.","immediate":"Desmaio com recuperação incompleta ou ausência de respiração normal exige socorro imediato.","return":"Retorne regularmente e antecipe após qualquer episódio. Previna desidratação e confirme com cardiologia os cuidados em doenças intercorrentes.","sources":[{"url":"https://www.nhs.uk/conditions/long-qt-syndrome/","title":"NHS — Long QT syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Síndrome do X Frágil","setting":"specialist","general":"Mantenha apoio familiar, escolar e terapias direcionadas às necessidades da criança. Valorize comunicação, participação e habilidades funcionais.","diagnosis":"Procure aconselhamento genético e organize o plano com pediatria, escola e profissionais de desenvolvimento. Intervenção precoce pode ajudar a adquirir habilidades.","expected":"É uma condição genética sem cura estabelecida; aprendizagem e autonomia variam. Metas precisam ser individuais e revistas durante o crescimento.","alarm":"Perda de habilidades já adquiridas, mudança importante de comportamento ou novos episódios suspeitos de convulsão exigem avaliação.","immediate":"Procure emergência se houver convulsão prolongada, dificuldade respiratória, alteração importante de consciência ou risco imediato à segurança.","return":"Mantenha revisões do desenvolvimento, comportamento e condições associadas; ajuste estratégias junto aos cuidadores e à escola conforme necessidades e resultados.","sources":[{"url":"https://www.cdc.gov/fragile-x-syndrome/about/index.html","title":"CDC — About Fragile X Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Síndrome dos Vômitos Cíclicos","aliases":[],"setting":"specialist","general":"Registre crises e possíveis gatilhos, preserve sono regular e siga o plano de início dos episódios; ambiente tranquilo pode ajudar.","diagnosis":"Vômitos cíclicos apresentam episódios repetidos com intervalos de melhora, mas outras causas precisam ser excluídas.","expected":"Frequência e duração variam; a prevenção pode reduzir crises, sem garantia de desaparecimento imediato.","alarm":"Informe mudança do padrão, perda de peso, dificuldade para beber ou redução da urina.","immediate":"Sangue no vômito, prostração intensa ou incapacidade de hidratação exigem pronto atendimento.","return":"Retorne para revisar gatilhos e resposta; vômitos graves podem exigir hidratação hospitalar.","sources":[{"url":"https://www.niddk.nih.gov/health-information/digestive-diseases/cyclic-vomiting-syndrome/treatment","title":"NIDDK — Treatment of Cyclic Vomiting Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Síndrome Febril em Pediatria","aliases":[],"setting":"home","general":"Após avaliação e orientação para casa, ofereça líquidos e observe comportamento, respiração e urina, além da temperatura.","diagnosis":"Febre é um sinal com várias causas; sua altura ou resposta ao antitérmico não determina sozinha a gravidade.","expected":"A evolução depende da causa; febre persistente por cinco dias ou mais necessita reavaliação.","alarm":"Observe piora do estado geral, recusa de líquidos, manchas preocupantes ou menor quantidade de urina.","immediate":"Bebê menor de três meses com febre, ou qualquer criança com dificuldade respiratória, alteração de consciência ou má circulação, precisa de avaliação imediata.","return":"Retorne antes do previsto se houver piora.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/febrile_child/","title":"RCH — Febrile child","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Não representa liberação domiciliar automática; neonatos e lactentes pequenos requerem limiar de avaliação mais baixo.","status":"source-reviewed"},
{"name":"Síndrome Hemolítico-Urêmica em Pediatria","aliases":["Síndrome hemolítico-urêmica","SHU"],"setting":"hospital","general":"A suspeita exige avaliação hospitalar. Informe diarreia recente, alimentos de risco e redução da urina; não force grandes volumes de líquido sem orientação.","diagnosis":"A síndrome pode comprometer sangue e rins e requer monitorização da circulação, função renal e eletrólitos.","expected":"Muitas crianças se recuperam, mas o risco de complicações e a necessidade de suporte variam conforme a causa.","alarm":"Palidez, hematomas, inchaço ou pouca urina precisam ser comunicados imediatamente.","immediate":"Convulsão, falta de ar, sangramento importante ou alteração de consciência exigem emergência.","return":"Após alta, mantenha controle de pressão, urina e função renal conforme a nefrologia.","sources":[{"url":"https://www.niddk.nih.gov/health-information/kidney-disease/children/hemolytic-uremic-syndrome","title":"NIDDK — Hemolytic uremic syndrome in children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome Hepatorrenal em Pediatria","aliases":["Síndrome hepatorrenal"],"setting":"hospital","general":"A redução da função renal em criança com doença hepática exige avaliação hospitalar. Informe diurese, perdas de líquidos e tratamentos em uso.","diagnosis":"É necessário distinguir síndrome hepatorrenal de desidratação, infecção e outras lesões renais, que também podem coexistir.","expected":"A evolução depende da doença hepática e da resposta ao suporte; avaliação de transplante pode ser necessária.","alarm":"Observe redução da urina, aumento do inchaço, febre, sangramento ou piora da disposição.","immediate":"Pouca urina com prostração, confusão, falta de ar ou sangramento exige atendimento imediato.","return":"O seguimento é conjunto entre hepatologia e nefrologia, com monitorização após qualquer estabilização.","sources":[{"url":"https://link.springer.com/article/10.1007/s00467-026-07205-w","title":"Pediatric Nephrology — Terlipressin in paediatric HRS-AKI","accessed":"2026-09-26"}],"reviewNotes":"Evidência pediátrica limitada; orientação de encaminhamento, sem transpor regimes adultos.","status":"source-reviewed"},
{"name":"Síndrome Inflamatória Multissistêmica Associada à Covid-19","aliases":["SIM-P","Síndrome inflamatória multissistêmica pediátrica"],"setting":"hospital","general":"A suspeita exige avaliação hospitalar. Informe infecção ou contato recente com covid e o início da febre e de outros sintomas.","diagnosis":"A síndrome pode afetar vários órgãos e se parecer com outras doenças. A equipe precisa avaliar coração, circulação e inflamação.","expected":"Muitas crianças recuperam-se, mas gravidade e tempo de recuperação variam; algumas precisam de terapia intensiva.","alarm":"Observe dor abdominal importante, fraqueza, alterações respiratórias, dor torácica ou redução da urina.","immediate":"Desmaio, dificuldade para respirar, pouca resposta ou sinais de choque exigem emergência.","return":"Após alta, mantenha seguimento; atividade física depende de liberação cardiológica quando houve comprometimento cardíaco.","sources":[{"url":"https://www.cdc.gov/mis/hcp/clinical-care-treatment/index.html","title":"CDC — Clinical Treatment of MIS-C","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Síndrome metabólica infantil","aliases":[],"setting":"specialist","general":"Adote mudanças sustentáveis para toda a família: refeições variadas, menos bebidas açucaradas, atividade agradável, sono adequado e ambiente sem fumaça.","diagnosis":"Na infância, a avaliação deve focar pressão, glicose, lipídios e crescimento; critérios de adultos não devem ser aplicados automaticamente.","expected":"A redução do risco ocorre com acompanhamento contínuo, sem promessa de resultado rápido ou metas de peso sem considerar crescimento.","alarm":"Observe sede ou urina excessivas, perda de peso inexplicada, fadiga e limitação física.","immediate":"Vômitos com prostração, respiração anormal, desmaio ou alteração de consciência exige atendimento imediato.","return":"Retorne para revisão dos fatores de risco e objetivos individualizados. Evite dietas extremas, suplementos para emagrecer e comentários que estigmatizem a criança.","sources":[{"url":"https://www.healthychildren.org/English/health-issues/conditions/obesity/Pages/Ways-to-Protect-Your-Kids-Against-Metabolic-Syndrome.aspx","title":"AAP — Ways to Protect Children Against Metabolic Syndrome","accessed":"2026-09-26"}],"reviewNotes":"Não define diagnóstico por corte adulto. Sinais agudos de possível descompensação exigem avaliação; não são critérios da síndrome.","status":"source-reviewed"},
{"name":"Síndrome Nefrótica na Infância","aliases":["Síndrome nefrótica"],"setting":"specialist","general":"Siga o plano de controle de peso, urina e edema. Restrição de líquidos, quando necessária, deve ser definida pela equipe.","diagnosis":"A perda de proteína pela urina pode causar inchaço. O primeiro episódio e apresentações atípicas precisam de avaliação especializada.","expected":"Muitas crianças respondem ao tratamento, mas recaídas são frequentes e exigem plano escrito.","alarm":"Observe aumento do edema, redução da urina, febre, dor abdominal ou dor em um membro.","immediate":"Falta de ar, dor torácica, prostração ou dor abdominal importante com febre exige emergência.","return":"Mantenha seguimento nefrológico e aprenda como reconhecer recaída; não ajuste tratamento apenas pela aparência do inchaço.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/nephrotic_syndrome/","title":"RCH — Nephrotic syndrome","accessed":"2026-09-26"}],"reviewNotes":"Distinguir primeiro episódio, recaída e formas atípicas; alta depende da estabilidade e educação familiar.","status":"source-reviewed"},
{"name":"Síndrome nefrótica por lesão mínima","aliases":[],"setting":"specialist","general":"Siga o plano da nefrologia para tratamento, alimentação e acompanhamento de peso e urina. Não altere líquidos, sal ou medicamentos por conta própria; registre edema e resultados solicitados.","diagnosis":"Na síndrome nefrótica, ocorre perda de proteína na urina e inchaço. Lesão mínima é uma causa frequente na infância, mas o diagnóstico e a resposta precisam de confirmação clínica.","expected":"Pode haver remissão e recaídas. A melhora do edema não autoriza interrupção do tratamento; o acompanhamento monitora doença, infecções e efeitos adversos.","alarm":"Febre, dor abdominal, aumento rápido do edema ou diminuição da urina requerem avaliação rápida.","immediate":"Falta de ar, dor torácica, inchaço doloroso de um membro, prostração ou pouca urina importante: emergência.","return":"Cumpra revisões e exames e avise a equipe quando surgirem sinais de recaída ou infecção.","sources":[{"url":"https://www.niddk.nih.gov/health-information/kidney-disease/children/nephrotic-syndrome-children","title":"NIDDK — Nephrotic Syndrome in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Síndrome SAPHO","aliases":["SAPHO"],"setting":"specialist","general":"Mantenha reumatologia e dermatologia; registre dor, mobilidade e lesões cutâneas. Não altere tratamento especializado sozinho.","diagnosis":"Confirmar inflamação óssea/articular e excluir infecção, neoplasia e outros diagnósticos conforme avaliação.","expected":"Pode haver recaídas; não há prazo universal de cura.","alarm":"Piora funcional, febre, dor nova ou lesões extensas exigem revisão.","immediate":"Déficit neurológico, incapacidade súbita de caminhar ou deterioração geral exigem urgência.","return":"Acompanhe atividade óssea, pele e função, com exames definidos pelo especialista.","sources":[{"url":"https://pubmed.ncbi.nlm.nih.gov/39909492/","title":"Matucci-Cerinic et al. — Paediatric SAPHO phenotypes, 2025","accessed":"2026-09-27"},{"url":"https://kompas.hosp.keio.ac.jp/disease/000735/","title":"Keio University Hospital — SAPHO","accessed":"2026-09-27"}],"reviewNotes":"Lacuna pediátrica documental suprida por coorte específica. Ramos são organização clínica inferida, não classificação homologada ou autorização de novos regimes.","status":"source-reviewed","evidenceSummary":"Coorte multicêntrica pediátrica 2025: 54 pacientes com manifestações cutâneas comparados a 167 CNO/CRMO; resumo primário lido. Fenótipos diferiram, mas dados observacionais não validam diagnóstico individual nem superioridade terapêutica. Fonte universitária complementa evolução geral.","decisionSupport":{"summary":"O cuidado geral é aplicável ao diagnóstico especializado; selecione opcionalmente o fenótipo documentado para acrescentar seguimento específico, sem inferir tratamento pela pele.","requirements":["Idade de início; diagnóstico especializado; imagem e exclusão de infecção/neoplasia.","Acne/hidradenite versus pustulose/psoríase; lesões vertebrais; mobilidade; tratamento e resposta."],"branchRequired":false,"branches":[{"id":"acne_hs","label":"Acne / hidradenite","when":"Fenótipo atribuído pela equipe.","setting":"specialist","overrides":{"diagnosis":"Avaliar conjuntamente pele e inflamação óssea.","expected":"Pele pode ter curso refratário.","return":"Reumatologia e dermatologia coordenam seguimento.","alarm":"Dor axial ou piora cutânea.","immediate":"Déficit neurológico: urgência."}},{"id":"ppp_psoriase","label":"Pustulose palmoplantar / psoríase","when":"Fenótipo atribuído pela equipe.","setting":"specialist","overrides":{"diagnosis":"Documentar atividade cutânea e osteoarticular.","expected":"Resposta variável; não prever pela coorte.","return":"Rever sintomas e função em conjunto.","alarm":"Nova limitação ou febre.","immediate":"Perda súbita de mobilidade: urgência."}},{"id":"sem_pele","label":"Osteíte sem manifestação cutânea","when":"Ausência de pele registrada; diagnóstico revisto.","setting":"specialist","overrides":{"diagnosis":"Não equiparar automaticamente CNO/CRMO a SAPHO.","expected":"Classificação e evolução permanecem individualizadas.","return":"Confirmar nomenclatura e plano especializado.","alarm":"Lesões novas ou dor persistente.","immediate":"Déficit neurológico ou deterioração: urgência."}}]},"revisedAt":"2026-09-27"},
{"name":"Síndrome Torácica Aguda","setting":"hospital","aliases":["Síndrome torácica aguda falciforme"],"general":"Complicação pulmonar da doença falciforme pode evoluir rapidamente e exige atendimento hospitalar.","diagnosis":"Informe o diagnóstico de base e crises recentes. A equipe acompanhará respiração, oxigenação e necessidade de suporte especializado.","expected":"A gravidade varia e a piora pode ocorrer durante uma crise dolorosa, mesmo após avaliação inicial.","alarm":"Dor torácica, febre, falta de ar ou respiração rápida são alarmes; a tosse pode aparecer depois.","immediate":"Procure emergência imediatamente com esses sintomas, sem esperar melhora em casa.","return":"Após alta, cumpra hematologia e o plano preventivo; qualquer recorrência respiratória exige nova avaliação urgente.","sources":[{"url":"https://www.nnuh.nhs.uk/publication/download/sickle-cell-disease-paediatrics-4/","title":"Norfolk and Norwich University Hospitals — Sickle Cell Disease: Paediatrics","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Documento hospitalar pediátrico aprovado em 2024, com revisão prevista em 2025, permanece acessível. Síntese restrita a reconhecimento e encaminhamento; exige conferência institucional antes de uso assistencial. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Síndromes de Dependência de Vitamina B6","aliases":[],"setting":"specialist","general":"Mantenha seguimento com neurologia e metabolismo e siga rigorosamente o plano individual; informe dificuldades de acesso ou administração do tratamento.","diagnosis":"Há diferentes causas de crises dependentes de vitamina B6, como alterações em ALDH7A1 e PNPO; as formas terapêuticas não são intercambiáveis automaticamente.","expected":"As crises podem ser controladas, mas dificuldades de desenvolvimento podem persistir e exigem acompanhamento.","alarm":"Comunique novas crises, perda de habilidades, vômitos que impeçam tratamento ou alteração de comportamento.","immediate":"Crise prolongada, crises sem recuperação ou dificuldade respiratória exige emergência.","return":"Mantenha avaliação do desenvolvimento e confirmação etiológica; não faça testes ou mudanças por conta própria.","sources":[{"url":"https://medlineplus.gov/genetics/condition/pyridoxine-dependent-epilepsy/","title":"MedlinePlus Genetics — Pyridoxine-dependent epilepsy","accessed":"2026-09-26"},{"url":"https://medlineplus.gov/genetics/condition/pyridoxal-phosphate-responsive-seizures/","title":"MedlinePlus Genetics — Pyridoxal phosphate-responsive seizures","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Grupo preservado; ALDH7A1, PNPO e PLPBP não foram cadastrados como sinônimos entre si. Não fornece doses nem teste empírico domiciliar.","status":"source-reviewed"},
{"name":"Síndromes Febris Periódicas","aliases":["Febres periódicas"],"setting":"specialist","general":"Registre datas, duração, temperatura e sintomas de cada episódio, incluindo como a criança fica entre crises. Leve o diário à pediatria ou reumatologia.","diagnosis":"Febres recorrentes exigem distinguir infecções, PFAPA e síndromes hereditárias; um rótulo genérico não define tratamento.","expected":"Algumas formas melhoram com a idade, enquanto outras precisam de acompanhamento prolongado e prevenção de complicações.","alarm":"Avise sobre perda de peso, falta de recuperação entre crises ou mudança do padrão habitual.","immediate":"Prostração, rigidez de nuca, falta de ar ou manchas arroxeadas exigem emergência.","return":"Mantenha seguimento e não atribua automaticamente toda nova febre à síndrome conhecida.","sources":[{"url":"https://link.springer.com/article/10.1186/s12969-020-00424-x","title":"CARRA — Consensus treatment plans for PFAPA","accessed":"2026-09-26"},{"url":"https://medlineplus.gov/genetics/condition/familial-mediterranean-fever/","title":"MedlinePlus Genetics — Familial Mediterranean fever","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Fontes exemplificam PFAPA e febre familiar do Mediterrâneo; não cobrem posologia nem prognóstico de todas as síndromes periódicas. Orientação geral exige identificação da síndrome.","status":"source-reviewed"},
{"name":"Sinovite transitória do quadril","aliases":[],"setting":"home","general":"Após avaliação, permita repouso e evite esportes enquanto houver dor. A criança pode adotar a posição mais confortável sem ser forçada a andar.","diagnosis":"Sinovite transitória é diagnóstico após considerar causas mais graves de claudicação. Febre ou piora pode exigir revisão dessa hipótese.","expected":"A melhora costuma começar em poucos dias, com recuperação em até cerca de duas semanas; o padrão deve ser progressivo.","alarm":"Observe aumento da dor, nova febre ou dificuldade crescente para apoiar.","immediate":"Febre com dor forte, prostração ou incapacidade de movimentar o quadril exige avaliação imediata para excluir infecção.","return":"Retorne se não começar a melhorar nos primeiros dias ou persistir além do esperado; retome atividade gradualmente após recuperação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Transient_synovitis/","title":"RCH — Transient synovitis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"Sinusite bacteriana aguda","aliases":[],"setting":"home","general":"Ofereça líquidos, permita repouso e mantenha o ambiente sem fumaça. Faça higiene nasal conforme orientação e use apenas os tratamentos definidos para idade e apresentação clínica.","diagnosis":"O diagnóstico de sinusite bacteriana depende do padrão e da duração dos sintomas; secreção colorida isolada não o confirma. Cumpra o tratamento prescrito e não reutilize sobras de receitas.","expected":"A melhora deve ser progressiva, mas congestão e tosse podem persistir por algum tempo. Piora ou falta de resposta exigem revisão da hipótese e do tratamento.","alarm":"Febre persistente, dor facial crescente ou piora após melhora inicial precisam de avaliação.","immediate":"Inchaço ao redor dos olhos, alteração visual, dor de cabeça muito intensa, rigidez de nuca ou sonolência: emergência.","return":"Retorne no prazo combinado e antecipadamente se piorar; quadros recorrentes requerem avaliação específica.","sources":[{"url":"https://www.nhs.uk/conditions/sinusitis-sinus-infection/","title":"NHS — Sinusitis","accessed":"2026-09-26"},{"url":"https://www.cdc.gov/antibiotic-use/hcp/clinical-care/pediatric-outpatient.html","title":"CDC — Outpatient Clinical Care for Pediatric Populations","accessed":"2026-09-26"},{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Periorbital_and_orbital_cellulitis/","title":"Royal Children’s Hospital — Periorbital and orbital cellulitis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica. CDC pediátrico fundamenta critérios clínicos; RCH fundamenta sinais de possíveis complicações orbitárias/intracranianas. Nenhuma posologia foi extrapolada.","status":"source-reviewed"},
{"name":"Sonambulismo e Outras Parassonias","aliases":["Sonambulismo","Parassonias"],"setting":"home","general":"Mantenha rotina regular, sono suficiente e ambiente protegido. Registre horário, duração e comportamento dos episódios.","diagnosis":"Caracterize o evento; comportamentos noturnos não são todos sonambulismo.","expected":"Formas típicas frequentemente diminuem com a idade; outros eventos têm evolução própria.","alarm":"Lesões, episódios frequentes, ronco com pausas ou sonolência diurna exigem consulta.","immediate":"Dificuldade respiratória, lesão importante ou alteração persistente da consciência exigem urgência.","return":"Reveja o quadro se persistente ou atípico; investigação do sono depende da avaliação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Sleepwalking/","title":"RCH — Sleepwalking","accessed":"2026-09-27"},{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Night_terrors_night_time_wakings/","title":"RCH — Night terrors","accessed":"2026-09-27"},{"url":"https://www.nhs.uk/conditions/night-terrors/","title":"NHS — Night terrors and nightmares","accessed":"2026-09-27"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3466793/","title":"AASM — Pediatric non-respiratory polysomnography indications","accessed":"2026-09-27"}],"reviewNotes":"Revisão documental por evento; não declara cobertura de todas as parassonias. Exige revisão individual, sem homologação humana.","status":"source-reviewed","evidenceSummary":"RCH/NHS: orientações pediátricas para eventos típicos. AASM 2012: avaliação especializada e possível vídeo-polissonografia/EEG para eventos atípicos ou lesivos; evidência pediátrica limitada e parcialmente extrapolada. Não presume benignidade de todo evento.","decisionSupport":{"summary":"Selecionar evento clinicamente caracterizado antes de preenchimento; o ramo atípico encaminha, sem confirmar parassonia.","requirements":["Idade; horário no sono; duração/frequência; lembrança e possibilidade de despertar.","Movimentos estereotipados, lesões, ronco/apneia, sonolência, estressores e produtos utilizados."],"branchRequired":true,"branches":[{"id":"sonambulismo","label":"Sonambulismo típico","when":"Deambulação sem despertar pleno, avaliada.","setting":"home","overrides":{"diagnosis":"Conduzir suavemente à cama; proteger saídas.","expected":"Frequentemente melhora com a idade.","return":"Rever recorrência ou impacto.","alarm":"Quedas, ronco ou sonolência.","immediate":"Lesão importante: urgência."}},{"id":"terror","label":"Terror noturno típico","when":"Agitação inicial sem lembrança, avaliada.","setting":"home","overrides":{"diagnosis":"Não despertar nem conter, salvo risco de lesão.","expected":"Frequentemente diminui com a idade.","return":"Rever episódios frequentes ou violentos.","alarm":"Risco de ferimentos.","immediate":"Dificuldade respiratória: urgência."}},{"id":"pesadelo","label":"Pesadelos","when":"Despertar com lembrança do sonho.","setting":"home","overrides":{"diagnosis":"Acolher e investigar estressores.","expected":"Pode melhorar com rotina e apoio.","return":"Consultar se frequente ou associado a trauma.","alarm":"Prejuízo diurno ou medo persistente.","immediate":"Risco imediato de lesão: urgência."}},{"id":"atipico","label":"Outro evento / atípico","when":"Fenômeno não esclarecido ou sinais incomuns.","setting":"specialist","overrides":{"diagnosis":"Excluir epilepsia e distúrbios respiratórios.","expected":"Indefinida até esclarecimento.","return":"Avaliação especializada antes de orientação definitiva.","alarm":"Eventos estereotipados ou pausas respiratórias.","immediate":"Pouca resposta persistente: emergência."}}]},"revisedAt":"2026-09-27"},
{"name":"SSJ e Necrólise Epidérmica Tóxica","aliases":["Síndrome de Stevens-Johnson","Necrólise epidérmica tóxica"],"setting":"hospital","general":"Procure hospital imediatamente se houver suspeita. Leve a lista e as embalagens de medicamentos utilizados recentemente.","diagnosis":"A reação pode causar bolhas, desprendimento da pele e lesões de mucosas. Identificar o agente e avaliar os olhos é importante.","expected":"A recuperação pode levar semanas ou meses e deixar sequelas; a gravidade determina a necessidade de suporte intensivo.","alarm":"Observe pele dolorosa, bolhas, descamação, feridas na boca, dor ocular ou dificuldade de engolir.","immediate":"Erupção progressiva com bolhas, lesões oculares ou dificuldade respiratória exige emergência, sem aguardar melhora.","return":"Após alta, siga cuidados de pele e mucosas e registre a suspeita causal para evitar reexposição.","sources":[{"url":"https://www.nhs.uk/conditions/stevens-johnson-syndrome/","title":"NHS — Stevens-Johnson syndrome","accessed":"2026-09-26"}],"reviewNotes":"SSJ e NET são mantidas como espectro; extensão e tratamento requerem avaliação especializada.","status":"source-reviewed"},
{"name":"Subluxação da cabeça do rádio (Pronação dolorosa)","setting":"urgent","general":"Mantenha o braço confortável e procure atendimento para avaliação e redução. Não tente recolocar a articulação em casa.","diagnosis":"Após tratamento, evite puxar, levantar ou balançar a criança pelas mãos ou punhos; levante pelas axilas e oriente outros cuidadores.","expected":"O uso do braço costuma retornar após a redução, às vezes com pequeno atraso. Episódios podem recorrer em crianças com articulações mais frouxas.","alarm":"Persistência da recusa em mover o braço ou dor importante pode indicar redução incompleta ou outra lesão.","immediate":"Procure atendimento imediatamente na suspeita inicial; deformidade, inchaço importante ou mão fria precisam de avaliação de trauma.","return":"Se não mover completamente o braço até o dia seguinte, retorne para novo exame. Retome atividades conforme conforto após liberação.","sources":[{"url":"https://www.rch.org.au/kidsinfo/fact_sheets/Pulled_elbow/","title":"RCH — Pulled elbow","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Taquicardia Supraventricular na Pediatria","aliases":[],"setting":"urgent","general":"Informe início das palpitações, episódios anteriores e tratamentos recebidos; procure avaliação para registrar o ritmo cardíaco.","diagnosis":"A taquicardia supraventricular pode causar palpitação nas crianças maiores e dificuldade para mamar, suor ou abatimento nos bebês.","expected":"O episódio pode ser controlado, mas pode voltar; o acompanhamento define prevenção e necessidade de outros procedimentos.","alarm":"Observe cansaço, palidez, tontura e piora da alimentação ou da respiração.","immediate":"Desmaio, sonolência incomum, falta de ar ou má circulação exigem emergência; não faça pressão nos olhos nem no pescoço.","return":"Após estabilização, siga o plano de cardiologia e as instruções individualizadas para recorrência.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Supraventricular_Tachycardia_SVT/","title":"RCH — Supraventricular Tachycardia","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Taquicardia Ventricular com Pulso na Infância","aliases":["Taquicardia ventricular com pulso"],"setting":"hospital","general":"Taquicardia ventricular exige atendimento monitorizado imediato, mesmo quando a criança ainda está consciente e tem pulso. Informe cardiopatias, tratamentos e o momento de início.","diagnosis":"A equipe avalia ritmo e estabilidade da circulação; presença de pulso não garante segurança para observação domiciliar.","expected":"A evolução depende da causa e pode deteriorar rapidamente, exigindo intervenção hospitalar.","alarm":"Palpitações com tontura, dor torácica, fraqueza ou alteração do comportamento são preocupantes.","immediate":"Desmaio, falta de ar, pouca resposta ou sinais de choque exigem SAMU 192.","return":"Após estabilização, mantenha investigação cardiológica e orientação individual sobre atividades e prevenção de recorrência.","sources":[{"url":"https://cpr.heart.org/-/media/CPR-Files/CPR-Guidelines-Files/2025-Accessible/Algorithm-PALS-Tachyarrhythmia-LngDscrp-250729-Ed.pdf?sc_lang=en","title":"American Heart Association — Pediatric tachyarrhythmia with a pulse algorithm, 2025","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. Algoritmo para profissionais fundamenta urgência e monitorização; não fornece alta ambulatorial nem autoriza manobras ou doses caseiras.","status":"source-reviewed"},
{"name":"Taquipneia transitória do recém-nascido","aliases":[],"setting":"hospital","general":"O recém-nascido deve permanecer sob avaliação e monitorização até estabilidade. Não force mamadas se houver respiração muito rápida ou esforço.","diagnosis":"O diagnóstico exige excluir outras causas de desconforto respiratório, como infecção; necessidade de oxigênio e alimentação assistida é definida pela equipe.","expected":"Em muitos casos há melhora em dois a três dias, mas persistência ou piora exige rever o diagnóstico e suporte.","alarm":"Observe gemência, retrações entre as costelas, coloração azulada e dificuldade alimentar.","immediate":"Pausas respiratórias, lábios azulados, piora do esforço ou pouca resposta exigem atendimento imediato.","return":"Após alta com respiração e alimentação estáveis, siga consultas pediátricas; retorne imediatamente se esses sinais reaparecerem e não presuma que continuam sendo transitórios.","sources":[{"url":"https://medlineplus.gov/ency/article/007233.htm","title":"MedlinePlus — Transient tachypnea of the newborn","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental das fontes consultadas; requer revisão médica antes do uso individual.","status":"source-reviewed"},
{"name":"TDAH tipo desatento","setting":"specialist","general":"Combine rotinas previsíveis, instruções curtas e apoio escolar com a equipe que acompanha a criança. Evite interpretar dificuldades como preguiça.","diagnosis":"O plano pode incluir treinamento de cuidadores e intervenções de sala de aula; avalie sono, aprendizagem, ansiedade e outras condições associadas.","expected":"O funcionamento pode melhorar com acompanhamento consistente; as necessidades mudam com a idade. A resposta deve ser avaliada em casa e na escola.","alarm":"Queda importante do rendimento, insônia persistente, perda de peso ou mudança intensa de humor justificam revisão antecipada.","immediate":"Busque emergência diante de autoagressão, risco imediato, desmaio ou sintomas graves novos; esses sinais não devem ser atribuídos ao TDAH.","return":"Retorne periodicamente para rever objetivos, efeitos adversos quando houver tratamento e relatos escolares; mantenha decisões compartilhadas com a criança e a família.","sources":[{"url":"https://www.cdc.gov/adhd/hcp/clinical-care/index.html","title":"CDC — Clinical Care of ADHD in Children","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"TDAH tipo hiperativo-impulsivo","aliases":["TDAH predominantemente hiperativo-impulsivo"],"setting":"specialist","general":"Mantenha rotinas previsíveis, instruções curtas e reforço positivo. Combine estratégias com a escola e evite punições físicas ou rótulos depreciativos.","diagnosis":"O plano considera idade, dificuldades funcionais e condições associadas. Treinamento de responsáveis e intervenções comportamentais são componentes importantes do cuidado.","expected":"A resposta varia e exige ajustes com a equipe. O objetivo é melhorar segurança, participação e relações, sem exigir desaparecimento imediato de todo comportamento.","alarm":"Informe piora do sono, perda de apetite, sofrimento emocional ou aumento de comportamentos perigosos, especialmente após mudanças terapêuticas.","immediate":"Risco imediato de ferir a si ou outras pessoas ou alteração acentuada da consciência exige urgência; não é manifestação habitual a ser atribuída ao TDAH.","return":"Mantenha retornos para avaliar benefícios, dificuldades e efeitos adversos. Leve observações de casa e da escola e não ajuste medicamentos por conta própria.","sources":[{"url":"https://www.cdc.gov/adhd/treatment/index.html","title":"CDC — Treatment of ADHD","accessed":"2026-09-26"}],"reviewNotes":"Fonte de tratamento aplica-se às apresentações do TDAH; predominância hiperativa-impulsiva precisa de diagnóstico clínico. Alertas de crise requerem avaliação de condições associadas. Rascunho para revisão médica.","status":"source-reviewed"},
{"name":"TDAH tipo misto","aliases":["TDAH apresentação combinada"],"setting":"specialist","general":"Estabeleça rotinas simples, instruções curtas e reforço positivo. Combine estratégias com a escola e mantenha sono, atividades e acompanhamento familiar de forma consistente.","diagnosis":"No TDAH de apresentação combinada, o plano considera desatenção e hiperatividade/impulsividade, idade e impacto funcional. Intervenções comportamentais e tratamentos devem ser individualizados e acompanhados.","expected":"O controle costuma exigir ajustes ao longo do desenvolvimento. O objetivo é melhorar funcionamento e bem-estar, sem prometer cura imediata ou atribuir todo comportamento ao diagnóstico.","alarm":"Dificuldades escolares persistentes, insônia, perda de apetite, sofrimento emocional ou efeitos adversos precisam de revisão.","immediate":"Risco de autoagressão, alteração mental aguda ou sintomas físicos graves após tratamento exigem atendimento urgente.","return":"Mantenha retornos para avaliar resposta em casa e na escola, crescimento, sono e condições associadas.","sources":[{"url":"https://www.cdc.gov/adhd/treatment/index.html","title":"CDC — Treatment of ADHD","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. O rótulo tipo misto foi preservado; terminologia atual equivalente: apresentação combinada.","status":"source-reviewed"},
{"name":"Teníase em Pediatria","setting":"home","aliases":["Teníase"],"general":"Infecção intestinal por tênia exige confirmação e tratamento adequado à espécie e ao contexto.","diagnosis":"Informe eliminação de segmentos nas fezes e histórico de exposição. Mantenha higiene das mãos e preparo seguro dos alimentos.","expected":"A melhora dos sintomas não comprova eliminação; exames de fezes de controle podem ser necessários.","alarm":"Dor persistente, perda de peso ou sintomas neurológicos precisam de avaliação.","immediate":"Convulsão, cefaleia intensa ou alteração de consciência exigem emergência e investigação de outras condições associadas.","return":"Cumpra controle após tratamento; não repita por conta própria se houver suspeita de comprometimento neurológico.","sources":[{"url":"https://www.cdc.gov/taeniasis/hcp/clinical-care/index.html","title":"CDC — Clinical Treatment of Taeniasis","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Teníase intestinal não equivale a cisticercose. Espécie e manifestações neurológicas precisam ser avaliadas; não aplicar automaticamente esquema único a todas as espécies. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Teníase por Taenia saginata","aliases":[],"setting":"home","general":"Mantenha higiene das mãos após o banheiro e antes de alimentos e consuma carne bem cozida. Faça os exames e o tratamento indicados; não use vermífugos repetidamente por conta própria.","diagnosis":"A teníase por T. saginata se relaciona à ingestão de carne bovina contaminada. A identificação adequada importa; não confundir essa espécie com T. solium e seus riscos específicos.","expected":"Muitas pessoas têm poucos sintomas, mas a eliminação do parasito precisa ser acompanhada conforme o plano. Melhora do desconforto sozinha não confirma cura.","alarm":"Dor abdominal persistente, perda de peso, vômitos ou permanência de segmentos nas fezes exigem revisão.","immediate":"Dor intensa, barriga muito distendida, vômitos persistentes ou sinais de desidratação: atendimento imediato.","return":"Retorne para controle conforme orientação e informe se continuar observando segmentos após o tratamento.","sources":[{"url":"https://www.cdc.gov/taeniasis/about/index.html","title":"CDC — About Human Tapeworm","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Teníase por Taenia solium","setting":"home","general":"Lave as mãos após usar o banheiro e antes de preparar alimentos. Utilize saneamento adequado e consuma carne suína bem cozida.","diagnosis":"A teníase intestinal vem da carne contaminada; ingerir ovos eliminados nas fezes pode causar cisticercose em si ou em outras pessoas. A higiene é essencial.","expected":"Sintomas podem ser leves ou ausentes; a eliminação de segmentos nas fezes não comprova resolução. É necessário tratamento e controle orientados.","alarm":"Dor abdominal persistente, perda de peso ou eliminação repetida de segmentos justificam reavaliação.","immediate":"Procure emergência diante de convulsão, alteração visual aguda, confusão ou cefaleia intensa, pois sintomas neurológicos precisam de investigação.","return":"Retorne com os exames solicitados e confirme a resposta ao tratamento; informe sintomas neurológicos antes de iniciar qualquer esquema.","sources":[{"url":"https://www.cdc.gov/taeniasis/about/index.html","title":"CDC — About Human Tapeworm","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Testículo ectópico","aliases":[],"setting":"specialist","general":"Procure urologia pediátrica ou cirurgia pediátrica para confirmar a posição do testículo e planejar correção. Não tente deslocá-lo com massagens ou manobras caseiras.","diagnosis":"O testículo ectópico está fora do trajeto habitual e do escroto. Diferencia-se do testículo retrátil; não se espera que alcance espontaneamente a posição correta.","expected":"A correção deve ser planejada precocemente. O acompanhamento posterior verifica posição, crescimento e possíveis complicações, sem garantir fertilidade apenas pela cirurgia.","alarm":"Observe dor, inchaço ou mudança de cor na virilha, no escroto ou no local onde o testículo foi identificado.","immediate":"Dor súbita intensa, especialmente com vômitos ou inchaço, exige emergência para excluir torção.","return":"Mantenha o calendário cirúrgico e as revisões após o procedimento. A ausência de dor não é motivo para adiar avaliação especializada.","sources":[{"url":"https://uroweb.org/guidelines/paediatric-urology/chapter/management-of-undescended-testes","title":"EAU — Management of undescended testes: ectopic testes","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental para revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Tetralogia de Fallot","aliases":[],"setting":"specialist","general":"Mantenha seguimento cardiológico e siga o plano individual de alimentação, atividade e saturação. Informe a cor habitual e qualquer mudança no cansaço durante mamadas ou brincadeiras.","diagnosis":"A tetralogia de Fallot é uma cardiopatia estrutural que geralmente necessita correção cirúrgica. Episódios súbitos de piora da coloração azulada podem refletir redução importante da oxigenação.","expected":"Após tratamento, muitas crianças têm boa evolução, mas precisam de acompanhamento por toda a vida para avaliar ritmo, válvulas e função cardíaca.","alarm":"Piora do ganho de peso, cansaço crescente, palpitações ou mudança da tolerância às atividades justificam revisão antecipada.","immediate":"Crise de cianose, desmaio, convulsão ou falta de ar intensa exige emergência imediata.","return":"Cumpra os retornos mesmo após cirurgia e confirme com a cardiologia orientações para exercícios e procedimentos.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/tetralogy-of-fallot.html","title":"CDC — Tetralogy of Fallot","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; não constitui homologação clínica. ","status":"source-reviewed"},
{"name":"Tinea Capitis na Criança","aliases":["Tinha do couro cabeludo"],"setting":"home","general":"Evite compartilhar pentes, bonés, toalhas e travesseiros; higienize os objetos e avalie animais com lesões suspeitas.","diagnosis":"A micose do couro cabeludo geralmente necessita tratamento oral; produtos locais isolados podem não resolver.","expected":"O tratamento costuma levar semanas, e o cabelo pode demorar mais a recuperar; complete o período indicado.","alarm":"Informe aumento da dor, pus, inchaço importante ou crescimento da área sem cabelo.","immediate":"Febre com lesão muito dolorosa ou criança abatida exige avaliação rápida.","return":"Retorne para confirmar resposta e duração; o retorno escolar deve seguir a orientação local após início do tratamento.","sources":[{"url":"https://www.nhs.uk/conditions/ringworm/","title":"NHS — Ringworm","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Tinea corporis","aliases":[],"setting":"home","general":"Mantenha pele limpa e seca e não compartilhe toalhas, roupas ou equipamentos. Higienize mãos após contato com animais.","diagnosis":"A tinha do corpo é causada por fungos; confirme o diagnóstico se a lesão for atípica. Não use corticoide isoladamente em suspeita de micose.","expected":"A resposta depende da extensão, local e tratamento correto. Complete o período prescrito mesmo se a aparência melhorar antes.","alarm":"Observe expansão, novas lesões, dor, pus ou ausência de melhora.","immediate":"Febre com prostração, infecção rapidamente progressiva ou acometimento importante próximo aos olhos exige avaliação imediata.","return":"Retorne em falha, recorrência ou imunossupressão; lesões no couro cabeludo ou unhas precisam de avaliação própria, sem copiar o tratamento da pele.","sources":[{"url":"https://www.cdc.gov/ringworm/about/index.html","title":"CDC — Ringworm Basics","accessed":"2026-09-26"}],"reviewNotes":"Orientação para tinea corporis; não extrapola tratamento de pele a couro cabeludo/unhas.","status":"source-reviewed"},
{"name":"Tinea cruris","aliases":[],"setting":"home","general":"Mantenha a virilha limpa e seca, troque roupas úmidas e prefira peças que reduzam atrito. Não compartilhe toalhas e use o tratamento apenas pelo período e modo orientados.","diagnosis":"Tinea cruris é uma micose da região inguinal; outras dermatites podem parecer semelhantes. Não use combinações com corticoide por conta própria nem trate mucosas como se fossem pele comum.","expected":"Costuma responder ao tratamento em semanas, mas pode voltar se persistirem fatores predisponentes. Melhora da coceira não significa que o tratamento terminou.","alarm":"Espalhamento, dor, pus, recorrência frequente ou ausência de resposta precisam de reavaliação.","immediate":"Febre com vermelhidão rapidamente progressiva, dor intensa ou prostração: atendimento imediato.","return":"Retorne se não melhorar em cerca de duas semanas ou antes se piorar; confirme o diagnóstico nas recorrências.","sources":[{"url":"https://medlineplus.gov/ency/article/000876.htm","title":"MedlinePlus — Jock itch","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Tinea pedis","setting":"home","general":"Mantenha os pés limpos e bem secos, sobretudo entre os dedos. Troque meias e use calçados ventilados; evite compartilhar toalhas e sapatos.","diagnosis":"Não coce as lesões e use chinelos em banheiros ou vestiários coletivos. Complete o cuidado recomendado e confira se o produto é adequado à idade.","expected":"A melhora geralmente ocorre ao longo de semanas, e reinfecção é possível; preservar os cuidados de higiene ajuda a evitar recorrência.","alarm":"Dor crescente, calor, vermelhidão, lesões em outros locais ou acometimento de unhas exigem revisão.","immediate":"Procure atendimento rápido se o pé ou a perna ficar quente, doloroso e vermelho, especialmente com febre, diabetes ou imunossupressão.","return":"Retorne se o tratamento orientado não funcionar, se a lesão voltar ou o diagnóstico permanecer incerto.","sources":[{"url":"https://www.nhs.uk/conditions/athletes-foot/","title":"NHS — Athlete's foot","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte consultada; requer revisão médica individual antes de emitir.","aliases":[],"status":"source-reviewed"},
{"name":"Toxocaríase em Pediatria","aliases":["Toxocaríase"],"setting":"specialist","general":"Informe exposição a animais, solo e sintomas visuais. Siga avaliação conforme os órgãos possivelmente envolvidos.","diagnosis":"Um exame sorológico positivo isolado não confirma doença ativa. Formas viscerais e oculares precisam de avaliações diferentes.","expected":"A evolução varia: algumas infecções são assintomáticas, enquanto comprometimento ocular pode deixar perda visual.","alarm":"Observe febre persistente, dor abdominal, tosse ou redução da visão.","immediate":"Perda visual nova, convulsão ou dificuldade respiratória exige avaliação imediata.","return":"Mantenha acompanhamento infectológico e oftalmológico quando indicado. A decisão de tratar depende do quadro clínico, não apenas do resultado laboratorial.","sources":[{"url":"https://www.cdc.gov/toxocariasis/hcp/clinical-overview/index.html","title":"CDC — Clinical overview of toxocariasis","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Toxoplasmose Congênita","setting":"specialist","aliases":["Toxoplasmose congênita"],"general":"Infecção adquirida antes do nascimento exige avaliação precoce, mesmo quando o bebê parece saudável.","diagnosis":"Cumpra investigação e acompanhamento de olhos, audição e desenvolvimento. Triagem isolada não substitui confirmação nem avaliação diante de suspeita clínica.","expected":"O curso varia com as lesões existentes; o cuidado precoce busca reduzir danos, mas alterações podem exigir seguimento prolongado.","alarm":"Mudança visual, dificuldade alimentar, alteração do crescimento da cabeça ou regressão merecem revisão.","immediate":"Convulsão, sonolência importante ou redução de resposta requerem emergência.","return":"Mantenha consultas e exames definidos pela equipe, inclusive na ausência de sintomas.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/t/toxoplasmose/publicacoes/fluxo_de_conduta_e_tratamento_do_recem_nascido.pdf","title":"Ministério da Saúde — Abordagem da toxoplasmose no recém-nascido","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Transposição de Grandes Artérias (TGA)","aliases":["d-TGA"],"setting":"hospital","general":"A suspeita em recém-nascido exige atendimento hospitalar especializado. Informe coloração azulada, alimentação e respiração.","diagnosis":"Na transposição clássica, a circulação depende da mistura de sangue entre circuitos; a anatomia associada modifica a gravidade.","expected":"O cuidado inicial e a correção são individualizados. A recuperação depende da anatomia e das intercorrências.","alarm":"Observe cansaço às mamadas, respiração rápida ou piora da coloração.","immediate":"Lábios azulados, prostração ou dificuldade respiratória exige emergência.","return":"Depois da correção, mantenha cardiologia ao longo da vida e avaliações de crescimento, função cardíaca e desenvolvimento conforme orientação.","sources":[{"url":"https://www.cdc.gov/heart-defects/about/d-tga.html","title":"CDC — Dextro-transposition of the great arteries","accessed":"2026-09-26"}],"reviewNotes":"Fonte e capítulo interpretados como d-TGA clássica. Não extrapolar para transposição congenitamente corrigida (l-TGA), que exige registro próprio.","status":"source-reviewed"},
{"name":"Transtorno Afetivo Bipolar em Pediatria","aliases":["Transtorno bipolar pediátrico"],"setting":"specialist","general":"Mantenha acompanhamento especializado, rotina de sono e registro de mudanças marcantes de humor, energia e funcionamento.","diagnosis":"O diagnóstico exige distinguir episódios de humor de outras condições e comportamentos próprios do desenvolvimento.","expected":"É possível alcançar melhor controle, mas o curso pode ser recorrente e requer cuidado continuado.","alarm":"Informe redução importante do sono, impulsividade, agitação, tristeza persistente ou piora escolar.","immediate":"Ideias de suicídio, comportamento perigoso ou sintomas psicóticos com risco exige emergência.","return":"Cumpra revisões, envolva responsáveis e escola conforme necessidade e não altere o tratamento sem combinar com a equipe.","sources":[{"url":"https://www.nimh.nih.gov/health/publications/bipolar-disorder-in-children-and-teens","title":"NIMH — Bipolar disorder in children and teens","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Transtorno de Ansiedade Generalizada em Pediatria","aliases":["Transtorno de ansiedade generalizada","TAG"],"setting":"specialist","general":"Mantenha rotina de sono, atividades e apoio escolar. Acolha o sofrimento e incentive participação gradual nas atividades planejadas com a equipe, sem punições.","diagnosis":"Preocupação persistente que interfere na vida requer avaliação; psicoterapia, família e escola podem integrar o cuidado.","expected":"A melhora costuma ser gradual e depende de acompanhamento e adesão; oscilações não significam fracasso.","alarm":"Relate piora funcional, recusa escolar persistente, agitação ou mudanças importantes após iniciar tratamento.","immediate":"Ideias de suicídio, automutilação ou risco imediato exigem atendimento de urgência e supervisão contínua.","return":"Mantenha revisões para avaliar sintomas, segurança, metas e resposta ao plano.","sources":[{"url":"https://cps.ca/en/documents/position/anxiety-in-children-and-youth-management","title":"Canadian Paediatric Society — Anxiety in children and youth: management","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"},
{"name":"Transtorno de Ansiedade Social em Pediatria","setting":"specialist","aliases":["Ansiedade social","Fobia social"],"general":"Medo persistente de situações sociais pode prejudicar escola e relações; não equivale apenas a timidez.","diagnosis":"Escute sem julgamento e procure avaliação especializada. Família e escola podem apoiar o plano terapêutico, evitando humilhação ou exposição forçada.","expected":"A melhora costuma ser gradual com tratamento apropriado; algumas crianças precisam de cuidado prolongado.","alarm":"Isolamento crescente, recusa escolar importante, depressão ou prejuízo do autocuidado exigem revisão.","immediate":"Risco de autoagressão ou suicídio exige supervisão contínua e atendimento de emergência.","return":"Mantenha seguimento e metas graduais combinadas com a equipe; antecipe consulta se houver piora.","sources":[{"url":"https://www.nhs.uk/mental-health/conditions/social-anxiety/","title":"NHS — Social anxiety","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Transtorno de Sintomas Somáticos em Pediatria","aliases":["Transtorno de sintomas somáticos"],"setting":"specialist","general":"Reconheça que os sintomas são reais. Combine com a equipe metas graduais de rotina, escola e atividades.","diagnosis":"O cuidado considera saúde física e mental em conjunto; sintomas somáticos podem coexistir com outras doenças.","expected":"A recuperação funcional costuma ser gradual e pode oscilar. Acompanhamento consistente ajuda a ajustar metas e estratégias.","alarm":"Informe mudança do padrão, perda de função ou sintomas novos para reavaliação.","immediate":"Risco à segurança, incapacidade de cuidar das necessidades básicas ou deterioração aguda exige atendimento urgente.","return":"Mantenha consultas programadas e comunicação entre profissionais, evitando investigações repetidas sem indicação clínica.","sources":[{"url":"https://cps.ca/en/documents/position/somatic-symptom-and-related-disorders","title":"Canadian Paediatric Society — Somatic symptom and related disorders","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Transtorno do Déficit de Atenção (TDAH) em Pediatria","aliases":["TDAH"],"setting":"specialist","general":"Organize rotinas, instruções curtas e apoio escolar; participe do treinamento de cuidadores indicado.","diagnosis":"O TDAH exige avaliação do funcionamento em diferentes ambientes; o plano depende da idade, sintomas e condições associadas.","expected":"O cuidado busca melhorar aprendizagem, relações e autonomia, com ajustes durante o crescimento.","alarm":"Informe problemas novos de sono, alimentação, humor ou piora importante no desempenho e nas relações.","immediate":"Risco de autoagressão ou alteração comportamental grave necessita avaliação imediata.","return":"Leve informações escolares aos retornos para revisar benefícios e dificuldades.","sources":[{"url":"https://www.cdc.gov/adhd/treatment/index.html","title":"CDC — Treatment of ADHD","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. Abrange TDAH geral, preservando apresentações distintas; não exige apresentação combinada.","status":"source-reviewed"},
{"name":"Transtorno do Pânico em Pediatria","aliases":[],"setting":"specialist","general":"Acolha a criança, ajude-a a usar estratégias aprendidas e mantenha sono e rotina; combine acompanhamento psicológico e familiar.","diagnosis":"Ataque isolado não confirma transtorno do pânico; sintomas físicos precisam de avaliação para excluir outras causas.","expected":"O tratamento pode reduzir crises e medo antecipatório, mas a resposta leva tempo e varia.","alarm":"Informe evitação crescente, faltas escolares, depressão ou piora após mudança de tratamento.","immediate":"Risco de autoagressão, desmaio ou falta de ar diferente do padrão avaliado exige atendimento imediato.","return":"Retorne para acompanhar frequência das crises e impacto nas atividades, com plano individual para episódios.","sources":[{"url":"https://www.nimh.nih.gov/health/publications/panic-disorder-when-fear-overwhelms","title":"NIMH — Panic Disorder: What You Need to Know","accessed":"2026-09-26"},{"url":"https://cps.ca/en/documents/position/anxiety-in-children-and-youth-management","title":"Canadian Paediatric Society — Anxiety in children and youth: management","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Transtorno Obsessivo Compulsivo na Pediatria","aliases":["Transtorno obsessivo-compulsivo","TOC"],"setting":"specialist","general":"Acolha a criança sem punição pelos rituais. Participe do plano terapêutico e combine apoio da escola quando necessário.","diagnosis":"Pensamentos intrusivos e compulsões podem causar sofrimento; avaliação especializada diferencia sintomas do transtorno de outros comportamentos.","expected":"A melhora costuma ser gradual. Psicoterapia com exposição e prevenção de resposta é adaptada à idade e à família.","alarm":"Observe prejuízo importante do sono, alimentação, escola, isolamento ou piora de humor.","immediate":"Ideação suicida, autoagressão ou incapacidade de manter segurança exige avaliação imediata.","return":"Mantenha consultas regulares e monitorização de efeitos do tratamento; mudanças e interrupções devem ser combinadas com a equipe.","sources":[{"url":"https://www.nice.org.uk/guidance/cg31/chapter/Recommendations","title":"NICE — Obsessive-compulsive disorder: recommendations","accessed":"2026-09-26"}],"reviewNotes":"Fonte inclui recomendações próprias para crianças e adolescentes.","status":"source-reviewed"},
{"name":"TRAPS (Síndrome Periódica Associada ao Receptor 1 de Fator de Necrose Tumoral)","setting":"specialist","aliases":["TRAPS"],"general":"Síndrome genética autoinflamatória pode causar febre prolongada, dor e inflamação recorrentes.","diagnosis":"Registre as crises e mantenha o plano especializado. Discuta vacinação e prevenção de infecções conforme o tratamento individual.","expected":"Controle contínuo reduz complicações; pode haver inflamação mesmo entre crises, sem sintomas evidentes.","alarm":"Inchaço, urina espumosa, dor intensa ou febre diferente do padrão precisam de avaliação.","immediate":"Falta de ar, confusão ou deterioração rápida exigem emergência.","return":"Cumpra revisões e exames de urina, rins e inflamação; não abandone seguimento quando as crises diminuírem.","sources":[{"url":"https://www.ncbi.nlm.nih.gov/sites/books/NBK586171/","title":"GeneReviews — TNF Receptor-Associated Periodic Fever Syndrome","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Triquinose em Pediatria","aliases":["Triquinelose"],"setting":"specialist","general":"Informe consumo de carne suína ou de caça malcozida e outras pessoas expostas; siga avaliação e tratamento individualizados.","diagnosis":"A triquinose pode começar com sintomas intestinais e depois causar febre, dores musculares e inchaço ao redor dos olhos.","expected":"A melhora depende da intensidade e do momento do tratamento; dores podem persistir por período prolongado.","alarm":"Informe fraqueza crescente, dificuldade para se movimentar, dor no peito ou sintomas neurológicos.","immediate":"Falta de ar, desmaio, alteração de consciência ou dor torácica importante exigem emergência.","return":"Mantenha retornos para acompanhar a recuperação e cozinhe adequadamente carnes para prevenir novas exposições.","sources":[{"url":"https://www.cdc.gov/trichinellosis/hcp/clinical-overview/index.html","title":"CDC — Clinical Overview of Trichinellosis","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental para revisão médica; leitura das fontes não equivale a homologação clínica. ","status":"source-reviewed"},
{"name":"Trombocitopenia Primária Imune","setting":"specialist","aliases":["PTI","Trombocitopenia imune"],"general":"Plaquetas baixas aumentam o risco de sangramento; a conduta depende dos sintomas, não apenas do número.","diagnosis":"Evite atividades com impacto e novos medicamentos sem orientação. Cumpra o plano de restrição e os exames indicados.","expected":"Muitas crianças melhoram espontaneamente; algumas têm curso prolongado e precisam de acompanhamento.","alarm":"Sangramento de mucosas, sangue na urina ou fezes e hematomas que aumentam exigem contato médico.","immediate":"Qualquer trauma na cabeça, cefaleia intensa, vômitos ou alteração de consciência requerem emergência.","return":"Mantenha retorno e hemograma nos prazos definidos; antecipe revisão diante de novos sangramentos.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Immune_thrombocytopenic_purpura/","title":"RCH — Immune thrombocytopenic purpura","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Tronco Arterioso","aliases":["Truncus arteriosus"],"setting":"hospital","general":"O bebê deve ser acompanhado em centro cardiológico com cirurgia pediátrica. Informe mudanças na alimentação, respiração e coloração.","diagnosis":"Uma única grande artéria recebe sangue dos dois ventrículos. A anatomia associada define o planejamento da correção.","expected":"A correção costuma ser necessária cedo; novas intervenções e acompanhamento ao longo da vida podem ser necessários.","alarm":"Observe suor nas mamadas, dificuldade para alimentar, cansaço, pouca evolução do peso ou arroxeamento.","immediate":"Respiração muito difícil, sonolência intensa, pouca resposta ou coloração azulada progressiva exigem atendimento imediato.","return":"Após cirurgia, mantenha controles do coração, dos condutos e do desenvolvimento, conforme a equipe.","sources":[{"url":"https://www.chop.edu/conditions-diseases/truncus-arteriosus","title":"CHOP — Truncus Arteriosus","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Tuberculose Pulmonar na Criança","aliases":["Tuberculose pulmonar"],"setting":"specialist","general":"Mantenha seguimento com a equipe de tuberculose, boa ventilação e medidas de higiene respiratória orientadas.","diagnosis":"A avaliação infantil considera sintomas, exposição e exames. Contatos próximos precisam de investigação conforme o serviço.","expected":"A recuperação depende do tratamento completo; melhora dos sintomas não significa que já possa interrompê-lo.","alarm":"Informe piora da tosse, febre, perda de peso ou dificuldade para tolerar o tratamento.","immediate":"Falta de ar, prostração intensa ou sangue em quantidade ao tossir exige avaliação imediata.","return":"Compareça às revisões e monitorização. Afastamento e precauções dependem da avaliação de transmissibilidade individual.","sources":[{"url":"https://www.gov.br/saude/pt-br/assuntos/saude-de-a-a-z/t/tuberculose","title":"Ministério da Saúde — Tuberculose","accessed":"2026-09-26"}],"reviewNotes":"Fonte oficial geral aplicada apenas a orientações de seguimento e prevenção. Não extrapola esquemas, critérios de diagnóstico de adultos ou prazos de transmissibilidade para toda criança.","status":"source-reviewed"},
{"name":"Urolitíase em Pediatria","aliases":["Urolitíase","Litíase urinária"],"setting":"specialist","general":"Ofereça líquidos conforme orientação para idade e função renal. Guarde eventual cálculo eliminado para análise, se solicitado.","diagnosis":"O tamanho, a localização e a composição do cálculo orientam o cuidado. Crianças precisam investigar fatores que favorecem novos cálculos.","expected":"Cálculos pequenos podem sair espontaneamente; obstrução ou dor importante pode exigir procedimento. O tempo de resolução varia.","alarm":"Observe dor persistente, sangue na urina, febre, vômitos ou redução da urina.","immediate":"Procure pronto atendimento se não urinar, houver dor intensa, febre ou incapacidade de beber.","return":"Mantenha seguimento urológico ou nefrológico para exames e prevenção individualizada de recorrência.","sources":[{"url":"https://www.niddk.nih.gov/health-information/urologic-diseases/kidney-stones-children/treatment-prevention","title":"NIDDK — Treatment and Prevention for Kidney Stones in Children","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica e adequação ao caso.","status":"source-reviewed"},
{"name":"Urticária em Pediatria","aliases":["Urticária"],"setting":"home","general":"Após avaliação de quadro isolado, observe possíveis desencadeantes e fotografe as lesões para mostrar à equipe.","diagnosis":"Placas que coçam podem ocorrer por infecção ou sem causa definida; nem toda urticária durante tratamento significa alergia ao medicamento.","expected":"As lesões podem mudar de lugar e reaparecer. Persistência por semanas exige investigação orientada.","alarm":"Avise sobre febre, dor, lesões persistentes no mesmo local ou recorrência frequente.","immediate":"Inchaço de língua, dificuldade respiratória, desmaio ou sintomas em vários órgãos exige emergência por possível anafilaxia.","return":"Retorne se houver piora ou duração prolongada; evite restrições alimentares sem indicação.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/urticaria/","title":"RCH — Urticaria","accessed":"2026-09-26"}],"reviewNotes":"Síntese documental de fonte lida, destinada à revisão médica; não representa homologação clínica humana.","status":"source-reviewed"},
{"name":"Varicela em Pediatria","aliases":["Varicela"],"setting":"home","general":"Mantenha hidratação e unhas curtas; evite coçar as lesões. Siga orientações para evitar transmissão e contato com pessoas vulneráveis.","diagnosis":"A avaliação de risco considera idade, imunidade e doenças associadas; não use medicamentos por conta própria.","expected":"A maioria evolui bem, mas infecção da pele e complicações respiratórias ou neurológicas podem ocorrer.","alarm":"Observe febre persistente, lesão muito vermelha, quente, dolorosa ou com pus.","immediate":"Falta de ar, dificuldade de acordar, confusão, rigidez no pescoço ou dificuldade para caminhar exige emergência.","return":"Procure revisão diante de piora, febre por mais de quatro dias ou condição de alto risco.","sources":[{"url":"https://www.cdc.gov/chickenpox/treatment/index.html","title":"CDC — How to Treat Chickenpox","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fonte consultada; requer revisão médica individual.","status":"source-reviewed"},
{"name":"Vasculite por IgA (Púrpura de Henoch-Schönlein)","setting":"specialist","aliases":["Vasculite por IgA","Púrpura de Henoch-Schönlein"],"general":"Vasculite pode causar manchas, dor articular e abdominal; comprometimento renal pode ocorrer sem sintomas.","diagnosis":"Siga as revisões com pressão arterial e exame de urina, mesmo após desaparecimento das manchas.","expected":"Muitos casos melhoram espontaneamente, mas recaídas e alterações renais exigem vigilância por período definido pela equipe.","alarm":"Dor abdominal intensa, vômitos, sangue nas fezes, inchaço ou urina alterada são alarmes.","immediate":"Dor intensa persistente, sangramento importante ou dor testicular requerem urgência imediata.","return":"Cumpra o calendário de acompanhamento; novas manifestações devem antecipar a revisão, inclusive depois da melhora inicial.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/henochSchonlein_Purpura/","title":"RCH — IgA Vasculitis","accessed":"2026-09-26"}],"status":"source-reviewed","reviewNotes":"Fonte oficial/primária aberta e sintetizada para orientação geral. Rascunho documental; requer revisão médica individual e não constitui homologação clínica humana."},
{"name":"Ventrículo Único","aliases":["Coração funcionalmente univentricular"],"setting":"specialist","general":"Siga o plano específico da cardiopatia e da etapa cirúrgica. Quando orientado, registre peso, alimentação e saturação usando os limites fornecidos pela equipe.","diagnosis":"Ventrículo único reúne anatomias diferentes. O período entre operações pode exigir vigilância domiciliar intensiva e acesso rápido ao centro cardiológico.","expected":"Crescimento, oxigenação e evolução dependem da anatomia e das intervenções; não existe uma meta universal de saturação.","alarm":"Comunique piora das mamadas, perda de peso, respiração diferente ou queda de saturação.","immediate":"Cianose acentuada, desmaio ou pouca resposta exigem emergência.","return":"Mantenha contatos e consultas frequentes conforme o programa de acompanhamento.","sources":[{"url":"https://www.gosh.nhs.uk/conditions-and-treatments/conditions-we-treat/functionally-univentricular-heart/","title":"Great Ormond Street Hospital — Functionally univentricular heart","accessed":"2026-09-26"},{"url":"https://www.childrensnational.org/get-care/departments/single-ventricle-program/single-ventricle-home-monitoring-program","title":"Children’s National — Single Ventricle Home Monitoring Program","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. A fonte de monitorização refere-se particularmente ao período entre a primeira e a segunda cirurgia; não generalizar metas ou frequência para Glenn, Fontan ou outras anatomias.","status":"source-reviewed"},
{"name":"Vômitos em Crianças","aliases":["Vômitos"],"setting":"home","general":"Se a criança foi avaliada e está alerta, ofereça líquidos em pequenas quantidades frequentes, conforme orientação. Observe urina e capacidade de manter a ingestão.","diagnosis":"Vômito é um sintoma; sua causa precisa ser reconsiderada quando persiste ou aparece sem diarreia.","expected":"A evolução depende da causa; parar de vomitar após tratamento não exclui doença importante.","alarm":"Recusa persistente de líquidos, pouca urina, dor localizada ou prostração exigem reavaliação.","immediate":"Vômito verde, sangue, alteração da consciência, dor abdominal intensa ou sinais neurológicos exigem emergência.","return":"Retorne se não conseguir hidratar, houver piora ou a recuperação não seguir o plano estabelecido.","sources":[{"url":"https://www.rch.org.au/clinicalguide/guideline_index/Vomiting/","title":"Royal Children’s Hospital — Vomiting","accessed":"2026-09-26"}],"reviewNotes":"Rascunho documental baseado em fontes consultadas; requer revisão médica individual antes da emissão. ","status":"source-reviewed"}
];
